module proteinPrecipitationDetection
module digestCompletionDetection

manifest ProteinSample
manifest TrichloroaceticAcid
manifest WashBuffer
manifest ResolubilizingBuffer
manifest TCEP_Reductant
manifest Iodoacetamide
manifest Trypsin

// ============================================================
// Digital Microfluidics for Automated Proteomic Processing
// Jebrail M.J., Luk V.N., Shih S.C.C., Fobel R., Ng A.H.C.,
// Yang H., Freire S.L.S., Wheeler A.R.
// JoVE. 33. DOI: 10.3791/1603 (2009)
//
// Protocol integrates protein extraction by precipitation with
// multistep solution-phase processing: reduction, alkylation,
// and tryptic digestion -- all on a single DMF device.
//
// DEVICE CONFIGURATION:
//   Two-plate DMF device (bottom: patterned Cr electrodes,
//   Parylene-C dielectric, Teflon-AF hydrophobic layer;
//   top: unpatterned ITO with Teflon-AF).
//   Gap set by 140 um double-sided tape.
//   Actuation: 100 V_rms / 18 kHz via 40-pin connectors.
//   Droplet volume: ~600 nL (defined by electrode dimensions).
//   Control: LabView (National Instruments) with in-house
//   feedback calibration.
//
// RESERVOIR MAP (Figure 1b):
//   R-1  ProteinSample       -- serum/protein in working buffer
//   R-2  TrichloroaceticAcid -- 20% TCA precipitant in DI water
//   R-3  Waste reservoir     -- supernatant / waste (modelled as drain)
//   R-4  WashBuffer          -- 70/30 Chloroform/ACN rinse
//   R-5  ResolubilizingBuffer-- 100 mM AmBic pH 8.0, 0.08% Pluronic
//   R-6  TCEP_Reductant      -- 10 mM TCEP in working buffer
//   R-7  Iodoacetamide       -- 12 mM IAM in working buffer
//   R-8  Trypsin             -- trypsin at 1/5 of protein conc.
//
// WORKING BUFFER (WB): 100 mM TrisHCl pH 7.8, 0.08% Pluronic F127.
//   Pluronic F127 is a surfactant additive to prevent biofouling.
//
// NOTE ON PRECIPITATION ABSTRACTION:
//   Steps 2-4 use mix/heat to abstract the DMF precipitation
//   event (protein:TCA merge, incubation, supernatant removal,
//   and wash). BioScript has no native "precipitate" or "wash"
//   primitive; mix + heat model the electrode-actuated incubation
//   and the wash steps are modelled as sequential mix/drain.
//   The precipitate physically remains on the device surface
//   between wash and resolubilization; this is abstracted by
//   allowing the variable to persist until disposeWaste.
//
// NOTE ON MIXING PATTERN:
//   Parts 4.5-4.7 specify circular mixing (6-electrode circular
//   actuation) for reduction, alkylation, and digestion steps.
//   All mix durations reflect actual incubation times from the
//   protocol (not mixing time only). BioScript `mix` unifies
//   both the droplet merging+mixing actuation and the subsequent
//   incubation.
//
// NOTE ON TEMPERATURE CONTROL:
//   heat at 25c models room-temperature incubation steps.
//   heat at 37c models the hot plate used for tryptic digestion.
//   BioScript duration tokens are s / m only.
//   Incubation times: reduction 1h = 60m, alkylation 15m,
//   digestion 3h = 180m.
//
// CFG STRUCTURE:
//   BB1  main                -- extraction, reduction, alkylation,
//                               digestion, post-processing
//   BB2  digestPass          -- digestSignal > 0: digestion complete;
//                               dispose processed sample
//   BB3  digestFail          -- digestSignal <= 0: incomplete digest;
//                               drain sample
//   BB4  finalCleanup        -- terminal: dispose QC signal
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// PART 3 / PART 4 - STEP 1: Dispense protein sample droplet
//   from R-1. Protein dissolved in WB (100 mM TrisHCl pH 7.8,
//   0.08% Pluronic F127). ~600 nL dispensed by electrode
//   actuation. This is the starting material for the entire
//   proteomic workup (e.g. BSA as model protein, Figure 4).
// ------------------------------------------------------------

proteinDroplet     = dispense 1 units of ProteinSample

// ------------------------------------------------------------
// PART 4 - STEP 2a: Dispense precipitant from R-2.
//   20% Trichloroacetic acid (TCA) in DI water. TCA
//   denatures and precipitates proteins by lowering pH and
//   disrupting hydration shells.
// ------------------------------------------------------------

precipitantDroplet = dispense 1 units of TrichloroaceticAcid

// ------------------------------------------------------------
// PART 4 - STEP 2b: Merge protein + precipitant droplets.
//   Combined droplet incubated for 5 min at room temperature.
//   Proteins precipitate onto the device surface (Figure 2,
//   Frames 1-3). `mix` abstracts the electrode-driven merge
//   and 5-min incubation on the DMF surface.
// ------------------------------------------------------------

precipitationMix   = mix proteinDroplet with precipitantDroplet for 5m

// ------------------------------------------------------------
// PART 4 - STEP 2c: Remove supernatant (actuate away to R-3).
//   After precipitation, the aqueous supernatant (containing
//   TCA and soluble contaminants) is actuated to the waste
//   reservoir. The protein precipitate remains on-surface.
//   `drain` models the electrode-driven supernatant removal
//   to R-3 (Figure 2, Frame 4).
// ------------------------------------------------------------

drain precipitationMix

// ------------------------------------------------------------
// PART 4 - STEP 3: Wash precipitate with three droplets of
//   wash buffer from R-4 (70/30 Chloroform/ACN).
//   Each droplet is driven across the precipitated protein and
//   actuated to waste reservoir R-3 to remove residual TCA
//   and non-protein contaminants (Figure 2, Frame 5).
//   Three sequential wash steps modelled as independent
//   dispense/drain pairs (see NOTE ON COMPILER CONSTRAINT).
//
//   NOTE ON COMPILER CONSTRAINT: lilott8/BioScript does not
//   support loop constructs or multi-unit wash iteration.
//   The three wash steps are unrolled explicitly. Each wash
//   droplet is dispensed independently and drained individually.
// ------------------------------------------------------------

wash1              = dispense 1 units of WashBuffer
drain wash1

wash2              = dispense 1 units of WashBuffer
drain wash2

wash3              = dispense 1 units of WashBuffer
drain wash3

// ------------------------------------------------------------
// PART 4 - STEP 4: Resolubilize protein precipitate.
//   Allow precipitate to dry on surface, then dispense
//   resolubilizing buffer from R-5 (100 mM Ammonium Bicarbonate
//   pH 8.0, 0.08% Pluronic F127). Incubate 20 min until
//   precipitate fully dissolves (Figure 2, Frame 6).
//   `mix` with heat at 25c abstracts the 20-min incubation
//   at room temperature.
// ------------------------------------------------------------

resolubilizingBuffer = dispense 1 units of ResolubilizingBuffer

// Dispense a second protein droplet to represent the
// on-surface precipitate being re-contacted with buffer.
// This models the resolubilization of the dried protein
// precipitate on the electrode surface into the buffer droplet.
proteinPrecipitate   = dispense 1 units of ProteinSample

resolubilizedSample  = mix proteinPrecipitate with resolubilizingBuffer for 20m

// ------------------------------------------------------------
// PART 4 - STEP 5: Reduction.
//   Dispense reductant (TCEP) from R-6 and merge with sample.
//   TCEP (tris(2-carboxyethyl)phosphine) at 10 mM reduces
//   disulfide bonds. Mix by circular 6-electrode actuation.
//   Incubate 1 h (60 min) at room temperature in a humidified
//   chamber (Figure 3, Frames 1-2).
// ------------------------------------------------------------

reductantDroplet   = dispense 1 units of TCEP_Reductant
reducedSample      = mix resolubilizedSample with reductantDroplet for 60m
heat reducedSample at 25c for 60m

// ------------------------------------------------------------
// PART 4 - STEP 6: Alkylation.
//   Dispense alkylating agent (IAM) from R-7 and merge with
//   sample. Iodoacetamide (12 mM) alkylates free thiols to
//   prevent re-oxidation of cysteines. Mix as in step 5.
//   Incubate 15 min at room temperature, protected from light
//   (Figure 3, Frames 2-3).
// ------------------------------------------------------------

alkylatingDroplet  = dispense 1 units of Iodoacetamide
alkylatedSample    = mix reducedSample with alkylatingDroplet for 15m
heat alkylatedSample at 25c for 15m

// ------------------------------------------------------------
// PART 4 - STEP 7: Tryptic digestion.
//   Dispense trypsin from R-8 and merge with sample. Trypsin
//   concentration is 1/5 of total protein concentration.
//   Mix as in step 5 (circular 6-electrode actuation).
//   Incubate 3 h (180 min) at 37 C in a humidified chamber
//   on a hot plate (Figure 3, Frames 3-4).
//   Trypsin cleaves at Lys-X and Arg-X peptide bonds.
// ------------------------------------------------------------

trypsinDroplet     = dispense 1 units of Trypsin
digestedSample     = mix alkylatedSample with trypsinDroplet for 180m
heat digestedSample at 37c for 180m

// ------------------------------------------------------------
// PART 4 - POST-PROCESSING QC:
//   Detect digest completion via peptide signal (abstracts the
//   downstream nano-HPLC/MS readout described in Parts 5-6).
//   In the paper, the processed sample is quenched with 0.6 mL
//   2.5% TFA (off-chip), purified by C18 ZipTip SPE, and
//   evaluated by nano-HPLC-MS/MS. For the eGFP-analogue here,
//   digestCompletionDetection abstracts the SEQUEST database
//   search result (protein ID at 99.9% confidence, >=30%
//   sequence coverage; Figure 4, 25 peptides from BSA, 44% cov).
// ------------------------------------------------------------

digestSignal = detect digestCompletionDetection on digestedSample for 30s

// ============================================================
// BB2 / BB3: Digest QC gate
// Pass (BB2): digestSignal > 0 -> digestion complete and
//             peptides detected at required confidence;
//             dispose processed sample.
// Fail (BB3): digestSignal <= 0 -> digest incomplete or no
//             identifiable peptides; drain sample.
// Both branches converge at BB4 (finalCleanup).
// ============================================================

if (digestSignal > 0) {
    dispose digestedSample
} else {
    drain digestedSample
}

// ============================================================
// BB4: finalCleanup (terminal)
// Dispose digest QC signal droplet. Experiment ends.
// ============================================================

dispose digestSignal

// [terminal -- no further instructions; exit node for CFG]

module glucoamylaseDetection
module maltodextrinGrowthDetection
module fermentationDetection

manifest IDY1_Cells
manifest IDY2_Cells
manifest YPD_Media
manifest MUG_Alpha_Substrate
manifest PhosphateBuffer_pH7_5
manifest BSA_Solution
manifest HFE7500_Surfactant
manifest SpacerOil
manifest MaltodextrinMedia
manifest SyntheticBeverageMedia

// ============================================================
// A Microfluidic Multiplex Sorter for Strain Development
// Leal-Alves, Dumont, Deng, Alkhaldi, Leung, Oeser, Shih
// Adv. Mater. Technol. 2025, 10, 2401209
// DOI: 10.1002/admt.202401209
//
// Protocol: Droplet-digital multiplex electrostatic sorting
// of genome-shuffled diastatic yeast (S. cerevisiae var.
// diastaticus) based on two fluorescence thresholds of
// glucoamylase activity, followed by post-HTS strain
// recovery and beverage fermentation evaluation.
//
// BIOLOGICAL OVERVIEW:
//   Two diastatic yeast strains (IDY1 and IDY2), isolated
//   from the beverage industry, are genome-shuffled via
//   self-mating to generate libraries of >10^7 variants.
//   Single cells are encapsulated in 30 pL droplets with
//   YPD media and the fluorescent glucoamylase substrate
//   4-methylumbelliferyl-alpha-D-glucopyranoside (4-MUG-a).
//   After 48 h incubation off-chip at 30 C, droplets are
//   re-injected into the multiplex electrostatic sorter
//   (15 kHz, 105 Vrms) and partitioned into two gates:
//     GT1 (gate-SC1): high fluorescence (top 95th percentile)
//     GT2 (gate-SC2): mid fluorescence (85th percentile)
//   Non-selected waste droplets flow to the central channel.
//   Recovered colonies are screened on maltodextrin and the
//   best performers are selected for beverage fermentation.
//
// SUBSTRATE NOTE:
//   4-MUG-a (4-methylumbelliferyl-alpha-D-glucopyranoside)
//   was validated for glucoamylase detection at pH 7.5 with
//   a fluorescence readout (ex 360 nm / em 450 nm). This
//   substrate is used in preference to 4-NPM (absorbance)
//   because fluorescence detection is more sensitive and
//   compatible with droplet path lengths at 30 pL volume.
//   All droplets contain 2 mM 4-MUG-a in 0.1 M phosphate
//   buffer pH 7.5 and 10% BSA to reduce surface adsorption.
//
// DROPLET GENERATION NOTE:
//   Cells are co-encapsulated with substrate at a Poisson
//   ratio (lambda = 0.3) for single-cell occupancy:
//     30 pL -> 2x10^7 cells/mL
//   Droplets are generated at T-junction generators in
//   HFE7500 oil with 2% fluorosurfactant and collected
//   into PCR tubes for off-chip incubation.
//
// SORTER DESIGN NOTE:
//   Co-planar electrostatic electrodes (SE1 and SE2) are
//   activated at 15 kHz / 105 Vrms to laterally displace
//   droplets from the central waste channel (WC) into
//   sorting channels SC1 (high) or SC2 (mid). Sorting
//   throughput: 160 Hz for 30 pL droplets. False negative
//   rate: ~3%. No pressure rebalancing or redesign is
//   required when switching droplet sizes (30-1000 pL).
//   `mix` steps below abstract electrode-actuated droplet
//   merging and flow-through sorting events.
//
// CFG STRUCTURE:
//   BB1  main               -- entry: cell prep, genome shuffling,
//                              droplet encapsulation, off-chip
//                              incubation, sorter re-injection
//   BB2  highGatePass       -- gt1Signal > 0: high-fitness droplet
//                              sorted into SC1; recover colonies
//   BB3  highGateFail       -- gt1Signal <= 0: not high-fitness;
//                              continue to mid-gate check
//   BB4  highGateJoin       -- join: mid-gate branch begins
//   BB5  midGatePass        -- gt2Signal > 0: mid-fitness droplet
//                              sorted into SC2; recover colonies
//   BB6  midGateFail        -- gt2Signal <= 0: waste; drain
//   BB7  midGateJoin        -- join: post-HTS recovery branch
//   BB8  maltodextrinPass   -- growthSignal > 0: improved growth;
//                              select for fermentation assay
//   BB9  maltodextrinFail   -- growthSignal <= 0: no improvement;
//                              drain
//   BB10 fermentationPass   -- fermentSignal > 0: improved
//                              fermentation; dispose (strain banked)
//   BB11 fermentationFail   -- fermentSignal <= 0: no fermentation
//                              improvement; drain
//   BB12 finalCleanup       -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prepare diastatic yeast cell suspension.
//   IDY1 or IDY2 parental strains grown overnight in YPD
//   broth at 30 C / 200 rpm. Cultures sonicated and washed
//   3x with PBS by centrifugation. Final pellet resuspended
//   in 2x YPD broth (buffered at pH 7.5).
//   Cell concentration adjusted for Poisson lambda = 0.3:
//     30 pL droplets -> 2x10^7 cells/mL
//   10% (w/w) BSA added to reduce surface adsorption.
//
//   NOTE: This .bs file encodes the IDY1 arm as the
//   representative protocol. A separate file should be
//   used for IDY2 with IDY2_Cells as the manifest entry.
//   Both arms use identical sorter parameters and assay
//   conditions; only the parental strain differs.
// ------------------------------------------------------------

cellSuspension   = dispense 1 units of IDY1_Cells
bsaAdditive      = dispense 1 units of BSA_Solution
cellsWithBSA     = mix cellSuspension with bsaAdditive for 2s

// ------------------------------------------------------------
// STEP 2: Prepare fluorescent glucoamylase substrate.
//   4-MUG-a prepared at 4 mM in 0.1 M phosphate buffer
//   pH 7.5. Co-encapsulated 1:1 with cell suspension to
//   yield a final droplet concentration of 2 mM 4-MUG-a.
//   Phosphate buffer keeps pH neutral for cell viability
//   while providing sufficient glucoamylase signal at 30 C.
// ------------------------------------------------------------

phosphateBuffer  = dispense 1 units of PhosphateBuffer_pH7_5
mugSubstrate     = dispense 1 units of MUG_Alpha_Substrate
assayMix         = mix mugSubstrate with phosphateBuffer for 5s

// ------------------------------------------------------------
// STEP 3: Co-encapsulate single cells with substrate in 30 pL
//   droplets at T-junction generator.
//   Cell solution mixed 1:1 with substrate solution; droplets
//   formed in HFE7500 oil + 2% fluorosurfactant.
//   Droplet size set by T-junction geometry (40 um channel,
//   30 pL target volume, D = 40 um diameter).
//   `mix` abstracts the T-junction co-flow encapsulation
//   event; this is a pressure-driven droplet generation step,
//   not a DMF electrode mixing operation.
// ------------------------------------------------------------

oilCarrier          = dispense 1 units of HFE7500_Surfactant
encapsulatedDroplets = mix cellsWithBSA with assayMix for 5s
dropletsInOil        = mix encapsulatedDroplets with oilCarrier for 2s

// ------------------------------------------------------------
// STEP 4: Off-chip incubation for 48 h at 30 C.
//   Droplets collected into PCR tubes with 50 uL of 2%
//   fluorosurfactant in HFE7500 and incubated in the dark
//   at 30 C. Fluorescence and bright-field images taken
//   every 24 h to monitor cell growth and glucoamylase
//   activity. 48 h selected based on optimisation data
//   showing peak fluorescence at this timepoint for 30 pL
//   droplets (IDY1: ~3 a.u.; IDY2: ~1 a.u.).
//   48 h = 2880 min.
// ------------------------------------------------------------

heat dropletsInOil at 30c for 2880m

// ------------------------------------------------------------
// STEP 5: Re-inject incubated droplets into multiplex sorter.
//   Droplets re-injected through 1/32" OD PEEK tubing at:
//     Re-injection flow rate: 3 nL/s
//     Spacer oil flow rate: 300 nL/s
//   Fluorescence population measured and displayed as a
//   histogram (Gaussian distribution, n ~= 720,000 droplets
//   screened at 160 Hz) to set sorting gate thresholds:
//     gate-SC1 (GT1): high fluorescence, 95th percentile
//     gate-SC2 (GT2): mid fluorescence, 85th percentile
//   `mix` abstracts the re-injection and flow-through
//   fluorescence interrogation event at the sorter inlet.
// ------------------------------------------------------------

spacerOil           = dispense 1 units of SpacerOil
reinjectedDroplets  = mix dropletsInOil with spacerOil for 1s

// ------------------------------------------------------------
// STEP 6: Fluorescence detection for multiplex gate assignment.
//   glucoamylaseDetection module abstracts in-line optical
//   fiber fluorescence measurement (ex 470 nm LED, emission
//   collected at 450 nm via bandpass filter). Signal measured
//   by in-house automation software and used to determine
//   which sorting electrode (SE1 or SE2) to actuate.
//   Detection window: 0.4 ms travel time at 160 Hz.
//   GT1 signal > 0: high fluorescence (SC1 sort)
//   GT2 signal > 0: mid fluorescence (SC2 sort)
//   Waste: neither threshold exceeded (central WC channel)
// ------------------------------------------------------------

gt1Signal = detect glucoamylaseDetection on reinjectedDroplets for 1s

// ============================================================
// BB2 / BB3: High-fitness gate (GT1 / SC1)
// Pass (BB2): gt1Signal > 0 -> high-glucoamylase droplet
//   detected above 95th percentile; actuate SE1 (15 kHz,
//   105 Vrms) to deflect into SC1. Recover into pipette tip.
// Fail (BB3): gt1Signal <= 0 -> not high-fitness; do not
//   actuate SE1; proceed to mid-gate evaluation (BB4).
// Both branches converge at BB4 (highGateJoin).
// ============================================================

if (gt1Signal > 0) {
    // --------------------------------------------------------
    // HIGH-FITNESS RECOVERY (GT1 / SC1):
    //   Droplet deflected to SC1 by SE1 electrode actuation.
    //   Sorted droplets collected by pipetting the top layer
    //   of the oil emulsion from pipette tips at the SC1
    //   outlet. Aliquots (5 uL) diluted into 50 uL YPD broth,
    //   plated on YPD agar plates, and incubated at 30 C for
    //   48 h. Several colonies selected for post-HTS analysis.
    //   High-sorted IDY1 strains labelled H2, H3 (paper).
    //   High-sorted IDY2 strains labelled H13, H23 (paper).
    // --------------------------------------------------------
    highFitnessDroplet = mix reinjectedDroplets with spacerOil for 1s
    dispose highFitnessDroplet
} else {
    drain reinjectedDroplets
}

// ============================================================
// BB4: highGateJoin
// Dispose GT1 QC signal. Control falls into mid-gate
// evaluation branch (BB5/BB6).
// ============================================================

dispose gt1Signal

// ------------------------------------------------------------
// STEP 7: Mid-fitness gate evaluation (GT2 / SC2).
//   For droplets that did not exceed the GT1 threshold,
//   the automation software evaluates whether the signal
//   exceeds the GT2 (mid, 85th percentile) threshold.
//   If yes, SE2 is actuated (15 kHz, 105 Vrms) to deflect
//   the droplet into SC2. If no, the droplet flows to the
//   central waste channel (WC) undeflected.
//   `detect` here abstracts the second threshold evaluation
//   performed on the same re-injected droplet population
//   (the sorter evaluates GT1 then GT2 sequentially per drop).
// ------------------------------------------------------------

gt2Signal = detect glucoamylaseDetection on spacerOil for 1s

// ============================================================
// BB5 / BB6: Mid-fitness gate (GT2 / SC2)
// Pass (BB5): gt2Signal > 0 -> mid-glucoamylase droplet
//   detected above 85th percentile; actuate SE2 (15 kHz,
//   105 Vrms) to deflect into SC2. Recover into pipette tip.
// Fail (BB6): gt2Signal <= 0 -> below both thresholds;
//   droplet flows undeflected into WC (waste). Drain.
// Both branches converge at BB7 (midGateJoin).
// ============================================================

if (gt2Signal > 0) {
    // --------------------------------------------------------
    // MID-FITNESS RECOVERY (GT2 / SC2):
    //   Droplet deflected to SC2 by SE2 electrode actuation.
    //   Recovery, plating, and incubation identical to GT1.
    //   Mid-sorted IDY1 strains labelled M2, M23 (paper).
    //   Mid-sorted IDY2 strains labelled M9, M22 (paper).
    //   KEY FINDING: Mid-selected strains (IDY1-M23, IDY2-M9)
    //   showed superior fermentation performance vs high-selected
    //   strains, attributed to lower metabolic burden from
    //   balanced glucoamylase expression.
    // --------------------------------------------------------
    midFitnessDroplet = mix spacerOil with spacerOil for 1s
    dispose midFitnessDroplet
} else {
    drain spacerOil
}

// ============================================================
// BB7: midGateJoin
// Dispose GT2 QC signal. Control falls into post-HTS
// maltodextrin growth screening branch (BB8/BB9).
// ============================================================

dispose gt2Signal

// ============================================================
// POST-HTS STEP 1: Maltodextrin growth screening (Step 3
// of paper's 4-step workflow).
// Recovered colonies (both GT1 and GT2 populations, 24
// colonies each) grown for 48 h at 30 C / 300 rpm in
// maltodextrin media (2 g/L yeast extract, 4 g/L bacto
// peptone, 20 g/L maltodextrin). Optical density at 600 nm
// measured at 24 h and 48 h. Growth fold improvement
// calculated relative to wild-type parental strain.
// Maltodextrin growth evaluates starch-utilisation capacity,
// an industrially relevant parameter for beverage fermentation.
//
// NOTE: In the paper, all 24 colonies per gate are screened
// simultaneously in parallel wells. The BioScript abstraction
// below models a single representative colony going through
// sequential evaluation steps (growth -> fermentation).
// ============================================================

// ------------------------------------------------------------
// Inoculate recovered colony into maltodextrin media.
//   5 uL from sorted population plated; overnight glycerol
//   stocks prepared; then 5 uL inoculated into 1 mL
//   maltodextrin media for growth measurement.
// ------------------------------------------------------------

maltodextrinMedia   = dispense 1 units of MaltodextrinMedia
ypd_preculture      = dispense 1 units of YPD_Media
recoveredColony     = mix maltodextrinMedia with ypd_preculture for 5s

// Incubation at 30 C for 48 h (= 2880 min).
// OD600 measured at 24 h and 48 h via plate reader.
heat recoveredColony at 30c for 2880m

// Maltodextrin growth QC signal: OD600 at 48 h vs wild type.
growthSignal = detect maltodextrinGrowthDetection on recoveredColony for 30s

// ============================================================
// BB8 / BB9: Maltodextrin growth QC gate
// Pass (BB8): growthSignal > 0 -> improved growth vs WT;
//   strain carries forward to fermentation assay.
// Fail (BB9): growthSignal <= 0 -> no growth improvement;
//   drain (strain not selected for fermentation).
// Both branches converge at BB10/BB11 (fermentation branch).
// ============================================================

if (growthSignal > 0) {
    // --------------------------------------------------------
    // IMPROVED GROWTH:
    //   Strain exhibits statistically significant growth
    //   improvement in maltodextrin vs wild type.
    //   IDY2 GT1 and GT2 strains showed on average 2.2x and
    //   1.7x more growth respectively (paper Figure 5C).
    //   IDY1-H2 and IDY1-M2 showed ~2.5x and ~1.4x improvement
    //   respectively (paper Figure 5A).
    //   Strain selected for fermentation evaluation (STEP 3->4).
    // --------------------------------------------------------
    dispose recoveredColony
} else {
    drain recoveredColony
}

// ============================================================
// BB10 / BB11: Fermentation evaluation in synthetic beverage
// media (Step 4 of paper's 4-step workflow).
// Selected mutant strains evaluated in lab-scale fermentation
// assay mimicking industrial beverage conditions.
// Media (3 mL synthetic medium per vial):
//   125 g/L maltose, 60 g/L maltodextrin, 1 mL ethanol,
//   1.25 mL 50% glycerol, 3 mL 85% lactic acid,
//   2 g/L yeast extract, 6.4 g/L bactopeptone,
//   pH 5.9, 25 mg/mL chloramphenicol.
// Inoculation: 100 uL preculture into 3 mL synthetic media.
// Temperature: 20 C for 22 h, then 30 C until 72 h endpoint.
// Monitoring: CO2 release by weight loss at 0, 18, 24, 42,
//   48, 66, 72 h. Fermentation complete at 72 h (final mass
//   loss point). Dry biomass weight by pelleting at 60 C.
// Metric: CO2 released per mg biomass; ethanol yield normalised
//   to dry biomass.
//
// KEY RESULT: Mid-level sorted strains (IDY1-M23, IDY2-M9)
//   outperformed high-level sorted strains in fermentation
//   efficiency, producing more CO2 per mg biomass and higher
//   ethanol yields. IDY1-M23 showed the highest CO2 mass loss
//   (~7.8 mg CO2/mg biomass vs ~5.01 for WT at 72 h).
//   IDY2-M9 and IDY2-H13 showed improved CO2 mass loss rates
//   (~0.128 and ~0.105 h^-1 respectively vs WT).
//
// NOTE ON TEMPERATURE SEQUENCE:
//   The fermentation protocol uses a two-phase temperature
//   profile: 20 C for 22 h then 30 C for the remaining 50 h.
//   BioScript `heat` statements are used sequentially to
//   model this ramp; the compiler treats them as serial
//   heating events on the same fluid variable.
//   22 h = 1320 min; 50 h = 3000 min; total = 72 h.
// ============================================================

syntheticMedia      = dispense 1 units of SyntheticBeverageMedia
ypd_ferment_pre     = dispense 1 units of YPD_Media

// Preculture: 48 h at 30 C / 300 rpm in YPD before inoculation.
// 48 h = 2880 min.
heat ypd_ferment_pre at 30c for 2880m

// Inoculate 100 uL preculture into synthetic beverage media.
fermentationMix     = mix syntheticMedia with ypd_ferment_pre for 5m

// Phase 1: 20 C for 22 h (= 1320 min). Initial fermentation phase.
heat fermentationMix at 20c for 1320m

// Phase 2: 30 C for 50 h (= 3000 min). Main fermentation phase.
heat fermentationMix at 30c for 3000m

// Detect fermentation performance: CO2 release, ethanol yield.
// fermentationDetection abstracts CO2 weight-loss measurement
// and end-point ethanol determination from dried biomass.
fermentSignal = detect fermentationDetection on fermentationMix for 30s

// ============================================================
// BB10 / BB11: Fermentation performance QC gate
// Pass (BB10): fermentSignal > 0 -> improved CO2 release
//   and/or ethanol yield vs WT parental strain; strain
//   banked as a superior industrial candidate.
// Fail (BB11): fermentSignal <= 0 -> no fermentation
//   improvement; drain (strain not selected).
// Both branches converge at BB12 (finalCleanup).
// ============================================================

if (fermentSignal > 0) {
    // --------------------------------------------------------
    // FERMENTATION IMPROVEMENT CONFIRMED:
    //   Strain shows statistically significant improvement in
    //   CO2 release and/or ethanol yield relative to WT.
    //   Top producers: IDY1-M23 (mid-gate), IDY2-M9 (mid-gate).
    //   Both would have been missed by a binary (GT1-only)
    //   screening approach, validating the multiplex strategy.
    //   Hypothesised mechanism: balanced glucoamylase expression
    //   in mid-level strains avoids metabolic burden from
    //   high-level enzyme overproduction, maintaining resources
    //   for growth and fermentation.
    //   Strain disposed (banked for industrial use).
    // --------------------------------------------------------
    dispose fermentationMix
} else {
    drain fermentationMix
}

// ============================================================
// BB12: finalCleanup (terminal)
// Dispose all remaining QC signal droplets.
// Dispose growth and fermentation signals.
// Experiment ends.
// ============================================================

dispose growthSignal
dispose fermentSignal

// [terminal -- no further instructions; exit node for CFG]

module mCherryDetection
module geneKnockdownDetection
module geneKnockoutDetection

manifest HEK293T_cells
manifest TargetCells
manifest PluronicF127
manifest pMDLg_pRRE
manifest pRSV_Rev
manifest pMD2g
manifest TransferPlasmid
manifest Lipofectamine3000
manifest P3000_Reagent
manifest OptiMEM
manifest DMEM_Polybrene
manifest TrypsinEDTA
manifest PBS
manifest shRNA_Plasmid
manifest sgRNA_Cas9_Plasmid
manifest ViralSupernatant

instructions:

// ============================================================
// LENGEN: Lentiviral GENeration, packaging, and transduction
// Quach, Little, Shih - Anal. Chem. 2022, 94, 4039-4047
// Protocol: lentiviral production in HEK293T cells, serial
// dilution transduction into breast cancer target cells,
// mCherry fluorescence titer readout.
// Optional branches: shRNA knockdown (ESR1), CRISPR knockout (ESR1)
//
// CFG STRUCTURE:
//   BB1  main         -- entry: producer seeding, mastermix,
//                        transfection, viral harvest, target
//                        seeding, serial dilution, transduction,
//                        mCherry detection
//   BB2  qcPass       -- signal_1_3 > 0: dispose signal droplets
//   BB3  qcFail       -- signal_1_3 <= 0: drain signal droplets
//   BB4  qcJoin       -- join: shRNA branch begins
//   BB5  shrnaPass    -- shrnaSignal > 0: dispose shrnaSignal
//   BB6  shrnaFail    -- shrnaSignal <= 0: drain shrnaSignal
//   BB7  shrnaJoin    -- join: CRISPR branch begins
//   BB8  crisprPass   -- crisprMCherry > 0: dispose crisprMCherry
//   BB9  crisprFail   -- crisprMCherry <= 0: drain crisprMCherry
//   BB10 finalCleanup -- terminal: experiment ends
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Seed HEK293T producer cells onto 1.6 mm hydrophilic
//         production spot. Cell density: ~2.5-3.0 x 10^6
//         cells/mL + 0.05% Pluronics F-127. Incubate 24h.
//         heat is void; producerCells remains valid after heat.
// ------------------------------------------------------------

producerCells      = dispense 1 units of HEK293T_cells
pluronic1          = dispense 1 units of PluronicF127
producerSuspension = mix producerCells with pluronic1 for 2s
heat producerSuspension at 37c for 24h

// ------------------------------------------------------------
// STEP 2: Prepare lipofectamine-DNA mastermix for co-transfection
//         Plasmids: 0.75 ug pMDLg/pRRE, 0.75 ug pRSV-Rev,
//                   1.5 ug pMD2.G, 3 ug transfer plasmid
//         Reagents: 12.5 uL Lipofectamine3000 + 12 uL P3000
//                   in OptiMEM + 0.05% Pluronics F-127
// ------------------------------------------------------------

packaging1   = dispense 1 units of pMDLg_pRRE
packaging2   = dispense 1 units of pRSV_Rev
envelope     = dispense 1 units of pMD2g
transfer     = dispense 1 units of TransferPlasmid
lipo         = dispense 1 units of Lipofectamine3000
p3000        = dispense 1 units of P3000_Reagent
optimem      = dispense 1 units of OptiMEM
pluronic2    = dispense 1 units of PluronicF127

plasmidMix1  = mix packaging1 with packaging2 for 5s
plasmidMix2  = mix plasmidMix1 with envelope for 5s
plasmidMix3  = mix plasmidMix2 with transfer for 5s
lipoReagent  = mix lipo with p3000 for 5s
preMastermix = mix plasmidMix3 with lipoReagent for 5s
mastermix    = mix preMastermix with optimem for 5s

// Add Pluronics F-127 and incubate 20 min at 25c for
// DNA-liposomal complex formation (room temperature)
lipoMix = mix mastermix with pluronic2 for 20m
heat lipoMix at 25c for 20m

// ------------------------------------------------------------
// STEP 3: Transfect HEK293T cells - mix lipoMix into
//         producerSuspension; 3 circulations x 1 min on
//         four-prong electrode array (paper: ~1 min mixing)
// ------------------------------------------------------------

transfectionMix = mix lipoMix with producerSuspension for 1m

// ------------------------------------------------------------
// STEP 4: Incubate 24h for lentiviral particle production.
//         Viral supernatant dispensed fresh to model the
//         cell-free harvest step (cells adhere to hydrophilic
//         spot; supernatant collected by electrode actuation).
// ------------------------------------------------------------

heat transfectionMix at 37c for 24h
viralSupernatant = dispense 1 units of ViralSupernatant

// ------------------------------------------------------------
// STEP 5: Seed four independent target cell droplets onto
//         four 1.2 mm transduction sites (one per dilution).
//         Paper uses six sites; four used for dilution series.
//         Each is a separate dispense to satisfy use-once rules.
// ------------------------------------------------------------

targetCellDrop1   = dispense 1 units of TargetCells
pluronic3a        = dispense 1 units of PluronicF127
targetSuspension1 = mix targetCellDrop1 with pluronic3a for 2s
heat targetSuspension1 at 37c for 24h

targetCellDrop2   = dispense 1 units of TargetCells
pluronic3b        = dispense 1 units of PluronicF127
targetSuspension2 = mix targetCellDrop2 with pluronic3b for 2s
heat targetSuspension2 at 37c for 24h

targetCellDrop3   = dispense 1 units of TargetCells
pluronic3c        = dispense 1 units of PluronicF127
targetSuspension3 = mix targetCellDrop3 with pluronic3c for 2s
heat targetSuspension3 at 37c for 24h

targetCellDrop4   = dispense 1 units of TargetCells
pluronic3d        = dispense 1 units of PluronicF127
targetSuspension4 = mix targetCellDrop4 with pluronic3d for 2s
heat targetSuspension4 at 37c for 24h

// ------------------------------------------------------------
// STEP 6: Serial dilutions of viral supernatant (~98% accuracy)
//         Diluent: DMEM + 8 ug/mL polybrene + 0.05% Pluronics
//         1:3  = 1 uL DMEM + 2 uL viral supernatant
//         1:6  = serial dilution of 1:3 product
//         1:12 = serial dilution of 1:6 product
//         1:24 = serial dilution of 1:12 product
// ------------------------------------------------------------

dmem1        = dispense 1 units of DMEM_Polybrene
dilution_1_3 = mix dmem1 with viralSupernatant for 5s

dmem2        = dispense 1 units of DMEM_Polybrene
dilution_1_6 = mix dmem2 with dilution_1_3 for 5s

dmem3         = dispense 1 units of DMEM_Polybrene
dilution_1_12 = mix dmem3 with dilution_1_6 for 5s

dmem4         = dispense 1 units of DMEM_Polybrene
dilution_1_24 = mix dmem4 with dilution_1_12 for 5s

// ------------------------------------------------------------
// STEP 7: Deliver each dilution to its own target cell site
//         via highway track. Device flipped; incubate 24h.
//         Incubation encoded in mix duration (ref. syntax).
// ------------------------------------------------------------

transduction_1_3  = mix dilution_1_3  with targetSuspension1 for 24h
transduction_1_6  = mix dilution_1_6  with targetSuspension2 for 24h
transduction_1_12 = mix dilution_1_12 with targetSuspension3 for 24h
transduction_1_24 = mix dilution_1_24 with targetSuspension4 for 24h

// ------------------------------------------------------------
// STEP 8: Detect mCherry fluorescence to calculate viral titer
//         TU/mL = (#transduced x %fluorescent x dilution) / vol
//         Expected: ~1 x 10^7 TU/mL at 1:3 dilution after 48h
// ------------------------------------------------------------

signal_1_3  = detect mCherryDetection on transduction_1_3  for 30s
signal_1_6  = detect mCherryDetection on transduction_1_6  for 30s
signal_1_12 = detect mCherryDetection on transduction_1_12 for 30s
signal_1_24 = detect mCherryDetection on transduction_1_24 for 30s

// ============================================================
// BB2 / BB3: mCherry QC gate on 1:3 dilution (highest titer)
// Pass (BB2): signal > 0 -> data accepted, dispose droplets
// Fail (BB3): signal <= 0 -> no viable titer, drain droplets
// Both branches converge at BB4 (qcJoin)
// ============================================================

if (signal_1_3 > 0) {
    dispose transduction_1_3
    dispose transduction_1_6
    dispose transduction_1_12
    dispose transduction_1_24
} else {
    drain transduction_1_3
    drain transduction_1_6
    drain transduction_1_12
    drain transduction_1_24
}

// ============================================================
// BB4: qcJoin
// Dispose all main-branch signal droplets regardless of QC.
// Control falls into shRNA branch (BB5/BB6).
// ============================================================

dispose signal_1_3
dispose signal_1_6
dispose signal_1_12
dispose signal_1_24

// ============================================================
// STEP 9 (shRNA knockdown): Replace transfer plasmid with
//         MISSION shRNA plasmid (TRCN00000003300) targeting ESR1
//         Fresh producer cells and target cells for this branch.
//         Cells retrieved by trypsinization -> 7-day outgrowth
//         -> qRT-PCR (DDCq method, ACTB reference gene)
// ============================================================

shrnaTransfer  = dispense 1 units of shRNA_Plasmid
shrnaPkg1      = dispense 1 units of pMDLg_pRRE
shrnaPkg2      = dispense 1 units of pRSV_Rev
shrnaEnv       = dispense 1 units of pMD2g
shrnaLipo      = dispense 1 units of Lipofectamine3000
shrnaP3000     = dispense 1 units of P3000_Reagent
shrnaOptiMEM   = dispense 1 units of OptiMEM
shrnaPluronic  = dispense 1 units of PluronicF127

shrnaPlasmids1 = mix shrnaPkg1 with shrnaPkg2 for 5s
shrnaPlasmids2 = mix shrnaPlasmids1 with shrnaEnv for 5s
shrnaPlasmids3 = mix shrnaPlasmids2 with shrnaTransfer for 5s
shrnaLipoMix1  = mix shrnaLipo with shrnaP3000 for 5s
shrnaPreMix    = mix shrnaPlasmids3 with shrnaLipoMix1 for 5s
shrnaMastermix = mix shrnaPreMix with shrnaOptiMEM for 5s
shrnaLipoMix2  = mix shrnaMastermix with shrnaPluronic for 20m
heat shrnaLipoMix2 at 25c for 20m

shrnaProducerCells = dispense 1 units of HEK293T_cells
shrnaPluronicProd  = dispense 1 units of PluronicF127
shrnaProducerSusp  = mix shrnaProducerCells with shrnaPluronicProd for 2s
heat shrnaProducerSusp at 37c for 24h

shrnaTxMix = mix shrnaLipoMix2 with shrnaProducerSusp for 1m
heat shrnaTxMix at 37c for 24h

shrnaViral       = dispense 1 units of ViralSupernatant
shrnaTargetCells = dispense 1 units of TargetCells
shrnaPluronic2   = dispense 1 units of PluronicF127
shrnaTargetSusp  = mix shrnaTargetCells with shrnaPluronic2 for 2s
heat shrnaTargetSusp at 37c for 24h

shrnaDMEM1        = dispense 1 units of DMEM_Polybrene
shrnaDilution     = mix shrnaDMEM1 with shrnaViral for 5s
shrnaTransduction = mix shrnaDilution with shrnaTargetSusp for 24h

shrnaTrypsin = dispense 1 units of TrypsinEDTA
shrnaPBS     = dispense 1 units of PBS
shrnaWash    = mix shrnaPBS with shrnaTransduction for 5s
shrnaCells   = mix shrnaTrypsin with shrnaWash for 2m

shrnaSignal = detect geneKnockdownDetection on shrnaCells for 30s

// ============================================================
// BB5 / BB6: shRNA QC gate
// Pass (BB5): shrnaSignal > 0 -> knockdown confirmed, dispose
// Fail (BB6): shrnaSignal <= 0 -> assay failed, drain
// Both branches converge at BB7 (shrnaJoin)
// ============================================================

if (shrnaSignal > 0) {
    dispose shrnaCells
} else {
    drain shrnaCells
}

// ============================================================
// BB7: shrnaJoin
// Dispose shrnaSignal; control falls into CRISPR branch.
// ============================================================

dispose shrnaSignal

// ============================================================
// STEP 10 (CRISPR-Cas9 knockout): Replace transfer plasmid
//          with pLentiCRISPR-mCherry-NeoRv2 (LCMNv2), all-in-one
//          Cas9 + sgRNA targeting ESR1. Knockout confirmed by
//          genomic cleavage assay at 7 days post transduction.
//          Fresh producer cells and target cells for this branch.
// ============================================================

crisprTransfer  = dispense 1 units of sgRNA_Cas9_Plasmid
crisprPkg1      = dispense 1 units of pMDLg_pRRE
crisprPkg2      = dispense 1 units of pRSV_Rev
crisprEnv       = dispense 1 units of pMD2g
crisprLipo      = dispense 1 units of Lipofectamine3000
crisprP3000     = dispense 1 units of P3000_Reagent
crisprOptiMEM   = dispense 1 units of OptiMEM
crisprPluronic  = dispense 1 units of PluronicF127

crisprPlasmids1 = mix crisprPkg1 with crisprPkg2 for 5s
crisprPlasmids2 = mix crisprPlasmids1 with crisprEnv for 5s
crisprPlasmids3 = mix crisprPlasmids2 with crisprTransfer for 5s
crisprLipoMix1  = mix crisprLipo with crisprP3000 for 5s
crisprPreMix    = mix crisprPlasmids3 with crisprLipoMix1 for 5s
crisprMastermix = mix crisprPreMix with crisprOptiMEM for 5s
crisprLipoMix2  = mix crisprMastermix with crisprPluronic for 20m
heat crisprLipoMix2 at 25c for 20m

crisprProducerCells = dispense 1 units of HEK293T_cells
crisprPluronicProd  = dispense 1 units of PluronicF127
crisprProducerSusp  = mix crisprProducerCells with crisprPluronicProd for 2s
heat crisprProducerSusp at 37c for 24h

crisprTxMix = mix crisprLipoMix2 with crisprProducerSusp for 1m
heat crisprTxMix at 37c for 24h

crisprViral        = dispense 1 units of ViralSupernatant
crisprTargetCells  = dispense 1 units of TargetCells
crisprPluronic2    = dispense 1 units of PluronicF127
crisprTargetSusp   = mix crisprTargetCells with crisprPluronic2 for 2s
heat crisprTargetSusp at 37c for 24h

crisprDMEM1        = dispense 1 units of DMEM_Polybrene
crisprDilution     = mix crisprDMEM1 with crisprViral for 5s
crisprTransduction = mix crisprDilution with crisprTargetSusp for 24h

crisprTrypsin = dispense 1 units of TrypsinEDTA
crisprPBS     = dispense 1 units of PBS
crisprWash    = mix crisprPBS with crisprTransduction for 5s
crisprCells   = mix crisprTrypsin with crisprWash for 2m

crisprMCherry = detect mCherryDetection on crisprCells for 30s

// ============================================================
// BB8 / BB9: CRISPR QC gate
// Pass (BB8): crisprMCherry > 0 -> transduction confirmed, dispose
// Fail (BB9): crisprMCherry <= 0 -> transduction failed, drain
// Both branches converge at BB10 (finalCleanup)
// ============================================================

if (crisprMCherry > 0) {
    dispose crisprCells
} else {
    drain crisprCells
}

// ============================================================
// BB10: finalCleanup  (terminal -- no successors)
// Dispose final signal droplet; experiment ends.
// ============================================================

dispose crisprMCherry

// [terminal -- no instructions; exit node for CFG]

module fluorescence

// Reagents used in the DMF-LAMP c-Myc amplification protocol
// (Coelho et al., Sensors 2017, 17, 2616)
manifest LAMPMix
manifest DNASample

instructions:

// --- Reagent dispensing and transport ---
// 10 droplets of LAMP reagents (~0.14 uL/droplet -> ~1.40 uL total)
// dispensed from the left reservoir
reagent = dispense 10 units of LAMPMix

// 1 droplet of target DNA sample (~0.14 uL) dispensed from the
// right reservoir, giving a final 0.5 ng/uL DNA concentration
sample = dispense 1 units of DNASample

// --- Merging and mixing in the central reaction reservoir ---
// Total on-chip reaction volume: 1.54 uL
LAMP_Reaction = mix reagent with sample

// --- Isothermal amplification at the bottom-plate set point (65C) ---
// LAMP is isothermal, so there is no thermal cycling as in PCR;
// amplification efficiency was evaluated in 15 min increments
// (15 min, 30 min, 45 min) per Figure 3e

heat LAMP_Reaction at 65c for 15m
Amp_Check_15 = detect fluorescence on LAMP_Reaction for 30s

if (Amp_Check_15 <= 80) {

    heat LAMP_Reaction at 65c for 15m
    Amp_Check_30 = detect fluorescence on LAMP_Reaction for 30s

    if (Amp_Check_30 <= 80) {

        heat LAMP_Reaction at 65c for 15m
        Amp_Check_45 = detect fluorescence on LAMP_Reaction for 30s

        if (Amp_Check_45 <= 80) {
            dispose LAMP_Reaction
        }
    }
}

// --- Reaction product transport for withdrawal ---
// Successful amplification (positive signal at/after 45 min total)
// is routed to the retrieving reservoir; product is withdrawn
// from the device via pipette
dispose LAMP_Reaction

