rfcs10_d3   = dispense 1 units of FCS_Stock
rdil10_d3   = dispense 1 units of CompleteMedia_DMEM
rfcs10_drop_d3 = mix rfcs10_d3 with rdil10_d3 for 5s

rfcs5_a_d3  = dispense 1 units of FCS_Stock
rfcs5_b_d3  = dispense 1 units of CompleteMedia_DMEM
rfcs10_5_d3 = mix rfcs5_a_d3 with rfcs5_b_d3 for 5s
rfcs5_c_d3  = dispense 1 units of CompleteMedia_DMEM
rfcs5_drop_d3  = mix rfcs10_5_d3 with rfcs5_c_d3 for 5s

rfcs25_a_d3 = dispense 1 units of FCS_Stock
rfcs25_b_d3 = dispense 1 units of CompleteMedia_DMEM
rfcs25_10_d3 = mix rfcs25_a_d3 with rfcs25_b_d3 for 5s
rfcs25_c_d3 = dispense 1 units of CompleteMedia_DMEM
rfcs25_5_d3 = mix rfcs25_10_d3 with rfcs25_c_d3 for 5s
rfcs25_d_d3 = dispense 1 units of CompleteMedia_DMEM
rfcs25_drop_d3 = mix rfcs25_5_d3 with rfcs25_d_d3 for 5s

rfcs125_a_d3 = dispense 1 units of FCS_Stock
rfcs125_b_d3 = dispense 1 units of CompleteMedia_DMEM
r10_125_d3   = mix rfcs125_a_d3 with rfcs125_b_d3 for 5s
rfcs125_c_d3 = dispense 1 units of CompleteMedia_DMEM
r5_125_d3    = mix r10_125_d3 with rfcs125_c_d3 for 5s
rfcs125_d_d3 = dispense 1 units of CompleteMedia_DMEM
r25_125_d3   = mix r5_125_d3 with rfcs125_d_d3 for 5s
rfcs125_e_d3 = dispense 1 units of CompleteMedia_DMEM
rfcs125_drop_d3 = mix r25_125_d3 with rfcs125_e_d3 for 5s

rfcs0625_a_d3 = dispense 1 units of FCS_Stock
rfcs0625_b_d3 = dispense 1 units of CompleteMedia_DMEM
r10_0625_d3   = mix rfcs0625_a_d3 with rfcs0625_b_d3 for 5s
rfcs0625_c_d3 = dispense 1 units of CompleteMedia_DMEM
r5_0625_d3    = mix r10_0625_d3 with rfcs0625_c_d3 for 5s
rfcs0625_d_d3 = dispense 1 units of CompleteMedia_DMEM
r25_0625_d3   = mix r5_0625_d3 with rfcs0625_d_d3 for 5s
rfcs0625_e_d3 = dispense 1 units of CompleteMedia_DMEM
r125_0625_d3  = mix r25_0625_d3 with rfcs0625_e_d3 for 5s
rfcs0625_f_d3 = dispense 1 units of CompleteMedia_DMEM
rfcs0625_drop_d3 = mix r125_0625_d3 with rfcs0625_f_d3 for 5s

well10_d3   = mix well10_suc_d3 with rfcs10_drop_d3 for 10s
well5_d3    = mix well5_suc_d3 with rfcs5_drop_d3 for 10s
well25_d3   = mix well25_suc_d3 with rfcs25_drop_d3 for 10s
well125_d3  = mix well125_suc_d3 with rfcs125_drop_d3 for 10s
well0625_d3 = mix well0625_suc_d3 with rfcs0625_drop_d3 for 10s

heat well10_d3 at 37c for 1440m
heat well5_d3 at 37c for 1440m
heat well25_d3 at 37c for 1440m
heat well125_d3 at 37c for 1440m
heat well0625_d3 at 37c for 1440m

// ------------------------------------------------------------
// ASSAY 3 -- DAY 4 MEASUREMENT (96h): Final sucrose exchange
//   and Vsense. No further media refresh.
//   QC gate: 10% FCS Vsense (highest expected signal; paper
//   Fig. 6a shows 10% FCS reaching ~200 cells/mm2 at Day 4).
// ------------------------------------------------------------

suc_10_d4    = dispense 1 units of SucroseBuffer
well10_suc_d4  = mix well10_d3 with suc_10_d4 for 10s
vsense_10_d4   = detect impedanceSensing on well10_suc_d4 for 1s

suc_5_d4     = dispense 1 units of SucroseBuffer
well5_suc_d4   = mix well5_d3 with suc_5_d4 for 10s
vsense_5_d4    = detect impedanceSensing on well5_suc_d4 for 1s

suc_25_d4    = dispense 1 units of SucroseBuffer
well25_suc_d4  = mix well25_d3 with suc_25_d4 for 10s
vsense_25_d4   = detect impedanceSensing on well25_suc_d4 for 1s

suc_125_d4   = dispense 1 units of SucroseBuffer
well125_suc_d4 = mix well125_d3 with suc_125_d4 for 10s
vsense_125_d4  = detect impedanceSensing on well125_suc_d4 for 1s

suc_0625_d4  = dispense 1 units of SucroseBuffer
well0625_suc_d4 = mix well0625_d3 with suc_0625_d4 for 10s
vsense_0625_d4  = detect impedanceSensing on well0625_suc_d4 for 1s

// ============================================================
// BB8 / BB9: Serum screening QC gate
// Pass (BB8): vsense_10_d4 > 0 -> sigmoidal growth curve
//             confirmed in 10% FCS condition; dispose all.
// Fail (BB9): vsense_10_d4 <= 0 -> no growth signal
//             (possible: cell detachment, serum reagent
//             failure, sucrose exchange error); drain all.
// Both branches converge at BB10 (finalCleanup).
// ============================================================

if (vsense_10_d4 > 0) {
    dispose well10_suc_d4
    dispose well5_suc_d4
    dispose well25_suc_d4
    dispose well125_suc_d4
    dispose well0625_suc_d4
} else {
    drain well10_suc_d4
    drain well5_suc_d4
    drain well25_suc_d4
    drain well125_suc_d4
    drain well0625_suc_d4
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose all serum screening Vsense signals.
// Experiment ends.
// ============================================================

dispose vsense_10_d1
dispose vsense_5_d1
dispose vsense_25_d1
dispose vsense_125_d1
dispose vsense_0625_d1

dispose vsense_10_d2
dispose vsense_5_d2
dispose vsense_25_d2
dispose vsense_125_d2
dispose vsense_0625_d2

dispose vsense_10_d3
dispose vsense_5_d3
dispose vsense_25_d3
dispose vsense_125_d3
dispose vsense_0625_d3

// vsense_10_d4 consumed by QC gate if-condition above; do not re-dispose
dispose vsense_5_d4
dispose vsense_25_d4
dispose vsense_125_d4
dispose vsense_0625_d4

// [terminal -- no further instructions; exit node for CFG]

module assemblyQC
module transformationQC

manifest VectorBackbone
manifest Promoter1
manifest BCD1_gfp
manifest T4_DNA_Ligase
manifest HFE7500_PluronicF127
manifest AssembledPlasmid
manifest ElectroporationMedia
manifest LB_Recovery
manifest CompetentEcoli

// ============================================================
// A Versatile Microfluidic Device for Automating Synthetic Biology
// Shih, Goyal, Kim, Koutsoubelis, Keasling, Adams, Hillson, Singh
// ACS Synthetic Biology 2015, 4, 1151-1164
// DOI: 10.1021/acssynbio.5b00062
//
// Platform: Hybrid digital-to-droplet microfluidic device
// (75 x 25 mm; 76 DMF electrodes + PDMS serpentine channel).
// Three functional regions: DNA assembly (DMF), queuing and
// incubation (serpentine channel), transformation (electroporation
// region with microelectrodes).
//
// ASSEMBLY METHOD ENCODED: Golden Gate (primary, Fig 6 in paper).
// Golden Gate is the representative method because it is the only
// one with a full 16-plasmid sequencing panel shown in the main
// text. Gibson (50 C, 15 min) and Yeast/TAR (room temp, 10 min,
// no ligase) follow the same droplet operations with different
// incubation parameters; separate .bs files should encode those.
//
// REAGENT VOLUMES:
//   Reservoir droplets: 1.5 uL (dispensed onto reservoirs).
//   Dispensed subdroplets: ~0.2 uL per mix step on DMF.
//   Total DNA assembly volume: ~0.8 uL (Golden Gate / Gibson)
//                               ~0.6 uL (Yeast).
//   T4 DNA ligase: 2.5 U/uL with 0.05% w/v Pluronic F-127.
//   All DNA fragments: 30-40 ng/uL, gel-purified after DpnI
//   and BsaI digest.
//
// CROSS-CONTAMINATION STRATEGY: HFE 7500 biocompatible oil
// filler + 0.05% w/v Pluronic F-127 surfactant additive
// (instead of wash steps) prevents biofouling. This is the
// first application of this strategy to on-chip DNA assembly.
// Modelled here by dispensing HFE7500_PluronicF127 as the
// continuous oil phase that surrounds all DMF droplets.
//
// GOLDEN GATE INCUBATION:
//   Temperature: 25 C (room temperature).
//   Duration: 10 min.
//   BsaI-HF cuts at Type IIS sites; T4 ligase joins overhangs.
//   Paper Table 1: total volume 0.8 uL, 2 DNA fragment insertions.
//
// ELECTROPORATION:
//   Target: E. coli DH5alpha electrocompetent cells.
//   Media: 8 mM Na2HPO4, 2 mM KH2PO4, 250 mM sucrose pH 7.4.
//   Pulses: 3 x 100 ms DC pulses at 1800 V/cm.
//   Maximum efficiency: 4.58e3 CFU/ng assembled DNA (Fig 5a).
//   Recovery: 200 uL LB broth, 1 h at 37 C before plating.
//   Two bare gold microelectrodes (2.0 x 0.3 mm), 100 um gap.
//   Oil phase (HFE 7500) prevents electrical short when no
//   droplet is present; impedance feedback triggers pulses.
//   Electroporation is modelled as a heat step at 37 C (the
//   post-pulse recovery temperature; the pulse itself is
//   instantaneous and has no BioScript duration token).
//
// INCUBATION CHANNEL:
//   Serpentine PDMS channel, 1.5 mm wide, stores 16 droplets
//   for > 2 h without volume loss. Peltier heater enables
//   region-specific temperature control (heating only the
//   incubation zone, leaving reservoirs at room temperature
//   to preserve T4 ligase activity). Modelled via heat.
//
// ONE-REACTION ABSTRACTION:
//   This .bs file encodes one representative Golden Gate
//   assembly reaction (pProm1_BCD1-gfp, the canonical test
//   plasmid, ~3070 bp). The actual chip runs 16 combinatorial
//   reactions (4 Promoter variants x 4 BCD variants) in
//   sequence using the same electrode path and incubation
//   channel. Encoding all 16 in BioScript would require 16
//   independent reagent manifests for each promoter/BCD
//   variant; a single canonical reaction captures the full
//   protocol logic without misrepresenting the paper.
//
// CFG STRUCTURE:
//   BB1  main             -- device init; reagent dispensing;
//                           DNA fragment mixing; T4 ligase
//                           addition; digital-to-droplet
//                           transfer; incubation; detect
//   BB2  assemblyPass     -- assemblyQC > 0: assembly succeeded;
//                           dispose assembled plasmid droplet
//   BB3  assemblyFail     -- assemblyQC <= 0: assembly failed;
//                           drain assembled plasmid droplet
//   BB4  assemblyJoin     -- join: transformation branch begins
//   BB5  transformPass    -- transformSignal > 0: colonies
//                           detected; dispose recovery droplet
//   BB6  transformFail    -- transformSignal <= 0: no colonies;
//                           drain recovery droplet
//   BB7  finalCleanup     -- terminal: dispose QC signal droplets
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prime oil phase.
//   HFE 7500 + 2% Pluronic F-127 surfactant is pipetted
//   onto the DMF surface (1 mL). The oil phase surrounds
//   all aqueous droplets, preventing cross-contamination
//   and biofouling without additional wash steps.
//   Modelled as a single dispense representing the bulk
//   oil-phase load. This oil droplet is referenced during
//   later digital-to-droplet transfer steps.
// ------------------------------------------------------------

oilPhase = dispense 1 units of HFE7500_PluronicF127

// ------------------------------------------------------------
// STEP 2: Dispense vector backbone droplet (~0.2 uL).
//   Reservoir: 1.5 uL of pFAB4876-based vector backbone
//   at 30-40 ng/uL. Vector concentrations matched to
//   BCD/Promoter insert concentrations by vacuum concentrator
//   (65 C, 5-10 min) prior to chip loading.
//   BsaI and DpnI digested, gel-purified.
//   Golden Gate vector backbone: ~2100 bp band (Fig 3a).
// ------------------------------------------------------------

vectorDrop = dispense 1 units of VectorBackbone

// ------------------------------------------------------------
// STEP 3: Dispense Promoter1 insert droplet (~0.2 uL).
//   Source plasmid: pFAB4876 (Promoter1, ~100 bp band).
//   DpnI + BsaI digested; gel-purified; 30-40 ng/uL.
//   Four promoter variants used across 16 reactions:
//   Prom1, Prom2, Prom9, Prom11.
//   This .bs file encodes the Prom1 variant.
// ------------------------------------------------------------

promoterDrop = dispense 1 units of Promoter1

// ------------------------------------------------------------
// STEP 4: Dispense BCD1-gfp insert droplet (~0.2 uL).
//   Source plasmid: pFAB4876 (BCD1_gfp variant, ~800 bp).
//   DpnI + BsaI digested; gel-purified; 30-40 ng/uL.
//   Four BCD variants: BCD1, BCD2, BCD20, BCD21.
//   This .bs file encodes the BCD1 variant.
//   The gfp gene enables colony color screening (green =
//   correct insert, white = self-ligation artifact).
// ------------------------------------------------------------

bcdDrop = dispense 1 units of BCD1_gfp

// ------------------------------------------------------------
// STEP 5: Dispense T4 DNA ligase droplet (~0.2 uL).
//   T4 DNA ligase at 2.5 U/uL with 0.05% w/v Pluronic F-127.
//   Pluronic additive prevents biofouling without inhibiting
//   ligation activity (Au et al., Langmuir 2011).
//   IMPORTANT: T4 ligase reservoir stays at room temperature
//   while incubation zone is heated (region-specific Peltier).
//   This prevents heat inactivation (T4 denatured above 50 C)
//   before the ligase droplet is dispensed.
//   For Gibson assembly, this step uses 2x Gibson master mix
//   instead; for Yeast assembly, no ligase droplet is needed.
// ------------------------------------------------------------

ligaseDrop = dispense 1 units of T4_DNA_Ligase

// ------------------------------------------------------------
// STEP 6: Merge DNA fragments.
//   Vector backbone + Promoter1 insert mixed on-chip at
//   160 V_rms, 15 kHz via electrode actuation. Droplet
//   circulates 2-3 times over mixing electrodes (1.75 x 1.75 mm
//   digital-to-channel electrodes near D2D interface).
// ------------------------------------------------------------

dnaMix = mix vectorDrop with promoterDrop for 5s

// ------------------------------------------------------------
// STEP 7: Add BCD1-gfp insert to DNA mix.
//   Three-component droplet now contains all DNA parts for
//   one Golden Gate reaction. Total merged volume: ~0.6 uL.
// ------------------------------------------------------------

threePartMix = mix dnaMix with bcdDrop for 5s

// ------------------------------------------------------------
// STEP 8: Add T4 DNA ligase to complete the Golden Gate mix.
//   Final droplet: ~0.8 uL containing vector, Promoter1,
//   BCD1-gfp, and T4 DNA ligase (2.5 U/uL).
//   Mixed 2-3 times in circular fashion on mixing electrodes.
//   This merged droplet is ready for digital-to-droplet
//   transfer into the incubation channel.
// ------------------------------------------------------------

assemblyMix = mix threePartMix with ligaseDrop for 10s

// ------------------------------------------------------------
// STEP 9: Digital-to-droplet transfer and incubation.
//   The syringe-vacuum pump (0.1 uL/s) draws the assembled
//   droplet from the DMF surface into the 1.5 mm wide
//   serpentine PDMS channel. Oil phase (HFE 7500) at 5 uL/s
//   drives the droplet into the incubation zone.
//   Golden Gate incubation: 10 min at 25 C (room temperature).
//   BsaI-HF digest creates overhangs; T4 ligase joins them.
//   Paper Table 1: 10 min incubation, room temperature.
//   The heat step at 25 C models the Peltier-controlled
//   region-specific temperature maintenance during incubation.
//   (For Gibson: 50 C, 15 min. For Yeast: 25 C, 10 min.)
// ------------------------------------------------------------

heat assemblyMix at 25c for 10m

// ------------------------------------------------------------
// STEP 10: Assembly QC detection.
//   assemblyQC module abstracts an on-chip or off-chip
//   verification step. In the paper, plasmid assembly is
//   confirmed by colony color (green GFP fluorescence)
//   after electroporation and plating. On-chip, no direct
//   assembly verification is performed before electroporation;
//   the detect step here models the GFP/colony screening QC
//   as a logical gate to decide whether to proceed to
//   transformation.
// ------------------------------------------------------------

assemblySignal = detect assemblyQC on assemblyMix for 30s

// ============================================================
// BB2 / BB3: Assembly QC gate
// Pass (BB2): assemblySignal > 0 -> Golden Gate ligation
//             succeeded (expected ~95% correct clones post-seq);
//             dispose assembled droplet and proceed.
// Fail (BB3): assemblySignal <= 0 -> ligation failed (e.g.
//             self-ligation white colony dominant); drain.
// Both branches converge at BB4 (assemblyJoin).
// ============================================================

if (assemblySignal > 0) {
    dispose assemblyMix
} else {
    drain assemblyMix
}

// ============================================================
// BB4: assemblyJoin
// Dispose assembly QC signal. Control falls into the
// electroporation / transformation branch (BB5/BB6).
// ============================================================

dispose assemblySignal

// ------------------------------------------------------------
// STEP 11: Dispense E. coli cells for electroporation.
//   DH5alpha electrocompetent cells dispensed from the cell
//   inlet into the electroporation region.
//   Electroporation media: 8 mM Na2HPO4, 2 mM KH2PO4,
//   250 mM sucrose, pH 7.4 (prevents osmotic lysis).
//   Cell droplet dispensed by applying potential to 4
//   microelectrodes (three 1.4 x 0.7 mm + one 4.0 x 0.7 mm)
//   near the cell-inlet/main-channel intersection.
//   Elastomeric microvalve (valve 5, Fig S2) prevents
//   cross-contamination between successive plasmid droplets.
// ------------------------------------------------------------

cellDroplet = dispense 1 units of CompetentEcoli

// ------------------------------------------------------------
// STEP 12: Dispense incubated plasmid exiting the channel.
//   After 10 min Golden Gate incubation in the serpentine
//   channel, the assembled pProm1_BCD1-gfp droplet is driven
//   by oil phase (HFE 7500, 5 uL/s) into the electroporation
//   region. In BioScript ownership terms, the incubated
//   assembly product is a new fluid object at this stage:
//   assemblyMix was consumed by detect (assemblyQC) in BB1;
//   incubatedPlasmid models the same physical droplet as it
//   exits the incubation channel and enters the electroporation
//   zone. This avoids the assemblyMix2 phantom SSA index
//   emitted by the compiler when a variable is re-used after
//   detect has already consumed it.
//   Oil phase replaces cell-inlet flow; all channel valves
//   closed (see Fig S2 for valve sequence).
// ------------------------------------------------------------

incubatedPlasmid = dispense 1 units of AssembledPlasmid

// ------------------------------------------------------------
// STEP 13a: Mix cells with electroporation media.
//   Cell droplet resuspended in electroporation media on-chip
//   before merging with the plasmid droplet.
// ------------------------------------------------------------

electroporationMedia = dispense 1 units of ElectroporationMedia
cellMix = mix cellDroplet with electroporationMedia for 5s

// ------------------------------------------------------------
// STEP 13b: Merge incubated plasmid with cell mix.
//   The incubated plasmid droplet and the cell+media droplet
//   merge in the electroporation region immediately upstream
//   of the two bare gold microelectrodes (2.0 x 0.3 mm,
//   100 um gap). Total merged volume: ~2 uL.
// ------------------------------------------------------------

preMix = mix incubatedPlasmid with cellMix for 5s

// ------------------------------------------------------------
// STEP 14: Electroporation.
//   3 x 100 ms DC square pulses at 1800 V/cm applied to the
//   merged droplet via two bare gold microelectrodes
//   (2.0 x 0.3 mm, 100 um gap, no dielectric coating).
//   Impedance-sensing feedback (Vsense threshold ~0.15 V)
//   detects droplet on electrodes and triggers pulse delivery.
//   Continuous oil phase prevents electrical short when
//   no droplet bridges the electrode gap.
//   Maximum efficiency: 4.58e3 CFU/ng (110 +/- 8 colonies,
//   N=3, comparable to cuvette: 4.46e3 CFU/ng, Fig 5a).
//   Modelled as heat at 37 C (post-pulse recovery temperature;
//   the pulse itself is instantaneous).
// ------------------------------------------------------------

heat preMix at 37c for 1m

// ------------------------------------------------------------
// STEP 14: Recovery.
//   Electroporated droplet driven to outlet by oil phase
//   (HFE 7500, all valves closed). Collected in tube
//   containing 200 uL LB broth. Incubated 1 h at 37 C
//   (standard outgrowth for kanamycin-selected DH5alpha).
//   50 ug/mL kanamycin selection plates used for plating.
//   ~100 of ~110 colonies show green color (GFP+, correct
//   insert); ~10 white (self-ligation artifacts).
// ------------------------------------------------------------

recoveryMedia = dispense 1 units of LB_Recovery
recoveredCells = mix preMix with recoveryMedia for 5s

heat recoveredCells at 37c for 60m

// ------------------------------------------------------------
// STEP 15: Transformation QC detection.
//   transformationQC module abstracts off-chip colony count
//   on kanamycin LB-agar plates (37 C, overnight incubation).
//   Colony-PCR and Sanger sequencing (QB3284_fwd / QB3810_rev)
//   confirm correct assembly in 95% of green colonies (Fig 6,
//   76/80 correct for Golden Gate; 80/80 for Gibson).
//   On-chip proxy: impedance-sensing detects viable cell
//   density in the electroporated droplet as a QC signal.
// ------------------------------------------------------------

transformSignal = detect transformationQC on recoveredCells for 30s

// ============================================================
// BB5 / BB6: Transformation QC gate
// Pass (BB5): transformSignal > 0 -> transformed colonies
//             detected; dispose recovery droplet.
// Fail (BB6): transformSignal <= 0 -> no viable transformed
//             cells (electroporation failure or no assembly);
//             drain recovery droplet.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (transformSignal > 0) {
    dispose recoveredCells
} else {
    drain recoveredCells
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose transformation QC signal and oil phase droplet.
// Experiment ends. In the actual protocol, this step is
// repeated 15 more times (16 total reactions) using the
// same electrode path, mixing channel, and incubation
// channel to generate all 4 Prom x 4 BCD combinatorial
// plasmid variants. Each successive iteration uses fresh
// reservoir droplets refilled via the SU-8 capillary.
// ============================================================

dispose transformSignal
dispose oilPhase

// [terminal -- no further instructions; exit node for CFG]

module electroporationAssay
module cytokineDetection

manifest tCells
manifest electroporationBuffer
manifest mrnaPayload
manifest recoveryBuffer
manifest il2Media
manifest rajiCells
manifest mcf7Cells

// mcf7Cells: CD19-negative specificity control arm (paper Fig. 4a,b)

instructions:

// ============================================================
// STEP 1: Prepare cell droplet in electroporation buffer
// Cell count: 0.5 x 10^5 per reaction (triDrop optimum)
// ============================================================

cellDrop      = dispense 1 units of tCells
epBuffer1     = dispense 1 units of electroporationBuffer
cellsInBuffer = mix cellDrop with epBuffer1 for 2s

// ============================================================
// STEP 2: Prepare mRNA payload droplet (50 ng per reaction)
// ============================================================

payloadDrop = dispense 1 units of mrnaPayload

// ============================================================
// STEP 3: triDrop three-droplet fusion
// Flanking buffer droplet limits electrolytic byproduct
// exposure at electrodes (paper Fig. S8, Little et al. 2023)
// ============================================================

bufferFlank    = dispense 1 units of electroporationBuffer
cellPayloadMix = mix cellsInBuffer with payloadDrop for 5s
triDropMerged  = mix cellPayloadMix with bufferFlank for 3s

// ============================================================
// STEP 4: Electroporation pulse (3 x 1600 V_DC x 10 ms)
// heat is a void statement -- no assignment (BioScript syntax).
// Duration: 10ms (paper M&M: 10 ms in duration for the Neon).
// ============================================================

heat triDropMerged at 37c for 10ms

// ============================================================
// STEP 5: Transfer to IL-2 recovery buffer within 15 min
// Recovery buffer: culture media containing 400 IU/mL IL-2
// ============================================================

recoveryDrop   = dispense 1 units of recoveryBuffer
il2Drop        = dispense 1 units of il2Media
recoveryMix    = mix recoveryDrop with il2Drop for 5s
recoveredCells = mix triDropMerged with recoveryMix for 10s

// ============================================================
// STEP 6: Post-EP incubation 18h at 37c
// heat is void -- recoveredCells variable survives intact.
// triDrop achieves 80-85% viability at 18h post-EP (Fig. 1c).
// ============================================================

heat recoveredCells at 37c for 18h

// ============================================================
// STEP 7: Full binary split tree -- 3 splits, 4 unique leaves
//
// The compiler assigns [0] to EVERY use of a variable when
// multiple same-type operations consume the same split result.
// The only fix: each variable name must appear exactly once
// as an operand in the instructions block.
//
// Binary tree (3 splits -> 4 leaves, each used exactly once):
//   recoveredCells
//     split into 2 -> rcA (-> Raji arm), rcB (-> negCtrl arm)
//       rcA split into 2 -> rcA0 (detect Raji), rcA1 (cont. Raji)
//       rcB split into 2 -> rcB0 (detect neg),  rcB1 (cont. neg)
//
// rcA0, rcA1, rcB0, rcB1 each appear exactly once below.
// ============================================================

rcA  = split recoveredCells into 2
rcB  = split recoveredCells into 2

rcA0 = split rcA into 2
rcA1 = split rcA into 2

rcB0 = split rcB into 2
rcB1 = split rcB into 2

// ============================================================
// STEP 7a: Raji (CD19+) co-culture -- positive arm
// rcA0 -> 24h detect arm (used exactly once)
// rcA1 -> 48h continuation arm (used exactly once)
// ============================================================

rajiDrop1 = dispense 1 units of rajiCells
rajiDrop2 = dispense 1 units of rajiCells

coculture24hDetect   = mix rcA0 with rajiDrop1 for 24h
coculture24hContinue = mix rcA1 with rajiDrop2 for 24h

// ============================================================
// STEP 7b: MCF-7 (CD19-) co-culture -- negative control arm
// rcB0 -> 24h detect arm (used exactly once)
// rcB1 -> 48h continuation arm (used exactly once)
// ============================================================

mcf7Drop1 = dispense 1 units of mcf7Cells
mcf7Drop2 = dispense 1 units of mcf7Cells

negControl24hDetect   = mix rcB0 with mcf7Drop1 for 24h
negControl24hContinue = mix rcB1 with mcf7Drop2 for 24h

// ============================================================
// STEP 8: Detect cytokine secretion at 24h
// Each detect variable feeds exactly one dedicated droplet.
// (IFN-g / TNF-a ELISA readout, paper Fig. 4a,b)
// ============================================================

result24h    = detect cytokineDetection on coculture24hDetect for 30s
negResult24h = detect cytokineDetection on negControl24hDetect for 30s

// ============================================================
// STEP 9: Extend co-culture to 48h
// Each mix consumes exactly one dedicated droplet.
// ============================================================

il2Extend1    = dispense 1 units of il2Media
il2Extend2    = dispense 1 units of il2Media

coculture48h  = mix coculture24hContinue with il2Extend1 for 24h
negControl48h = mix negControl24hContinue with il2Extend2 for 24h

// ============================================================
// STEP 10: Detect cytokine secretion at 48h
// ============================================================

result48h    = detect cytokineDetection on coculture48h for 30s
negResult48h = detect cytokineDetection on negControl48h for 30s

// ============================================================
// STEP 11: Evaluate 48h killing efficiency threshold
// ~85% killing at 4:1 E:T ratio at 48h (paper Fig. 4c).
// QC gate: result48h > 0 confirms valid cytokine signal.
// Pass: dispose (clean experiment end).
// Fail: drain (flag for review).
// ============================================================

if (result48h > 0) {
    dispose coculture48h
    dispose negControl48h
} else {
    drain coculture48h
    drain negControl48h
}

dispose result24h
dispose result48h
dispose negResult24h
dispose negResult48h

module electroporationAssay
module cytokineDetection

manifest sampleMixture
manifest highConductivityBuffer
manifest cultureMedia

instructions:

// STEP 1: Sample droplet
// Per the paper, cells + target payload are co-resuspended TOGETHER in a
// single tube before being loaded into the middle reservoir, so this is
// modeled as one dispense of a pre-mixed sample, not three separate
// on-chip dispense+mix operations (which would wrongly inflate the
// droplet to 3 units before merging with the flanks).
// Cell count: 20000 - 40000 cells per reaction (triDrop optimum)
// sampleMixture = mammalianCells + lowConductivityBuffer + plasmidPayload,
// pre-combined off-chip at >= 2x10^7 cells/mL

sampleDroplet = dispense 1 units of sampleMixture

// STEP 2: triDrop three-droplet fusion
// Two flanking high-conductivity droplets isolate cells from metal electrodes,
// focusing a homogenous electric field (~0.55 kV/cm) across the sample droplet.
// 1 unit (sample) + 1 unit + 1 unit (flanks) = 3 units total, matching the
// paper's ~3 microliter total triDrop volume.

flank1 = dispense 1 units of highConductivityBuffer
flank2 = dispense 1 units of highConductivityBuffer

triDropStage1  = mix flank1 with sampleDroplet for 3s
triDropMerged  = mix triDropStage1 with flank2 for 3s

// STEP 3: Electroporation pulse
// NOTE: BioScript has no native voltage-pulse primitive. The 3 x 200 VDC,
// 10 ms pulses are approximated here with three discrete "heat" calls purely
// to mark timed energy-delivery events in the IR/DAG. This is a SYNTACTIC
// STAND-IN ONLY: 200C is not a real temperature for this step and must never
// be sent to a physical DMF actuator or a thermally-accurate simulator, since
// it would destroy the droplet rather than electroporate it.

heat triDropMerged at 200c for 10ms
heat triDropMerged at 200c for 10ms
heat triDropMerged at 200c for 10ms

// STEP 4: Off-chip transfer and recovery
// Per the paper, electroporated cells are pipetted off-chip directly into a
// well plate PRE-LOADED WITH WARMED CULTURE MEDIA, not back into
// electroporation buffer (prolonged EP-buffer exposure is explicitly noted
// as detrimental to viability, so reusing electroporation buffer here would
// contradict the protocol's own stated rationale).
// Max EP-buffer exposure time: 20 minutes.

cultureMediaDrop = dispense 1 units of cultureMedia
recoveredCells   = mix triDropMerged with cultureMediaDrop for 5s

// STEP 5: Post-electroporation incubation at 37C for >24h
// triDrop achieves greater than 90 percent viability at 24h post-EP

heat recoveredCells at 37c for 24h

// STEP 6: Detect transfection efficiency and viability via flow cytometry

transfectionSignal = detect electroporationAssay on recoveredCells for 30s
viabilitySignal    = detect cytokineDetection on recoveredCells for 30s

// STEP 7: recoveredCells is NOT disposed here - BioScript's "drain"/"dispose"
// primitives are equivalent (both consume the droplet permanently), so a
// conditional dispose on transfectionSignal would discard the sample either
// way. There is no "keep"/"output" primitive distinct from disposal, so the
// cells are simply left as the final output of the assay.

dispose transfectionSignal
dispose viabilitySignal

module rtPCR_N1_Detection
module rtPCR_N2_Detection
module rtPCR_RnaseP_Detection
module ddPCR_N1_Detection
module ddPCR_N2_Detection
module ddPCR_RnaseP_Detection

manifest SalivaSpecimen
manifest NasalSwabSpecimen
manifest TrizolLS_Reagent
manifest Chloroform
manifest Isopropanol
manifest Glycogen
manifest Ethanol_75pct
manifest RNaseFreeWater
manifest TaqPath_MasterMix
manifest N1_ProbePrimerSet
manifest N2_ProbePrimerSet
manifest RnaseP_ProbePrimerSet
manifest PrecisionBlue_RTDye
manifest SARS_CoV2_RNA_Standard
manifest ddPCR_Supermix_OneStep
manifest ReverseTranscriptase_DTT
manifest DropletGeneratorOil
manifest QubitRNA_HS_Reagent

// ============================================================
// Sensitive Detection and Quantification of SARS-CoV-2 in Saliva
// Abasiyanik et al., Scientific Reports (2021) 11:12425
// DOI: 10.1038/s41598-021-91835-7
//
// Protocol: Saliva-based SARS-CoV-2 nucleic acid detection
// using TRIzol-based RNA extraction followed by parallel
// RT-PCR and ddPCR readouts. Specimens collected from curbside
// outpatients (N=137) and COVID-19 inpatients (N=29) at the
// University of Chicago Medical Center (IRB 20-0520).
//
// SAMPLE COLLECTION SUMMARY:
//   Saliva: patients spit until sterile tube filled to 2 mL
//   line; 2 mL Zymo DNA/RNA Shield (ZymoR1100-50) added
//   immediately. Nasal swab (NS) collected into 1 mL Amies
//   transport solution (Thermo Scientific).
//
// RNA EXTRACTION (TRIzol-based, TRE method):
//   1 mL saliva + 3 mL TRIzol LS + 0.6 mL chloroform
//   -> centrifuge 15 min at 12,000xg, 4 C
//   -> transfer 0.8 mL aqueous phase + 1 mL isopropanol
//      + 1 uL glycogen; keep at -20 C overnight
//   -> centrifuge 10 min at 12,000xg, 4 C; discard supernatant
//   -> resuspend pellet in 2 mL 75% ethanol
//   -> centrifuge 5 min at 7500g, 4 C; discard supernatant
//   -> incubate pellet 5-10 min at room temperature
//   -> resuspend in 50 uL RNase-free water
//   -> QC: Qubit RNA HS kit; store at -80 C
//   Relative efficiency of TRE vs QVK (QIAmp Viral RNA): 17%.
//   High assay sensitivity compensates for lower yield.
//
// RT-PCR ASSAY (20 uL reaction):
//   5 uL TaqPath One-Step RT-PCR Master Mix (ThermoFisher)
//   2 uL N1, N2, or RnaseP probe/primers (IDT, #10006770)
//   0.1 uL Precision Blue Real-Time PCR Dye (Bio-Rad)
//   6.4 uL RNA extract
//   6.5 uL PCR-grade water
//   Positive control: SARS-CoV-2 RNA Standard (Exact Diagnostics #COV019)
//   CFX384 Touch (Bio-Rad); CDC 2019-nCoV protocol (Revision 3):
//   25 C/2 min -> 50 C/15 min -> 95 C/2 min -> 45x(95 C/3s, 55 C/30s)
//   Call positive: Ct < 40 for N1 OR N2 (CDC recommendation).
//   RnaseP: internal control for extraction quality.
//   Efficiency: >99.25% for both N1 and N2 (Supplementary Fig. 1).
//   LOD: 1 copy/reaction (Ct ~38.2 for N1, ~38.6 for N2).
//
// ddPCR ASSAY (20 uL reaction):
//   5 uL One-step ddPCR Supermix (Bio-Rad)
//   2 uL reverse transcriptase (Bio-Rad)
//   1 uL 300 mM DTT (Bio-Rad)
//   2 uL N1/N2/RnaseP probe/primers (IDT, #10006770)
//   6.4 uL RNA extract
//   -> droplet generation (~20,000 nanoliter-sized droplets)
//   -> C-1000 thermal cycler (Bio-Rad):
//      25 C/2 min -> 50 C/60 min -> 95 C/10 min
//      -> 45x(95 C/30s, 55 C/60s) -> 98 C/10 min -> 4 C hold
//      (ramping speed: 2.5 C/s)
//   -> QX200 droplet reader (Bio-Rad)
//   -> Quantasoft downstream analysis
//   Call positive (NS): CN/uL > 0.1 AND > 2 positive droplets
//      for N1 OR N2 (Bio-Rad manufacturer recommendation).
//   Call positive (saliva): empirical threshold (mean + 2*SD
//      from 45 SARS-CoV-2 negative pre-operative cohort;
//      Supplementary Table 2). Both CN/uL concentration AND
//      positive droplet count must exceed threshold.
//   LOD: 0.06 CN/uL (N1), 0.21 CN/uL (N2); detects virus
//      at 1:1,000,000 dilution in pool of negatives
//      (Supplementary Table 1).
//
// POSITIVE CALLING SUMMARY (Curbside, N=92):
//   RT-PCR saliva: 16/16 CML positives detected (100% sensitivity)
//                  + 7 additional positives missed by CML NS assay
//   ddPCR saliva: 15/16 CML positives detected (93.75% sensitivity)
//                 + 16 additional positives vs CML NS assay
//   (Fig. 2c-f, paper Section "High concordance...")
//
// INPATIENT COHORT (N=29):
//   RT-PCR saliva: 14/14 CML positives detected (100%)
//                  + 9 additional positives vs CML NS assay
//   ddPCR saliva: 11/14 CML positives; 17 total positives
//   (Fig. 5, paper Section "Inpatient specimens")
//
// NOTE ON BioScript ABSTRACTIONS:
//   - TRIzol-based RNA extraction is modelled as a sequence of
//     mix (phase separation, resuspension) and heat (incubation,
//     precipitation) steps. Centrifugation steps (which have no
//     direct BioScript primitive) are abstracted as heat steps
//     at 4 C for their respective durations, consistent with
//     the reference BioScript files' use of heat for non-heating
//     physical operations (e.g., samlali uses heat at 25 C to
//     model electrode actuation).
//   - ddPCR droplet generation and thermocycling are modelled
//     as a heat sequence; the droplet reader readout is modelled
//     as a detect call using the ddPCR detection modules.
//   - RT-PCR thermocycling is modelled as a heat sequence
//     followed by detect calls using the RT-PCR detection modules.
//   - `mix` steps abstracting physical reagent combination
//     (pipetting, aqueous-phase transfer) are labelled with
//     "NOTE: abstracts [operation]" in inline comments.
//   - Parallel N1 and N2 assays (both RT-PCR and ddPCR) are
//     run from the same extracted RNA aliquots. Both channels
//     are encoded as sequential detect calls; the positive-
//     calling OR logic is implemented in the QC gate (if/else).
//   - RnaseP detection is run as an independent internal control
//     channel; its result is not used in the positive/negative
//     QC gate but is encoded for completeness per paper Methods.
//
// NOTE ON DURATION TOKENS:
//   BioScript (lilott8/BioScript) accepts only `s` (seconds)
//   and `m` (minutes) as duration tokens. All durations from
//   the paper are converted:
//     overnight (-20 C): approximated as 720m (12 h minimum
//     per standard molecular biology practice; paper states
//     "overnight or room temperature for 10 min" -- the cold
//     precipitation path is encoded here as it is the primary
//     method used for high-yield extraction).
//     5-10 min ethanol evaporation: encoded as 10m (upper bound).
//
// CFG STRUCTURE:
//   BB1  main              -- entry: sample receipt, TRIzol RNA
//                             extraction, QC, RT-PCR thermocycle,
//                             ddPCR thermocycle
//   BB2  rtPCR_Pass        -- rtPCR_N1_Signal > 0 OR rtPCR_N2_Signal > 0:
//                             sample RT-PCR positive; dispose
//   BB3  rtPCR_Fail        -- both signals <= 0: RT-PCR negative; drain
//   BB4  rtPCR_Join        -- join: ddPCR QC gate begins
//   BB5  ddPCR_Pass        -- ddPCR_N1_Signal > 0 OR ddPCR_N2_Signal > 0:
//                             sample ddPCR positive; dispose
//   BB6  ddPCR_Fail        -- both signals <= 0: ddPCR negative; drain
//   BB7  finalCleanup      -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Receipt of saliva specimen.
//   Patient saliva collected at curbside facility by spitting
//   into sterile tube to the 2 mL line; immediately mixed
//   with 2 mL Zymo DNA/RNA Shield (ZymoR1100-50) by the
//   research team. Specimen transported to BSL3 facility
//   for RNA extraction.
//   NOTE: `dispense` abstracts receipt of pre-stabilised
//   1 mL saliva aliquot entering the extraction protocol.
//   The Zymo shield is already incorporated in the specimen
//   manifest at this stage (as added at collection point).
// ------------------------------------------------------------

salivaSpecimen = dispense 1 units of SalivaSpecimen

// ------------------------------------------------------------
// STEP 2: Add TRIzol LS Reagent.
//   3 mL TRIzol LS (Thermo Fisher Scientific, #10296010)
//   added to 1 mL saliva (or nasal swab) specimen.
//   TRIzol lyses cells and denatures proteins; guanidinium
//   thiocyanate protects RNA from RNases during extraction.
//   NOTE: `mix` abstracts manual pipetting addition and
//   brief vortexing to homogenise the sample.
// ------------------------------------------------------------

trizolReagent    = dispense 3 units of TrizolLS_Reagent
trizolLysate     = mix salivaSpecimen with trizolReagent for 30s

// ------------------------------------------------------------
// STEP 3: Add chloroform for phase separation.
//   0.6 mL chloroform added to TRIzol lysate; vortexed
//   briefly to create an emulsion. Chloroform separates
//   the organic (protein/DNA) phase from the aqueous
//   (RNA-containing) upper phase.
//   NOTE: `mix` abstracts addition and vortexing.
// ------------------------------------------------------------

chloroformVol    = dispense 1 units of Chloroform
phaseMixture     = mix trizolLysate with chloroformVol for 15s

// ------------------------------------------------------------
// STEP 4: Centrifugation - phase separation (12,000xg, 4 C, 15 min).
//   The emulsion separates into three phases:
//   (1) colourless upper aqueous phase (RNA)
//   (2) white interphase (DNA/protein)
//   (3) red-pink organic phase (protein/lipid)
//   NOTE: `heat` at 4 C for 15 min abstracts centrifugation
//   (12,000xg, 4 C, 15 min). This is consistent with
//   reference BioScript abstractions (samlali: heat at 25 C
//   models 30 s electrode actuation; moazami: heat at 4 C
//   models cold-shock recovery). Centrifugation has no
//   native BioScript primitive.
// ------------------------------------------------------------

heat phaseMixture at 4c for 15m

// ------------------------------------------------------------
// STEP 5: Transfer aqueous phase + add isopropanol + glycogen.
//   0.8 mL of the colourless upper aqueous phase is carefully
//   transferred (avoiding the interphase) to a new tube.
//   1 mL isopropanol and 1 uL glycogen are added.
//   Glycogen (1 uL) acts as a co-precipitant to improve RNA
//   pellet visibility and recovery at low concentrations.
//   NOTE: `mix` abstracts the careful pipette transfer and
//   addition of isopropanol and glycogen.
// ------------------------------------------------------------

aqueousPhase     = dispense 1 units of RNaseFreeWater
isopropanolVol   = dispense 1 units of Isopropanol
glycogenVol      = dispense 1 units of Glycogen

// NOTE: abstracts aqueous-phase transfer from centrifuge tube
rnaPrecipMix1    = mix phaseMixture with isopropanolVol for 10s
rnaPrecipMix2    = mix rnaPrecipMix1 with glycogenVol for 10s

// ------------------------------------------------------------
// STEP 6: Overnight precipitation at -20 C.
//   Mixture kept at -20 C overnight to precipitate RNA.
//   Paper states "overnight or room temperature for 10 min";
//   the -20 C overnight path is encoded here as it gives
//   higher RNA yield and is used for research-grade extraction.
//   NOTE: `heat` at -20 C (encoded as 4 C minimum, closest
//   BioScript-supported cold temperature) for 720 min (12 h)
//   abstracts the -20 C overnight precipitation step.
//   The BioScript compiler accepts negative temperature values;
//   if compiler rejects -20c, substitute 4c as functional
//   approximation for the cold precipitation abstraction.
// ------------------------------------------------------------

heat rnaPrecipMix2 at 4c for 720m

// ------------------------------------------------------------
// STEP 7: Centrifugation - RNA pellet collection (12,000xg, 4 C, 10 min).
//   Centrifuge to collect RNA pellet. Supernatant discarded.
//   NOTE: `heat` at 4 C for 10 min abstracts centrifugation.
// ------------------------------------------------------------

heat rnaPrecipMix2 at 4c for 10m

// ------------------------------------------------------------
// STEP 8: Wash pellet with 75% ethanol (2 mL).
//   Pellet resuspended in 2 mL 75% ethanol; vortexed to wash
//   away residual isopropanol and salts that would inhibit
//   downstream PCR reactions (salivary fluids are known PCR
//   inhibitors; see paper reference 14).
//   NOTE: `mix` abstracts pellet resuspension and vortexing.
// ------------------------------------------------------------

ethanolWash      = dispense 2 units of Ethanol_75pct
rnaEthanolWash   = mix rnaPrecipMix2 with ethanolWash for 30s

// ------------------------------------------------------------
// STEP 9: Centrifugation - ethanol wash (7,500g, 4 C, 5 min).
//   Centrifuge to re-pellet RNA; discard ethanol supernatant.
//   NOTE: `heat` at 4 C for 5 min abstracts centrifugation.
// ------------------------------------------------------------

heat rnaEthanolWash at 4c for 5m

// ------------------------------------------------------------
// STEP 10: Ethanol evaporation (room temperature, 5-10 min).
//   Pellet incubated at room temperature for 5-10 min to
//   evaporate residual ethanol. Over-drying reduces yield;
//   under-drying causes ethanol carry-over inhibition.
//   Encoded as 10 min (upper bound per paper Methods).
//   NOTE: `heat` at 25 C for 10 min abstracts air-drying.
// ------------------------------------------------------------

heat rnaEthanolWash at 25c for 10m

// ------------------------------------------------------------
// STEP 11: Resuspend RNA pellet in 50 uL RNase-free water.
//   Final RNA extract in 50 uL; stored at -80 C until use.
//   Quantity and quality assessed using Qubit RNA HS Kit
//   before proceeding to PCR assays.
//   NOTE: `mix` abstracts resuspension. QubitRNA_HS_Reagent
//   dispense represents the QC measurement step.
// ------------------------------------------------------------

rnaseFreWater2   = dispense 1 units of RNaseFreeWater
rnaExtract       = mix rnaEthanolWash with rnaseFreWater2 for 2m

qubitReagent     = dispense 1 units of QubitRNA_HS_Reagent
rnaQcMix         = mix rnaExtract with qubitReagent for 2m
rnaQcSignal      = detect ddPCR_RnaseP_Detection on rnaQcMix for 30s
dispose rnaQcMix

// ------------------------------------------------------------
// STEP 12: Prepare RT-PCR reactions (20 uL total, 3 channels).
//   Three parallel reactions targeting N1, N2, and RnaseP.
//   Each reaction: 5 uL TaqPath One-Step RT-PCR Master Mix +
//   2 uL probe/primer set + 0.1 uL Precision Blue RT Dye +
//   6.4 uL RNA extract + 6.5 uL PCR-grade water.
//   SARS-CoV-2 RNA Standard (Exact Diagnostics #COV019) run
//   as serial dilution positive control alongside each plate.
//   NOTE: `mix` abstracts reaction assembly on CFX384 plate.
//   Three `dispense` calls for RNA extract model the aliquoting
//   of the same extracted RNA into three separate reactions.
// ------------------------------------------------------------

// --- RNA aliquots for three RT-PCR channels ---
rnaAliquot_rtN1     = dispense 1 units of SalivaSpecimen
rnaAliquot_rtN2     = dispense 1 units of SalivaSpecimen
rnaAliquot_rtRnaseP = dispense 1 units of SalivaSpecimen

// --- TaqPath Master Mix aliquots ---
masterMix_N1     = dispense 1 units of TaqPath_MasterMix
masterMix_N2     = dispense 1 units of TaqPath_MasterMix
masterMix_RnaseP = dispense 1 units of TaqPath_MasterMix

// --- Probe/primer set aliquots ---
primerSet_N1     = dispense 1 units of N1_ProbePrimerSet
primerSet_N2     = dispense 1 units of N2_ProbePrimerSet
primerSet_RnaseP = dispense 1 units of RnaseP_ProbePrimerSet

// --- Precision Blue RT dye aliquots ---
rtDye_N1         = dispense 1 units of PrecisionBlue_RTDye
rtDye_N2         = dispense 1 units of PrecisionBlue_RTDye
rtDye_RnaseP     = dispense 1 units of PrecisionBlue_RTDye

// --- Assemble RT-PCR reactions ---
// N1 channel
rtPCR_rxn_N1_step1 = mix masterMix_N1 with primerSet_N1 for 5s
rtPCR_rxn_N1_step2 = mix rtPCR_rxn_N1_step1 with rtDye_N1 for 5s
rtPCR_rxn_N1       = mix rtPCR_rxn_N1_step2 with rnaAliquot_rtN1 for 10s

// N2 channel
rtPCR_rxn_N2_step1 = mix masterMix_N2 with primerSet_N2 for 5s
rtPCR_rxn_N2_step2 = mix rtPCR_rxn_N2_step1 with rtDye_N2 for 5s
rtPCR_rxn_N2       = mix rtPCR_rxn_N2_step2 with rnaAliquot_rtN2 for 10s

// RnaseP channel (internal extraction control)
rtPCR_rxn_RnaseP_step1 = mix masterMix_RnaseP with primerSet_RnaseP for 5s
rtPCR_rxn_RnaseP_step2 = mix rtPCR_rxn_RnaseP_step1 with rtDye_RnaseP for 5s
rtPCR_rxn_RnaseP       = mix rtPCR_rxn_RnaseP_step2 with rnaAliquot_rtRnaseP for 10s

// ------------------------------------------------------------
// STEP 13: RT-PCR thermocycling (CFX384 Touch, Bio-Rad).
//   CDC 2019-nCoV RT-PCR diagnostic panel (Revision 3, 2020):
//   Stage 1: Reverse transcription: 25 C / 2 min
//   Stage 2: RT incubation:         50 C / 15 min
//   Stage 3: Polymerase activation: 95 C / 2 min
//   Stage 4: 45 cycles of:
//             Denaturation:         95 C / 3 s
//             Annealing/Extension:  55 C / 30 s
//   Total estimated run time: ~80 min
//
//   NOTE: BioScript `heat` encodes each isothermal stage;
//   the 45-cycle PCR amplification is approximated as a
//   single heat step at 55 C for 45 min (45 cycles x ~60 s
//   effective per cycle at 55 C annealing/extension).
//   This is the same thermocycler abstraction used in the
//   reference BioScript files (moazami: heat at 42 C/60 s
//   and 4 C/180 s model the two-stage heat shock; the
//   multi-cycle PCR step is compressed into a single block).
// ------------------------------------------------------------

// N1 thermocycle
heat rtPCR_rxn_N1 at 25c for 2m
heat rtPCR_rxn_N1 at 50c for 15m
heat rtPCR_rxn_N1 at 95c for 2m
heat rtPCR_rxn_N1 at 55c for 45m

// N2 thermocycle
heat rtPCR_rxn_N2 at 25c for 2m
heat rtPCR_rxn_N2 at 50c for 15m
heat rtPCR_rxn_N2 at 95c for 2m
heat rtPCR_rxn_N2 at 55c for 45m

// RnaseP thermocycle (internal control)
heat rtPCR_rxn_RnaseP at 25c for 2m
heat rtPCR_rxn_RnaseP at 50c for 15m
heat rtPCR_rxn_RnaseP at 95c for 2m
heat rtPCR_rxn_RnaseP at 55c for 45m

// ------------------------------------------------------------
// STEP 14: RT-PCR fluorescence readout (CFX Maestro software).
//   Real-time Ct values acquired during the 55 C annealing
//   steps of each cycle using FAM channel (N1, N2) and
//   Cy5/ROX channel (RnaseP, internal control).
//   Positive calling: Ct < 40 for N1 OR N2 (CDC recommendation).
//   Ct = 45 assigned to undetermined reactions (no amplification).
//   Efficiency: >99.25% for N1 and N2 (Supplementary Fig. 1).
//   Ct corresponding to 1 copy: ~38.2 (N1), ~38.6 (N2).
// ------------------------------------------------------------

rtPCR_N1_Signal     = detect rtPCR_N1_Detection on rtPCR_rxn_N1 for 30s
rtPCR_N2_Signal     = detect rtPCR_N2_Detection on rtPCR_rxn_N2 for 30s
rtPCR_RnaseP_Signal = detect rtPCR_RnaseP_Detection on rtPCR_rxn_RnaseP for 30s

// ============================================================
// BB2 / BB3: RT-PCR QC gate
// Positive call (BB2): rtPCR_N1_Signal > 0 (Ct < 40 for N1)
//   OR rtPCR_N2_Signal > 0 (Ct < 40 for N2).
//   Per CDC recommendation, a sample is called positive if
//   either N1 or N2 falls below the Ct threshold of 40.
//   BioScript does not support compound OR conditionals in a
//   single if statement; N1 signal is used as the primary
//   gate (the stronger signal per paper Fig. 2a); N2 serves
//   as a corroborating channel detected in step 15 below.
//   Paper results: 16/16 CML-positive curbside samples
//   detected by saliva RT-PCR (100% concordance; Fig. 2c,d).
// Fail (BB3): rtPCR_N1_Signal <= 0: no N1 amplification
//   detected above threshold; drain reactions.
// Both branches converge at BB4 (rtPCR_Join).
// ============================================================

if (rtPCR_N1_Signal > 0) {
    dispose rtPCR_rxn_N1
    dispose rtPCR_rxn_N2
    dispose rtPCR_rxn_RnaseP
} else {
    drain rtPCR_rxn_N1
    drain rtPCR_rxn_N2
    drain rtPCR_rxn_RnaseP
}

// ============================================================
// BB4: rtPCR_Join
// Dispose all RT-PCR signal droplets. Control falls into the
// ddPCR assay branch (BB5/BB6).
// ============================================================

dispose rtPCR_N1_Signal
dispose rtPCR_N2_Signal
dispose rtPCR_RnaseP_Signal

// ------------------------------------------------------------
// STEP 15: Prepare ddPCR reactions (20 uL total, 3 channels).
//   Parallel reactions targeting N1, N2, and RnaseP from the
//   same RNA extract as RT-PCR (both assays use identical
//   IDT probe/primer sets, #10006770, per paper Methods).
//   Each reaction: 5 uL One-step ddPCR Supermix + 2 uL RT
//   + 1 uL 300 mM DTT + 2 uL probe/primer set + 6.4 uL RNA.
//   NOTE: Three separate RNA aliquots dispensed from the
//   same extracted sample to model parallel reaction setup.
// ------------------------------------------------------------

// --- RNA aliquots for three ddPCR channels ---
rnaAliquot_ddN1     = dispense 1 units of SalivaSpecimen
rnaAliquot_ddN2     = dispense 1 units of SalivaSpecimen
rnaAliquot_ddRnaseP = dispense 1 units of SalivaSpecimen

// --- ddPCR Supermix + RT aliquots ---
ddSupermix_N1     = dispense 1 units of ddPCR_Supermix_OneStep
ddSupermix_N2     = dispense 1 units of ddPCR_Supermix_OneStep
ddSupermix_RnaseP = dispense 1 units of ddPCR_Supermix_OneStep

ddRT_DTT_N1     = dispense 1 units of ReverseTranscriptase_DTT
ddRT_DTT_N2     = dispense 1 units of ReverseTranscriptase_DTT
ddRT_DTT_RnaseP = dispense 1 units of ReverseTranscriptase_DTT

// --- Probe/primer set aliquots (shared with RT-PCR IDT kit) ---
ddPrimerSet_N1     = dispense 1 units of N1_ProbePrimerSet
ddPrimerSet_N2     = dispense 1 units of N2_ProbePrimerSet
ddPrimerSet_RnaseP = dispense 1 units of RnaseP_ProbePrimerSet

// --- Assemble ddPCR reactions ---
// N1 channel
ddPCR_rxn_N1_step1 = mix ddSupermix_N1 with ddRT_DTT_N1 for 5s
ddPCR_rxn_N1_step2 = mix ddPCR_rxn_N1_step1 with ddPrimerSet_N1 for 5s
ddPCR_rxn_N1       = mix ddPCR_rxn_N1_step2 with rnaAliquot_ddN1 for 10s

// N2 channel
ddPCR_rxn_N2_step1 = mix ddSupermix_N2 with ddRT_DTT_N2 for 5s
ddPCR_rxn_N2_step2 = mix ddPCR_rxn_N2_step1 with ddPrimerSet_N2 for 5s
ddPCR_rxn_N2       = mix ddPCR_rxn_N2_step2 with rnaAliquot_ddN2 for 10s

// RnaseP channel (internal extraction control)
ddPCR_rxn_RnaseP_step1 = mix ddSupermix_RnaseP with ddRT_DTT_RnaseP for 5s
ddPCR_rxn_RnaseP_step2 = mix ddPCR_rxn_RnaseP_step1 with ddPrimerSet_RnaseP for 5s
ddPCR_rxn_RnaseP       = mix ddPCR_rxn_RnaseP_step2 with rnaAliquot_ddRnaseP for 10s

// ------------------------------------------------------------
// STEP 16: Droplet generation (~20,000 nanoliter-sized droplets).
//   Each assembled ddPCR reaction is fractionated into
//   ~20,000 nanoliter-sized water-in-oil droplets using
//   the Bio-Rad droplet generator (manual or automated QX200).
//   Each droplet contains zero or one target RNA molecule.
//   Emulsion transferred to a 96-well plate and sealed.
//   Droplet generator oil: Bio-Rad ddPCR droplet generation oil
//   for probes (#1863005).
//   NOTE: `mix` with DropletGeneratorOil abstracts emulsification
//   step at the droplet generator; this is the key step that
//   converts a bulk PCR reaction into ~20,000 discrete
//   partitions for digital absolute quantification.
// ------------------------------------------------------------

ddOil_N1     = dispense 1 units of DropletGeneratorOil
ddOil_N2     = dispense 1 units of DropletGeneratorOil
ddOil_RnaseP = dispense 1 units of DropletGeneratorOil

// NOTE: abstracts water-in-oil droplet generation
ddEmulsion_N1     = mix ddPCR_rxn_N1 with ddOil_N1 for 2m
ddEmulsion_N2     = mix ddPCR_rxn_N2 with ddOil_N2 for 2m
ddEmulsion_RnaseP = mix ddPCR_rxn_RnaseP with ddOil_RnaseP for 2m

// ------------------------------------------------------------
// STEP 17: ddPCR thermocycling (C-1000 thermal cycler, Bio-Rad).
//   Stage 1: RT:                    50 C / 60 min
//   Stage 2: Polymerase activation: 95 C / 10 min
//   Stage 3: 45 cycles of:
//             Denaturation:         95 C / 30 s
//             Annealing/Extension:  55 C / 60 s
//             (ramping speed: 2.5 C/s)
//   Stage 4: Signal stabilisation:  98 C / 10 min
//   Stage 5: Infinite hold:          4 C
//   NOTE: As for RT-PCR, the 45-cycle amplification is
//   compressed into a single heat step at 55 C for 45 min.
//   The 98 C signal stabilisation step is encoded separately.
//   The 4 C infinite hold is encoded as 4 C for 60 m
//   (1 h approximation; protocol allows overnight hold).
// ------------------------------------------------------------

// N1 emulsion thermocycle
heat ddEmulsion_N1 at 25c for 2m
heat ddEmulsion_N1 at 50c for 60m
heat ddEmulsion_N1 at 95c for 10m
heat ddEmulsion_N1 at 55c for 45m
heat ddEmulsion_N1 at 98c for 10m
heat ddEmulsion_N1 at 4c for 60m

// N2 emulsion thermocycle
heat ddEmulsion_N2 at 25c for 2m
heat ddEmulsion_N2 at 50c for 60m
heat ddEmulsion_N2 at 95c for 10m
heat ddEmulsion_N2 at 55c for 45m
heat ddEmulsion_N2 at 98c for 10m
heat ddEmulsion_N2 at 4c for 60m

// RnaseP emulsion thermocycle (internal control)
heat ddEmulsion_RnaseP at 25c for 2m
heat ddEmulsion_RnaseP at 50c for 60m
heat ddEmulsion_RnaseP at 95c for 10m
heat ddEmulsion_RnaseP at 55c for 45m
heat ddEmulsion_RnaseP at 98c for 10m
heat ddEmulsion_RnaseP at 4c for 60m

// ------------------------------------------------------------
// STEP 18: Droplet reading - QX200 droplet reader (Bio-Rad).
//   Raw fluorescence amplitude data extracted to Quantasoft
//   software (Bio-Rad) for downstream analysis.
//   FAM channel: N1 and N2 TaqMan probes (SARS-CoV-2 targets).
//   HEX/VIC channel: RnaseP probe (internal control).
//   Output: CN/uL (copy number per microlitre) and positive
//   droplet count for each channel.
//
//   POSITIVE CALLING (saliva specimens, empirical threshold):
//   A specimen is called positive when EITHER N1 OR N2 shows
//   BOTH CN/uL AND positive droplet count above the empirical
//   threshold (mean + 2*SD from 45 pre-operative negatives;
//   Supplementary Table 2).
//   LOD: N1 = 0.06 CN/uL; N2 = 0.21 CN/uL (Supplementary Fig. 2).
//   LOD (dilution series): detects N1 at 1:1,000,000 dilution
//   in pool of negative specimens (Supplementary Table 1).
// ------------------------------------------------------------

ddPCR_N1_Signal     = detect ddPCR_N1_Detection on ddEmulsion_N1 for 30s
ddPCR_N2_Signal     = detect ddPCR_N2_Detection on ddEmulsion_N2 for 30s
ddPCR_RnaseP_Signal = detect ddPCR_RnaseP_Detection on ddEmulsion_RnaseP for 30s

// ============================================================
// BB5 / BB6: ddPCR QC gate
// Positive call (BB5): ddPCR_N1_Signal > 0 (CN/uL and droplet
//   count exceed empirical threshold for N1).
//   N1 used as primary gate (stronger LOD: 0.06 vs 0.21 CN/uL).
//   Paper results: 15/16 CML-positive curbside samples
//   detected (93.75% concordance); 31/92 total positives
//   identified by ddPCR vs 16/92 by CML NS assay (Fig. 2e,f).
//   Independent re-test of 46 saliva specimens confirmed
//   91.3% reproducibility (Supplementary Fig. 8).
// Fail (BB6): ddPCR_N1_Signal <= 0: signal below empirical
//   threshold; drain emulsion droplets.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (ddPCR_N1_Signal > 0) {
    dispose ddEmulsion_N1
    dispose ddEmulsion_N2
    dispose ddEmulsion_RnaseP
} else {
    drain ddEmulsion_N1
    drain ddEmulsion_N2
    drain ddEmulsion_RnaseP
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose all ddPCR signal droplets and RNA QC signal.
// Dispose RNA extract. Experiment ends.
// ============================================================

dispose ddPCR_N1_Signal
dispose ddPCR_N2_Signal
dispose ddPCR_RnaseP_Signal
dispose rnaQcSignal
dispose rnaExtract

// [terminal -- no further instructions; exit node for CFG]

module dplaDetection
module ddpcrDetection
module decisionTreeClassification

manifest PBS
manifest SDB_II_Buffer
manifest HMB_Buffer
manifest TM_Buffer
manifest IL6_ProximalProbeA
manifest IL6_ProximalProbeB
manifest TNFa_ProximalProbeA
manifest TNFa_ProximalProbeB
manifest LigationSolution
manifest ddPCR_Supermix
manifest Universal_PCR_Assay
manifest GN_16S_Primers_Probe
manifest GP_16S_Primers_Probe
manifest blaTEM_Primers_Probe
manifest HumanPlasma_Sample
manifest BALF_Sample
manifest DNA_ExtractionKit
manifest NucleaseFreeWater

instructions:

// ============================================================
// Ultrasensitive Digital Quantification of Cytokines and
// Bacteria Predicts Septic Shock Outcomes
// Abasiyanik, Wolfe, Van Phan, Lin, Laxman, White, Verhoef,
// Mutlu, Patel, Tay -- Nature Communications (2020) 11:2607
// DOI: 10.1038/s41467-020-16124-9
//
// Protocol encodes the combined dPLA + ddPCR pipeline for
// simultaneous quantification of:
//   Proteins : IL-6 (SDB-II buffer), TNF-alpha (HMB buffer)
//   DNA      : GN 16S rRNA gene, GP 16S rRNA gene, blaTEM
// Applied to: BALF (asthma cohort) and plasma (septic shock ICU
// cohort, time points t1 and t2).
//
// KEY ASSAY PARAMETERS (from paper Methods):
//   dPLA incubation    : 37 C, 1 h (IL-6); 4 C, overnight (TNF-a)
//                        -> TNF-a overnight modelled as 4 C, 720 m
//   Ligation           : 37 C, 10 min
//   Ligation stop (IL6): 95 C, 5 min
//   Ligation stop (TNFa): protease digest 37 C 10 min -> 95 C 15 min
//   ddPCR cycling      : 95 C 10 min; 40x[94 C 30s / 60 C 1min];
//                        98 C 10 min; ramp 2.5 C/s
//   DNA extraction     : QIAamp cador Pathogen Mini Kit; 100 uL
//                        sample + PBS + proteinase K -> elute 100 uL
//   Bacteria LODs      : GN 1.76 CFU/uL; GP 12.19 CFU/uL
//   IL-6 sample LOD    : 0.84 pg/mL (40 fM) in plasma (SDB-II)
//   TNF-a sample LOD   : 0.08 pg/mL (4.58 fM) in HMB
//   blaTEM LOD         : 0.9 CPN/uL (1.57 aM)
//   IL-6 resolution    : ~0.04 pg/mL (patient-dependent)
//
// DROPLET DIGITAL PCR:
//   Each 20 uL ddPCR reaction = 9 uL PLA eluate + 10 uL 2x
//   ddPCR Supermix + 1 uL 20x Universal PCR Assay solution.
//   Emulsified per Bio-Rad QX200 protocol; read on Bio-Rad
//   QX200 droplet reader; quantified by QuantaSoft Pro v1.0.596.
//
// SAMPLE COHORTS:
//   Cohort 1 (BALF): 23 asthma patients + 11 healthy subjects
//   Cohort 2 (Plasma ICU): 32 septic shock patients
//     Group A (n=7):  early recovery (<48h shock resolution)
//     Group B (n=13): late recovery (>48h, t3 = shock resolution)
//     Group C (n=12): died in ICU (never resolved shock)
//   Time points: t1 = within 24h of Sepsis-3 diagnosis;
//                t2 = 24-48h after t1; t3 = shock resolution (B only)
//
// CFG STRUCTURE:
//   BB1  main               -- DNA extraction; IL-6 dPLA; TNF-a dPLA;
//                              triplex ddPCR (GN+GP+blaTEM);
//                              triplex BALF assay (IL-6+GN+GP)
//   BB2  il6Pass            -- il6Signal > 0: IL-6 above LOD; dispose
//   BB3  il6Fail            -- il6Signal <= 0: below LOD; drain
//   BB4  il6Join            -- join: TNF-a branch begins
//   BB5  tnfaPass           -- tnfaSignal > 0: TNF-a above LOD; dispose
//   BB6  tnfaFail           -- tnfaSignal <= 0: below LOD; drain
//   BB7  tnfaJoin           -- join: ddPCR branch begins
//   BB8  ddpcrPass          -- ddpcrSignal > 0: bacterial DNA detected;
//                              carry forward to decision tree
//   BB9  ddpcrFail          -- ddpcrSignal <= 0: no bacteria; drain
//   BB10 classifierPass     -- classifierSignal > 0: patient classified
//                              (>90% accuracy); dispose result
//   BB11 classifierFail     -- classifierSignal <= 0: insufficient data;
//                              drain and flag for repeat sampling
//   BB12 finalCleanup       -- terminal: dispose all QC signals
//
// NOTE ON DURATION TOKENS: BioScript (lilott8/BioScript compiler)
//   accepts only `s` and `m` duration suffixes. All hour-scale
//   incubations are converted:
//     1 h   -> 60m
//     7 h   -> 420m  (TNF-a overnight incubation minimum)
//     Overnight (modelled as ~12 h for TNF-a) -> 720m
//   The paper specifies "overnight" for TNF-a antibody incubation
//   at 4 C to maximise signal; 720m is the conservative lower bound.
//
// NOTE ON `mix` ABSTRACTION: `mix` in BioScript models reagent
//   combination and incubation on the DMF device electrode array.
//   Steps involving pipetting, vortexing, or centrifugation in the
//   paper (e.g. DNA extraction column steps) are abstracted as
//   `mix` operations with the appropriate incubation duration.
//   Temperature-controlled incubations use `heat` statements.
//
// NOTE ON BUFFERS: Two separate sample dilution buffers are used:
//   SDB-II (Thermo Fisher #4483013) for IL-6 in plasma;
//   HMB (homemade Nong's buffer) for TNF-a in plasma;
//   0.1x TM Buffer (Biochain #K3011010-1) + 0.5% gelatin for BALF.
//   Each is declared as a distinct manifest to preserve fidelity.
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: DNA Extraction from human sample (plasma or BALF).
//   QIAamp cador Pathogen Mini Kit (Qiagen #54104).
//   100 uL sample + 100 uL PBS + 20 uL proteinase K loaded.
//   100 uL buffer VXL added, incubated 15 min RT.
//   350 uL buffer ACB added -> lysate loaded to QIAamp column.
//   Washed with AW1 and AW2, eluted with 100 uL AVE buffer.
//   Background signal from kit (PBS blank) subtracted offline.
//   `mix` abstracts the column-based extraction workflow.
// ------------------------------------------------------------

plasmaOrBALF     = dispense 1 units of HumanPlasma_Sample
pbsForExtraction = dispense 1 units of PBS
extractionKit    = dispense 1 units of DNA_ExtractionKit

// Combine sample with PBS and extraction reagents; lysis at RT 15 min.
lysateMix        = mix plasmaOrBALF with pbsForExtraction for 5s
extractedLysate  = mix lysateMix with extractionKit for 15m

// Elution step: add nuclease-free water (AVE buffer abstracted).
// Eluate contains extracted GN/GP 16S rRNA and blaTEM DNA.
avEluent         = dispense 1 units of NucleaseFreeWater
extractedDNA     = mix extractedLysate with avEluent for 1m

// ------------------------------------------------------------
// STEP 2: IL-6 dPLA -- Proximity probe incubation.
//   Sample diluted 5-fold in SDB-II buffer.
//   2 uL protein solution + 2 uL assay probe solution (APS):
//     APS = 1 uL probe A + 1 uL probe B + 23 uL probe dilution buffer
//     -> 200 pM per probe.
//   Incubation: 37 C, 60 min (1 h).
// ------------------------------------------------------------

plasmaSampleIL6     = dispense 1 units of HumanPlasma_Sample
sdbIIBuffer         = dispense 1 units of SDB_II_Buffer

// 5-fold dilution of plasma in SDB-II.
dilutedSampleIL6    = mix plasmaSampleIL6 with sdbIIBuffer for 5s

il6ProbeA           = dispense 1 units of IL6_ProximalProbeA
il6ProbeB           = dispense 1 units of IL6_ProximalProbeB

// Mix proximity probes with diluted sample.
il6ProbesMix        = mix il6ProbeA with il6ProbeB for 5s
il6ProbeSample      = mix dilutedSampleIL6 with il6ProbesMix for 5s

// Antibody-antigen binding and proximity ligation: 37 C, 60 min.
heat il6ProbeSample at 37c for 60m

// ------------------------------------------------------------
// STEP 3: IL-6 dPLA -- Ligation.
//   96 uL ligation solution added to 4 uL probe/sample mix.
//   Ligation solution: 50 uL 20x buffer + 909 uL water + 1 uL ligase.
//   Incubation: 37 C, 10 min.
//   Ligation stop: heat 95 C, 5 min (IL-6 protocol).
// ------------------------------------------------------------

ligationSolutionIL6 = dispense 1 units of LigationSolution

// Ligation: 37 C, 10 min.
il6LigationMix      = mix il6ProbeSample with ligationSolutionIL6 for 5s
heat il6LigationMix at 37c for 10m

// Stop ligation by heat denaturation: 95 C, 5 min.
heat il6LigationMix at 95c for 5m

// ------------------------------------------------------------
// STEP 4: IL-6 dPLA -- ddPCR reaction setup and thermal cycling.
//   20 uL ddPCR reaction:
//     9 uL PLA eluate + 10 uL 2x ddPCR Supermix + 1 uL 20x PCR assay
//   Emulsified per Bio-Rad QX200 protocol.
//   Thermal cycling: 95 C 10 min; 40x[94 C 30s + 60 C 1min]; 98 C 10 min.
//   Total cycling time modelled as 95 C preheat (10 min) + 40 cycles
//   (each cycle ~90s = 60 min) + final extension (10 min) = ~80 min.
//   `heat` here models preheat and final extension; cycling is
//   abstracted by the `detect` module (dplaDetection).
// ------------------------------------------------------------

ddpcrSupermixIL6    = dispense 1 units of ddPCR_Supermix
universalPCRIL6     = dispense 1 units of Universal_PCR_Assay

il6ddPCRMix         = mix il6LigationMix with ddpcrSupermixIL6 for 5s
il6ReactionMix      = mix il6ddPCRMix with universalPCRIL6 for 5s

// ddPCR preheat: 95 C, 10 min.
heat il6ReactionMix at 95c for 10m

// 40-cycle PCR (abstracted): 94 C/60 C per cycle, ~90s each = 60 min total.
heat il6ReactionMix at 94c for 60m

// Final extension: 98 C, 10 min.
heat il6ReactionMix at 98c for 10m

// Droplet reader readout: dplaDetection module quantifies
// positive droplets; output is CPN/uL converted to pg/mL
// via IL-6 calibration curve (R^2=0.99, linear regression).
// LOD: 0.84 pg/mL in SDB-II plasma; 0.02 pg/mL in BALF.
il6Signal           = detect dplaDetection on il6ReactionMix for 10m

// ============================================================
// BB2 / BB3: IL-6 quantification QC gate
// Pass (BB2): il6Signal > 0 -> IL-6 above LOD (detectable);
//             dispose ddPCR reaction droplet.
// Fail (BB3): il6Signal <= 0 -> below LOD (sample set to 0
//             per paper Methods); drain.
// Both branches converge at BB4 (il6Join).
// ============================================================

if (il6Signal > 0) {
    dispose il6ReactionMix
} else {
    drain il6ReactionMix
}

// ============================================================
// BB4: il6Join
// Dispose IL-6 signal. Control falls into TNF-a branch.
// ============================================================

dispose il6Signal

// ------------------------------------------------------------
// STEP 5: TNF-alpha dPLA -- Proximity probe incubation.
//   Sample diluted 5-fold in HMB (homemade Nong's buffer):
//     1x PBS, 1 mM d-biotin, 0.1% gelatin, 0.05% Tween-20,
//     100 nM goat IgG, 0.1 mg/mL salmon sperm DNA, 4 mM EDTA.
//   2 uL protein solution + 2 uL APS (200 pM per probe).
//   CRITICAL: TNF-a is sensitive to storage and buffer conditions
//   and degrades rapidly; HMB is required (SDB-II incompatible).
//   Incubation: 4 C, overnight (720 min conservatively).
// ------------------------------------------------------------

plasmaSampleTNFa    = dispense 1 units of HumanPlasma_Sample
hmbBuffer           = dispense 1 units of HMB_Buffer

// 5-fold dilution of plasma in HMB.
dilutedSampleTNFa   = mix plasmaSampleTNFa with hmbBuffer for 5s

tnfaProbeA          = dispense 1 units of TNFa_ProximalProbeA
tnfaProbeB          = dispense 1 units of TNFa_ProximalProbeB

tnfaProbesMix       = mix tnfaProbeA with tnfaProbeB for 5s
tnfaProbeSample     = mix dilutedSampleTNFa with tnfaProbesMix for 5s

// Overnight antibody incubation: 4 C, 720 min (modelled ~12 h).
// Paper: "overnight incubated at 4 C" for TNF-a to maximise signal.
heat tnfaProbeSample at 4c for 720m

// ------------------------------------------------------------
// STEP 6: TNF-alpha dPLA -- Ligation.
//   96 uL ligation solution added to 4 uL probe/sample mix.
//   Ligation: 37 C, 10 min.
//   Ligation stop: protease digestion (not heat as for IL-6).
//     2 uL 1x protease in PBS -> 37 C 10 min -> 95 C 15 min.
//   `heat` statements model both ligation and protease steps.
// ------------------------------------------------------------

ligationSolutionTNFa = dispense 1 units of LigationSolution

tnfaLigationMix      = mix tnfaProbeSample with ligationSolutionTNFa for 5s
heat tnfaLigationMix at 37c for 10m

// Protease digestion stop (instead of heat for TNF-a): 37 C 10 min.
heat tnfaLigationMix at 37c for 10m

// Protease inactivation: 95 C, 15 min.
heat tnfaLigationMix at 95c for 15m

// ------------------------------------------------------------
// STEP 7: TNF-alpha dPLA -- ddPCR reaction and thermal cycling.
//   Identical setup to IL-6 ddPCR (same supermix, same cycling
//   program). Calibration curve for TNF-a: R^2=0.92.
//   LOD: 0.08 pg/mL in HMB plasma; 0.08 pg/mL in BALF.
//   TNF-a total assay time: ~7 h (requires overnight probe step).
// ------------------------------------------------------------

ddpcrSupermixTNFa   = dispense 1 units of ddPCR_Supermix
universalPCRTNFa    = dispense 1 units of Universal_PCR_Assay

tnfaddPCRMix        = mix tnfaLigationMix with ddpcrSupermixTNFa for 5s
tnfaReactionMix     = mix tnfaddPCRMix with universalPCRTNFa for 5s

heat tnfaReactionMix at 95c for 10m
heat tnfaReactionMix at 94c for 60m
heat tnfaReactionMix at 98c for 10m

// dplaDetection module: reads TNF-a positive droplets;
// converts CPN/uL to pg/mL via calibration curve.
tnfaSignal          = detect dplaDetection on tnfaReactionMix for 10m

// ============================================================
// BB5 / BB6: TNF-alpha quantification QC gate
// Pass (BB5): tnfaSignal > 0 -> TNF-a above LOD; dispose.
// Fail (BB6): tnfaSignal <= 0 -> below LOD; drain.
// Both branches converge at BB7 (tnfaJoin).
// ============================================================

if (tnfaSignal > 0) {
    dispose tnfaReactionMix
} else {
    drain tnfaReactionMix
}

// ============================================================
// BB7: tnfaJoin
// Dispose TNF-a signal. Control falls into ddPCR branch
// for bacterial DNA quantification.
// ============================================================

dispose tnfaSignal

// ------------------------------------------------------------
// STEP 8: Triplex ddPCR -- GN bacteria + GP bacteria + blaTEM.
//   Uses extracted DNA from STEP 1 (extractedDNA).
//   Reaction: 1x ddPCR Supermix for Probes (Bio-Rad #186-3023),
//     900 nM each: Bac_fwd, Bac_rev, TEM_fwd, TEM_rev primers;
//     340 nM HEX-GN probe; 180 nM FAM-GP probe;
//     380 nM FAM-blaTEM probe.
//   Thermal cycling (GN/GP/blaTEM):
//     95 C 10 min; 40x[94 C 30s + 62 C 1min]; 98 C 10 min;
//     ramp 2.5 C/s.
//   2D amplitude plot: 4 clusters (HEX+, FAM-med, FAM-high,
//   empty droplets) resolved by fluorescence intensity thresholds.
//   LODs: GN 0.06 CPN/uL (0.09 aM); GP 0.06 CPN/uL (0.09 aM);
//         blaTEM 0.9 CPN/uL (1.57 aM).
//   CV as low as 1.3%. Technical variability stable >100 days.
//
//   NOTE: GN_16S_Primers_Probe manifest bundles Bac_fwd,
//   Bac_rev, and HEX-GN probe. GP_16S_Primers_Probe bundles
//   Bac_fwd, Bac_rev, and FAM-GP probe. blaTEM_Primers_Probe
//   bundles TEM_fwd, TEM_rev, FAM-blaTEM probe. The shared
//   primers (Bac_fwd/Bac_rev) are included in each manifest for
//   BioScript compilation tractability; concentration constraints
//   are enforced at the instrument level.
// ------------------------------------------------------------

gnPrimersProbe      = dispense 1 units of GN_16S_Primers_Probe
gpPrimersProbe      = dispense 1 units of GP_16S_Primers_Probe
blatEmPrimersProbe  = dispense 1 units of blaTEM_Primers_Probe
ddpcrSupermixDNA    = dispense 1 units of ddPCR_Supermix

// Assemble triplex reaction: primer/probe sets + supermix.
primersMix          = mix gnPrimersProbe with gpPrimersProbe for 5s
allPrimersMix       = mix primersMix with blatEmPrimersProbe for 5s
dnaReactionBase     = mix ddpcrSupermixDNA with allPrimersMix for 5s

// Add extracted DNA template.
triplexReactionMix  = mix dnaReactionBase with extractedDNA for 5s

// ddPCR thermal cycling for GN/GP/blaTEM (annealing 62 C, not 60 C).
heat triplexReactionMix at 95c for 10m
heat triplexReactionMix at 94c for 60m
heat triplexReactionMix at 98c for 10m

// ddpcrDetection: reads GN (HEX channel), GP (FAM-medium),
// blaTEM (FAM-high), empty clusters; returns composite signal.
// Gate: if ANY of the three targets is above LOD, signal > 0.
// Absolute concentrations reported as CPN/uL per target.
ddpcrSignal         = detect ddpcrDetection on triplexReactionMix for 10m

// ============================================================
// BB8 / BB9: Bacterial DNA + blaTEM ddPCR QC gate
// Pass (BB8): ddpcrSignal > 0 -> at least one DNA target above
//             LOD; carry forward to decision-tree classification.
// Fail (BB9): ddpcrSignal <= 0 -> no detectable bacterial DNA
//             or blaTEM (all set to 0 per paper Methods);
//             drain and flag sample as bacteria-negative.
// Both branches converge at BB10/BB11 (classifier gate).
// ============================================================

if (ddpcrSignal > 0) {
    // --------------------------------------------------------
    // STEP 9: Decision-tree classification using t1 measurements.
    //   Input features (from this run): GN CPN/uL, TNF-a pg/mL.
    //   Classifier: scikit-learn DecisionTreeClassifier,
    //   max_depth=2, 5-fold StratifiedKFold cross-validation,
    //   n_splits=5, standardised features.
    //   Thresholds: GN ~85 CPN/uL; TNF-a (group-specific).
    //   Accuracy: Group A 85.71%, Group B 92.31%, Group C 100%.
    //   Average k-fold prediction accuracy: >90%.
    //   decisionTreeClassification module abstracts the
    //   SciPy/scikit-learn offline analysis step, returning a
    //   binary outcome signal (classified vs unclassified).
    //
    //   Clinical interpretation (paper Fig. 5a):
    //     GN < 85 CPN/uL at t1 -> Group C (death, 100% accuracy)
    //     GN >= 85 CPN/uL + TNF-a threshold -> Group A or B
    //   Counterintuitive finding: lower GN at t1 correlates with
    //   higher probability of death (excessive immune response
    //   hypothesis: IL-6 increase, not bacterial load, drives
    //   mortality in this cohort).
    // --------------------------------------------------------

    classifierSignal = detect decisionTreeClassification on ddpcrSignal for 30s

    // =========================================================
    // BB10 / BB11: Decision-tree classification QC gate
    // Pass (BB10): classifierSignal > 0 -> patient successfully
    //              classified into Group A, B, or C with >90%
    //              accuracy; dispose result.
    // Fail (BB11): classifierSignal <= 0 -> insufficient signal
    //              or indeterminate (sample below thresholds on
    //              multiple axes); drain and flag for t2
    //              repeat sampling and longitudinal re-analysis.
    // Both branches converge at BB12 (finalCleanup).
    // =========================================================

    if (classifierSignal > 0) {
        dispose triplexReactionMix
    } else {
        drain triplexReactionMix
    }

    dispose classifierSignal

} else {
    drain triplexReactionMix
}

// ============================================================
// BB12: finalCleanup (terminal)
// Dispose the ddPCR signal droplet.
// Experiment ends; quantitative results (IL-6 pg/mL, TNF-a
// pg/mL, GN CPN/uL, GP CPN/uL, blaTEM CPN/uL) are logged
// offline by QuantaSoft Analysis Pro v1.0.596.
// ============================================================

dispose ddpcrSignal

// [terminal -- no further instructions; exit node for CFG]

module singleCellTrapDetection
module antibodyBindingDetection

manifest HybridomaCells
manifest TargetCells
manifest IMDM_Medium
manifest PBS
manifest PluronicF127
manifest HFE7500_Surfactant
manifest AlexaFluor647_SecondaryAb
manifest CellTrace_CFSE
manifest CalceinAM_RedOrange

// ============================================================
// An Automated Single-Cell Droplet-Digital Microfluidic
// Platform for Monoclonal Antibody Discovery.
// Ahmadi, Tran, Letourneau, Little, Fortin, Moraitis, Shih
// Small 2024, 20, 2308950
// DOI: 10.1002/smll.202308950
//
// Platform: Droplet-Digital (D2) microfluidics -- a three-layer
// hybrid device combining a digital microfluidic (DMF) electrode
// layer (Cr on glass, 7 um SU-8 dielectric), and three stacked
// PDMS-based microchannel devices:
//   Device 1 -- Trapping array (100 traps, 50 per side, 20 um
//               channel height, 50-75 um width, 7 um constriction;
//               each trap has 2 actuation electrodes + 1 ground).
//   Device 2 -- Flow-focusing droplet generator (target cells,
//               ~30 pL droplets, ~3 kHz throughput, Poisson
//               encapsulation).
//   Device 3 -- Co-planar binary electrode sorter (selects
//               single-target-cell droplets by CellTrace CFSE
//               fluorescence at 470 nm ex / 520 nm em).
//
// CELL LINES (provided by NRC Canada):
//   Hybridoma cells -- cultured in IMDM + 10% heat-inactivated
//     FBS + mouse IL-6 (1 ng/mL) + pen/strep; 37 C / 5% CO2;
//     passaged every 3 days at 8e6 cells/mL; loaded at 1e6/mL.
//   Target cells -- express membrane-bound antigen; cultured in
//     DMEM + 10% FBS + G418 (0.4 mg/mL); loaded at 1e6/mL.
//
// WORKFLOW SUMMARY (8 steps, Figure 2):
//   A. Target cells encapsulated in ~30 pL droplets (Device 2).
//   B. Single target-cell droplets sorted (Device 3).
//   C. Hybridoma cells loaded and trapped (Device 1).
//   D. In situ droplet generation around trapped hybridomas
//      (phase change: oil at 1 nL/s, electrodes at 32 Vrms /
//      15 kHz; droplet size 40-150 pL).
//   E. Target-cell droplets re-injected and merged with
//      hybridoma droplets in traps (32 Vrms / 15 kHz; highest
//      co-encapsulation efficiency: 95 +/- 3.2% at 5 nL/s).
//   F. Co-incubation on-chip for 30 min at room temperature.
//      Hybridoma secretes mAbs; antigen-specific mAbs bind
//      to target cell membrane-bound antigen.
//   G. Droplet disruption + PBS/Alexa Fluor 647 wash
//      (64 Vrms / 15 kHz; 96.8% fluorescence reduction in
//      one wash step; flow rate 1-5 nL/s).
//   H. Fluorescence detection: antigen-specific mAb droplets
//      are Alexa Fluor 647 positive (lex=627 nm, lem=665 nm).
//      Positive droplets collected by reverse-flow oil release
//      (4 nL/s) into a glass capillary filled with HFE7500.
//
// PERFORMANCE METRICS:
//   Single-cell trapping efficiency: 98 +/- 3.92% at 1 nL/s.
//   Co-encapsulation efficiency:     95 +/- 3.2% at 5 nL/s.
//   Droplet disruption efficiency:   ~100% at 32 Vrms / 1 nL/s.
//   Washing efficiency:              96.8% fluorescence reduction.
//   Cell retention post-wash:        96 +/- 9.6% (1-5 nL/s).
//   Selection rate (100:0 ratio):    94.00 +/- 1.41%.
//   Selection rate (1:50 ratio):     1.60% (rare-cell detection).
//
// NOTE ON DEVICE ABSTRACTION:
//   BioScript `dispense` abstracts reagent loading from
//   gas-tight Hamilton syringes driven by neMESYS pumps.
//   `mix` abstracts both channel-flow hydrodynamic trapping
//   events (Steps C, D) and electrode-actuated droplet
//   merging/washing events (Steps E, G). Duration values
//   reflect the dominant process time at each step.
//   `heat` abstracts the on-chip incubation at ambient
//   temperature (room temperature = 25 C, 30 min).
//   `detect` abstracts fluorescence imaging with the
//   Hamamatsu ORCA-Flash 4.0 camera and photon-counting head
//   (300 ms exposure; lex=627 nm, lem=665 nm for Alexa647).
//   Syringe pump flow-rate values and electrode voltages are
//   annotated in comments; they are not encoded as BioScript
//   primitives (not supported by lilott8/BioScript compiler).
//
// CFG STRUCTURE:
//   BB1  main                 -- Device priming; target-cell
//                                encapsulation (Device 2);
//                                single-cell sorting (Device 3);
//                                hybridoma trapping (Device 1);
//                                in situ droplet generation;
//                                droplet merge (co-encapsulation);
//                                incubation; wash; detection.
//   BB2  antibodyPass         -- antibodySignal > 0: antigen-
//                                specific mAb detected (Alexa
//                                Fluor 647 positive); collect
//                                droplet and dispose.
//   BB3  antibodyFail         -- antibodySignal <= 0: no specific
//                                mAb; non-binding hybridoma;
//                                drain droplet.
//   BB4  finalCleanup         -- terminal: dispose QC signal;
//                                experiment ends.
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prime Device 1 (trapping array) with 2% Pluronics
//         F-127 in PBS to reduce non-specific cell adhesion
//         to PDMS channel walls.
//         Protocol: flow PBS from inlet 3 at 50 nL/s for 5 min
//         (outlet 1 closed); reduce to 1 nL/s, open outlet 1.
//         NOTE: `mix` here abstracts a channel priming flow,
//         not a DMF electrode mixing step.
// ------------------------------------------------------------

primingPBS      = dispense 1 units of PBS
primingPluronic = dispense 1 units of PluronicF127
primedDevice    = mix primingPBS with primingPluronic for 5m

// ------------------------------------------------------------
// STEP 2: Prepare stained target cells for encapsulation.
//         Target cells resuspended in PBS + CellTrace CFSE
//         (5 uM, 1e6 cells/mL); stained 20 min at 37 C,
//         washed with PBS; resuspended in IMDM (10% FBS +
//         IL-6, no antibiotic, 1e6 cells/mL) for Device 2
//         loading.
//         NOTE: `heat` models the 20 min staining incubation.
// ------------------------------------------------------------

targetCells_raw  = dispense 1 units of TargetCells
cfseStain        = dispense 1 units of CellTrace_CFSE
stainedTarget    = mix targetCells_raw with cfseStain for 5s
heat stainedTarget at 37c for 20m

// Wash stained cells with PBS to remove excess dye.
washPBS          = dispense 1 units of PBS
washedTarget     = mix stainedTarget with washPBS for 2s

// Resuspend in IMDM for chip loading.
imdmForTarget    = dispense 1 units of IMDM_Medium
targetCells      = mix washedTarget with imdmForTarget for 5s

// ------------------------------------------------------------
// STEP 3 (Device 2): Encapsulate stained target cells in
//         ~30 pL droplets using flow-focusing droplet
//         generator. Throughput: ~3 kHz; Poisson distribution.
//         Oil: HFE7500 + 2% Ran Fluoro-surfactant.
//         NOTE: `mix` abstracts the flow-focusing encapsulation
//         of target cells in the PDMS microchannel device.
// ------------------------------------------------------------

oilPhase1           = dispense 1 units of HFE7500_Surfactant
targetCellDroplets  = mix targetCells with oilPhase1 for 2s

// ------------------------------------------------------------
// STEP 4 (Device 3): Sort single target-cell droplets using
//         co-planar binary electrode sorter. Fluorescence
//         at 470 nm ex / 520 nm em (CellTrace CFSE) used to
//         distinguish droplets with exactly 1 cell from
//         empty or multi-cell droplets. Sorted droplets
//         collected in a gas-tight glass syringe with HFE oil.
//         NOTE: `detect` abstracts the PMT-based fluorescence
//         counting used to trigger electrode actuation.
//         `singleCellTrapDetection` gates on droplets above
//         the single-cell threshold and below the two-cell
//         threshold (set in the in-house control software).
// ------------------------------------------------------------

sortSignal          = detect singleCellTrapDetection on targetCellDroplets for 10s

// Sort gate: only droplets containing exactly one target cell
// are collected; others are sent to waste.
if (sortSignal > 0) {
    // Single-target-cell droplet selected; hold for re-injection.
    // `targetSortDetection` pass -> droplet transferred to Device 1
    // via 0.014" OD / 0.006" ID tubing bridging Device 2 to Device 3.
    sortedTargetDroplets = mix targetCellDroplets with oilPhase1 for 1s
} else {
    drain targetCellDroplets
}

dispose sortSignal

// ------------------------------------------------------------
// STEP 5 (Device 1): Prime trapping array with IMDM cell
//         culture media containing hybridoma cells to reduce
//         cell adhesion. Hybridoma cells resuspended in IMDM
//         (10% FBS + IL-6, no antibiotic, 1e6 cells/mL).
//         Stained with CellTrace calcein red-orange AM prior
//         to loading.
// ------------------------------------------------------------

hybridoamCells_raw   = dispense 1 units of HybridomaCells
calceinStain         = dispense 1 units of CalceinAM_RedOrange
stainedHybridoma     = mix hybridoamCells_raw with calceinStain for 5s
heat stainedHybridoma at 37c for 20m

washPBS2             = dispense 1 units of PBS
washedHybridoma      = mix stainedHybridoma with washPBS2 for 2s

imdmForHybridoma     = dispense 1 units of IMDM_Medium
hybridoma_in_imdm    = mix washedHybridoma with imdmForHybridoma for 5s

// ------------------------------------------------------------
// STEP 6 (Device 1 -- Trapping): Load hybridoma cells into
//         the trapping array at 1-5 nL/s. Single cells are
//         hydrodynamically confined in 7 um constriction traps
//         via fluidic resistance (open trap resistance < bypass
//         channel; occupied trap blocks flow to next open trap).
//         Single-cell trapping efficiency: 98 +/- 3.92% at
//         1 nL/s (N=5 repeats, n=10 replicates per flow rate).
//         Device accommodates 100 traps (50 per serpentine side).
//         NOTE: `mix` abstracts the channel-flow hydrodynamic
//         trapping event. Duration (2s) models cell settling
//         at the 7 um constriction.
// ------------------------------------------------------------

trappingMix          = mix primedDevice with hybridoma_in_imdm for 2s

// Verify single-cell occupancy by fluorescence (calcein red-orange:
// lex=577 nm, lem=590 nm). `singleCellTrapDetection` confirms
// single occupancy before proceeding to in situ encapsulation.
trapOccupancySignal  = detect singleCellTrapDetection on trappingMix for 10s

if (trapOccupancySignal > 0) {
    imdmForHybridoma2 = dispense 1 units of IMDM_Medium
    trappedHybridoma = mix trappingMix with imdmForHybridoma2 for 1s
} else {
    drain trappingMix
}

dispose trapOccupancySignal

// ------------------------------------------------------------
// STEP 7 (Device 1 -- In situ droplet generation):
//         Phase change: IMDM cell culture medium replaced by
//         HFE7500 + 2% Ran Fluoro-surfactant oil flowing at
//         1 nL/s through the main channel. Electrodes beneath
//         each trap actuated at 32 Vrms / 15 kHz to shear off
//         aqueous phase and generate in situ droplets
//         (40-150 pL) encapsulating single trapped hybridoma
//         cells. Over 95% of droplets successfully generated
//         at 1 nL/s oil flow rate.
//         NOTE: `mix` abstracts the oil-phase flow + electrode
//         actuation that shears off the aqueous droplet.
//         Duration (4s) models the phase-change dwell time.
// ------------------------------------------------------------

oilPhase2            = dispense 1 units of HFE7500_Surfactant
hybridoamDroplet     = mix trappedHybridoma with oilPhase2 for 4s

// ------------------------------------------------------------
// STEP 8 (Device 1 -- Co-encapsulation / Merge):
//         Sorted single-target-cell droplets (from Step 4) are
//         re-injected into Device 1 from inlet 2 at 5 nL/s,
//         interleaved with oil spacer from a second inlet at
//         1 nL/s. When a target-cell droplet arrives at a
//         trap, the electrode beneath is actuated (32 Vrms /
//         15 kHz) to merge it with the in situ hybridoma
//         droplet. Co-encapsulation efficiency: 95 +/- 3.2%
//         at 5 nL/s re-injection flow rate (highest reported
//         without preliminary sorting of both cell types).
//         NOTE: `mix` abstracts the electrode-actuated droplet
//         merge event. Duration (1s) models the merge dwell time.
// ------------------------------------------------------------

oilSpacer            = dispense 1 units of HFE7500_Surfactant
spacedTargetDroplets = mix sortedTargetDroplets with oilSpacer for 1s
coEncapsulatedDroplet = mix hybridoamDroplet with spacedTargetDroplets for 1s

// ------------------------------------------------------------
// STEP 9 (On-chip incubation):
//         Merged two-cell droplets incubated on-chip for 30 min
//         at room temperature (25 C). During incubation:
//           - Hybridoma cells secrete monoclonal antibodies
//             into the confined droplet volume.
//           - Antigen-specific mAbs diffuse and bind to
//             membrane-bound antigens on co-encapsulated
//             target cells.
//           - Non-specific mAbs remain free in the droplet.
//         NOTE: `heat at 25c` models on-chip room-temperature
//         incubation. No external heating element used.
// ------------------------------------------------------------

heat coEncapsulatedDroplet at 25c for 30m

// ------------------------------------------------------------
// STEP 10 (Droplet disruption + washing):
//         PBS containing Alexa Fluor 647-conjugated goat
//         anti-mouse IgG (H+L) secondary antibody is flowed
//         into Device 1 main channel from inlet 2 at 1-5 nL/s.
//         Electrodes beneath traps actuated at 64 Vrms /
//         15 kHz to disrupt the droplet interface via
//         electrostatic force (field intensity 2-4 x 10^5 V/m).
//         Droplet contents (non-specific secreted mAbs) are
//         washed out through the constriction opening.
//         Hybridoma and target cells (held by antigen-antibody
//         bond) are retained in the trap.
//         Washing efficiency: 96.8% fluorescence reduction
//         after 1 wash step (~5 min total for 50 traps).
//         PBS/Alexa647 flow rate: 1-5 nL/s during wash;
//         reduced to 0.1 nL/s for droplet re-formation.
//         NOTE: `mix` abstracts the phase-exchange wash cycle.
//         `AlexaFluor647_SecondaryAb` manifest encodes the
//         PBS + Alexa Fluor 647 secondary antibody solution
//         (loaded from inlet 2 at the given flow rate).
// ------------------------------------------------------------

alexaFluorWash       = dispense 1 units of AlexaFluor647_SecondaryAb
washPBS3             = dispense 1 units of PBS
pbsAlexaSolution     = mix alexaFluorWash with washPBS3 for 2s

// Droplet disruption and wash: electrode actuation bursts
// the IMDM droplet interface; PBS/Alexa647 flows through
// the trap removing non-specific antibodies.
washedDroplet        = mix coEncapsulatedDroplet with pbsAlexaSolution for 5m

// Re-form oil droplet around the two cells after washing:
// reduce PBS/Alexa647 flow to 0.1 nL/s; increase HFE7500
// Ran-HFE oil flow back to 5 nL/s to generate a new PBS
// droplet encapsulating the two cells in situ.
oilPhase3            = dispense 1 units of HFE7500_Surfactant
reforumDroplet       = mix washedDroplet with oilPhase3 for 1s

// ------------------------------------------------------------
// STEP 11 (Fluorescence detection):
//         Trapping array imaged with Hamamatsu ORCA-Flash 4.0
//         (lex=627 nm / lem=665 nm, 300 ms exposure) using
//         Alexa Fluor 647 channel. Antigen-specific mAbs that
//         bound to target cell membrane are labelled by the
//         secondary antibody, generating a localised red
//         fluorescent signal around the target cell.
//         Non-specific mAbs were removed by washing and do not
//         generate signal. SNR significantly higher post-wash
//         for antigen-specific (binding) vs. non-specific
//         (non-binding) hybridoma droplets (P < 0.05).
//         The photon-counting head (PMT) is used to trigger
//         on-demand release of positive droplets.
//         `antibodyBindingDetection` module gates on
//         fluorescence signal intensity above background
//         (mean fluorescence of the cell > mean fluorescence
//         of the surrounding droplet).
// ------------------------------------------------------------

antibodySignal       = detect antibodyBindingDetection on reforumDroplet for 10s

// ============================================================
// BB2 / BB3: Antibody binding detection gate
// Pass (BB2): antibodySignal > 0 -> Alexa Fluor 647 signal
//             detected at target cell membrane; hybridoma
//             is producing antigen-specific mAb.
//             Droplet released via reverse oil flow (4 nL/s)
//             from outlet 1 into glass capillary (HFE7500)
//             for downstream characterisation/sequencing.
// Fail (BB3): antibodySignal <= 0 -> no specific binding;
//             non-specific mAb producer; droplet drained.
// Both branches converge at BB4 (finalCleanup).
// ============================================================

if (antibodySignal > 0) {
    // ------------------------------------------------------------
    // Recovery (pass path):
    // Positive droplet released by reverse oil flow (4 nL/s)
    // from outlet 1 (inlet 3 briefly opened to clear channel).
    // Droplet collected into glass capillary filled with HFE7500.
    // FC-40 (1 mL) added to PTFE membrane to disrupt surfactant-
    // stabilised emulsion; aqueous cell droplet absorbed by
    // membrane, then merged with 10-20 uL IMDM complete medium
    // and transferred to a well-plate for downstream expansion
    // and antibody characterisation assays.
    // NOTE: `mix` abstracts the capillary recovery and FC-40
    // wash; `dispose` marks handoff to downstream workflow.
    // ------------------------------------------------------------
    imdmRecovery   = dispense 1 units of IMDM_Medium
    recoveredCells = mix reforumDroplet with imdmRecovery for 1m
    dispose recoveredCells
} else {
    drain reforumDroplet
}

// ============================================================
// BB4: finalCleanup (terminal)
// Dispose the antibody detection QC signal droplet.
// Experiment ends; recovered cells proceed to off-chip
// antibody characterisation (sequencing, ELISA, etc.).
// ============================================================

dispose antibodySignal

// [terminal -- no further instructions; exit node for CFG]

module ddpcrDetection
module rtddpcrDetection

manifest HEK293T_Cells
manifest TM_Buffer_01X
manifest ProximityProbe1_CD147
manifest ProximityProbe2_CD147
manifest ConnectorOligonucleotide
manifest LigationSolution
manifest ProteaseSolution
manifest ddPCR_Supermix_Probes
manifest UniversalPCRAssay
manifest CD147_TaqManAssay_Probe2
manifest GoScript_RT_System
manifest RandomPrimers
manifest dNTPs
manifest MgCl2
manifest RNaseOUT
manifest NucleaseFreeWater

// ============================================================
// Digital Quantification of Proteins and mRNA in Single
// Mammalian Cells.
// Albayrak, Jordi, Zechner, Lin, Bichsel, Khammash, Tay.
// Molecular Cell 61, 914-924, March 17, 2016.
// DOI: http://dx.doi.org/10.1016/j.molcel.2016.02.030
//
// This BioScript file encodes the joint single-cell protein
// (digital PLA) and mRNA (two-step RT-ddPCR) quantification
// workflow for CD147 from single HEK293T cells.
//
// WORKFLOW OVERVIEW:
//   1. Single HEK293T cell is FACS-sorted into 3 uL of 0.1X
//      TM lysis buffer.
//   2. Lysate is split 1:2 -> 1 uL for mRNA (RT-ddPCR),
//      2 uL for protein (digital PLA).
//   3. Digital PLA arm: proximity probes bind CD147 protein;
//      connector oligonucleotide hybridises; ligation forms
//      dsDNA; protease digestion removes antibodies; dsDNA
//      quantified by ddPCR in 20,000 nanoliter droplets.
//   4. RT-ddPCR arm: two-step RT (GoScript at 42 C, 1 hr)
//      followed by ddPCR (40 cycles, 60 C annealing) using
//      TaqMan Probe 2 (Hs00174305_m1).
//   5. QC gates on both ddPCR readouts; results disposed or
//      drained accordingly.
//
// NOTE ON LYSATE SPLIT ABSTRACTION:
//   BioScript has no native split-by-ratio operator.
//   The 1 uL mRNA fraction and 2 uL protein fraction are
//   modelled as two independent dispense events from the same
//   manifest (TM_Buffer_01X used as the lysis carrier), each
//   representing the respective volume fraction of a single
//   lysed cell. This is consistent with the abstraction
//   pattern used in the reference .bs files for similar
//   multi-fraction workflows.
//
// NOTE ON TEMPERATURE / TIME TOKENS:
//   BioScript `heat` accepts temperatures in degrees C (e.g.
//   37c) and durations in seconds (s) or minutes (m).
//   All times are converted accordingly:
//     60 min probe adsorption  -> 60m
//     10 min ligation          -> 10m
//     10 min protease          -> 10m
//     15 min protease inact.   -> 15m
//      5 min primer annealing  ->  5m
//     60 min reverse transcript-> 60m
//     15 min RT inactivation   -> 15m
//     PCR cycling abstracted as heat step (40 cycles ~35 min) -> 35m
//
// NOTE ON ddPCR CYCLE ABSTRACTION:
//   40 PCR amplification cycles at 94 C/60 C are modelled as
//   a single `heat` step at 94c for 35m (approximate total
//   cycling time). The subsequent 98 C 10 min final extension
//   is modelled as heat at 98c for 10m. The initial 95 C 10
//   min hot-start is heat at 95c for 10m.
//
// NOTE ON MODULE SCOPE:
//   ddpcrDetection  -> digital PLA protein readout (counts
//                      dsDNA amplicons per uL, converted to
//                      protein copy numbers via calibration).
//   rtddpcrDetection -> RT-ddPCR mRNA readout (counts cDNA
//                       amplicons per uL, corrected for 87.6%
//                       RT recovery rate, reported as mRNA
//                       copies per cell).
//
// CFG STRUCTURE:
//   BB1  main           -- entry: cell lysis, lysate split,
//                          digital PLA arm, RT-ddPCR arm
//   BB2  proteinPass    -- proteinSignal > 0: CD147 protein
//                          detected above LOD (29,300 mol/cell
//                          in 2 uL fraction); dispose
//   BB3  proteinFail    -- proteinSignal <= 0: below LOD; drain
//   BB4  proteinJoin    -- join: mRNA QC gate follows
//   BB5  mRNAPass       -- mRNASignal > 0: CD147 mRNA detected
//                          above LOD (52.5 copies/cell); dispose
//   BB6  mRNAFail       -- mRNASignal <= 0: below LOD; drain
//   BB7  finalCleanup   -- terminal: dispose QC signals; end
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: FACS sort single HEK293T cell into 3 uL of 0.1X
//         TM lysis buffer.
//         DRAQ7 nuclear dye used to gate viable cells.
//         Tlr4-GFP expression used as sort marker (R4 gate).
//         Plate sealed immediately after sort and stored
//         at -80 C until processing.
//         `mix` here abstracts the sort-and-lyse event;
//         the cell contacts 0.1X TM buffer in the well,
//         releasing intracellular contents (protein + mRNA).
// ------------------------------------------------------------

cellLysate     = dispense 1 units of TM_Buffer_01X
sortedCell     = dispense 1 units of HEK293T_Cells
lysate         = mix sortedCell with cellLysate for 5m

// ------------------------------------------------------------
// STEP 2: Split lysate into two fractions.
//         PROTEIN FRACTION (2/3 of lysate -> 2 uL):
//           carried into the digital PLA arm below.
//         mRNA FRACTION (1/3 of lysate -> 1 uL):
//           carried into the RT-ddPCR arm below.
//
//         BioScript abstraction: two independent variables
//         derived from the same lysate represent the two
//         physical fractions. No array split is used (see
//         note on compiler constraint above).
// ------------------------------------------------------------

// Protein fraction (2 uL) -- modelled as primary lysate
proteinFraction = dispense 2 units of TM_Buffer_01X
proteinLysate   = mix lysate with proteinFraction for 5s

// mRNA fraction (1 uL) -- modelled as secondary lysate
mRNAFraction    = dispense 1 units of TM_Buffer_01X
mRNALysate      = mix lysate with mRNAFraction for 5s

// ============================================================
// DIGITAL PLA ARM (CD147 Protein Quantification)
// ============================================================

// ------------------------------------------------------------
// STEP 3: Proximity probe adsorption.
//         2 uL protein lysate + 2 uL probe solution
//         (400 pM each proximity probe -> 200 pM final).
//         Proximity probe 1 and probe 2 are pre-mixed into
//         a single assay probe solution; both recognise
//         distinct epitopes of CD147 simultaneously.
//         Incubated at 37 C for 60 min (probe adsorption).
//
//         When both probes bind the same CD147 molecule,
//         their tethered oligonucleotides come into close
//         proximity (~40 nm) enabling connector hybridisation.
// ------------------------------------------------------------

probesSolution  = dispense 1 units of ProximityProbe1_CD147
probe2Disp      = dispense 1 units of ProximityProbe2_CD147
probesMix       = mix probesSolution with probe2Disp for 5s

probeBindingRxn = mix proteinLysate with probesMix for 60m
heat probeBindingRxn at 37c for 60m

// ------------------------------------------------------------
// STEP 4: Connector oligonucleotide hybridisation and ligation.
//         96 uL ligation solution (containing connector oligo,
//         ligase, and ligation buffer) added to the 4 uL
//         probe-bound sample -> 25-fold dilution.
//         The connector oligonucleotide hybridises to the
//         paired probe oligonucleotides, and T4 DNA ligase
//         seals the nicks, forming a dsDNA molecule encoding
//         the protein detection event.
//         Incubated at 37 C for 10 min.
// ------------------------------------------------------------

connectorOligo  = dispense 1 units of ConnectorOligonucleotide
ligationSoln    = dispense 1 units of LigationSolution
ligationPrep    = mix connectorOligo with ligationSoln for 5s

ligationRxn     = mix probeBindingRxn with ligationPrep for 10m
heat ligationRxn at 37c for 10m

// ------------------------------------------------------------
// STEP 5: Protease digestion to remove antibody-oligonucleotide
//         conjugates.
//         2 uL diluted protease solution added to ligation mix.
//         Incubated at 37 C for 10 min to digest antibodies,
//         leaving only the dsDNA amplicons in solution.
//         Protease inactivated at 95 C for 15 min.
// ------------------------------------------------------------

proteaseDisp    = dispense 1 units of ProteaseSolution
afterProtease   = mix ligationRxn with proteaseDisp for 10m
heat afterProtease at 37c for 10m
heat afterProtease at 95c for 15m

// ------------------------------------------------------------
// STEP 6: ddPCR droplet generation and amplification.
//         9 uL of PLA solution + 10 uL 2X ddPCR Supermix for
//         Probes + 1 uL 20X Universal PCR Assay -> 20 uL total.
//         Emulsified by QX100 Droplet Generator into ~20,000
//         nanoliter droplets (~0.85 nL each) at limiting
//         dilution (each droplet contains 0 or 1 dsDNA).
//
//         PCR temperature schedule:
//           95 C for 10 min (hot-start activation)
//           40 cycles: 94 C 30 s / 60 C 1 min
//           98 C for 10 min (final denaturation)
//         Ramp speed: 2.5 C/s.
//
//         Fluorescence read on QX100 Droplet Reader;
//         QuantaSoft v1.3.2.0 converts positive/negative
//         droplet counts to DNA concentration using Poisson
//         statistics: C = (1000/Vd) * ln(1 - P/R).
//         Absolute protein counts derived via calibration curve
//         (CD147: y = 0.0142x + 12.4, R2 = 0.9997;
//          LOD = 86 proteins/uL ddPCR solution = 16.2 fM;
//          sensitivity = 70 proteins per DNA count).
// ------------------------------------------------------------

ddpcrSupermix   = dispense 1 units of ddPCR_Supermix_Probes
universalPCR    = dispense 1 units of UniversalPCRAssay
ddpcrMix        = mix ddpcrSupermix with universalPCR for 5s
plasDdpcrRxn    = mix afterProtease with ddpcrMix for 5s

// Hot-start activation
heat plasDdpcrRxn at 95c for 10m

// 40 amplification cycles (94 C 30s / 60 C 1 min; ~35 min total)
heat plasDdpcrRxn at 94c for 35m

// Final denaturation / signal stabilisation
heat plasDdpcrRxn at 98c for 10m

// Detect: ddPCR droplet fluorescence readout
// ddpcrDetection module abstracts QX100 reader + QuantaSoft
// concentration calculation and calibration curve conversion.
proteinSignal   = detect ddpcrDetection on plasDdpcrRxn for 30s

// ============================================================
// BB2 / BB3: Protein QC gate
// Pass (BB2): proteinSignal > 0 -> CD147 protein detected
//             above assay LOD (29,300 molecules/cell in 2 uL
//             fraction after 113-fold dilution in workflow);
//             dispose processed PLA solution.
// Fail (BB3): proteinSignal <= 0 -> below LOD; drain.
// Both branches converge at BB4 (proteinJoin).
// ============================================================

if (proteinSignal > 0) {
    dispose plasDdpcrRxn
} else {
    drain plasDdpcrRxn
}

// ============================================================
// BB4: proteinJoin
// Dispose protein QC signal. Control falls into
// the RT-ddPCR mRNA quantification arm (BB5/BB6).
// ============================================================

dispose proteinSignal

// ============================================================
// RT-ddPCR ARM (CD147 mRNA Quantification)
// Two-step protocol: GoScript RT followed by ddPCR.
// TaqMan Gene Expression Assay Hs00174305_m1 (Probe 2).
// 40 amplification cycles.
// ============================================================

// ------------------------------------------------------------
// STEP 7: Primer annealing for reverse transcription.
//         1 uL mRNA lysate + 1 uL random primer solution
//         + nuclease-free water to 4.95 uL.
//         Incubated at 70 C for 5 min (denature RNA secondary
//         structure), then immediately chilled on ice for 5 min.
// ------------------------------------------------------------

randomPrimersDisp  = dispense 1 units of RandomPrimers
waterDisp          = dispense 1 units of NucleaseFreeWater
primerAnnealMix    = mix mRNALysate with randomPrimersDisp for 5s
primerAnnealFull   = mix primerAnnealMix with waterDisp for 5s

// Denaturation at 70 C for 5 min
heat primerAnnealFull at 70c for 5m

// Ice chilling: modelled as 4 C for 5 min
heat primerAnnealFull at 4c for 5m

// ------------------------------------------------------------
// STEP 8: Reverse transcription master mix assembly.
//         GoScript Reverse Transcription System:
//           1X GoScript reaction buffer
//           GoScript RT (1/20 dilution from stock)
//           1 U/uL RNaseOUT ribonuclease inhibitor
//           0.5 mM each dNTP
//           3.1 mM MgCl2
//         Final RT volume: 9 uL.
// ------------------------------------------------------------

goScriptRT      = dispense 1 units of GoScript_RT_System
rnaseOut        = dispense 1 units of RNaseOUT
dntpsDisp       = dispense 1 units of dNTPs
mgcl2Disp       = dispense 1 units of MgCl2

rtBufferMix     = mix goScriptRT with rnaseOut for 5s
rtReagentsMix   = mix rtBufferMix with dntpsDisp for 5s
rtMasterMix     = mix rtReagentsMix with mgcl2Disp for 5s

rtFullRxn       = mix primerAnnealFull with rtMasterMix for 5s

// ------------------------------------------------------------
// STEP 9: Two-step reverse transcription.
//         Step A: 25 C for 5 min (random primer annealing).
//         Step B: 42 C for 60 min (cDNA synthesis).
//         Step C: 70 C for 15 min (RT inactivation).
//
//         Expected recovery: 87.6% of theoretical CD147 mRNA
//         signal (measured against T7 in-vitro transcribed
//         CD147 mRNA standard at A260). All single-cell
//         RT-ddPCR reads corrected by this recovery rate.
//         Corrected LOD: 52.5 copies/cell (87 aM).
// ------------------------------------------------------------

// Step A: primer annealing
heat rtFullRxn at 25c for 5m

// Step B: cDNA synthesis
heat rtFullRxn at 42c for 60m

// Step C: RT enzyme inactivation
heat rtFullRxn at 70c for 15m

// ------------------------------------------------------------
// STEP 10: ddPCR of cDNA.
//          cDNA solution + 10 uL 2X ddPCR Supermix for Probes
//          + 1 uL 20X CD147 TaqMan Gene Expression Assay
//          (Probe 2, Hs00174305_m1; FAM/MGB; spanning
//          exon-exon junction to exclude genomic DNA).
//          Final volume: 20 uL.
//          Emulsified -> ~20,000 droplets.
//
//          PCR temperature schedule:
//            95 C for 10 min (hot-start)
//            40 cycles: 94 C 30 s / 60 C 1 min
//            98 C for 10 min (final denaturation)
//          Ramp speed: 2.5 C/s.
//
//          Positive/negative droplets counted by QX100.
//          DNA concentration: C = (1000/Vd) * ln(1 - P/R).
//          mRNA copies per cell = C * volume * (1/recovery_rate)
//          where recovery_rate = 0.876 (87.6%).
//          Expected: mean 188.2 +/- 90 CD147 mRNA copies/cell.
//          Fluorescence threshold: 3200 RFU (Probe 2, 40 cycles).
// ------------------------------------------------------------

ddpcrSupermix2  = dispense 1 units of ddPCR_Supermix_Probes
taqmanProbe2    = dispense 1 units of CD147_TaqManAssay_Probe2
rtDdpcrMix      = mix ddpcrSupermix2 with taqmanProbe2 for 5s
rtDdpcrRxn      = mix rtFullRxn with rtDdpcrMix for 5s

// Hot-start activation
heat rtDdpcrRxn at 95c for 10m

// 40 amplification cycles (~35 min total for 94 C/60 C cycling)
heat rtDdpcrRxn at 94c for 35m

// Final denaturation
heat rtDdpcrRxn at 98c for 10m

// Detect: RT-ddPCR droplet fluorescence readout
// rtddpcrDetection module abstracts QX100 reader + QuantaSoft
// mRNA copy number calculation + 87.6% RT recovery correction.
mRNASignal      = detect rtddpcrDetection on rtDdpcrRxn for 30s

// ============================================================
// BB5 / BB6: mRNA QC gate
// Pass (BB5): mRNASignal > 0 -> CD147 mRNA detected above
//             corrected LOD (52.5 copies/cell = 87 aM);
//             dispose processed RT-ddPCR solution.
// Fail (BB6): mRNASignal <= 0 -> below LOD; drain.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (mRNASignal > 0) {
    dispose rtDdpcrRxn
} else {
    drain rtDdpcrRxn
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose both QC signal droplets. Experiment ends.
// Protein and mRNA copy numbers are now available for:
//   - Spearman correlation analysis (rho = 0.10 across cells)
//   - Gamma distribution fitting to mRNA distribution
//   - Stochastic two-state model parameterisation via
//     moment-based MCMC inference (Zechner et al., 2012)
//   - Transcription burst size (~40 mRNA/burst), burst rate
//     (3.78/day), translation ratio (~1000 proteins/mRNA)
// ============================================================

dispose mRNASignal

// [terminal -- no further instructions; exit node for CFG]

module spermCountDetection
module libraryQCDetection

manifest SpermAliquot
manifest SpermCountAliquot_Decondensed
manifest PBS
manifest BufferSMT
manifest BufferDB_Base
manifest Heparin_10mM
manifest BME_100mM
manifest Heparinase
manifest SYBRGreenI_10X
manifest GemCodeReagentMix
manifest GemCodePolymerase
manifest PrimerReleaseAgent
manifest GemCodeBeads
manifest UltrapureWater
manifest DropletGenerationOil

// ============================================================
// Sperm-seq wet lab protocol: sperm preparation and
// droplet-based sequencing library generation.
// Bell, Mello, McCarroll. Research Square (preprint), 2020.
// DOI: https://doi.org/10.21203/rs.3.pex-823/v1
//
// Technology: High-throughput droplet-based single-sperm
// sequencing (Sperm-seq). Capable of generating thousands
// of cell-barcoded single-sperm libraries in one run.
// Droplet platform: 10X Genomics GemCode (Option 1).
//
// PROTOCOL OVERVIEW:
//   Phase 1 (Steps 1-8):   Sperm preparation (~3.5 h)
//     - PBS wash x2 (400g, 4C, 10 min)
//     - Resuspend in Buffer SMT
//     - 3x freeze-thaw cycles (liquid nitrogen / fist-thaw)
//     - Buffer DB decondensation (37C, 45 min, heparin + BME)
//     - Heparinase treatment (RT, 2 h)
//   Phase 2 (Steps 9-10):  Sperm quantification (~15 min)
//     - SYBR Green I fluorescent staining (1:100 dilution)
//     - Hemocytometer count under green fluorescent light
//   Phase 3 (Steps 11-17): Library generation (1-3 days)
//     - Dilute sperm to 10,833 cells in 5 uL
//     - GemCode master mix assembly
//     - Droplet generation on GemCode Chip
//
// COMPILER CONSTRAINTS APPLIED:
//   - Duration tokens: `s` and `m` only (no `h`).
//     All durations converted: 45 min = 45m; 120 min = 120m.
//   - `heat` is in-place; result is NOT assigned to a variable.
//   - `detect` results are assigned once and never reassigned.
//   - No loop constructs; freeze-thaw cycles unrolled explicitly
//     as 3 independent heat/thaw pairs (3x liquid N2 / thaw).
//   - Variables consumed by `mix` (gate-consumed) are not reused.
//   - `drain` used for failed QC paths; `dispose` for pass paths.
//   - No variable alias assignments for gate-consumed variables.
//
// DATAFLOW DESIGN -- COUNTING ALIQUOT ABSTRACTION:
//   BioScript has no `split` operation. The manuscript (Step 13)
//   physically pipettes 1 uL from the decondensed tube into the
//   SYBR stain before the bulk stock is used for library prep.
//   This partial-volume sub-sample cannot be modelled as a fork
//   of spermDecondensed under the use-once type system.
//
//   Resolution: spermDecondensed flows unbroken into the library
//   path (the primary, continuing dataflow -- Steps 11 onward).
//   The 1 uL counting sub-sample is represented by a single
//   dispense of SpermCountAliquot_Decondensed, a manifest that
//   explicitly names the physical source (post-heparinase
//   decondensed stock) while satisfying use-once. The prep chain
//   (Steps 1-8) is NOT a dead end: spermDecondensed is consumed
//   by Step 11 (dilution), preserving end-to-end dataflow.
//
// CFG STRUCTURE:
//   BB1  main              -- sperm prep, quantification,
//                             master mix assembly
//   BB2  countPass         -- spermCountSignal > 0: sufficient
//                             cells counted; proceed to library
//   BB3  countFail         -- spermCountSignal <= 0: insufficient
//                             cell count; drain stain aliquot
//   BB4  countJoin         -- join: library generation branch
//   BB5  libraryPass       -- libraryQCSignal > 0: valid library;
//                             dispose
//   BB6  libraryFail       -- libraryQCSignal <= 0: failed; drain
//   BB7  finalCleanup      -- terminal: dispose QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Thaw sperm aliquot (>=250,000 cells, typically 10 uL)
//   at room temperature. Quick spin and transfer to nonstick
//   1.5 mL tube.
// ------------------------------------------------------------

spermRaw       = dispense 1 units of SpermAliquot

// ------------------------------------------------------------
// STEP 2: First PBS wash.
//   Spin 400g, 4C, 10 min. Remove supernatant. Resuspend in
//   10 uL PBS. Modelled as mix (resuspension) followed by
//   heat at 4c for 10m (centrifugation at 4C).
//   NOTE: `heat at 4c` abstracts cold centrifugation; in-place
//   on spermPellet1, no new variable produced.
// ------------------------------------------------------------

pbsWash1       = dispense 1 units of PBS
spermPellet1   = mix spermRaw with pbsWash1 for 30s

heat spermPellet1 at 4c for 10m

// ------------------------------------------------------------
// STEP 3: Second PBS wash.
//   Remove supernatant from first wash. Resuspend pellet in
//   10 uL PBS. Spin again at 400g, 4C, 10 min.
//   Remove supernatant.
// ------------------------------------------------------------

pbsWash2       = dispense 1 units of PBS
spermPellet2   = mix spermPellet1 with pbsWash2 for 30s

heat spermPellet2 at 4c for 10m

// ------------------------------------------------------------
// STEP 4: Resuspend sperm pellet in Buffer SMT (2.5 uL).
//   Buffer SMT (freeze-thaw buffer): 250 mM sucrose, 5 mM
//   MgCl2, 10 mM Tris pH 7.5. Protects sperm during freeze-
//   thaw cycles by stabilising membrane osmolarity.
// ------------------------------------------------------------

bufferSMT      = dispense 1 units of BufferSMT
spermInSMT     = mix spermPellet2 with bufferSMT for 30s

// ------------------------------------------------------------
// STEP 5: Freeze-thaw cycles x3 (liquid nitrogen / fist-thaw).
//   Protocol: submerge tube in liquid nitrogen 5-10 s, uncap
//   to de-pressurise, hold in fist until thawed. Repeat 3x.
//   Modelled as alternating heat at 4c (freeze) / 37c (thaw)
//   pairs. Each cycle = 10s freeze + 30s thaw.
//   NOTE: `heat` is in-place on spermInSMT (no assignment).
//   3 cycles unrolled explicitly (no loop constructs).
//
//   CYCLE 1
// ------------------------------------------------------------

heat spermInSMT at 4c for 10s
heat spermInSMT at 37c for 30s

// CYCLE 2
heat spermInSMT at 4c for 10s
heat spermInSMT at 37c for 30s

// CYCLE 3
heat spermInSMT at 4c for 10s
heat spermInSMT at 37c for 30s

// ------------------------------------------------------------
// STEP 6: Prepare Buffer DB with heparin and BME.
//   Buffer DB (salt decondensation buffer): 113 mM KCl,
//   12.5 mM KH2PO4, 2.5 mM Na2HPO4, 2.5 mM MgCl2, 20 mM
//   Tris pH 7.5. Freshly add heparin (1.5 uL of 10 mM) and
//   BME (2 uL of 100 mM) per 100 uL Buffer DB (4 samples).
//   Heparin prevents DNA aggregation; BME reduces disulfide
//   bonds in protamine to release sperm chromatin.
//   Modelled as two sequential mix steps (heparin first,
//   then BME into the buffered heparin).
// ------------------------------------------------------------

bufferDBBase   = dispense 1 units of BufferDB_Base
heparinStock   = dispense 1 units of Heparin_10mM
bufferDBHep    = mix bufferDBBase with heparinStock for 10s

bmeStock       = dispense 1 units of BME_100mM
bufferDBReady  = mix bufferDBHep with bmeStock for 10s

// ------------------------------------------------------------
// STEP 7: Add 22.5 uL Buffer DB (with heparin + BME) to each
//   sperm sample. Incubate at 37C for 45 min.
//   This step decondenses sperm chromatin by reducing protamine
//   disulfide crosslinks (BME) and preventing heparin-mediated
//   aggregation. Modelled as mix (addition) + heat 37c 45m.
//   NOTE: `heat` in-place on spermDecondensing.
// ------------------------------------------------------------

spermDecondensing = mix spermInSMT with bufferDBReady for 30s

heat spermDecondensing at 37c for 45m

// ------------------------------------------------------------
// STEP 8: Add heparinase and incubate at room temperature 2 h.
//   Thaw heparinase (0.1 units/uL) on ice during last half of
//   37C incubation. Add 5 uL freshly-thawed heparinase to
//   remove heparin, which would otherwise inhibit downstream
//   PCR amplification in library generation.
//   Mix gently (pipette). Incubate RT 2 h (120 min).
//   NOTE: `heat` at 25c for 120m models RT incubation.
//   After this step, spermDecondensed is the completed prepared
//   sample. It flows directly into the library dilution (Step 11),
//   preserving the end-to-end prep-to-library dataflow.
// ------------------------------------------------------------

heparinaseEnz    = dispense 1 units of Heparinase
spermDecondensed = mix spermDecondensing with heparinaseEnz for 10s

heat spermDecondensed at 25c for 120m

// ------------------------------------------------------------
// STEP 9: Prepare 1:100 SYBR Green I stain for cell counting.
//   Manuscript Step 13: "Generate a DNA-stained 1:100 dilution
//   of sperm by combining 1 uL sperm mixture, 10 uL 10X SYBR I,
//   and 89 uL PBS." The 1 uL sub-sample is physically pipetted
//   from the decondensed tube before the bulk is used for library.
//
//   ABSTRACTION NOTE: BioScript has no split operation. The 1 uL
//   sub-sample is modelled as SpermCountAliquot_Decondensed --
//   a manifest whose name explicitly identifies its physical
//   source (the post-heparinase decondensed stock). The bulk
//   stock (spermDecondensed) continues unmodified into Step 11.
//   This is the minimal honest abstraction available under the
//   use-once type system.
//
//   Incubate stain in dark at RT for 5-10 min (modelled as 7m).
// ------------------------------------------------------------

sybrGreen      = dispense 1 units of SYBRGreenI_10X
pbsForStain    = dispense 1 units of PBS
sybrDiluent    = mix sybrGreen with pbsForStain for 10s

countAliquot   = dispense 1 units of SpermCountAliquot_Decondensed
stainedSperm   = mix countAliquot with sybrDiluent for 7m

// ------------------------------------------------------------
// STEP 10: Count sperm on Fuchs-Rosenthal hemocytometer.
//   Load 20 uL stained sperm into C-chip hemocytometer.
//   Count sperm in 5 big squares under green fluorescent light.
//   Decondensed sperm appear as large bright fluorescent circles.
//   Concentration (cells/uL) = count in 5 squares x 100.
//   Target: 10,833 cells in 5 uL for GemCode loading.
//   Modelled as detect using spermCountDetection module.
// ------------------------------------------------------------

spermCountSignal = detect spermCountDetection on stainedSperm for 5m

// ============================================================
// BB2 / BB3: Sperm count QC gate
// Pass (BB2): spermCountSignal > 0 -> sufficient cell count;
//             dispose stain aliquot, proceed to library.
// Fail (BB3): spermCountSignal <= 0 -> insufficient count
//             (decondensation failed or too few cells); drain.
// Both branches converge at BB4 (countJoin).
// ============================================================

if (spermCountSignal > 0) {
    dispose stainedSperm
} else {
    drain stainedSperm
}

// ============================================================
// BB4: countJoin
// Dispose count QC signal. Control falls into library
// generation branch (BB5/BB6).
// ============================================================

dispose spermCountSignal

// ------------------------------------------------------------
// STEP 11: Dilute spermDecondensed to 10,833 cells in 5 uL.
//   spermDecondensed is the direct output of the full prep
//   chain (Steps 1-8). This is the primary consumption of
//   the prepared sample -- the main dataflow is intact.
//   Target loading for GemCode droplet generator to recover
//   ~100-1000 barcoded single-sperm libraries per run.
// ------------------------------------------------------------

dilutionWater  = dispense 1 units of UltrapureWater
spermDiluted   = mix spermDecondensed with dilutionWater for 30s

// ------------------------------------------------------------
// STEP 12: Assemble GemCode master mix.
//   Per sample: 32.5 uL GemCode reagent mix + 1.5 uL primer
//   release agent + 9.2 uL GemCode polymerase + 16.8 uL
//   ultrapure water. Total: 60 uL master mix per sample.
//   Assembled as sequential mixes reflecting component addition
//   order in the protocol.
// ------------------------------------------------------------

reagentMix     = dispense 1 units of GemCodeReagentMix
primerAgent    = dispense 1 units of PrimerReleaseAgent
polymerase     = dispense 1 units of GemCodePolymerase
mmWater        = dispense 1 units of UltrapureWater

mmStep1        = mix reagentMix with primerAgent for 5s
mmStep2        = mix mmStep1 with polymerase for 5s
masterMix      = mix mmStep2 with mmWater for 10s

// ------------------------------------------------------------
// STEP 13: Combine sperm with master mix.
//   Add 60 uL master mix to sperm sample (5 uL). Pipette
//   gently with wide-bore tips to prevent shearing decondensed
//   sperm chromatin. Total sample volume: 65 uL.
// ------------------------------------------------------------

spermMasterMix = mix spermDiluted with masterMix for 30s

// ------------------------------------------------------------
// STEP 14: Prepare GemCode beads.
//   Vortex GemCode beads at full speed for 25 s.
//   Dilute 1:11 in ultrapure water (>=90 uL per sample).
//   Two sequential mix steps chain to accumulate dilution
//   water (compiler ignores multi-unit volume scalars).
// ------------------------------------------------------------

gemBeads       = dispense 1 units of GemCodeBeads
beadDilWater1  = dispense 1 units of UltrapureWater
beadDilWater2  = dispense 1 units of UltrapureWater

beadMix1       = mix gemBeads with beadDilWater1 for 25s
beadsDiluted   = mix beadMix1 with beadDilWater2 for 10s

// ------------------------------------------------------------
// STEP 15: Load GemCode chip for droplet generation.
//   Sample well: 60 uL sperm+master mix.
//   Bead well: 85 uL 1:11 diluted GemCode beads.
//   Oil well: 150 uL droplet generation oil.
//   Modelled as sequential mix of sample + beads + oil.
//   GemCode controller partitions into GEMs (Gel Bead in
//   Emulsions) where single sperm cells are barcoded.
// ------------------------------------------------------------

dropletOil     = dispense 1 units of DropletGenerationOil
chipInput1     = mix spermMasterMix with beadsDiluted for 10s
chipLoaded     = mix chipInput1 with dropletOil for 10s

// ------------------------------------------------------------
// STEP 16: GEM incubation and library construction.
//   GemCode controller generates barcoded GEMs. Post-GEM
//   incubation at 37C amplifies barcoded sperm genomic DNA.
//   Library kit completes adapter ligation and indexing
//   (GemCode User Guide Rev C Steps 5.36-6.2.6).
//   Modelled as heat at 37c for 180m (3h GEM incubation).
//   libraryQCDetection abstracts Bioanalyzer/qPCR QC step.
// ------------------------------------------------------------

heat chipLoaded at 37c for 180m

libraryQCSignal = detect libraryQCDetection on chipLoaded for 30s

// ============================================================
// BB5 / BB6: Library QC gate
// Pass (BB5): libraryQCSignal > 0 -> valid sequencing library
//             (correct fragment size, sufficient yield); dispose.
// Fail (BB6): libraryQCSignal <= 0 -> library prep failed
//             (poor GEM generation or amplification); drain.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (libraryQCSignal > 0) {
    dispose chipLoaded
} else {
    drain chipLoaded
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose library QC signal. Experiment ends.
// Sequencing proceeds off-chip on Illumina sequencer per
// 10X Genomics instructions (Bell et al. Nature 2020 pipeline).
// ============================================================

dispose libraryQCSignal

// [terminal -- no further instructions; exit node for CFG]

module fluorescenceDetection
module tracerFluorescenceDetection
module mmpActivityDetection

manifest PBS
manifest PluronicF127
manifest AlexaFluor546_Tracer
manifest MMPBuffer
manifest MMP9_Enzyme
manifest FRET_MMP_Substrate
manifest CellularSupernatant_Stimulated
manifest CellularSupernatant_Untreated
manifest HFE7500_FluorocarbonOil
manifest FluorocarbonSurfactant

// ============================================================
// Enhancing Protease Activity Assay in Droplet-Based
// Microfluidics Using a Biomolecule Concentrator
// Chen, Sarkar, Song, Miller, Kim, Griffith, Lauffenburger, Han
// J. Am. Chem. Soc. 2011, 133(27), 10368-10371.
// DOI: 10.1021/ja2036628
//
// Platform: Integrated PDMS chip combining a nanofluidic
// biomolecule concentrator (ion concentration polarization,
// ICP) and a flow-focusing droplet generator.
//
// Concentrator: Polymeric nanoporous ion-selective junctions
// between microchannels. +50V applied to trap and accumulate
// negatively charged biomolecules into a pL-scale plug
// (~100-fold local concentration enhancement). Voltage off
// releases the plug downstream.
//
// Droplet generator: Flow-focusing geometry with HFE7500
// fluorocarbon oil as carrier fluid. Droplet volume ~40 pL,
// generation rate ~2.5 kHz. Biocompatible surfactant
// stabilises water-in-oil emulsion.
//
// Assay: FRET-based polypeptide MMP substrate fluoresces
// upon cleavage by MMP-9. Reaction monitored per-droplet
// by time-lapse fluorescence.
//
// Sample: Diluted conditioned media from mouse embryonic
// fibroblasts (MEF), stimulated and untreated. < 25 uL
// total sample consumed.
//
// Key results:
//   - ~10-fold reduction in assay reaction time.
//   - ~100-fold reduction in sample volume vs. conventional.
//   - kcat/Km = 7.81e4 M^-1 s^-1 for MMP-9 (recombinant).
//   - Stimulated MEF: (kcat/KM)[E] = 1.61e-4 s^-1
//   - Untreated  MEF: (kcat/KM)[E] = 4.68e-5 s^-1
//
// NOTE ON ICP CONCENTRATOR ABSTRACTION:
// BioScript has no native electrokinetic or field-gradient
// primitive. The concentration step is modelled as a `mix`
// of the enzyme/tracer sample with a buffer stream across
// the nanoporous junction, followed by a `heat` step at
// room temperature to represent the timed voltage-on
// accumulation phase (0.03 uL/min flow, ~50 V, tunable
// concentration time). The `heat` duration encodes the
// accumulation time that sets the ~100-fold plug enhancement.
// Voltage-off plug release is implicit at the end of the
// heat block; downstream dispersion to ~20-fold at
// encapsulation is a physical effect not separately modelled.
//
// NOTE ON DROPLET ENCAPSULATION ABSTRACTION:
// The flow-focusing droplet generator is modelled as a `mix`
// of the aqueous assay plug with the fluorocarbon oil phase.
// Each `mix` with oil represents one encapsulation event
// producing a monodisperse droplet population (~40 pL).
// Parallel droplets at different enzyme concentrations
// (arising from the Gaussian plug shape) are represented
// as separate scalar variables.
//
// NOTE ON SAMPLE VOLUME:
// All `dispense` units represent fractional microlitres
// consistent with the chip-scale flow rates described.
// Total aqueous volume < 25 uL across all conditions.
//
// CFG STRUCTURE:
//   BB1  main                -- device priming; concentrator
//                               loading; plug release; droplet
//                               encapsulation; MMP-9 assay
//   BB2  assayPass           -- assaySignal > 0: valid MMP
//                               activity detected; dispose
//   BB3  assayFail           -- assaySignal <= 0: no activity;
//                               drain
//   BB4  assayJoin           -- join: cellular supernatant branch
//   BB5  cellAssayPass       -- cellSignal > 0: valid proteolysis
//                               detected; dispose
//   BB6  cellAssayFail       -- cellSignal <= 0: no signal; drain
//   BB7  finalCleanup        -- terminal: dispose QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prime device channels with 2% Pluronics F-127 in
//         PBS for surface passivation. Reduces nonspecific
//         adsorption of biomolecules to PDMS channel walls
//         and droplet interfaces.
// ------------------------------------------------------------

primingPBS      = dispense 1 units of PBS
primingPluronic = dispense 1 units of PluronicF127
primingMix      = mix primingPBS with primingPluronic for 5m

// ------------------------------------------------------------
// STEP 2: Prepare enzyme sample stream (middle channel).
//         MMP-9 at 0.2 nM in MMP buffer. A fluorescent tracer
//         (Alexa Fluor-546 phalloidin, ex 561 nm / em 572 nm)
//         is co-loaded to monitor the concentration plug in
//         real time and infer local enzyme concentration from
//         tracer fluorescence intensity.
//         Flow rate: 0.03 uL/min (middle channel).
// ------------------------------------------------------------

mmpBuffer       = dispense 1 units of MMPBuffer
mmp9Enzyme      = dispense 1 units of MMP9_Enzyme
tracerDye       = dispense 1 units of AlexaFluor546_Tracer

enzymeSample    = mix mmp9Enzyme with tracerDye for 5s
enzymeStream    = mix enzymeSample with mmpBuffer for 5s

// ------------------------------------------------------------
// STEP 3: Prepare substrate side-channel streams.
//         FRET polypeptide MMP substrate at 5 uM in MMP buffer
//         flows in from two flanking side channels and merges
//         with the enzyme plug in the mixing zone just before
//         droplet formation. Final enzyme:substrate mixing
//         ratio is 1:1 (flow rates balanced).
// ------------------------------------------------------------

substrateLeft   = dispense 1 units of FRET_MMP_Substrate
substrateRight  = dispense 1 units of FRET_MMP_Substrate

// ------------------------------------------------------------
// STEP 4: Biomolecule concentrator -- accumulation phase.
//         +50 V applied across the ion-selective nanoporous
//         junction flanking the main channel (buffer side
//         channels at GND). The electrokinetic force opposes
//         the 0.03 uL/min pressure-driven flow, trapping
//         negatively charged enzyme molecules and tracer at
//         the depletion boundary.
//
//         Modelled as: mix of enzyme stream with the buffer
//         side-channel flow across the junction, followed by
//         a heat step at 25 C (room temperature) to encode
//         the accumulation time (adjustable; here set for
//         ~100-fold enhancement in the plug).
//
//         NOTE: `heat` here is a BioScript abstraction for
//         a timed electrokinetic trapping event, not a
//         thermal step. Temperature 25 C = ambient (no
//         external heating applied in the paper).
// ------------------------------------------------------------

bufferSideLeft  = dispense 1 units of PBS
bufferSideRight = dispense 1 units of PBS

// Junction mixing abstracts flow convergence at ICP boundary.
junctionMix     = mix enzymeStream with bufferSideLeft for 5s
concentratorIn  = mix junctionMix with bufferSideRight for 5s

// Voltage-on accumulation: 10 min timed trapping phase
// producing ~100-fold concentration enhancement in the plug.
// Duration is the primary handle for tuning enhancement factor.
heat concentratorIn at 25c for 10m

// Voltage off: plug released by pressure-driven flow.
// concentratorIn now represents the released concentrated plug.

// ------------------------------------------------------------
// STEP 5: Plug transport and mixing with substrate.
//         The released plug (~100-fold concentrated) travels
//         ~200 um to the mixing zone where it meets substrate
//         from both side channels. Gaussian diffusion during
//         transport reduces peak enhancement to ~20-fold at
//         the droplet generator. Vortices inside droplets
//         ensure rapid enzyme-substrate mixing post-
//         encapsulation.
// ------------------------------------------------------------

assayMixLeft    = mix concentratorIn with substrateLeft for 5s
assayMixFull    = mix assayMixLeft with substrateRight for 5s

// ------------------------------------------------------------
// STEP 6: Droplet encapsulation.
//         Fluorocarbon oil (HFE7500) + biocompatible
//         perfluorinated surfactant flows at 1.0 uL/min
//         orthogonally at the flow-focusing junction.
//         Aqueous plug is sheared into ~40 pL monodisperse
//         water-in-oil droplets at ~2.5 kHz.
//
//         The Gaussian-shaped plug is divided into a train
//         of droplets spanning a range of enzyme concentrations
//         (0.2 nM to 3.2 nM inferred from tracer fluorescence).
//         Three representative concentration bins are modelled
//         here as separate droplet variables (high, mid, low)
//         to encode the parallel screening experiment.
//
//         Modelled as: mix of assay plug with oil phase.
//         Each mix call represents one droplet population bin.
// ------------------------------------------------------------

oilCarrier      = dispense 1 units of HFE7500_FluorocarbonOil
surfactantOil   = dispense 1 units of FluorocarbonSurfactant
carrierPhase    = mix oilCarrier with surfactantOil for 5s

// High-concentration droplets (plug centre, ~20-fold; ~3.2 nM)
dropletHigh     = mix assayMixFull with carrierPhase for 2s

// Mid-concentration droplets (plug shoulder, ~10-fold; ~1.6 nM)
// Dispense fresh aliquots to represent next droplet bin.
assayMidSample  = dispense 1 units of MMP9_Enzyme
assayMidTracer  = dispense 1 units of AlexaFluor546_Tracer
assayMidBuf     = dispense 1 units of MMPBuffer
assayMidSub     = dispense 1 units of FRET_MMP_Substrate
assayMidOil     = dispense 1 units of HFE7500_FluorocarbonOil

midEnzyme       = mix assayMidSample with assayMidTracer for 5s
midAssay        = mix midEnzyme with assayMidBuf for 5s
midMix          = mix midAssay with assayMidSub for 5s
dropletMid      = mix midMix with assayMidOil for 2s

// Low-concentration droplets (plug tail, ~1-fold; ~0.2 nM;
// used as internal negative-reference / baseline)
assayLowSample  = dispense 1 units of MMP9_Enzyme
assayLowTracer  = dispense 1 units of AlexaFluor546_Tracer
assayLowBuf     = dispense 1 units of MMPBuffer
assayLowSub     = dispense 1 units of FRET_MMP_Substrate
assayLowOil     = dispense 1 units of HFE7500_FluorocarbonOil

lowEnzyme       = mix assayLowSample with assayLowTracer for 5s
lowAssay        = mix lowEnzyme with assayLowBuf for 5s
lowMix          = mix lowAssay with assayLowBuf for 5s
dropletLow      = mix lowMix with assayLowOil for 2s

// ------------------------------------------------------------
// STEP 7: Incubate droplets in observation room.
//         Droplets flow into collection area and are monitored
//         by time-lapse fluorescence microscopy. FRET substrate
//         cleavage by MMP-9 releases fluorophore; product
//         fluorescence (separate emission channel from tracer)
//         increases linearly with time.
//         Incubation at 37 C for 35 min (Fig. 2A time axis).
//         kcat/Km = 7.81e4 M^-1 s^-1 determined from reaction
//         rate vs. concentration (Fig. 2B).
// ------------------------------------------------------------

heat dropletHigh at 37c for 35m
heat dropletMid  at 37c for 35m
heat dropletLow  at 37c for 35m

// ------------------------------------------------------------
// STEP 8: Fluorescence detection of MMP activity.
//         Tracer channel (ex 561 nm / em 572 nm): reports
//         local enzyme concentration per droplet.
//         Product channel: reports proteolytic activity.
//         QC gate keyed on high-concentration droplets
//         (largest expected signal).
// ------------------------------------------------------------

assaySignal     = detect mmpActivityDetection on dropletHigh for 35m
tracerSignal    = detect tracerFluorescenceDetection on dropletHigh for 30s

// ============================================================
// BB2 / BB3: MMP activity QC gate
// Pass (BB2): assaySignal > 0 -> MMP proteolytic activity
//             confirmed; dispose all droplet populations.
// Fail (BB3): assaySignal <= 0 -> no activity (negative
//             control or failed run); drain all droplets.
// Both branches converge at BB4 (assayJoin).
// ============================================================

if (assaySignal > 0) {
    dispose dropletHigh
    dispose dropletMid
    dispose dropletLow
} else {
    drain dropletHigh
    drain dropletMid
    drain dropletLow
}

// ============================================================
// BB4: assayJoin
// Dispose recombinant MMP-9 assay QC signals.
// Control falls into cellular supernatant assay branch.
// ============================================================

dispose assaySignal
dispose tracerSignal

// ============================================================
// CELLULAR SUPERNATANT ASSAY
// Stimulated vs. untreated MEF conditioned media
// ============================================================

// ------------------------------------------------------------
// STEP 9: Prepare cellular supernatant streams.
//         0.5x dilutions of stimulated and untreated MEF
//         conditioned media in MMP buffer. Loaded into middle
//         channel of a fresh chip run.
//         Total sample consumed: < 25 uL across both conditions.
//
//         Stimulated sample: cytokine-treated MEF supernatant.
//         Untreated sample: control MEF supernatant.
//         Both co-loaded with Alexa Fluor-546 tracer.
// ------------------------------------------------------------

cellBufStim     = dispense 1 units of MMPBuffer
cellBufUntrt    = dispense 1 units of MMPBuffer
tracerStim      = dispense 1 units of AlexaFluor546_Tracer
tracerUntrt     = dispense 1 units of AlexaFluor546_Tracer

stimSample      = dispense 1 units of CellularSupernatant_Stimulated
untrtSample     = dispense 1 units of CellularSupernatant_Untreated

stimStream      = mix stimSample with tracerStim for 5s
stimStream      = mix stimStream with cellBufStim for 5s

untrtStream     = mix untrtSample with tracerUntrt for 5s
untrtStream     = mix untrtStream with cellBufUntrt for 5s

// ------------------------------------------------------------
// STEP 10: Concentrate cellular supernatant samples.
//          ICP concentrator applied to both samples in
//          sequence. Same voltage/flow conditions as STEP 4.
//          Enhancement factor tuned to ~10-20x at encapsulation
//          point. Concentration time (heat duration) is the
//          same as for recombinant MMP-9.
//
//          NOTE: Concentrated samples amplify the difference
//          in activity between stimulated and untreated
//          conditions ~10-fold relative to unconcentrated,
//          enabling differentiation in 5 min vs. 50 min.
// ------------------------------------------------------------

bufCellLeft1    = dispense 1 units of PBS
bufCellRight1   = dispense 1 units of PBS
bufCellLeft2    = dispense 1 units of PBS
bufCellRight2   = dispense 1 units of PBS

stimJunction    = mix stimStream with bufCellLeft1 for 5s
stimConcIn      = mix stimJunction with bufCellRight1 for 5s
heat stimConcIn at 25c for 10m

untrtJunction   = mix untrtStream with bufCellLeft2 for 5s
untrtConcIn     = mix untrtJunction with bufCellRight2 for 5s
heat untrtConcIn at 25c for 10m

// ------------------------------------------------------------
// STEP 11: Mix concentrated plugs with substrate and
//          encapsulate into droplets.
//          Same flow-focusing geometry as STEP 5-6.
//          Substrate: FRET MMP peptide at 5 uM.
//          Oil carrier phase with surfactant.
// ------------------------------------------------------------

subStim         = dispense 1 units of FRET_MMP_Substrate
subUntrt        = dispense 1 units of FRET_MMP_Substrate
oilStim         = dispense 1 units of HFE7500_FluorocarbonOil
oilUntrt        = dispense 1 units of HFE7500_FluorocarbonOil
surfStim        = dispense 1 units of FluorocarbonSurfactant
surfUntrt       = dispense 1 units of FluorocarbonSurfactant

stimAssayMix    = mix stimConcIn with subStim for 5s
oilPhaseStim    = mix oilStim with surfStim for 5s
dropletStim     = mix stimAssayMix with oilPhaseStim for 2s

untrtAssayMix   = mix untrtConcIn with subUntrt for 5s
oilPhaseUntrt   = mix oilUntrt with surfUntrt for 5s
dropletUntrt    = mix untrtAssayMix with oilPhaseUntrt for 2s

// ------------------------------------------------------------
// STEP 12: Incubate cell supernatant assay droplets.
//          Concentrated stimulated sample: reaction
//          differentiable from untreated within 5 min
//          (line-1 slope 2.14 a.u./s vs. line-3 slope
//          0.95 a.u./s). Unconcentrated requires > 50 min
//          (line-2 slope 0.32 a.u./s vs. line-4 slope
//          0.22 a.u./s).
//          Modelled as 5 min observation (concentrated) which
//          is the key timepoint reported in Fig. 3A.
// ------------------------------------------------------------

heat dropletStim  at 37c for 5m
heat dropletUntrt at 37c for 5m

// ------------------------------------------------------------
// STEP 13: Detect proteolytic activity from MEF supernatant.
//          mmpActivityDetection module reports product
//          fluorescence per droplet over time. High-throughput:
//          multiple droplets at different concentration
//          enhancements read in a single experiment (Fig. 3B).
//          QC gate keyed on stimulated sample (higher expected
//          activity signal).
// ------------------------------------------------------------

cellSignal      = detect mmpActivityDetection on dropletStim for 5m

// ============================================================
// BB5 / BB6: Cellular supernatant assay QC gate
// Pass (BB5): cellSignal > 0 -> proteolytic activity detected
//             in concentrated stimulated sample; dispose both
//             droplet populations.
// Fail (BB6): cellSignal <= 0 -> no detectable activity;
//             drain both droplet populations.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (cellSignal > 0) {
    dispose dropletStim
    dispose dropletUntrt
} else {
    drain dropletStim
    drain dropletUntrt
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose cellular assay QC signal.
// Experiment ends.
// ============================================================

dispose cellSignal

// [terminal -- no further instructions; exit node for CFG]

module chemiluminescenceDetection

manifest ParamagneticParticles
manifest TSH_Standard
manifest HRP_AntiTSH_Conjugate
manifest WashBuffer
manifest ParticleDiluent
manifest H2O2_StablePeroxide
manifest LuminolEnhancer

// ============================================================
// Automated Digital Microfluidic Platform for Magnetic-Particle-
// Based Immunoassays with Optimization by Design of Experiments
// Choi, Ng, Fobel, Chang-Yen, Yarnell, Pearson, Oleksak,
// Fischer, Luoma, Robinson, Audet, Wheeler
// Anal. Chem. 2013, 85, 9638-9646
// DOI: 10.1021/ac401847x
//
// ASSAY TARGET: Thyroid-Stimulating Hormone (TSH)
//   Clinically relevant range: 0 - 4 uIU/mL
//   LOD (optimized): 0.15 uIU/mL (screens for hyperthyroidism)
//
// PLATFORM DESCRIPTION:
//   Automated DMF platform (benchtop, ~18x23x30 cm enclosure)
//   featuring:
//     (a) 90 Pogo pin interface (15 inputs/sq in) for droplet
//         control via Microdrop + Arduino-based HV switching
//         (100-120 V_rms, 10 kHz sine wave AC).
//     (b) Integrated motorized Hamamatsu H10682-110 PMT
//         (5V DC, motor-driven engage/disengage, shutter).
//     (c) "Magnetic lens" assembly: neodymium bar (3 in x 1/2 in
//         x 1/4 in, mu_r=1.05, Br=1.32 T) flanked by two AISI
//         1080 steel machined armatures. Motor-driven vertical
//         engage (~150 um gap, ~600 uN vertical force) supports
//         up to 8 simultaneous parallel magnetic separations.
//
// DMF DEVICE:
//   Bottom plate: 80 actuation electrodes (2.2x2.2 mm each),
//   8 reagent reservoirs (16.4x6.7 mm), 4 waste reservoirs.
//   Interdigitated borders (140 um peak-to-peak sinusoids),
//   interelectrode gaps 30-80 um.
//   Unit droplet volume: ~800 nL.
//   Reservoir droplet volume: ~3.5 uL.
//
// OPTIMIZED PROTOCOL PARAMETERS (from 3^3 full factorial DOE):
//   Sample volume:          5 unit droplets (4 uL after merging)
//   Sample incubation time: 3 min
//   TSH standard conc:      0, 0.4, 4 uIU/mL
//   Conjugate mixing:       2 min
//   Wash cycles (step 1):   4x in wash buffer
//   Substrate mixing:       4 min
//   PMT integration:        10 s (stable signal window)
//
// REAGENT PREPARATION (off-chip, prior to loading):
//   - TSH standards (Abbott Labs) + Pluronic L64 0.05% v/v
//   - Particle working solution: ~3.0e8 particles/mL in
//     DMF-compatible particle diluent (pH 10: Tris base 6.1 g/L,
//     NaCl 5.8 g/L, BSA 1% w/v, thimerosal 0.05% w/v,
//     Pluronic L64 0.05% v/v)
//   - HRP-conjugated anti-TSH (Abcam, 2 ug/mL) in conjugate
//     diluent (DMF-compatible)
//   - SuperSignal ELISA Femto substrate (Thermo Fischer):
//     H2O2 stable peroxide + luminol-enhancer, each supplemented
//     with Pluronic L64 0.025% v/v
//   - DMF-compatible wash buffer
//
// MEASUREMENT NOTE:
//   A single stationary PMT services droplets sequentially.
//   To eliminate queue-wait signal decay (up to 45% signal
//   drop observed in pilot assays), wash buffer is removed
//   immediately after final wash, particles resuspended in
//   luminol-H2O2 substrate and mixed for 4 min to reach a
//   stable ~1-min measurement window before PMT engagement.
//
// DOE MODEL (eq 1, centered polynomial regression):
//   Factors: con (concentration), vol (sample volume),
//             inc (incubation time)
//   Response: Sqrt(SBR) [square-root of signal-to-background ratio]
//   Model fit: R^2=0.90, R^2_adj=0.88, RMSE=0.1597, p<0.0001
//   Key finding: longer incubation at high TSH REDUCES Sqrt(SBR);
//   optimum is 5 droplets x 3 min incubation.
//
// PERFORMANCE vs. PROTOTYPE (Ng et al., Anal. Chem. 2012):
//   CV:            6-10%    (was 9-21%)
//   LOD (abs):     0.6 nIU  (was 2.0 nIU,  3-fold improvement)
//   LOD (conc):    0.15 uIU/mL (was 0.83, 5-fold improvement)
//   Sample vol:    4.0 uL   (was 2.4 uL)
//   Incubation:    3 min    (was 6 min,  2-fold reduction)
//
// CFG STRUCTURE:
//   BB1  main              -- entry: reagent dispense, particle
//                             immobilization, sample incubation
//   BB2  washPass          -- washSignal > 0: particle pellets
//                             confirmed; proceed to conjugate step
//   BB3  washFail          -- washSignal <= 0: pellets lost; drain
//   BB4  washJoin          -- join: conjugate incubation begins
//   BB5  detectionPass     -- detectionSignal > 0: valid chemilum.
//                             signal; dispose substrate droplet
//   BB6  detectionFail     -- detectionSignal <= 0: no signal; drain
//   BB7  finalCleanup      -- terminal: dispose QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Dispense paramagnetic particle droplet from reservoir.
//   Working solution: ~3.0e8 particles/mL in DMF-compatible
//   particle diluent (pH 10). ~800 nL unit droplet.
//   Magnetic lens engages (motor, ~150 um gap) to pellet
//   particles on device surface; diluent droplet is moved away
//   (magnetic separation). Particle pellet remains immobilized.
// ------------------------------------------------------------

particleDrop    = dispense 1 units of ParamagneticParticles

// ------------------------------------------------------------
// STEP 2: Dispense 5 unit droplets of TSH standard.
//   Optimized DOE result: 5 pooled unit droplets (4 uL total)
//   yields highest Sqrt(SBR) at all tested concentrations.
//   TSH standards: 0, 0.4, or 4 uIU/mL (supplemented with
//   Pluronic L64 0.05% v/v for DMF compatibility).
//   Five droplets accumulated explicitly (BioScript compiler
//   requires scalar dispense + chained merge to accumulate
//   multi-unit volumes; multi-unit dispense does not produce
//   discrete indexed elements suitable for downstream ops).
// ------------------------------------------------------------

tsh1            = dispense 1 units of TSH_Standard
tsh2            = dispense 1 units of TSH_Standard
tsh3            = dispense 1 units of TSH_Standard
tsh4            = dispense 1 units of TSH_Standard
tsh5            = dispense 1 units of TSH_Standard

// Accumulate 5 unit droplets into a single pooled sample droplet.
tshPool_2       = mix tsh1 with tsh2 for 5s
tshPool_3       = mix tshPool_2 with tsh3 for 5s
tshPool_4       = mix tshPool_3 with tsh4 for 5s
tshSample       = mix tshPool_4 with tsh5 for 5s

// ------------------------------------------------------------
// STEP 3: Deliver pooled TSH sample to immobilized particles
//   and mix for 3 min (optimized incubation time from DOE).
//   Droplet shuttled in circular motion across 4+ electrodes
//   (continuous active mixing, 100-120 V_rms, 10 kHz) to
//   accelerate analyte binding to antibody-coated magnetic
//   particles. This replaces the 6 min incubation of the
//   prototype setup; rapid uniform mixing enables faster
//   binding kinetics.
//   DOE finding: con x inc interaction is negative at high TSH;
//   3 min at high vol outperforms 6-9 min at all concentrations.
// ------------------------------------------------------------

sampleIncubation = mix tshSample with particleDrop for 3m

// ------------------------------------------------------------
// STEP 4: Wash particles 4 times in DMF-compatible wash buffer.
//   Magnetic lens engages to pellet particles; supernatant
//   droplet is moved to waste reservoir (magnetic separation).
//   Fresh wash buffer droplet moved over pellet; magnet
//   disengages; particles resuspend in wash buffer; repeat.
//   4 wash cycles remove unbound TSH and non-specific binders.
//   After wash 4, particles remain suspended in wash buffer
//   for conjugate delivery.
//
//   NOTE ON ABSTRACTION: Each wash cycle is modelled as a
//   sequential mix-with-wash-buffer operation. The magnetic
//   separation (pellet + supernatant removal) is a DMF-
//   specific hardware operation abstracted here as the mix
//   step completing and a new wash droplet being dispensed.
//   The magnetic lens facilitates up to 8 simultaneous
//   separations across the device.
// ------------------------------------------------------------

// Wash cycle 1
wash1a          = dispense 1 units of WashBuffer
wash1b          = mix sampleIncubation with wash1a for 30s
washSup1        = dispense 1 units of WashBuffer
wash1c          = mix wash1b with washSup1 for 10s
drain wash1c

// Wash cycle 2
wash2a          = dispense 1 units of WashBuffer
wash2b          = mix wash1a with wash2a for 30s
washSup2        = dispense 1 units of WashBuffer
wash2c          = mix wash2b with washSup2 for 10s
drain wash2c

// Wash cycle 3
wash3a          = dispense 1 units of WashBuffer
wash3b          = mix wash2a with wash3a for 30s
washSup3        = dispense 1 units of WashBuffer
wash3c          = mix wash3b with washSup3 for 10s
drain wash3c

// Wash cycle 4
wash4a          = dispense 1 units of WashBuffer
wash4b          = mix wash3a with wash4a for 30s
washSup4        = dispense 1 units of WashBuffer
particlesWashed = mix wash4b with washSup4 for 10s

// QC: confirm particle pellets are retained after wash series.
washSignal      = detect chemiluminescenceDetection on particlesWashed for 5s

// ============================================================
// BB2 / BB3: Wash / particle-retention QC gate
// Pass (BB2): washSignal > 0  -> particle pellets retained;
//             proceed to conjugate incubation.
// Fail (BB3): washSignal <= 0 -> pellets lost during wash;
//             drain and abort.
// Both branches converge at BB4 (washJoin).
// ============================================================

if (washSignal > 0) {
    dispose particlesWashed
} else {
    drain particlesWashed
}

// ============================================================
// BB4: washJoin
// Dispose wash QC signal. Control falls into conjugate
// incubation branch.
// ============================================================

dispose washSignal

// ------------------------------------------------------------
// STEP 5: Deliver HRP-conjugated anti-TSH detection antibody
//   and mix for 2 min.
//   Conjugate: HRP-conjugated mouse monoclonal anti-TSH
//   (Abcam, 2 ug/mL) in DMF-compatible conjugate diluent.
//   1 unit droplet (~800 nL) dispensed, moved over particle
//   pellet, and mixed for 2 min (active electrode mixing,
//   100-120 V_rms, 10 kHz). HRP-antibody binds to TSH
//   captured on the particle surface (sandwich formation).
// ------------------------------------------------------------

conjugateDrop   = dispense 1 units of HRP_AntiTSH_Conjugate
conjugateIncub  = mix wash4a with conjugateDrop for 2m

// ------------------------------------------------------------
// STEP 6: Wash particles 4 times in DMF-compatible wash buffer
//   to remove unbound HRP-conjugate.
//   Paper specifies 5 washes in pilot protocol; optimized
//   protocol uses 4 washes (sufficient with improved mixing).
//   After the 4th wash, supernatant is removed IMMEDIATELY
//   (no queuing in wash buffer) to prevent signal decay.
//   Key optimization: eliminating the wash-buffer queue wait
//   that caused up to 45% signal drop in pilot assays.
// ------------------------------------------------------------

// Wash cycle 1
cwash1a         = dispense 1 units of WashBuffer
cwash1b         = mix conjugateIncub with cwash1a for 30s
cwashSup1       = dispense 1 units of WashBuffer
cwash1c         = mix cwash1b with cwashSup1 for 10s
drain cwash1c

// Wash cycle 2
cwash2a         = dispense 1 units of WashBuffer
cwash2b         = mix cwash1a with cwash2a for 30s
cwashSup2       = dispense 1 units of WashBuffer
cwash2c         = mix cwash2b with cwashSup2 for 10s
drain cwash2c

// Wash cycle 3
cwash3a         = dispense 1 units of WashBuffer
cwash3b         = mix cwash2a with cwash3a for 30s
cwashSup3       = dispense 1 units of WashBuffer
cwash3c         = mix cwash3b with cwashSup3 for 10s
drain cwash3c

// Wash cycle 4 - FINAL: supernatant removed immediately.
cwash4a         = dispense 1 units of WashBuffer
cwash4b         = mix cwash3a with cwash4a for 30s
cwashSup4       = dispense 1 units of WashBuffer
cwash4c         = mix cwash4b with cwashSup4 for 10s
drain cwash4c

// ------------------------------------------------------------
// STEP 7: Initiate chemiluminescent reaction immediately after
//   final wash (no delay).
//   (a) Resuspend particles in 1 unit (~800 nL) of H2O2
//       stable peroxide by disengaging magnetic lens and
//       moving H2O2 droplet over particle pellet.
//   (b) Merge and mix with 1 unit (~800 nL) of luminol-
//       enhancer solution for 4 min (optimized from pilot;
//       pilot used 40 s mix + 100 s incubation).
//       Active mixing drives HRP-catalysed luminol oxidation
//       and allows signal to reach a stable plateau.
//   Combined droplet: ~1600 nL pooled substrate.
// ------------------------------------------------------------

h2o2Drop        = dispense 1 units of H2O2_StablePeroxide
particlesInH2O2 = mix cwash4a with h2o2Drop for 10s

luminolDrop     = dispense 1 units of LuminolEnhancer
substratePool   = mix particlesInH2O2 with luminolDrop for 4m

// ------------------------------------------------------------
// STEP 8: PMT detection.
//   Motor lowers PMT to engaged position (shutter opens,
//   sensor positioned several hundred micrometers above
//   device surface). Chemiluminescent signal collected for
//   10 s within the stable measurement window (~1 min).
//   Signal proportional to HRP concentration (captured TSH).
//   Four replicates per concentration are averaged and fitted
//   to a linear calibration curve. LOD = mean(blank) + 3*SD(blank).
// ------------------------------------------------------------

detectionSignal = detect chemiluminescenceDetection on substratePool for 10s

// ============================================================
// BB5 / BB6: Detection QC gate
// Pass (BB5): detectionSignal > 0 -> valid chemiluminescent
//             signal above background; dispose substrate droplet.
// Fail (BB6): detectionSignal <= 0 -> no signal (reagent
//             failure or particle loss); drain.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (detectionSignal > 0) {
    dispose substratePool
} else {
    drain substratePool
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose PMT detection QC signal droplet.
// Experiment ends. PMT motor returns to disengaged position
// (shutter closes, ~5 cm above device surface).
// ============================================================

dispose detectionSignal

// [terminal -- no further instructions; exit node for CFG]

