manifest ReferencePrimersProbe_HEX
manifest ddPCR_Supermix_NoUTP
manifest GenerationOil
manifest FoilSealSheet

// ============================================================
// Polymerase Chain Reaction (PCR) and Droplet Digital PCR
// (ddPCR) Protocol
// Lam, Arogundade, Clelland
// Weill Institute for Neurosciences / Dept. of Neurology,
// University of California, San Francisco
// Contact: claire.clelland@ucsf.edu
//
// This file encodes two sequential protocols:
//
// PROTOCOL 1: Standard PCR (20 uL reaction) with gel
//   electrophoresis QC readout.
//   DNA extraction via QuickExtract from 96-well plate cells.
//   Master Mix: 10 uL BioMix Red, 0.6 uL DMSO, 1 uL each
//   primer (10 uM), 6.4 uL H2O. Total = 19 uL + 1 uL DNA.
//   Thermocycler: 94 C enzyme activation (3 min), then
//   34 x [94 C 30s / 50-65 C 30s / 72 C extension] +
//   72 C final extension (5 min), hold 4 C.
//   Gel: 1.5-2% agarose, 1X TAE, SYBR Safe stain;
//   run at 100-140 V; image on LI-COR Odyssey M.
//
// PROTOCOL 2: Droplet Digital PCR (ddPCR, 22 uL reaction)
//   using Bio-Rad QX200 Droplet Generator system.
//   Master Mix: 11 uL 2X ddPCR Supermix (No dUTP),
//   1.1 uL 20X target primers/probe (FAM),
//   1.1 uL 20X reference primers/probe (HEX/VIC - RPP30),
//   balance H2O + up to 350 ng DNA template.
//   Droplet generation: DG8 cartridge + 70 uL generation oil;
//   transfer 40 uL droplets to 96-well plate; heat-seal at 180 C.
//   ddPCR cycle: 94 C 10 min activation, 39 x [94 C 30s /
//   50-65 C 1 min], 98 C 10 min deactivation, hold 4 C.
//   Readout: QX200 Droplet Reader + QuantaSoft software;
//   2-channel (FAM/HEX) droplet counting with manual threshold.
//
// BIOSCRIPT ABSTRACTIONS:
//   - DNA extraction incubation steps are modelled with `heat`
//     at the stated temperatures (65 C and 98 C).
//   - Thermocycler PCR/ddPCR cycles are abstracted as `heat`
//     at the representative cycling temperature (72 C for PCR,
//     60 C for ddPCR combined annealing/extension step), with
//     duration = total cycling time for one representative cycle.
//     BioScript has no loop construct; one cycle is encoded
//     by convention.
//   - Droplet generation, transfer, and plate sealing are
//     abstracted as `mix` operations with oil/seal reagents.
//   - All incubation durations use `s` (seconds) or `m`
//     (minutes) tokens only; no `h` token is used.
//   - `drain` normalises to `dispose` in IR output per
//     compiler behaviour; both are used contextually here.
//
// CFG STRUCTURE:
//   BB1  main             -- DNA extraction; PCR master mix
//                           prep; thermocycler run; gel QC
//   BB2  gelPass          -- gelSignal > 0: band detected,
//                           correct size; dispose gel products
//   BB3  gelFail          -- gelSignal <= 0: no band / wrong
//                           size; drain gel products
//   BB4  gelJoin          -- join: ddPCR branch begins
//   BB5  ddpcrPass        -- ddpcrSignal > 0: valid droplet
//                           partitioning detected; dispose
//   BB6  ddpcrFail        -- ddpcrSignal <= 0: no signal /
//                           poor droplet generation; drain
//   BB7  finalCleanup     -- terminal: dispose QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 1: DNA extraction by QuickExtract.
//   Cells in 96-well plate washed with 100 uL PBS and
//   aspirated. 30 uL QuickExtract added; cells scraped
//   and transferred to PCR tubes. Vortex 15 s, incubate
//   at 65 C for 6 min, vortex 15 s, incubate at 98 C
//   for 2 min. Store at -20 C.
//   NOTE: `mix` abstracts the cell scraping + vortex step;
//   two sequential `heat` steps model the 65 C and 98 C
//   incubations. Vortex intervals (15 s each) are folded
//   into the mix durations.
// ------------------------------------------------------------

cellSample       = dispense 1 units of Cells
pbsWash          = dispense 1 units of PBS
quickExtractSoln = dispense 1 units of QuickExtract

// Wash cells: 100 uL PBS aspirate (wash + aspirate abstracted
// as a brief mix then the PBS is disposed).
washedCells      = mix cellSample with pbsWash for 15s
dispose pbsWash

// Add QuickExtract and scrape/vortex (first vortex 15 s).
scrapedCells     = mix washedCells with quickExtractSoln for 15s

// Incubate at 65 C for 6 min (= 6m).
heat scrapedCells at 65c for 6m

// Second vortex 15 s, modelled as a brief self-mix duration
// (BioScript has no standalone vortex op; heat at ambient
// temperature for 15 s is the closest approximation).
heat scrapedCells at 25c for 15s

// Incubate at 98 C for 2 min (= 2m).
heat scrapedCells at 98c for 2m

// scrapedCells now contains PCR-ready DNA template.

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 2: Prepare PCR Master Mix (20 uL rxn).
//   For one 20 uL reaction:
//     BioMix Red        10.0 uL
//     DMSO               0.6 uL
//     Forward primer     1.0 uL  (10 uM)
//     Reverse primer     1.0 uL  (10 uM)
//     RNase/DNase H2O    6.4 uL
//   Total Master Mix  = 19.0 uL + 1 uL DNA template = 20 uL.
//   NOTE: Each reagent is dispensed as 1 unit. The compiler
//   treats units abstractly; volume ratios are captured in
//   comments and the JSON metadata file.
// ------------------------------------------------------------

biomixRed      = dispense 1 units of BioMixRed
dmso           = dispense 1 units of DMSO
fwdPrimer      = dispense 1 units of ForwardPrimer_10uM
revPrimer      = dispense 1 units of ReversePrimer_10uM
h2o_pcr        = dispense 1 units of RNaseDNaseFreeH2O

// Assemble Master Mix: BioMix + DMSO + fwd primer.
mmStep1        = mix biomixRed with dmso for 5s
mmStep2        = mix mmStep1 with fwdPrimer for 5s

// Add reverse primer.
mmStep3        = mix mmStep2 with revPrimer for 5s

// Add water to complete Master Mix (19 uL total).
masterMix      = mix mmStep3 with h2o_pcr for 5s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 3: Add DNA template to Master Mix.
//   1 uL DNA sample (scrapedCells) + 19 uL Master Mix
//   = 20 uL total reaction volume per tube.
// ------------------------------------------------------------

pcrReaction    = mix masterMix with scrapedCells for 5s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 4: PCR thermocycling (Bio-Rad Thermal
//   Cycler). One representative cycle encoded (no loop in
//   BioScript). Full program runs 34 amplification cycles
//   on the instrument.
//
//   Step 1: Enzyme Activation  94 C  3 min  (= 3m)
//   Step 2: Denaturation       94 C  30 s
//   Step 3: Annealing       50-65 C  30 s
//   Step 4: Primary Extension  72 C  1 min/kb
//   Step 5: Repeat steps 2-4 x34 (instrument-controlled)
//   Step 6: Secondary Ext.     72 C  5 min  (= 5m)
//   Step 7: Hold               4 C   inf
//
//   BioScript encoding:
//     - Enzyme activation at 94 C for 3 min.
//     - One representative cycle: denature 94 C 30s,
//       anneal 57 C 30s (midpoint of 50-65 C range),
//       extend 72 C 60s (1 min/kb for a ~1 kb target).
//     - Final extension at 72 C for 5 min.
//     - Hold at 4 C for 1s (terminal, instrument holds
//       indefinitely; 1s is the minimum BioScript token).
// ------------------------------------------------------------

// Enzyme activation.
heat pcrReaction at 94c for 3m

// One representative amplification cycle.
heat pcrReaction at 94c for 30s
heat pcrReaction at 57c for 30s
heat pcrReaction at 72c for 60s

// Final/secondary extension.
heat pcrReaction at 72c for 5m

// Hold (instrument holds at 4 C; BioScript minimum = 1s).
heat pcrReaction at 4c for 1s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 5: Gel electrophoresis QC.
//   Prepare 1.5-2% agarose gel in 1X TAE buffer with SYBR
//   Safe DNA Gel Stain (15 uL per 150 mL gel).
//   Load ~12 uL DNA ladder + PCR product into wells.
//   Run at 100-140 V until bands are resolved.
//   Image on LI-COR Odyssey M Imager (488 nm / SYBR Safe).
//
//   NOTE: Gel preparation and casting are off-chip benchtop
//   steps abstracted as dispense + mix of gel matrix and
//   stain components. Loading and running are modelled as
//   a heat step (voltage application at ambient temp). The
//   gelElectrophoresisDetection module abstracts the LI-COR
//   imaging readout.
// ------------------------------------------------------------

gelMatrix      = dispense 1 units of AgaroseGel_1pct5to2pct
taeBuffer      = dispense 1 units of TAE_Buffer_1X
sybrStain      = dispense 1 units of SYBR_Safe_Stain
dnaLadder      = dispense 1 units of DNALadder

// Prepare gel: dissolve agarose in TAE buffer (microwave),
// then add SYBR Safe stain. Modelled as sequential mixes.
gelInBuffer    = mix gelMatrix with taeBuffer for 5m
gelWithStain   = mix gelInBuffer with sybrStain for 30s

// Load ladder and PCR product into gel wells.
gelLoaded      = mix gelWithStain with dnaLadder for 15s
gelRunReady    = mix gelLoaded with pcrReaction for 15s

// Electrophoresis: 100-140 V at ambient temperature until
// bands resolve (~30-45 min typical). Modelled at 25 C for
// 40 min (= 40m) to represent a standard run duration.
heat gelRunReady at 25c for 40m

// LI-COR Odyssey M imaging: 488 nm channel, SYBR Safe,
// focus offset 2.00 mm. Modelled as a 5 min detection step.
gelSignal      = detect gelElectrophoresisDetection on gelRunReady for 5m

// ============================================================
// BB2 / BB3: Gel QC gate
// Pass (BB2): gelSignal > 0 -> band detected at expected size;
//             PCR successful; dispose gel products.
// Fail (BB3): gelSignal <= 0 -> no band or wrong-size band;
//             PCR failed; drain gel products for repeat.
// Both branches converge at BB4 (gelJoin).
// ============================================================

if (gelSignal > 0) {
    dispose gelRunReady
} else {
    drain gelRunReady
}

// ============================================================
// BB4: gelJoin
// Dispose gel QC signal. Control falls into ddPCR branch.
// ============================================================

dispose gelSignal

// ============================================================
// PROTOCOL 2: Droplet Digital PCR (ddPCR)
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 1: Prepare 20X target primers/probe mix.
//   For 100 uL of 20X stock:
//     Forward primer (100 uM)   18 uL
//     Reverse primer (100 uM)   18 uL
//     Target probe FAM           5 uL  (*light sensitive)
//     RNase/DNase H2O           59 uL
//   Store at -20 C, protect from light.
//   NOTE: Each component dispensed as 1 unit; ratios in
//   comments and metadata. Vortex at full speed 15 s
//   between each mixing step per protocol requirement.
// ------------------------------------------------------------

fwdPrimer100   = dispense 1 units of ForwardPrimer_100uM
revPrimer100   = dispense 1 units of ReversePrimer_100uM
targetProbeFAM = dispense 1 units of TargetProbe_FAM
h2o_probe      = dispense 1 units of RNaseDNaseFreeH2O

// Assemble 20X target primers/probe (vortex 15 s each merge).
probeStep1     = mix fwdPrimer100 with revPrimer100 for 15s
probeStep2     = mix probeStep1 with targetProbeFAM for 15s
targetPrimersProbe = mix probeStep2 with h2o_probe for 15s

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 2: Prepare ddPCR Master Mix (22 uL rxn).
//   For one 22 uL reaction:
//     2X ddPCR Supermix (No dUTP)              11.0 uL
//     20X target primers/probe (FAM)             1.1 uL
//     20X reference primers/probe (HEX) RPP30   1.1 uL
//     RNase/DNase H2O + DNA template        to 22.0 uL
//   DNA sample: up to 350 ng total input.
//   Thaw all components to room temperature before use.
//   Vortex at full speed 15 s when mixing.
// ------------------------------------------------------------

ddpcrSupermix  = dispense 1 units of ddPCR_Supermix_NoUTP
refPrimersHEX  = dispense 1 units of ReferencePrimersProbe_HEX
h2o_ddpcr      = dispense 1 units of RNaseDNaseFreeH2O

// Fresh DNA template from the same QuickExtract prep.
// (A new dispense models the aliquot taken for ddPCR.)
dnaSample      = dispense 1 units of Cells
extractSoln2   = dispense 1 units of QuickExtract
pbsWash2       = dispense 1 units of PBS
washedCells2   = mix dnaSample with pbsWash2 for 15s
dispose pbsWash2
rawDNA         = mix washedCells2 with extractSoln2 for 15s
heat rawDNA at 65c for 6m
heat rawDNA at 25c for 15s
heat rawDNA at 98c for 2m

// Assemble ddPCR Master Mix.
ddmmStep1      = mix ddpcrSupermix with targetPrimersProbe for 15s
ddmmStep2      = mix ddmmStep1 with refPrimersHEX for 15s
ddmmStep3      = mix ddmmStep2 with h2o_ddpcr for 15s

// Add DNA template (up to 350 ng); total = 22 uL.
ddpcrReaction  = mix ddmmStep3 with rawDNA for 15s

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 3: Droplet generation (QX200 system).
//   Insert DG8 cartridge into holder.
//   Load >20 uL sample into sample wells (all 8 wells must
//   be loaded; empty wells get 50:50 Supermix:H2O).
//   Load 70 uL generation oil into oil wells.
//   Apply DG8 Gasket; load into QX200 Droplet Generator.
//   Run (~1 min). Generation oil is single-use.
//   NOTE: `mix` with GenerationOil abstracts the microfluidic
//   droplet partitioning step (water-in-oil emulsion, ~20,000
//   droplets per well at ~0.85 nL each).
// ------------------------------------------------------------

genOil         = dispense 1 units of GenerationOil

// Load sample + generation oil into DG8 cartridge and run
// QX200 droplet generator.
dropletEmulsion = mix ddpcrReaction with genOil for 1m

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 4: Transfer droplets to 96-well plate
//   and heat-seal. Transfer must occur within 5 min of
//   droplet generation. Transfer 40 uL droplets SLOWLY
//   (>7 sec aspiration/dispensing). Cover with foil seal
//   sheet (red line facing up); seal at 180 C for 5 s in
//   PX1 PCR Plate Sealer.
//   NOTE: plate sealing modelled as a heat step at 180 C
//   for 5 s with the foil seal reagent mixed in.
// ------------------------------------------------------------

foilSeal       = dispense 1 units of FoilSealSheet
sealedPlate    = mix dropletEmulsion with foilSeal for 30s

// Heat-seal: 180 C for 5 s.
heat sealedPlate at 180c for 5s

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 5: ddPCR thermocycling.
//   Bio-Rad C1000 Touch with 96-Deep Well block.
//   Plate must be run within 40 min of sealing.
//   Ramp rate: 2 C/sec throughout.
//
//   Step 1: Enzyme Activation  94 C  10 min  (= 10m)
//   Step 2: Denaturation       94 C  30 s
//   Step 3: Anneal/Extension 50-65 C  1 min
//   Step 4: Repeat steps 2-3 x39 (instrument-controlled)
//   Step 5: Enzyme Deactivation 98 C 10 min  (= 10m)
//   Step 6: Hold               4 C   inf
//
//   BioScript encoding:
//     - Enzyme activation at 94 C for 10 min.
//     - One representative cycle: denature 94 C 30s,
//       anneal/extend 57 C 60s (midpoint of 50-65 C range).
//     - Enzyme deactivation at 98 C for 10 min.
//     - Hold at 4 C for 1s (instrument holds indefinitely).
// ------------------------------------------------------------

// Enzyme activation.
heat sealedPlate at 94c for 10m

// One representative amplification cycle.
heat sealedPlate at 94c for 30s
heat sealedPlate at 57c for 60s

// Enzyme deactivation.
heat sealedPlate at 98c for 10m

// Hold.
heat sealedPlate at 4c for 1s

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 6: Read plate on QX200 Droplet Reader.
//   Let plate equilibrate at room temperature 1-2 min
//   (plate storable at 4 C for up to 3 days before reading).
//   Open QuantaSoft; configure wells:
//     Experiment: CNV2
//     Supermix: ddPCR Supermix for Probes (no dUTP)
//     Target 1 (FAM): Ch 1 Unknown
//     Target 2 (HEX/VIC): Ch 2 Reference (RPP30)
//   Set threshold manually (pink line); separate positive
//   droplets (blue/green) from negative (grey).
//   NOTE: dropletReadoutDetection module abstracts the
//   two-channel (FAM + HEX) droplet fluorescence counting
//   by the QX200 reader and QuantaSoft analysis.
// ------------------------------------------------------------

// Brief equilibration at room temperature (2 min = 2m).
heat sealedPlate at 25c for 2m

ddpcrSignal    = detect dropletReadoutDetection on sealedPlate for 30m

// ============================================================
// BB5 / BB6: ddPCR QC gate
// Pass (BB5): ddpcrSignal > 0 -> valid droplet partitioning
//             and fluorescence signal detected; dispose.
// Fail (BB6): ddpcrSignal <= 0 -> insufficient droplets or
//             no signal (reagent / sealing failure); drain.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (ddpcrSignal > 0) {
    dispose sealedPlate
} else {
    drain sealedPlate
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose ddPCR QC signal droplet. Experiment ends.
// ============================================================

dispose ddpcrSignal

// [terminal -- no further instructions; exit node for CFG]

module fluorescenceActivatedDropletSorting
module singleBeadDetection
module singleCellGFPDetection
module antibodyBindingDetection
module viabilityDetection

manifest PBS
manifest DMEM_Complete
manifest IMDM_Complete
manifest IMDM_NoPhenolRed
manifest HFE7500_Surfactant
manifest OptiPrep
manifest GFP_HEK293_Cells
manifest WT_HEK293_Cells
manifest FluoroSpheres_10um
manifest CalceinAM_RedOrange
manifest CellTrace_Blue
manifest AlexaFluor488_AntiMouse
manifest HybridomaSpecific_Cells
manifest HybridomaNonSpecific_Cells
manifest TargetCells
manifest SYTOX_Blue
manifest ConditionedMedia_HEK
manifest RecoveryBuffer_PBS
manifest RecoveryBuffer_DMEM
manifest RecoveryBuffer_IMDM
manifest IL6_Supplement

// ============================================================
// Recovery of Phenotypically Sorted Cells Using
// Droplet-Digital Microfluidics
// Deng, Perry, Weiss, Genth, Autour, Merten, Shih
// Lab on a Chip, 2025, 25, 4410-4421
// DOI: 10.1039/d5lc00415b
//
// Platform: Droplet-Digital (D2) Microfluidic Device
//   - Three-layer device: Cr-electrode / PDMS dielectric /
//     PDMS channel layer
//   - Integrated flow-focusing droplet generator
//   - Fiber-optic PMT detection (470 nm excitation, ~520 nm
//     emission for GFP/beads; 488 nm for Alexa Fluor 488)
//   - DMF binary sorter (patterned electrodes beneath channel,
//     AC 140 Vrms, 15 kHz) -- significantly lower than
//     conventional DEP systems (200-1200 V)
//   - Semicircular open-access collection outlet (3 mm punch)
//   - On-demand 3 uL recovery buffer droplet generated by
//     500 uL gastight syringe at 1 uL/s
//   - Sorted 1 nL droplet merges with recovery buffer via
//     electrode actuation (3x, 500 ms/actuation)
//     after a 7-9 s delay post-sorting
//   - Merged contents manually pipetted (~5 uL P20) into
//     individual wells of a 96-well plate
//   - Droplet generation rate: ~50 Hz
//   - Monodisperse droplet size: ~1 nL
//   - Oil: 2% 008-fluoro-surfactant in HFE7500
//   - Oil flow rate: 0.15 uL/s
//   - Aqueous (cell/bead) flow rate: 0.05 uL/s
//   - Waste withdrawal: -0.15 uL/s
//
// THREE PROTOCOLS ARE ENCODED IN SEQUENCE:
//
// PROTOCOL 1: Single fluorescent bead recovery
//   - FluoSpheres 10 um blue-green (430/465) beads
//   - Sorting threshold: 7e3 to 2e4 photon counts
//   - Single recovery: 1 droplet -> 1 well (50 events)
//   - D2 mean single-bead recovery: ~87%
//   - D2 pooled recovery: ~93.5% (vs 78.5% tubing)
//   - D2 SD: 5.29% (vs 26.1% for tubing)
//
// PROTOCOL 2: Low-input rare single GFP HEK293 cell recovery
//   - GFP:WT spiked ratios of 1:400 and 1:1000
//   - Total cell inputs: 1e4 and 1e5
//   - Sorting threshold: 1e3 to 2.5e3 photon counts
//   - D2 recovery rates: >80% across all conditions
//   - Post-sort viability: ~90% over 7 days
//   - Cells exhibit spreading (positive viability indicator)
//
// PROTOCOL 3: Rare specific-antibody-secreting hybridoma
//   cell screening and recovery (antibody discovery assay)
//   - Two hybridoma lines: specific-Ab producer (calcein-AM
//     red-orange stained) and non-specific-Ab producer
//   - Target cells: antigen-overexpressing line (CellTrace Blue)
//   - Secondary detection: Alexa Fluor 488 goat anti-mouse IgG
//   - Co-encapsulation (separate chip): 5-10% double-cell
//     occupancy by Poisson statistics
//   - Off-chip incubation: 2 h at 37 C / 5% CO2
//   - Sorting threshold (green channel): 1.8e4 to 3e4 counts
//   - Spike-in ratios: 1:400 (0.25%) and 1:1000 (0.1%)
//   - Recovery rate 1:400 ratio: ~88%
//   - Recovery rate 1:1000 ratio: ~78%
//
// NOTE ON ABSTRACTION OF DMF ELECTRODE ACTUATION:
//   The `mix` primitive abstracts on-chip DMF electrode
//   actuation sequences (AC 140 Vrms, 15 kHz) used for
//   droplet merging at the collection site. The `heat`
//   primitive models incubation in a mammalian cell incubator
//   (37 C / 5% CO2). BioScript has no duration token for
//   hours beyond minutes (m); all incubation times are
//   expressed in minutes (m) or seconds (s).
//
// NOTE ON CONDITIONED MEDIA (PROTOCOL 2):
//   The conditioned media used for the first 24 h post-sort
//   is 30% spent eGFP HEK cell supernatant (0.22 um filtered)
//   mixed 70% with fresh DMEM + 10% FBS + 1% P/S. This is
//   abstracted as ConditionedMedia_HEK in the manifest.
//   Subsequent media changes (every 48 h) use fresh DMEM.
//
// CFG STRUCTURE:
//   BB1  main                -- device priming; bead encapsulation,
//                               sorting, and single recovery
//   BB2  beadSortPass        -- beadSignal > 0: bead in threshold
//                               window; merge with recovery buffer
//   BB3  beadSortFail        -- beadSignal <= 0: no bead / multi-bead;
//                               drain
//   BB4  beadSortJoin        -- join: proceed to cell protocols
//   BB5  cellSortPass        -- cellSignal > 0: GFP cell detected;
//                               merge with cell recovery buffer
//   BB6  cellSortFail        -- cellSignal <= 0: no target cell; drain
//   BB7  cellSortJoin        -- join: proceed to viability check
//   BB8  viabilityPass       -- viabilitySignal > 0: cell viable (>80%);
//                               expand and dispose
//   BB9  viabilityFail       -- viabilitySignal <= 0: non-viable; drain
//   BB10 viabilityJoin       -- join: proceed to antibody assay protocol
//   BB11 antibodySortPass    -- abSignal > 0: specific-Ab hybridoma
//                               detected; merge and recover
//   BB12 antibodySortFail    -- abSignal <= 0: non-specific or empty;
//                               drain
//   BB13 finalCleanup        -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 1: Prime device channels with HFE7500 oil
//   containing 2% 008-fluoro-surfactant. Oil injected at
//   0.15 uL/s. Waste syringe set to -0.15 uL/s to ensure
//   all droplets default to the waste channel prior to sorting.
//   This establishes the baseline droplet flow direction.
// ------------------------------------------------------------

oilPrime = dispense 1 units of HFE7500_Surfactant

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 2: Prepare fluorescent bead suspension.
//   FluoSpheres polystyrene 10 um blue-green (430/465 nm)
//   beads washed 3x with PBS, diluted to 1e6 beads/mL.
//   16% OptiPrep added to prevent bead clumping and
//   sedimentation during chip operation.
//   OptiPrep is an iodixanol-based density gradient medium.
// ------------------------------------------------------------

beadSuspension  = dispense 1 units of FluoroSpheres_10um
optiprepBead    = dispense 1 units of OptiPrep
beadMix         = mix beadSuspension with optiprepBead for 5s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 3: Encapsulate beads in ~1 nL droplets.
//   Aqueous (bead) phase injected at 0.05 uL/s into
//   flow-focusing junction against 0.15 uL/s HFE7500 oil.
//   Generates monodisperse ~1 nL droplets at ~50 Hz.
//   Bead encapsulation follows Poisson statistics;
//   sorting threshold (7e3 to 2e4 photon counts) selects
//   for single-bead-containing droplets specifically.
//   NOTE: `mix` abstracts the flow-focusing encapsulation
//   event, not a DMF electrode mixing step.
// ------------------------------------------------------------

oilEncapsulate  = dispense 1 units of HFE7500_Surfactant
beadDroplets    = mix beadMix with oilEncapsulate for 2s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 4: Fiber-optic PMT detection.
//   470 nm excitation light cast at detection fiber region.
//   Blue-green bead fluorescence (~520 nm emission) measured
//   by photon counting head (Hamamatsu H11890).
//   Sorting threshold window: 7e3 to 2e4 photon counts.
//   Peaks above lower bound and below upper bound (multi-bead
//   exclusion) trigger electrode actuation at sorting junction.
//   PMT, fluid flow, and electrode actuation controlled via
//   in-house Python GUI (uflowcontrol).
// ------------------------------------------------------------

beadSignal = detect singleBeadDetection on beadDroplets for 10s

// ============================================================
// BB2 / BB3: Bead sorting QC gate
// Pass (BB2): beadSignal > 0 -> single bead detected within
//             threshold window (7e3-2e4 counts); electrode
//             actuated to divert droplet to collection channel.
//             3 uL PBS recovery buffer pre-generated and
//             'parked' at collection outlet at 1 uL/s.
//             After 7 s delay, sorted 1 nL droplet arrives
//             and merges with recovery buffer via 3x electrode
//             actuation (500 ms/actuation). Merged ~4 uL
//             volume pipetted (P20, 5 uL) into individual
//             well of 96-well plate (pre-filled: 100 uL PBS).
// Fail (BB3): beadSignal <= 0 -> no bead, multi-bead droplet,
//             or signal outside threshold window; droplet
//             diverted to waste by default flow direction.
// Both branches converge at BB4 (beadSortJoin).
// ============================================================

if (beadSignal > 0) {
    // Generate 3 uL recovery buffer at collection outlet.
    // Injected at 1 uL/s from 500 uL gastight syringe via
    // 1/32" PEEK tubing. Buffer 'parked' at semicircular
    // outlet before sorted droplet arrives.
    recoveryBufferBead = dispense 1 units of RecoveryBuffer_PBS

    // Electrode actuation merges sorted droplet with buffer.
    // 7 s delay post-sort allows droplet to travel from
    // sorting junction to collection outlet (~6 electrode
    // pairs arrest droplet in transit). 3x actuation
    // at 140 Vrms, 15 kHz, 500 ms per actuation.
    // NOTE: `mix` abstracts DMF electrode merging event.
    mergedBeadDrop = mix beadDroplets with recoveryBufferBead for 2s

    // Transfer merged contents (~4 uL) to individual well
    // of 96-well plate pre-loaded with 100 uL PBS per well.
    // Manual P20 pipette set to 5 uL collects all media.
    // Each transfer operation: ~10 s.
    dispose mergedBeadDrop
} else {
    drain beadDroplets
}

// ============================================================
// BB4: beadSortJoin
// Dispose bead detection signal. Control falls into
// GFP HEK293 cell sorting branch (BB5/BB6).
// ============================================================

dispose beadSignal

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 1: Prepare rare GFP HEK293 cell mixture.
//   GFP-expressing HEK293 and WT HEK293 cells both adjusted
//   to 1e6 cells/mL. Spiked at 1:400 and 1:1000 (GFP:WT)
//   ratios. Total volumes: 10,000 cells (400 uL) and
//   100,000 cells (400 uL) per tube.
//   80 uL OptiPrep added per 400 uL cell suspension to
//   improve density matching and reduce sedimentation.
//   Cells resuspended in PBS, loaded into 1 mL BD syringes.
//   NOTE: This step models the 1:1000 ratio condition
//   (rarest condition, 0.1% target frequency) as the
//   representative case for the CFG branch.
// ------------------------------------------------------------

gfpCells        = dispense 1 units of GFP_HEK293_Cells
wtCells         = dispense 1 units of WT_HEK293_Cells
optiprepCell    = dispense 1 units of OptiPrep

// Prepare spiked mixture: GFP cells diluted into WT background.
// Mix abstracts the tube-level spiking and vortex step.
spikeMix        = mix gfpCells with wtCells for 5s
cellSuspension  = mix spikeMix with optiprepCell for 5s

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 2: Encapsulate rare GFP cells in ~1 nL
//   droplets using the same flow-focusing D2 device.
//   Aqueous cell phase at 0.05 uL/s; oil phase at 0.15 uL/s.
//   Cell encapsulation follows Poisson statistics. Sorting
//   threshold set at 1e3 to 2.5e3 photon counts for single
//   GFP cell detection (lower than bead threshold due to
//   lower fluorescence intensity of single GFP-expressing cells).
//   Well plate pre-filled: 100 uL DMEM per well.
// ------------------------------------------------------------

oilCell         = dispense 1 units of HFE7500_Surfactant
cellDroplets    = mix cellSuspension with oilCell for 2s

// Fiber-optic PMT detection: 470 nm excitation, ~520 nm GFP
// emission. Sorting threshold: 1e3 to 2.5e3 photon counts.
cellSignal      = detect singleCellGFPDetection on cellDroplets for 10s

// ============================================================
// BB5 / BB6: GFP cell sorting QC gate
// Pass (BB5): cellSignal > 0 -> single GFP cell in threshold
//             window; electrode actuation diverts to collection.
//             3 uL DMEM recovery buffer pre-generated at outlet.
//             7 s delay; 3x electrode actuation (500 ms each)
//             merges droplet with recovery buffer.
//             Merged volume pipetted to individual well.
// Fail (BB6): cellSignal <= 0 -> WT cell, empty droplet, or
//             multi-cell droplet; routed to waste.
// Both branches converge at BB7 (cellSortJoin).
// ============================================================

if (cellSignal > 0) {
    recoveryBufferCell = dispense 1 units of RecoveryBuffer_DMEM
    mergedCellDrop     = mix cellDroplets with recoveryBufferCell for 2s
    dispose mergedCellDrop
} else {
    drain cellDroplets
}

// ============================================================
// BB7: cellSortJoin
// Dispose cell detection signal. Control falls into
// post-sort viability assay branch (BB8/BB9).
// ============================================================

dispose cellSignal

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 3: Post-sort cell culture and viability.
//   After recovery into 96-well plate:
//   - First 24 h: 150 uL conditioned media per well
//     (30% spent eGFP HEK supernatant, 0.22 um filtered,
//     + 70% fresh DMEM + 10% FBS + 1% P/S).
//   - Subsequent additions: 50 uL fresh DMEM + 10% FBS
//     + 1% P/S every 48 h for 7 days.
//   - Viability monitored every 24 h using SYTOX Blue
//     dead cell stain (10 wells per time point).
//   - Proliferation imaged every 24 h (EVOS M5000).
//   - Incubation: 37 C / 5% CO2.
//   NOTE: 7 days = 10080 min; BioScript supports only s/m.
//
//   BUG FIX: mergedCellDrop is disposed inside the BB5 pass
//   branch (after pipetting into the well). It cannot be
//   referenced again in BB7. The viability assay acts on
//   the well contents AFTER the cell has been deposited and
//   cultured. A fresh DMEM_Complete droplet is dispensed
//   here to represent the well environment (pre-loaded
//   100 uL DMEM + 10% FBS + 1% P/S) into which the
//   recovered cell was placed. This correctly models the
//   post-sort culture step without referencing a disposed
//   variable.
// ------------------------------------------------------------

wellEnvironment     = dispense 1 units of DMEM_Complete
conditionedMediaHEK = dispense 1 units of ConditionedMedia_HEK
sytoxBlue           = dispense 1 units of SYTOX_Blue

// 24 h conditioned media incubation (= 1440 min).
// wellEnvironment represents the 96-well plate contents
// (pre-loaded DMEM) combined with conditioned media top-up.
cellCultureInit     = mix wellEnvironment with conditionedMediaHEK for 1440m
heat cellCultureInit at 37c for 1440m

// SYTOX Blue viability stain applied at 24 h intervals.
// Live cells exclude SYTOX Blue (non-blue = viable).
// Dead cells stain blue under fluorescence.
// Viability = (non-blue wells) / (total stained wells) x 100.
stainedCells        = mix cellCultureInit with sytoxBlue for 30s
viabilitySignal     = detect viabilityDetection on stainedCells for 60s

// ============================================================
// BB8 / BB9: Post-sort viability QC gate
// Pass (BB8): viabilitySignal > 0 -> cell viable (~90%);
//             continue 7-day expansion (10080 min total,
//             subtracting 1440 min already elapsed = 8640 min).
//             Cells exhibit spreading (positive viability
//             indicator). Dispose after full expansion.
// Fail (BB9): viabilitySignal <= 0 -> non-viable cell; drain.
// Both branches converge at BB10 (viabilityJoin).
// ============================================================

if (viabilitySignal > 0) {
    // Continue clonal expansion: 6 days remaining = 8640 min.
    // Fresh DMEM + 10% FBS + 1% P/S added every 48 h.
    // Proliferation images taken every 24 h (EVOS M5000).
    freshDMEM    = dispense 1 units of DMEM_Complete
    expandedCell = mix stainedCells with freshDMEM for 8640m
    heat expandedCell at 37c for 8640m
    dispose expandedCell
} else {
    drain stainedCells
}

// ============================================================
// BB10: viabilityJoin
// Dispose viability signal. Control falls into hybridoma
// antibody assay branch (BB11/BB12).
// ============================================================

dispose viabilitySignal

// ------------------------------------------------------------
// PROTOCOL 3 - STEP 1: Prepare hybridoma cell mixtures.
//   Two hybridoma lines:
//   (A) Specific-Ab producer: secretes mAbs that bind to
//       surface antigen of target cells. Stained with
//       calcein-AM red-orange (per manufacturer protocol).
//   (B) Non-specific-Ab producer: secretes mAbs that do
//       not bind target cell surface. Unstained.
//   Mixed at 1:400 (0.25%) and 1:1000 (0.1%) specific:non-
//   specific ratios to model rare antigen-specific B cells
//   (0.1-2% of isolated B cells in literature).
//   Final concentration: 1e6 cells/mL in IMDM (no phenol
//   red) + 10% FBS + 1 ng/mL IL-6 (no antibiotics).
//   11% (w/v) OptiPrep added for density matching.
//   NOTE: 1:1000 ratio modelled as representative rare case.
// ------------------------------------------------------------

specificHybridoma    = dispense 1 units of HybridomaSpecific_Cells
nonspecificHybridoma = dispense 1 units of HybridomaNonSpecific_Cells
calceingAM           = dispense 1 units of CalceinAM_RedOrange
il6Supplement        = dispense 1 units of IL6_Supplement
optiprepHybrid       = dispense 1 units of OptiPrep

// Stain specific hybridoma cells with calcein-AM red-orange.
stainedSpecific = mix specificHybridoma with calceingAM for 30m

// Prepare spiked hybridoma mixture (1:1000 specific:nonspecific).
hybridomaMixRaw  = mix stainedSpecific with nonspecificHybridoma for 5s
hybridomaMix     = mix hybridomaMixRaw with optiprepHybrid for 5s
hybridomaFinal   = mix hybridomaMix with il6Supplement for 5s

// ------------------------------------------------------------
// PROTOCOL 3 - STEP 2: Prepare target cells for co-encapsulation.
//   Target cells: antigen-overexpressing line.
//   Dissociated with non-enzymatic cell dissociation solution
//   (1x, pre-warmed 37 C) to preserve surface antigen.
//   Resuspended at 3e6 cells/mL in IMDM (no phenol red) +
//   10% FBS + 1 ng/mL IL-6.
//   Stained with CellTrace Blue (per manufacturer protocol).
//   Alexa Fluor 488 goat anti-mouse IgG secondary antibodies
//   added at 2.5 ug/mL to detect specific mAb binding.
//   11% OptiPrep added for density matching.
//   Flow rate: 0.3 uL/s from dedicated co-encapsulation inlet.
// ------------------------------------------------------------

targetCells       = dispense 1 units of TargetCells
cellTraceBlue     = dispense 1 units of CellTrace_Blue
alexaFluor488     = dispense 1 units of AlexaFluor488_AntiMouse
optiprepTarget    = dispense 1 units of OptiPrep

// Stain target cells with CellTrace Blue.
stainedTargets    = mix targetCells with cellTraceBlue for 20m

// Add Alexa Fluor 488 secondary antibody to target cell suspension.
// Enables detection of specific mAb binding via green fluorescence
// accumulation on target cell surface after co-incubation.
targetWithAb      = mix stainedTargets with alexaFluor488 for 5s
targetFinal       = mix targetWithAb with optiprepTarget for 5s

// ------------------------------------------------------------
// PROTOCOL 3 - STEP 3: Co-encapsulation (off-chip co-encap device).
//   A separate co-encapsulation chip (flow-focusing, two cell
//   inlets) is used to generate double-cell droplets.
//   Hybridoma mixture inlet: 0.3 uL/s.
//   Target cell + secondary Ab inlet: 0.3 uL/s.
//   HFE7500 + 2% surfactant oil phase: 0.8 uL/s.
//   Withdrawal syringe (BD 1 mL plastic): 1.4 uL/s.
//   Target occupancy: 5-10% double-cell droplets
//   (hybridoma + target pair) by Poisson statistics.
//   Droplets collected in withdrawal syringe for off-chip
//   incubation. `mix` abstracts co-encapsulation flow event.
// ------------------------------------------------------------

oilCoEncap        = dispense 1 units of HFE7500_Surfactant
coEncapDroplets   = mix hybridomaFinal with targetFinal for 5s
encapsulatedPairs = mix coEncapDroplets with oilCoEncap for 2s

// ------------------------------------------------------------
// PROTOCOL 3 - STEP 4: Off-chip incubation of co-encapsulated
//   droplets at 37 C / 5% CO2 for 2 hours (= 120 min).
//   During incubation, specific mAbs secreted by hybridoma
//   cells bind to the surface antigen of co-encapsulated
//   target cells. Alexa Fluor 488 secondary antibodies then
//   bind to any surface-bound primary mAb, generating a sharp,
//   high-intensity green fluorescence signal (>18,000 photon
//   counts) unique to specific-Ab-secreting + target cell pairs.
//   Droplets with only non-specific hybridoma cells emit medium
//   fluorescence; droplets with only target cells emit background.
// ------------------------------------------------------------

heat encapsulatedPairs at 37c for 120m

// ------------------------------------------------------------
// PROTOCOL 3 - STEP 5: Re-injection into D2 sorting device.
//   Off-chip incubated droplets re-injected into the D2
//   sorting chip at 0.02 uL/s (slower to maintain droplet
//   integrity during re-injection).
//   Spacing oil: 0.15 uL/s.
//   Waste syringe: -0.12 uL/s.
//   Green channel (Alexa Fluor 488) fluorescence detected
//   at PMT. Sorting threshold: 1.8e4 to 3e4 photon counts.
//   Only droplets exceeding 18,000 photon count threshold
//   (specific mAb + target cell doublets) are sorted.
//   NOTE: All droplets contain identical background level of
//   Alexa Fluor 488 secondary antibody in solution; the
//   threshold distinguishes surface-accumulated (bound) signal
//   from free-floating secondary antibody baseline.
// ------------------------------------------------------------

oilReinject       = dispense 1 units of HFE7500_Surfactant
reinjectedDroplets = mix encapsulatedPairs with oilReinject for 2s

abSignal = detect antibodyBindingDetection on reinjectedDroplets for 10s

// ============================================================
// BB11 / BB12: Antibody binding sorting QC gate
// Pass (BB11): abSignal > 0 -> droplet fluorescence in
//              1.8e4 to 3e4 photon count window;
//              specific-Ab-secreting hybridoma + target cell
//              doublet confirmed.
//              3 uL IMDM recovery buffer (10% FBS, 1 ng/mL
//              IL-6) pre-generated at collection outlet at
//              1 uL/s. 7-9 s delay post-sort; 3x electrode
//              actuation (140 Vrms, 15 kHz, 500 ms/actuation)
//              merges sorted droplet with recovery buffer.
//              Merged contents pipetted (P20, 5 uL) to
//              individual well of 96-well plate pre-loaded
//              with 100 uL IMDM (10% FBS, 1 ng/mL IL-6,
//              1% P/S). Plate moved to incubator immediately.
//              Recovery rate: ~88% at 1:400; ~78% at 1:1000.
// Fail (BB12): abSignal <= 0 -> non-specific hybridoma,
//              target-only, or empty droplet; routed to waste.
// Both branches converge at BB13 (finalCleanup).
// ============================================================

if (abSignal > 0) {
    // Generate 3 uL IMDM recovery buffer at collection outlet.
    // IMDM: 10% FBS, 1 ng/mL IL-6, 1% P/S (no phenol red).
    recoveryBufferIMDM = dispense 1 units of RecoveryBuffer_IMDM

    // Merge sorted ~1 nL droplet with 3 uL recovery buffer.
    // 7-9 s delay allows droplet to travel to collection site.
    // 3x electrode actuation at 140 Vrms, 15 kHz (500 ms each).
    // NOTE: `mix` abstracts DMF electrode actuation for merging.
    mergedAbDrop = mix reinjectedDroplets with recoveryBufferIMDM for 3s

    // Pipette merged contents to 96-well plate for downstream
    // analysis. Plate pre-loaded with IMDM culture medium.
    // Well plate imaged using EVOS M5000 imaging system.
    // Specific-Ab hybridoma identified by: calcein-AM red
    // fluorescence (hybridoma) + CellTrace Blue (target cell) +
    // Alexa Fluor 488 green (bound antibody) co-localisation.
    dispose mergedAbDrop
} else {
    drain reinjectedDroplets
}

// ============================================================
// BB13: finalCleanup (terminal)
// Dispose all QC detection signal droplets.
// All three experimental protocols complete.
// Experiment ends.
// ============================================================

dispose abSignal

// [terminal -- no further instructions; exit node for CFG]

module cellTrackingDetection
module lysM_GFP_Detection
module f480_MacrophageDetection
module erkktr_ERKDetection

manifest PBS
manifest Fibronectin
manifest PluronicF127
manifest StemSpanSFEM
manifest SCF_IL3_IL6_Media
manifest MCSF_Media
manifest RhodamineDextran_40kDa
manifest PolystyrenBeads_10um
manifest LysM_GFP_GMPs
manifest AntiF480_APC_Antibody
manifest DMEM_SelfRenewing
manifest DMEM_Starvation
manifest FGF1_StarvationMedia
manifest MuESC_ERKKTR

instructions:

// ============================================================
// Automated Microfluidic System for Dynamic Stimulation and
// Tracking of Single Cells
// Dettinger, Frank, Etzrodt, Ahmed, Reimann, Trenzinger,
// Loeffler, Kokkaliaris, Schroeder, Tay
// Analytical Chemistry, 2018
// DOI: 10.1021/acs.analchem.8b00312
//
// Two protocols are encoded in sequence:
//
// PROTOCOL 1: Long-term culture and differentiation of murine
//   hematopoietic stem and progenitor cells (GMPs) under
//   dynamic M-CSF / permissive media stimulation via
//   diffusion-based media exchange every 30 min. LysM-GFP
//   expression tracked over 96 h as a differentiation marker.
//   In-culture F4/80 antibody staining performed as macrophage
//   commitment reporter.
//
// PROTOCOL 2: Dynamic FGF1 stimulation of murine embryonic
//   stem cells (muESCs) expressing the ERK kinase translocation
//   reporter (ERKKTR). Chip oscillates between FGF1-containing
//   starvation media and plain starvation media with 5 s / 2 s
//   flow pulses and 32 min / 15 min incubation periods.
//   ERK nuclear-to-cytoplasmic ratio imaged every 3 min.
//
// CHIP ARCHITECTURE:
//   Two-layer PDMS device. 48 independent cell culture chambers
//   (1000 um x 350 um x 25 um tall). 16 independent inputs,
//   2 outlets/harvesting ports. On-chip four-valve peristaltic
//   pump. Two media reservoirs per chamber connected via
//   50-um-wide diffusion ports (Fick's Law diffusive exchange).
//   Flow switching strategy alternates left and right reservoir
//   flushing to prevent direct flow into culture chambers.
//   Media equilibration time: ~10-20 min per chamber.
//
// NOTE ON FLOW ABSTRACTION:
//   `mix` steps represent the valve-controlled flow-switching
//   and diffusive media exchange events. No direct flow enters
//   culture chambers; diffusion is the sole mass-transfer mode
//   inside the cell culture area. The `mix` primitive is used
//   here to represent the convergence of the culture droplet
//   with fresh media in the flanking reservoir channels, which
//   then equilibrate by diffusion through the 50-um port.
//
// NOTE ON TIMING:
//   BioScript duration tokens: s (seconds), m (minutes) only.
//   96 h = 5760 m. 48 h = 2880 m. 16 h = 960 m. 7 d = 10080 m.
//
// CFG STRUCTURE:
//   BB1  main                 -- chip priming, validation,
//                                GMP seeding and culture
//   BB2  differentiationPass  -- lysM_GFP signal > 0: M-CSF
//                                drove differentiation; dispose
//   BB3  differentiationFail  -- lysM_GFP signal <= 0: no
//                                differentiation detected; drain
//   BB4  differentiationJoin  -- join: antibody staining branch
//   BB5  antibodyPass         -- f480Signal > 0: macrophage
//                                commitment confirmed; dispose
//   BB6  antibodyFail         -- f480Signal <= 0: no F4/80
//                                signal; drain
//   BB7  antibodyJoin         -- join: muESC ERKKTR protocol
//   BB8  erkPass              -- erkSignal > 0: valid ERK
//                                translocation detected; dispose
//   BB9  erkFail              -- erkSignal <= 0: no ERK
//                                response; drain
//   BB10 finalCleanup         -- terminal: dispose all QC
//                                signals, experiment ends
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prime chip with PBS to expel air from all channels.
//   Pressure applied via liquid supply lines while outlet
//   valves remain closed. Required before all biological use.
//   Surface must be fully wetted prior to functionalization.
// ------------------------------------------------------------

primingPBS = dispense 1 units of PBS

// ------------------------------------------------------------
// STEP 2: Surface functionalization with fibronectin.
//   Flow fibronectin (150 ng/mL) through all flow channels
//   for 3 h at room temperature (~25 C) to coat PDMS surfaces.
//   This step promotes hematopoietic progenitor attachment and
//   prevents non-specific adhesion during long-term culture.
//   Followed by extensive PBS washing and media equilibration.
//   NOTE: `mix` here represents flow-through coating of
//   channel surfaces, not droplet-level mixing.
// ------------------------------------------------------------

fibronectinCoat  = dispense 1 units of Fibronectin
coatedDevice     = mix primingPBS with fibronectinCoat for 3m

// 3 h functionalization at room temperature (180 m).
heat coatedDevice at 25c for 180m

// Wash with PBS after coating to remove unbound fibronectin.
pbsWash = dispense 1 units of PBS
washedDevice = mix coatedDevice with pbsWash for 5s

// ------------------------------------------------------------
// STEP 3: Chip validation - bead flow test.
//   10-um polystyrene beads (Spherotech) are flushed through
//   device after 0.1% Triton-X detergent treatment to prevent
//   aggregation. Bead translocation within cell culture area
//   is confirmed to be <2 um after 15 s of media reservoir
//   flushing, validating absence of direct flow in chambers.
//   40 kDa rhodamine-dextran (300 uM) used for diffusion rate
//   calibration (comparable size to cytokines).
// ------------------------------------------------------------

beads            = dispense 1 units of PolystyrenBeads_10um
rhodamineDextran = dispense 1 units of RhodamineDextran_40kDa

// Simulate 15 s reservoir flush to validate chamber isolation.
beadValidation   = mix beads with washedDevice for 15s
diffusionCalib   = mix rhodamineDextran with washedDevice for 30m

validationSignal = detect cellTrackingDetection on beadValidation for 15s

// ============================================================
// Flow switching: alternating left/right reservoir fill.
// Reservoir 1 (left) filled first; right-side valves closed.
// Then mirrored to fill right reservoir; left valves closed.
// This eliminates cross-chamber pressure-driven flow.
// Oscillation periods: 20 min or 40 min (paper Fig. 2B).
// Steady state reached within 10 min of each switching cycle.
// ============================================================

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 1: Seed LysM-GFP GMPs into chip chambers.
//   4-90 GMPs seeded per chamber via pressurized
//   microcentrifuge tube through PEEK tubing (ID = 65 um).
//   Peristaltic pump allows precise deposition of cell number.
//   lin-/Sca1-/c-Kit+/CD34+/CD16/32+ cells sorted by FACS
//   from C57BL/6J LysM-GFP bone marrow (male, 12-14 weeks).
//   Chip pre-filled with Stem-Span SFEM + 10% FCS + SCF/IL3/IL6.
// ------------------------------------------------------------

gmpCells         = dispense 1 units of LysM_GFP_GMPs
sfemMedia        = dispense 1 units of StemSpanSFEM

// Load cells into chamber via targeted seeding (peristaltic pump).
seededChamber    = mix gmpCells with sfemMedia for 2s

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 2: Baseline culture in permissive media.
//   Stem-Span SFEM + 1% pen/strep + 10% FCS + 100 ng/mL SCF +
//   10 ng/mL IL3 + 10 ng/mL IL6. Diffusion-based media
//   exchange every 30 min (flow-switching, ~30 min intervals).
//   Cells maintained without direct flow across culture area.
//   Proliferation and cell cycle comparable to standard Ibidi
//   VI channel slides (paper Figs. S1A, S1B).
//
//   NOTE: 48 h initial expansion before M-CSF arm switch.
//   48 h = 2880 m.
// ------------------------------------------------------------

permissiveMedia  = dispense 1 units of SCF_IL3_IL6_Media

// Exchange 1: left reservoir filled with fresh permissive media.
feedCycle1L      = mix seededChamber with permissiveMedia for 5s

// Exchange 2: right reservoir filled (alternating strategy).
permissiveMedia2 = dispense 1 units of SCF_IL3_IL6_Media
feedCycle1R      = mix feedCycle1L with permissiveMedia2 for 5s

// Baseline proliferation phase (48 h = 2880 m) at 37 C.
// 5% CO2 / 5% O2 / 90% N2 maintained by stage-top enclosure.
heat feedCycle1R at 37c for 2880m

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 3: Switch to M-CSF differentiation media.
//   20 ng/mL M-CSF replaces SCF/IL3/IL6 in media reservoirs.
//   Flow-switching maintains diffusion exchange every 30 min.
//   LysM-GFP expression monitored by time-lapse fluorescence
//   imaging every 30 min (Nikon Ti-eclipse, 10x/NA0.45, ORCA
//   Flash IV camera). Single-cell tracking performed using tTt.
//   Observation period: 96 h from seeding (= 5760 m total,
//   so 5760 - 2880 = 2880 m remaining after baseline phase).
//
//   Result: 77% of M-CSF colonies upregulate LysM-GFP within
//   96 h vs. 54% without M-CSF (p=0.001636, Kolmogorov-Smirnov).
// ------------------------------------------------------------

mcsfMedia        = dispense 1 units of MCSF_Media

// Flow-switch cycle: M-CSF into left reservoir.
mcsfFeedL        = mix feedCycle1R with mcsfMedia for 5s

// Flow-switch cycle: M-CSF into right reservoir.
mcsfMedia2       = dispense 1 units of MCSF_Media
mcsfFeedR        = mix mcsfFeedL with mcsfMedia2 for 5s

// Differentiation culture (2880 m = remaining 48 h of 96 h total).
heat mcsfFeedR at 37c for 2880m

// Detect LysM-GFP upregulation as macrophage differentiation signal.
differentiationSignal = detect lysM_GFP_Detection on mcsfFeedR for 30s

// ============================================================
// BB2 / BB3: Differentiation QC gate
// Pass (BB2): differentiationSignal > 0 -> LysM-GFP
//             upregulation detected (macrophage commitment);
//             dispose culture droplet and continue.
// Fail (BB3): differentiationSignal <= 0 -> no detectable
//             LysM-GFP induction; drain culture droplet.
// Both branches converge at BB4 (differentiationJoin).
// ============================================================

if (differentiationSignal > 0) {
    dispose mcsfFeedR
} else {
    drain mcsfFeedR
}

// ============================================================
// BB4: differentiationJoin
// Dispose differentiation QC signal. Control falls into
// in-culture antibody staining branch (BB5/BB6).
// ============================================================

dispose differentiationSignal

// ------------------------------------------------------------
// PROTOCOL 1 - STEP 4: In-culture continuous antibody staining.
//   Anti-F4/80-APC antibody (clone BM8, eBioscience,
//   0.2 mg/mL at 1:10,000 dilution) added to all media during
//   M-CSF culture period. Automated fluid replacement
//   incorporates antibody in each 30-min diffusion feed cycle.
//   F4/80 is a molecular reporter for macrophage commitment.
//   Fluorescence signal detected on differentiated cells
//   confirms macrophage lineage.
// ------------------------------------------------------------

freshGMPs        = dispense 1 units of LysM_GFP_GMPs
antibodyMedia    = dispense 1 units of AntiF480_APC_Antibody
mcsfForAb        = dispense 1 units of MCSF_Media
mcsfWithAb       = mix antibodyMedia with mcsfForAb for 5s

// Seed fresh GMPs for antibody staining experiment.
sfemMedia2       = dispense 1 units of StemSpanSFEM
antibodyChamber  = mix freshGMPs with sfemMedia2 for 2s

// Baseline phase in permissive media (2880 m) before antibody run.
permissiveBase   = dispense 1 units of SCF_IL3_IL6_Media
abFeedBaseL      = mix antibodyChamber with permissiveBase for 5s
permissiveBase2  = dispense 1 units of SCF_IL3_IL6_Media
abFeedBaseR      = mix abFeedBaseL with permissiveBase2 for 5s
heat abFeedBaseR at 37c for 2880m

// Switch to M-CSF + antibody media for full 96 h observation.
// Anti-F4/80-APC continuously present in diffusion media.
mcsfAb           = dispense 1 units of AntiF480_APC_Antibody
mcsfAbFeedL      = mix abFeedBaseR with mcsfAb for 5s
mcsfAb2          = dispense 1 units of AntiF480_APC_Antibody
mcsfAbFeedR      = mix mcsfAbFeedL with mcsfAb2 for 5s
heat mcsfAbFeedR at 37c for 2880m

// Detect F4/80 fluorescence as macrophage commitment signal.
f480Signal = detect f480_MacrophageDetection on mcsfAbFeedR for 30s

// ============================================================
// BB5 / BB6: Antibody staining QC gate
// Pass (BB5): f480Signal > 0 -> F4/80-APC fluorescence
//             detected on differentiated cells; dispose.
// Fail (BB6): f480Signal <= 0 -> no macrophage marker
//             detected; drain.
// Both branches converge at BB7 (antibodyJoin).
// ============================================================

if (f480Signal > 0) {
    dispose mcsfAbFeedR
} else {
    drain mcsfAbFeedR
}

// ============================================================
// BB7: antibodyJoin
// Dispose antibody staining QC signal. Control falls into
// muESC ERKKTR dynamic stimulation branch (BB8/BB9).
// ============================================================

dispose f480Signal

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 1: Seed murine ESCs (ERKKTR reporter).
//   Line R1 muESCs expressing ERK kinase translocation
//   reporter (ERKKTR). ~10 cells seeded per chamber.
//   E-Cadherin (150 ng/mL) used instead of fibronectin for
//   ESC surface functionalization (already encoded in STEP 2
//   above as a general fibronectin step - for ESCs, substitute
//   E-Cadherin in the same step; BioScript does not distinguish
//   surface coating reagent identity at the compiler level).
//
//   Cells cultured 2 days under self-renewing conditions:
//   DMEM + 10% FCS + 1000 U/mL Lif. Medium replaced every
//   30 min by diffusion feed cycle.
//   2 days = 2880 m.
// ------------------------------------------------------------

muESCells        = dispense 1 units of MuESC_ERKKTR
selfRenewMedia   = dispense 1 units of DMEM_SelfRenewing

// Seed muESCs into functionalized chamber.
escChamber       = mix muESCells with selfRenewMedia for 2s

// 2-day self-renewing culture at 37 C (2880 m).
selfRenewMedia2  = dispense 1 units of DMEM_SelfRenewing
escFeedL         = mix escChamber with selfRenewMedia2 for 5s
selfRenewMedia3  = dispense 1 units of DMEM_SelfRenewing
escFeedR         = mix escFeedL with selfRenewMedia3 for 5s
heat escFeedR at 37c for 2880m

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 2: Overnight starvation before stimulation.
//   Cells switched to 0.5% FCS DMEM without Lif for 16 h
//   prior to FGF1 stimulation experiments. Same 30-min
//   diffusion feeding cadence. Starvation synchronises
//   ERK baseline state across all cells.
//   16 h = 960 m.
// ------------------------------------------------------------

starvationMedia  = dispense 1 units of DMEM_Starvation

starvFeedL       = mix escFeedR with starvationMedia for 5s
starvationMedia2 = dispense 1 units of DMEM_Starvation
starvFeedR       = mix starvFeedL with starvationMedia2 for 5s

// Overnight starvation (960 m = 16 h) at 37 C.
heat starvFeedR at 37c for 960m

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 3: Dynamic FGF1 stimulation cycle.
//   Chip programmed to oscillate between:
//     - FGF1 arm:  10 ng/mL recombinant mouse FGF1 (R&D
//                  Systems) in starvation media; 5 s flow
//                  pulse into left reservoir; 32 min incubation.
//     - Wash arm:  plain starvation media; 2 s flow pulse
//                  into right reservoir; 15 min incubation.
//   This produces periodically increasing and decreasing
//   levels of FGF1 in the cell culture chamber over several
//   hours (paper Section: Embryonic Stem Cell Culture).
//
//   NOTE ON ABSTRACTION: Each `mix` step below encodes one
//   complete flow-switching event (reservoir fill + passive
//   diffusion equilibration). The 5 s / 2 s durations are
//   the reservoir flushing pulses. Incubation (32 m / 15 m)
//   is represented by the subsequent `heat` at 37 C.
//   Three complete oscillation cycles are encoded
//   (FGF1 on -> off -> on -> off -> on -> off) to represent
//   the multi-hour dynamic stimulation experiment.
//
//   93% of cells adjacent to reservoir respond within 3 min.
//   All cells respond within 10 min of stimulation onset.
//   ERK activity imaged every 3 min (ERKKTR nuclear/cyto ratio).
// ------------------------------------------------------------

fgf1Media        = dispense 1 units of FGF1_StarvationMedia

// ---- Oscillation Cycle 1: FGF1 ON ----
// 5 s pulse: FGF1 starvation media flows into left reservoir.
fgf1FeedL_C1     = mix starvFeedR with fgf1Media for 5s

// 32 min incubation: FGF1 diffuses into cell culture area.
heat fgf1FeedL_C1 at 37c for 32m

// 2 s pulse: plain starvation media washes right reservoir.
washMedia1       = dispense 1 units of DMEM_Starvation
washFeedR_C1     = mix fgf1FeedL_C1 with washMedia1 for 2s

// 15 min incubation: FGF1 dilutes from chamber by diffusion.
heat washFeedR_C1 at 37c for 15m

// ---- Oscillation Cycle 2: FGF1 ON ----
fgf1Media2       = dispense 1 units of FGF1_StarvationMedia
fgf1FeedL_C2     = mix washFeedR_C1 with fgf1Media2 for 5s
heat fgf1FeedL_C2 at 37c for 32m

washMedia2       = dispense 1 units of DMEM_Starvation
washFeedR_C2     = mix fgf1FeedL_C2 with washMedia2 for 2s
heat washFeedR_C2 at 37c for 15m

// ---- Oscillation Cycle 3: FGF1 ON ----
fgf1Media3       = dispense 1 units of FGF1_StarvationMedia
fgf1FeedL_C3     = mix washFeedR_C2 with fgf1Media3 for 5s
heat fgf1FeedL_C3 at 37c for 32m

washMedia3       = dispense 1 units of DMEM_Starvation
washFeedR_C3     = mix fgf1FeedL_C3 with washMedia3 for 2s
heat washFeedR_C3 at 37c for 15m

// ------------------------------------------------------------
// PROTOCOL 2 - STEP 4: Detect ERK kinase translocation signal.
//   ERKKTR nuclear-to-cytoplasmic ratio reported by the
//   erkktr_ERKDetection module. Images taken every 3 min
//   over entire dynamic stimulation period. Signal reflects
//   ERK activity as a function of oscillating FGF1 input.
//   Signal keyed on final wash-phase chamber state.
// ------------------------------------------------------------

erkSignal = detect erkktr_ERKDetection on washFeedR_C3 for 3m

// ============================================================
// BB8 / BB9: ERK detection QC gate
// Pass (BB8): erkSignal > 0 -> ERK translocation detected
//             (nuclear C/N ratio drop confirms FGF1 response);
//             dispose ESC chamber contents.
// Fail (BB9): erkSignal <= 0 -> no detectable ERK response;
//             drain ESC chamber contents.
// Both branches converge at BB10 (finalCleanup).
// ============================================================

if (erkSignal > 0) {
    dispose washFeedR_C3
} else {
    drain washFeedR_C3
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose all outstanding QC signal droplets.
// Dispose chip validation signal from STEP 3.
// Experiment ends.
// ============================================================

dispose erkSignal
dispose validationSignal
dispose diffusionCalib

// [terminal -- no further instructions; exit node for CFG]

module beadCountDetection

manifest PolyBeads_LysisBuffer
manifest PBS

// ============================================================
// Measuring Droplet Volume in Home-Made Microfluidic Devices
// Protocol Source: Drop-seq / home-made microfluidic device
// calibration procedure (Harvard / McCarroll Lab style).
// DOI / Reference: standard lab protocol (no primary paper DOI).
//
// Purpose: Determine droplet volume in a home-made droplet-
// microfluidic device using monodisperse polystyrene beads as
// a volumetric calibration standard (Poisson-statistics-based
// droplet occupancy method).
//
// Reagents:
//   PolyBeads_LysisBuffer : durable, monodisperse polystyrene
//     beads (~10 um, carboxylated, e.g. Bangs Labs PC06N-11355
//     or fluorescent FC06F-10163) washed and resuspended in
//     Drop-seq lysis buffer at 1000 beads/uL. Loaded in syringe
//     with magnetic mixer as per standard barcoded-bead protocol.
//   PBS : phosphate-buffered saline loaded in the syringe
//     intended for cells. Co-flowing beads with PBS gives an
//     estimated bead concentration of 500 beads/uL in the
//     combined droplet fluid.
//
// Key calculation (post-detection):
//   Droplet occupancy  = (total beads counted) / (droplets counted)
//   Droplet volume     = occupancy / 500 beads per uL
//                      = # uL per droplet
//
// Device/Method scope:
//   This protocol is encoded for a DMF-adjacent or electrode-
//   actuated droplet-generation device. The syringe pump flows
//   are abstracted as dispense operations; the microfluidic
//   chip junction (where beads + PBS co-flow and generate
//   droplets) is abstracted as the first mix step. The bead-
//   counting step (several hundred droplets imaged under
//   microscope, beads counted per droplet) is abstracted as the
//   beadCountDetection module.
//
// CFG STRUCTURE (3 basic blocks):
//   BB1  main          -- dispense beads + PBS, co-flow and
//                         generate droplets, detect bead count
//                         occupancy signal
//   BB2  validDrop     -- beadSignal > 0: valid droplet
//                         population generated; dispose
//   BB3  invalidDrop   -- beadSignal <= 0: no detectable beads
//                         in droplets (device failure or zero
//                         droplet generation); drain
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Dispense polystyrene bead suspension.
//   Beads (10 um carboxylated polystyrene, e.g. Bangs Labs
//   PC06N-11355 / fluorescent FC06F-10163) resuspended in
//   Drop-seq lysis buffer at 1000 beads/uL. Loaded into a
//   syringe with a magnetic mixer and drawn into syringe pump.
//   1 unit represents the bead-loaded syringe volume committed
//   to the droplet-generation run.
// ------------------------------------------------------------

beadSuspension  = dispense 1 units of PolyBeads_LysisBuffer

// ------------------------------------------------------------
// STEP 2: Dispense PBS (cell-channel syringe).
//   The syringe intended for cells is loaded with regular PBS.
//   When co-flowing with the bead suspension at equal volume
//   ratio, the bead concentration in the combined aqueous phase
//   is halved: 1000 / 2 = 500 beads/uL in the droplet fluid.
//   1 unit represents the PBS syringe volume committed to the
//   same run.
// ------------------------------------------------------------

pbsFlow         = dispense 1 units of PBS

// ------------------------------------------------------------
// STEP 3: Co-flow and droplet generation.
//   Connect all tubing to the appropriate channels in the
//   microfluidic device. Both syringe pumps are started:
//   the bead syringe and the PBS syringe co-flow into the
//   aqueous inlet; the oil phase (carrier) generates droplets
//   at the T-junction or flow-focus nozzle.
//
//   NOTE ON ABSTRACTION: `mix` here models the co-flow
//   merging of the two aqueous streams at the chip inlet
//   junction, not a DMF electrode-merging event. The result
//   is a homogeneous bead-containing aqueous phase at
//   500 beads/uL that is subsequently broken into droplets
//   by the oil phase at the nozzle. Duration of 30s models
//   the stabilisation period before droplet collection begins.
// ------------------------------------------------------------

combinedFluid   = mix beadSuspension with pbsFlow for 30s

// ------------------------------------------------------------
// STEP 4: Bead-counting detection (droplet occupancy).
//   Several hundred droplets are imaged under microscopy
//   (fluorescence if fluorescent beads are used; brightfield
//   otherwise). The total number of beads inside all counted
//   droplets is divided by the number of droplets counted to
//   yield the droplet occupancy (mean beads per droplet).
//
//   beadCountDetection module abstracts:
//     (a) image acquisition across >= several hundred droplets,
//     (b) bead segmentation and per-droplet counting,
//     (c) occupancy calculation: occupancy = total_beads /
//         total_droplets counted,
//     (d) volume calculation: droplet volume (uL) =
//         occupancy / 500 beads/uL.
//
//   Detection duration: 60s models the image acquisition
//   and automated counting window for a statistically
//   sound estimate (>= 200 droplets recommended).
//
//   beadSignal > 0 : beads detected in droplets; valid
//                    droplet population; occupancy and
//                    volume calculated successfully.
//   beadSignal <= 0 : no beads detected (device failure,
//                     clogged nozzle, or empty syringe);
//                     drain and troubleshoot.
// ------------------------------------------------------------

beadSignal      = detect beadCountDetection on combinedFluid for 60s

// ============================================================
// BB2 / BB3: Droplet generation QC gate
// Pass (BB2): beadSignal > 0 -> beads detected in droplets;
//             valid droplet population and volume estimate
//             obtained; dispose combined fluid.
// Fail (BB3): beadSignal <= 0 -> no bead signal detected;
//             drain combined fluid (device failure path:
//             check tubing connections, nozzle, oil flow
//             rate, and bead resuspension quality).
// Both branches terminate after their respective operation.
// ============================================================

if (beadSignal > 0) {
    dispose combinedFluid
} else {
    drain combinedFluid
}

// ============================================================
// finalCleanup (terminal)
// Dispose the bead detection QC signal. Experiment ends.
// Calculated droplet volume is available from the
// beadCountDetection module output log.
// ============================================================

dispose beadSignal

// [terminal -- no further instructions; exit node for CFG]

module chemiluminescenceDetection
module rubellaMagneticSeparation
module rubellaCLDetection

manifest PBS
manifest HRP_Standard
manifest SuperSignalSubstrate
manifest WashBuffer
manifest ParamagneticParticles
manifest RubellaIgG_Std_0
manifest RubellaIgG_Std_156
manifest RubellaIgG_Std_3125
manifest HRP_Conjugate
manifest H2O2_Solution
manifest LuminolEnhancer
manifest PluronicL64

// ============================================================
// Paper Microfluidics Goes Digital
// Ryan Fobel, Andrea E. Kirby, Alphonsus H. C. Ng,
// Ramin R. Farnood, and Aaron R. Wheeler
// Advanced Materials 2014, 26, 2838-2843
// DOI: 10.1002/adma.201305168
//
// This file encodes two DMF assays demonstrated on inkjet-
// printed silver-on-paper devices (Design A and Design B),
// fabricated using a Dimatix DMP-2800 printer with SunTronic
// U6503 silver nanoparticle ink. Drop volumes: ~440 nL (Design
// A) and ~750 nL (Design B). Actuation: ~100-125 V_rms, 15 kHz.
//
// ASSAY 1 (Design A): Homogeneous HRP chemiluminescence assay
//   with on-chip serial dilution. HRP standard diluted 1x, 2x,
//   and 4x in PBS by sequential merge + split. Each diluted
//   drop is mixed with SuperSignal substrate for 60 s, driven
//   to the detection zone, and measured by PMT after 2 min.
//   Total: 63 discrete steps (27 dispense, 18 mix, 6 split,
//   12 measure). R^2 = 0.993. Repeated 3 times per condition.
//   All solutions supplemented with 0.05% v/v Pluronic L64
//   to reduce protein adsorption.
//
//   NOTE ON SERIAL DILUTION ABSTRACTION: BioScript has no
//   native split-and-reuse construct. The 1x->2x->4x dilution
//   series is encoded as explicit dispense + merge steps (each
//   dilution level instantiated from fresh reagent) to avoid
//   variable-reuse and split-array compiler constraints. This
//   faithfully represents the droplet operations performed on
//   the paper device.
//
// ASSAY 2 (Design B): Rubella IgG sandwich ELISA using magnetic
//   bead separation. Paramagnetic beads coated with inactivated
//   rubella virus are loaded, incubated with rubella IgG
//   standard, washed 3x, incubated with HRP conjugate, washed
//   3x, resuspended in H2O2, merged with luminol-enhancer, and
//   detected by PMT. Three IgG concentrations tested: 0, 1.56,
//   and 3.125 IU/mL. 30 discrete steps per concentration.
//   LOD = 0.15 IU/mL. R^2 = 0.988. Repeated 2 times.
//
//   NOTE ON MAGNETIC SEPARATION ABSTRACTION: The rubellaMagnetic
//   Separation module abstracts the motorized magnet actuation
//   (engaged to pellet beads, removed for resuspension) paired
//   with DMF electrode switching to separate the bead pellet
//   from the supernatant droplet. This is the core reagent-
//   exchange mechanism in the ELISA workflow (Fig 4a, paper).
//
// CFG STRUCTURE:
//   BB1  main              -- entry: HRP assay serial dilution,
//                             incubation, detection
//   BB2  hrpPass           -- hrpSignal > 0: calibration valid,
//                             dispose all HRP assay droplets
//   BB3  hrpFail           -- hrpSignal <= 0: no signal, drain
//   BB4  hrpJoin           -- join: ELISA branch begins
//   BB5  elisaPass         -- elisaSignal > 0: IgG detected,
//                             dispose all ELISA droplets
//   BB6  elisaFail         -- elisaSignal <= 0: no signal, drain
//   BB7  finalCleanup      -- terminal: dispose QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// ASSAY 1 - STEP 1: Dispense wash buffer droplets.
//   All reagent solutions supplemented with 0.05% v/v Pluronic
//   L64 to reduce protein adsorption and limit cross-
//   contamination (paper M&M, ref [30]).
//   PBS diluent droplets used to generate dilution series.
// ------------------------------------------------------------

pluronic1 = dispense 1 units of PluronicL64
pbs1      = dispense 1 units of PBS
diluent1  = mix pbs1 with pluronic1 for 5s

pluronic2 = dispense 1 units of PluronicL64
pbs2      = dispense 1 units of PBS
diluent2  = mix pbs2 with pluronic2 for 5s

pluronic3 = dispense 1 units of PluronicL64
pbs3      = dispense 1 units of PBS
diluent3  = mix pbs3 with pluronic3 for 5s

// ------------------------------------------------------------
// ASSAY 1 - STEP 2: Dispense HRP standard stock droplets.
//   HRP standard: 100 uU/mL in DPBS + 0.05% v/v Pluronic L64.
//   Three stock droplets dispensed from reservoir (one per
//   dilution level). Each stock drop = 1 unit volume (~440 nL).
//   Paper M&M: "Drops of HRP standard (100 uU/mL in DPBS
//   supplemented with 0.05% v/v L64) and drops of wash buffer
//   were dispensed from reservoirs, mixed, and merged to form
//   a dilution series (1x, 2x, 4x)."
// ------------------------------------------------------------

hrpStock1 = dispense 1 units of HRP_Standard
hrpStock2 = dispense 1 units of HRP_Standard
hrpStock3 = dispense 1 units of HRP_Standard

// ------------------------------------------------------------
// ASSAY 1 - STEP 3: Generate 1x dilution (undiluted HRP drop).
//   The 1x sample is the HRP stock without additional diluent.
//   Mixed briefly to equilibrate on electrode array.
// ------------------------------------------------------------

hrp1x = mix hrpStock1 with diluent1 for 5s

// ------------------------------------------------------------
// ASSAY 1 - STEP 4: Generate 2x dilution.
//   1 unit HRP stock + 1 unit PBS diluent -> 2 units total.
//   Effective concentration: 50 uU/mL (1:2 dilution).
// ------------------------------------------------------------

hrp2x = mix hrpStock2 with diluent2 for 5s

// ------------------------------------------------------------
// ASSAY 1 - STEP 5: Generate 4x dilution.
//   1 unit HRP stock + 3 units PBS diluent -> 4 units total.
//   To accumulate 3 units of diluent, chain two additional
//   PBS+Pluronic mix steps (compiler requires explicit unrolling;
//   no multi-unit accumulation shorthand available).
//   Effective concentration: 25 uU/mL (1:4 dilution).
// ------------------------------------------------------------

pluronic4 = dispense 1 units of PluronicL64
pbs4      = dispense 1 units of PBS
diluent4a = mix pbs4 with pluronic4 for 5s

pluronic5 = dispense 1 units of PluronicL64
pbs5      = dispense 1 units of PBS
diluent4b = mix pbs5 with pluronic5 for 5s

diluent4ab = mix diluent4a with diluent4b for 5s
diluent4   = mix diluent4ab with diluent3 for 5s

hrp4x = mix hrpStock3 with diluent4 for 5s

// ------------------------------------------------------------
// ASSAY 1 - STEP 6: Dispense SuperSignal substrate droplets.
//   SuperSignal ELISA Femto substrate (Thermo Fischer Scientific)
//   comprises two components: stable peroxide (H2O2) and
//   Luminol-Enhancer solution, premixed before loading into
//   reservoir. One substrate drop per dilution level.
//   Paper M&M: "One drop of SuperSignal chemiluminescent
//   substrate was then dispensed, mixed, and merged with each
//   diluted drop of HRP."
// ------------------------------------------------------------

substrate1x = dispense 1 units of SuperSignalSubstrate
substrate2x = dispense 1 units of SuperSignalSubstrate
substrate4x = dispense 1 units of SuperSignalSubstrate

// ------------------------------------------------------------
// ASSAY 1 - STEP 7: Merge HRP dilutions with substrate.
//   Each diluted HRP drop is merged with one substrate drop.
//   Paper M&M: "the pooled drop was mixed for 60 s, driven to
//   the detection area, and the emitted light was measured
//   after 2 min." The 60 s mixing step is encoded here; the
//   2 min pre-measurement incubation is encoded in STEP 8.
// ------------------------------------------------------------

rxn1x = mix hrp1x with substrate1x for 60s
rxn2x = mix hrp2x with substrate2x for 60s
rxn4x = mix hrp4x with substrate4x for 60s

// ------------------------------------------------------------
// ASSAY 1 - STEP 8: Pre-measurement incubation at room
//   temperature (25 C) for 2 min (120 s).
//   Paper M&M: "emitted light was measured after 2 min with
//   an H10682-110 PMT (Hamamatsu Photonics K.K., Japan)."
//   heat step models the 2 min dwell at ambient temperature
//   in the detection zone before PMT readout.
// ------------------------------------------------------------

heat rxn1x at 25c for 2m
heat rxn2x at 25c for 2m
heat rxn4x at 25c for 2m

// ------------------------------------------------------------
// ASSAY 1 - STEP 9: PMT detection of chemiluminescence.
//   chemiluminescenceDetection module abstracts the H10682-110
//   PMT readout (Hamamatsu Photonics K.K., Hamamatsu, Japan).
//   Detection at 425-500 nm emission range. QC gate keyed on
//   the 1x (highest concentration) signal. R^2 = 0.993 across
//   four-point calibration curve (paper Fig 3b).
// ------------------------------------------------------------

hrpSignal1x = detect chemiluminescenceDetection on rxn1x for 30s
hrpSignal2x = detect chemiluminescenceDetection on rxn2x for 30s
hrpSignal4x = detect chemiluminescenceDetection on rxn4x for 30s

// ============================================================
// BB2 / BB3: HRP assay QC gate (keyed on 1x, highest signal)
// Pass (BB2): hrpSignal1x > 0 -> valid calibration signal;
//             dispose all three reaction droplets.
// Fail (BB3): hrpSignal1x <= 0 -> no chemiluminescence (HRP
//             inactive or substrate failure); drain all.
// Both branches converge at BB4 (hrpJoin).
// ============================================================

if (hrpSignal1x > 0) {
    dispose rxn1x
    dispose rxn2x
    dispose rxn4x
} else {
    drain rxn1x
    drain rxn2x
    drain rxn4x
}

// ============================================================
// BB4: hrpJoin
// Dispose all three HRP calibration signal droplets.
// Control falls into the rubella ELISA branch (BB5/BB6).
// ============================================================

dispose hrpSignal1x
dispose hrpSignal2x
dispose hrpSignal4x

// ============================================================
// ASSAY 2: Rubella IgG Sandwich ELISA (Design B)
// ============================================================
//
// Three IgG concentrations evaluated: 0, 1.56, 3.125 IU/mL.
// Each concentration processed identically through 7 steps:
//   i)   Dispense paramagnetic bead suspension (~1.5e8/mL,
//        ~1.6 uL = 2 unit volumes)
//   ii)  Dispense rubella IgG standard; deliver to beads;
//        mix for 3 min
//   iii) Wash beads 3x in wash buffer; magnetic separation
//        after each wash
//   iv)  Dispense HRP conjugate; deliver to beads; mix 2 min
//   v)   Wash beads 3x in wash buffer; magnetic separation
//   vi)  Resuspend beads in H2O2; merge with luminol-enhancer
//   vii) Incubate 2 min; detect by PMT
//
// For each concentration, bead+IgG incubation, washes, and
// conjugate steps are encoded as explicit sequential mix/heat
// operations. Magnetic separation is abstracted via the
// rubellaMagneticSeparation module invoked at each wash step.
// ============================================================

// ------------------------------------------------------------
// ASSAY 2 - CONCENTRATION 0 IU/mL (blank control)
// ------------------------------------------------------------

// Step i: Dispense paramagnetic particle suspension.
//   Paper M&M: "A ca. 1.6 uL drop (2 unit volumes) containing
//   paramagnetic particles was dispensed from a reservoir and
//   separated from the diluent."
//   Modelled as 2 unit dispenses merged to form 2-unit drop.
beadDrop0a = dispense 1 units of ParamagneticParticles
beadDrop0b = dispense 1 units of ParamagneticParticles
beadPool0  = mix beadDrop0a with beadDrop0b for 5s

// Step ii: Dispense rubella IgG standard (0 IU/mL = blank).
//   Delivered to immobilized bead drop. Incubate 3 min.
//   Paper M&M: "One drop of rubella IgG standard (0, 1.56 or
//   3.125 IU/mL) was dispensed, delivered to the immobilized
//   particles, and mixed for 3 min."
igG0      = dispense 1 units of RubellaIgG_Std_0
igGBead0  = mix beadPool0 with igG0 for 3m

// Step iii: 3x wash with wash buffer + magnetic separation.
//   Paper M&M: "The particles were washed three times in wash
//   buffer and separated from the supernatant."
//   rubellaMagneticSeparation module abstracts magnet
//   engagement + DMF electrode switching to remove supernatant.
wash0_1a   = dispense 1 units of WashBuffer
wash0_1mix = mix igGBead0 with wash0_1a for 30s
sep0_1     = detect rubellaMagneticSeparation on wash0_1mix for 30s

wash0_2a   = dispense 1 units of WashBuffer
wash0_2mix = mix wash0_1mix with wash0_2a for 30s
sep0_2     = detect rubellaMagneticSeparation on wash0_2mix for 30s

wash0_3a   = dispense 1 units of WashBuffer
wash0_3mix = mix wash0_2mix with wash0_3a for 30s
sep0_3     = detect rubellaMagneticSeparation on wash0_3mix for 30s

// Step iv: Dispense HRP conjugate; deliver to beads; mix 2 min.
//   Paper M&M: "One drop of HRP conjugate solution was
//   dispensed, delivered to the immobilized particles, and
//   mixed for 2 min." HRP conjugate: goat anti-human IgG
//   16 ng/mL diluted in conjugate diluent.
conj0    = dispense 1 units of HRP_Conjugate
conjBead0 = mix wash0_3mix with conj0 for 2m

// Step v: 3x post-conjugate wash + magnetic separation.
//   Paper M&M: "The particles were washed three times in wash
//   buffer [after conjugate incubation]."
cwash0_1a   = dispense 1 units of WashBuffer
cwash0_1mix = mix conjBead0 with cwash0_1a for 30s
csep0_1     = detect rubellaMagneticSeparation on cwash0_1mix for 30s

cwash0_2a   = dispense 1 units of WashBuffer
cwash0_2mix = mix cwash0_1mix with cwash0_2a for 30s
csep0_2     = detect rubellaMagneticSeparation on cwash0_2mix for 30s

cwash0_3a   = dispense 1 units of WashBuffer
cwash0_3mix = mix cwash0_2mix with cwash0_3a for 30s
csep0_3     = detect rubellaMagneticSeparation on cwash0_3mix for 30s

// Step vi: Resuspend beads in H2O2; merge with luminol-enhancer.
//   Paper M&M: "The particles were separated from the wash
//   buffer and resuspended in one drop of H2O2, and this drop
//   was merged and mixed with one drop of luminol-enhancer
//   solution."
h2o2_0     = dispense 1 units of H2O2_Solution
luminol0   = dispense 1 units of LuminolEnhancer
resuspend0 = mix cwash0_3mix with h2o2_0 for 30s
elisa0Pool = mix resuspend0 with luminol0 for 30s

// Step vii: Incubate 2 min; detect by PMT.
//   Paper M&M: "The pooled drop was incubated for 2 min and
//   the chemiluminescent signal was recorded using the PMT."
heat elisa0Pool at 25c for 2m
elisaSignal0 = detect rubellaCLDetection on elisa0Pool for 30s

// ------------------------------------------------------------
// ASSAY 2 - CONCENTRATION 1.56 IU/mL
// ------------------------------------------------------------

beadDrop156a = dispense 1 units of ParamagneticParticles
beadDrop156b = dispense 1 units of ParamagneticParticles
beadPool156  = mix beadDrop156a with beadDrop156b for 5s

igG156      = dispense 1 units of RubellaIgG_Std_156
igGBead156  = mix beadPool156 with igG156 for 3m

wash156_1a   = dispense 1 units of WashBuffer
wash156_1mix = mix igGBead156 with wash156_1a for 30s
sep156_1     = detect rubellaMagneticSeparation on wash156_1mix for 30s

wash156_2a   = dispense 1 units of WashBuffer
wash156_2mix = mix wash156_1mix with wash156_2a for 30s
sep156_2     = detect rubellaMagneticSeparation on wash156_2mix for 30s

wash156_3a   = dispense 1 units of WashBuffer
wash156_3mix = mix wash156_2mix with wash156_3a for 30s
sep156_3     = detect rubellaMagneticSeparation on wash156_3mix for 30s

conj156     = dispense 1 units of HRP_Conjugate
conjBead156 = mix wash156_3mix with conj156 for 2m

cwash156_1a   = dispense 1 units of WashBuffer
cwash156_1mix = mix conjBead156 with cwash156_1a for 30s
csep156_1     = detect rubellaMagneticSeparation on cwash156_1mix for 30s

cwash156_2a   = dispense 1 units of WashBuffer
cwash156_2mix = mix cwash156_1mix with cwash156_2a for 30s
csep156_2     = detect rubellaMagneticSeparation on cwash156_2mix for 30s

cwash156_3a   = dispense 1 units of WashBuffer
cwash156_3mix = mix cwash156_2mix with cwash156_3a for 30s
csep156_3     = detect rubellaMagneticSeparation on cwash156_3mix for 30s

h2o2_156     = dispense 1 units of H2O2_Solution
luminol156   = dispense 1 units of LuminolEnhancer
resuspend156 = mix cwash156_3mix with h2o2_156 for 30s
elisa156Pool = mix resuspend156 with luminol156 for 30s

heat elisa156Pool at 25c for 2m
elisaSignal156 = detect rubellaCLDetection on elisa156Pool for 30s

// ------------------------------------------------------------
// ASSAY 2 - CONCENTRATION 3.125 IU/mL
// ------------------------------------------------------------

beadDrop3125a = dispense 1 units of ParamagneticParticles
beadDrop3125b = dispense 1 units of ParamagneticParticles
beadPool3125  = mix beadDrop3125a with beadDrop3125b for 5s

igG3125      = dispense 1 units of RubellaIgG_Std_3125
igGBead3125  = mix beadPool3125 with igG3125 for 3m

wash3125_1a   = dispense 1 units of WashBuffer
wash3125_1mix = mix igGBead3125 with wash3125_1a for 30s
sep3125_1     = detect rubellaMagneticSeparation on wash3125_1mix for 30s

wash3125_2a   = dispense 1 units of WashBuffer
wash3125_2mix = mix wash3125_1mix with wash3125_2a for 30s
sep3125_2     = detect rubellaMagneticSeparation on wash3125_2mix for 30s

wash3125_3a   = dispense 1 units of WashBuffer
wash3125_3mix = mix wash3125_2mix with wash3125_3a for 30s
sep3125_3     = detect rubellaMagneticSeparation on wash3125_3mix for 30s

conj3125     = dispense 1 units of HRP_Conjugate
conjBead3125 = mix wash3125_3mix with conj3125 for 2m

cwash3125_1a   = dispense 1 units of WashBuffer
cwash3125_1mix = mix conjBead3125 with cwash3125_1a for 30s
csep3125_1     = detect rubellaMagneticSeparation on cwash3125_1mix for 30s

cwash3125_2a   = dispense 1 units of WashBuffer
cwash3125_2mix = mix cwash3125_1mix with cwash3125_2a for 30s
csep3125_2     = detect rubellaMagneticSeparation on cwash3125_2mix for 30s

cwash3125_3a   = dispense 1 units of WashBuffer
cwash3125_3mix = mix cwash3125_2mix with cwash3125_3a for 30s
csep3125_3     = detect rubellaMagneticSeparation on cwash3125_3mix for 30s

h2o2_3125     = dispense 1 units of H2O2_Solution
luminol3125   = dispense 1 units of LuminolEnhancer
resuspend3125 = mix cwash3125_3mix with h2o2_3125 for 30s
elisa3125Pool = mix resuspend3125 with luminol3125 for 30s

heat elisa3125Pool at 25c for 2m
elisaSignal3125 = detect rubellaCLDetection on elisa3125Pool for 30s

// ============================================================
// BB5 / BB6: Rubella ELISA QC gate
// Pass (BB5): elisaSignal3125 > 0 -> valid rubella IgG signal
//             at highest concentration; dispose all ELISA
//             reaction droplets. LOD = 0.15 IU/mL (paper).
// Fail (BB6): elisaSignal3125 <= 0 -> no detectable signal
//             (bead failure, HRP conjugate inactive, or
//             reagent error); drain all.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (elisaSignal3125 > 0) {
    dispose elisa0Pool
    dispose elisa156Pool
    dispose elisa3125Pool
} else {
    drain elisa0Pool
    drain elisa156Pool
    drain elisa3125Pool
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose all ELISA QC signal droplets.
// Experiment ends.
// ============================================================

dispose elisaSignal0
dispose elisaSignal156
dispose elisaSignal3125

// [terminal -- no further instructions; exit node for CFG]

module echoLevelDetection
module dropletHitDetection
module xrdSignalDetection
module xesSignalDetection
module residueDetection

manifest SampleSolution
manifest CouplingWater
manifest HFE7500_Oil
manifest MQWater
manifest Isopropanol
manifest FAS_NOctane
manifest HeliumGas
manifest ProteinCrystalSlurry

// ============================================================
// Droplet On Tape (DOT): Protocol
// Fuller et al., Nature Methods, 2017; 10.1038/nmeth.4195
// Protocol DOI: 10.1038/protex.2017.017
// Yano / Yachandra Lab, Lawrence Berkeley National Laboratory
//
// A sample delivery platform coupling Acoustic Droplet Ejection
// (ADE) onto a Kapton conveyor belt for time-resolved X-ray
// studies at XFELs (X-ray Free Electron Lasers).
// Supports simultaneous X-ray Diffraction (XRD) and X-ray
// Emission Spectroscopy (XES) from protein microcrystal slurry
// or protein solution, with optional laser or gas reaction
// initiation.
//
// FIVE MAIN SUBSYSTEMS ENCODED:
//   1. ADE Injector         -- acoustic droplet ejection
//   2. Control Systems      -- EPICS-managed hardware (abstracted)
//   3. Conveyor Belt System -- Kapton belt prep, tensioning,
//                             cleaning, drive
//   4. Sample Environment   -- Helium enclosure
//   5. Reaction Initiation  -- laser excitation / gas activation
//
// PLATFORM ABSTRACTION NOTES:
//   - `mix` steps involving the ADE injector abstract an acoustic
//     tone-burst event (15 MHz, <100 us, ~40 V) that ejects a
//     nano-liter droplet onto the moving Kapton belt. There is no
//     electrode-based DMF mixing in this system.
//   - `heat` steps model temperature-controlled incubation,
//     vacuum oven drying, and FAS reflux chemistry for belt
//     surface treatment. Not TEC-based.
//   - `detect` steps abstract optical/acoustic sensor readouts:
//     echo sonar level sensing, stroboscopic droplet-hit
//     confirmation, XRD/XES detector signals, and belt residue
//     XES background checks.
//   - All `dispense` units represent functional preparation
//     volumes (belt coatings, gas flows, sample reservoirs).
//   - Duration tokens: BioScript supports s and m only.
//     60 min = 3600s was preferred over 60m where precision
//     matters. Hours converted: 1h = 60m, 2h = 120m, 3h = 180m.
//
// CFG STRUCTURE:
//   BB1  main               -- belt prep, ADE ejection, echo QC,
//                             droplet timing setup
//   BB2  echoPass           -- echoSignal > 0: fluid level OK;
//                             continue to droplet-hit confirmation
//   BB3  echoFail           -- echoSignal <= 0: fluid level off;
//                             drain and re-adjust sample influx
//   BB4  echoJoin           -- join: laser excitation branch begins
//   BB5  laserHitPass       -- laserHitSignal > 0: spatial/temporal
//                             overlap confirmed; proceed to XRD/XES
//   BB6  laserHitFail       -- laserHitSignal <= 0: droplet missed;
//                             drain and re-adjust deposition delay
//   BB7  laserHitJoin       -- join: data collection branch begins
//   BB8  xrdPass            -- xrdSignal > 0: valid diffraction data;
//                             dispose and run XES check
//   BB9  xrdFail            -- xrdSignal <= 0: no hit/beam miss; drain
//   BB10 xrdJoin            -- join: XES branch begins
//   BB11 xesPass            -- xesSignal > 0: valid emission signal;
//                             dispose and proceed to residue check
//   BB12 xesFail            -- xesSignal <= 0: no emission; drain
//   BB13 xesJoin            -- join: belt residue QC branch begins
//   BB14 residuePass        -- residueSignal > 0: residue detected;
//                             re-clean belt
//   BB15 residueFail        -- residueSignal <= 0: belt clean; dispose
//   BB16 finalCleanup       -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// SUBSYSTEM 3 - BELT PREPARATION (Section 3b):
// STEP 1: Clean seamless Kapton (polyimide) belt by sonication
//         in Milli-Q water for 10 min followed by isopropanol
//         for 10 min. Belt dimensions: 0.063-0.125" width,
//         31-36" diameter, 50 micron thickness (BPB Inc.).
// ------------------------------------------------------------

mqWaterBath     = dispense 1 units of MQWater
isopropBath     = dispense 1 units of Isopropanol

// Sonication in MQ water: 10 min (600 s)
sonicatedBelt   = mix mqWaterBath with isopropBath for 10m

// ------------------------------------------------------------
// STEP 2: Dry belt in vacuum oven at 50 C for 1 hour before
//         hydrophobicity treatment. Precision vacuum oven,
//         model 19.
//         50 C / 60 min = 3600 s.
// ------------------------------------------------------------

heat sonicatedBelt at 50c for 60m

// ------------------------------------------------------------
// STEP 3: Hydrophobicity treatment with fluoroalkylsilane (FAS):
//         1H,1H,2H,2H-Perfluorodecyltriethoxysilane
//         (C10F17H4Si(OCH2CH3)3, 97%, Sigma-Aldrich).
//         Reflux belt in 0.25% (w/v) FAS in n-octane for 2 h.
//         This raises water contact angle (WCA) from ~60 deg
//         to 100 +/- 5 deg so that aqueous droplets bead up
//         on the belt surface and do not spread.
//         2 h = 120 min.
// ------------------------------------------------------------

fasSolution     = dispense 1 units of FAS_NOctane
treatedBelt     = mix sonicatedBelt with fasSolution for 120m

// ------------------------------------------------------------
// STEP 4: Remove residual FAS. Dry belt in vacuum oven at
//         150 C for 3 h to remove unreacted silane.
//         3 h = 180 min.
// ------------------------------------------------------------

heat treatedBelt at 150c for 180m

// ------------------------------------------------------------
// SUBSYSTEM 1 - ADE INJECTOR SETUP (Section 1):
// STEP 5: Fill sample reservoir with protein crystal slurry
//         or solution. The ADE transducer (Olympus V319-SU,
//         1" spherical focus, 15 MHz resonance) is positioned
//         below the reservoir, coupled through a water column.
//         A "probe" tone-burst (<100 ns) is sent a few ms
//         before the ejection burst to check fluid level via
//         acoustic echo (sonar principle).
//         Expected echo return time: ~35 us for 1" focal
//         length transducer at correct focus. Fluid level
//         can be monitored with <50 um accuracy.
//
//         `mix` here abstracts loading sample into the ADE
//         reservoir and coupling to the transducer water
//         column. Not a DMF electrode step.
// ------------------------------------------------------------

sampleReservoir = dispense 1 units of SampleSolution
couplingWater   = dispense 1 units of CouplingWater
adeLoaded       = mix sampleReservoir with couplingWater for 2s

// ------------------------------------------------------------
// STEP 6: Send acoustic probe pulse and detect echo return.
//         echoLevelDetection module abstracts:
//           - waveform generator (Agilent 33612A) producing
//             tone-burst at 15 MHz
//           - Amplifier Research 500A250C RF amp -> ~40 V
//           - bi-directional coupler (30 dB) sampling echo
//           - oscilloscope monitoring echo return time and
//             amplitude (remotely accessed via desktop)
//         A valid echo at ~35 us delay confirms the transducer
//         is focused on the sample-air interface.
//         Detection window: 10 s to allow stabilisation.
// ------------------------------------------------------------

echoSignal      = detect echoLevelDetection on adeLoaded for 10s

// ============================================================
// BB2 / BB3: Echo QC gate
// Pass (BB2): echoSignal > 0 -> fluid level and focus OK;
//             proceed with droplet ejection sequence.
// Fail (BB3): echoSignal <= 0 -> echo out of range (wrong
//             fluid level or transducer misaligned); drain
//             sample and re-adjust influx rate.
// Both branches converge at BB4 (echoJoin).
// ============================================================

if (echoSignal > 0) {
    // Eject nano-liter droplet onto the moving Kapton belt.
    // Ejection tone-burst typically <100 us at 15 MHz, ~40 V.
    // The Lexium M-Drive stepper motor moves the belt at
    // 30-300 mm/s so the ejected droplet lands on a clean
    // section. At 10 Hz rep rate, allowed belt speeds are
    // 30, 60, 150, or 300 mm/s (spacing = integer multiple
    // of 30 mm between IR gate positions).
    ejectedDroplet = mix adeLoaded with couplingWater for 1s
    dispose ejectedDroplet
} else {
    drain adeLoaded
}

// ============================================================
// BB4: echoJoin
// Dispose echo QC signal. Control falls into laser excitation
// timing / droplet-hit confirmation branch (BB5/BB6).
// ============================================================

dispose echoSignal

// ------------------------------------------------------------
// SUBSYSTEM 5 - REACTION INITIATION: LASER EXCITATION (Section 6-8):
// STEP 7: Dispense a fresh sample droplet for the main
//         experiment run. The belt carries droplets through
//         a high-precision CNC-machined grid of fiber-coupled
//         laser excitation points (tolerance: 0.0005").
//         Three laser excitations and 2 IR gate fibers are
//         mounted in the grid. For single-excitation
//         experiments (Section 7: Free Space Timing), a
//         movable 1 m focal length lens positions the laser
//         up to 6 mm upstream of the XFEL interaction point,
//         giving time delays of 20-100 ms at typical belt
//         speeds (300-60 mm/s).
//
//         The Helium enclosure (Section 4) surrounds the
//         belt/sample interaction region to reduce air scatter.
//         `mix` here abstracts belt transport of the droplet
//         through the laser excitation zone.
// ------------------------------------------------------------

experimentDrop  = dispense 1 units of ProteinCrystalSlurry
heliumFlow      = dispense 1 units of HeliumGas

// Droplet travels through Helium enclosure to laser zone.
// `mix` abstracts pneumatic flow of helium + sample transport
// through the enclosure to the laser interaction position.
laserZoneDrop   = mix experimentDrop with heliumFlow for 5s

// ------------------------------------------------------------
// STEP 8: Confirm droplet-hit by stroboscopic video system.
//         Side-view camera is synchronized to XFEL arrival.
//         At zero camera delay: observe droplet explosion
//         confirming XFEL hit. Adjust camera to negative delay
//         to match desired laser delay and note droplet position.
//         Move laser spot to that position.
//         Spatial overlap accuracy: 100 um (laser spot: 400 um).
//         Temporal overlap accuracy: 200 us (camera exposure).
//         Fine timing (nanosecond level) is confirmed by
//         relative photodiode measurements.
//
//         For fiber excitation (Section 8): adjust deposition
//         delay until droplet appears at XFEL crosshairs on
//         stroboscopic monitor, then adjust belt velocity until
//         IR gate signals coincide in time.
//
//         dropletHitDetection module abstracts the combined
//         stroboscopic camera + forward scatter detector +
//         IR gate photodiode confirmation.
// ------------------------------------------------------------

laserHitSignal  = detect dropletHitDetection on laserZoneDrop for 30s

// ============================================================
// BB5 / BB6: Laser-hit / timing QC gate
// Pass (BB5): laserHitSignal > 0 -> spatial and temporal
//             overlap confirmed; proceed to XFEL data
//             collection.
// Fail (BB6): laserHitSignal <= 0 -> droplet missed laser
//             (wrong deposition delay or belt speed); drain
//             and re-adjust parameters.
// Both branches converge at BB7 (laserHitJoin).
// ============================================================

if (laserHitSignal > 0) {
    dispose laserZoneDrop
} else {
    drain laserZoneDrop
}

// ============================================================
// BB7: laserHitJoin
// Dispose laser-hit QC signal. Control falls into XFEL data
// collection branch (BB8/BB9).
// ============================================================

dispose laserHitSignal

// ------------------------------------------------------------
// SUBSYSTEM 1 + 4 - XFEL DATA COLLECTION (Section 6, Fig 6):
// STEP 9: Dispense production sample onto belt for XFEL
//         measurement. The droplet travels through the Helium
//         enclosure at the calibrated belt speed and
//         deposition delay. The XFEL pulse (ultrashort,
//         intense) probes the droplet at the interaction
//         region for X-ray diffraction (XRD) from protein
//         microcrystal slurry.
//         Belts run at <4 revolutions/s via Lexium M-Drive
//         LMDCE423 direct-drive stepper (1" stainless shaft).
//
//         `mix` abstracts transport of the production sample
//         droplet through the full DOT system from ADE
//         deposition to XFEL interaction.
// ------------------------------------------------------------

productionSample = dispense 1 units of ProteinCrystalSlurry
heliumFlow2      = dispense 1 units of HeliumGas

xfelDrop         = mix productionSample with heliumFlow2 for 5s

// XRD signal: forward scattering detector.
// xrdSignalDetection abstracts the area detector readout
// for crystallographic diffraction patterns collected during
// a beamtime of 4-5 days per experiment.
xrdSignal        = detect xrdSignalDetection on xfelDrop for 30s

// ============================================================
// BB8 / BB9: XRD data quality gate
// Pass (BB8): xrdSignal > 0 -> valid diffraction pattern;
//             dispose droplet waste and proceed to XES check.
// Fail (BB9): xrdSignal <= 0 -> no diffraction (beam miss,
//             empty droplet, or crystal failure); drain.
// Both branches converge at BB10 (xrdJoin).
// ============================================================

if (xrdSignal > 0) {
    dispose xfelDrop
} else {
    drain xfelDrop
}

// ============================================================
// BB10: xrdJoin
// Dispose XRD QC signal. Control falls into XES branch
// (BB11/BB12).
// ============================================================

dispose xrdSignal

// ------------------------------------------------------------
// STEP 10: X-ray Emission Spectroscopy (XES) detection.
//          Simultaneous with XRD, the XES crystal spectrometer
//          (housed in second Helium bag between spectrometer
//          and main Helium chamber) collects X-ray emission
//          from the sample.
//          A fresh production droplet is used to represent
//          the concurrent XES channel.
//          xesSignalDetection abstracts the XES crystal
//          spectrometer readout (emission signal).
//          Accumulated residue is separately QC-checked by
//          running the belt dry (no sample) and probing the
//          XES background (residueDetection, STEP 12 below).
// ------------------------------------------------------------

xesSample       = dispense 1 units of ProteinCrystalSlurry
heliumFlow3     = dispense 1 units of HeliumGas
xesDrop         = mix xesSample with heliumFlow3 for 5s

xesSignal       = detect xesSignalDetection on xesDrop for 30s

// ============================================================
// BB11 / BB12: XES data quality gate
// Pass (BB11): xesSignal > 0 -> valid emission spectrum;
//              dispose and proceed to belt residue check.
// Fail (BB12): xesSignal <= 0 -> no emission (beam miss or
//              instrument issue); drain.
// Both branches converge at BB13 (xesJoin).
// ============================================================

if (xesSignal > 0) {
    dispose xesDrop
} else {
    drain xesDrop
}

// ============================================================
// BB13: xesJoin
// Dispose XES QC signal. Control falls into belt residue
// check branch (BB14/BB15).
// ============================================================

dispose xesSignal

// ------------------------------------------------------------
// SUBSYSTEM 3 - BELT CLEANING AND RESIDUE QC (Section 5):
// STEP 11: Belt cleaning run. Drive belt through four high-
//          pressure (200+ psi) water jets (500 um I.D.) to
//          remove accumulated sample residue.
//          Immediately dry belt top and bottom using two
//          compressed Helium blow-off nozzles powered by
//          three KNF Neuberger N145.1.2AN.18 diaphragm pumps
//          recirculating Helium from the chamber.
//          `mix` abstracts the cleaning pass of the belt
//          through the water jets + helium blow-off sequence.
// ------------------------------------------------------------

cleaningWater   = dispense 1 units of MQWater
beltCleanRun    = mix treatedBelt with cleaningWater for 5m

heliumDry       = dispense 1 units of HeliumGas
driedBelt       = mix beltCleanRun with heliumDry for 2m

// ------------------------------------------------------------
// STEP 12: Residue QC check. Run belt dry (no sample injected)
//          while probing XES background signal. Any accumulated
//          sample residue is detected sensitively by its XES
//          emission above baseline. This test was performed
//          periodically during beamtimes.
//          residueDetection abstracts the XES background
//          monitoring readout on the dry belt.
// ------------------------------------------------------------

residueSignal   = detect residueDetection on driedBelt for 30s

// ============================================================
// BB14 / BB15: Belt residue QC gate
// Pass (BB14): residueSignal > 0 -> residue detected above
//              XES background; re-clean belt (dispose and
//              trigger another cleaning cycle conceptually).
// Fail (BB15): residueSignal <= 0 -> belt clean (background
//              at baseline); dispose cleaned belt and proceed
//              to finalCleanup.
// Both branches converge at BB16 (finalCleanup).
// ============================================================

if (residueSignal > 0) {
    // Belt still dirty: dispose for re-cleaning cycle.
    // In practice, repeat STEP 11 until residueSignal <= 0.
    dispose driedBelt
} else {
    // Belt clean: ready for next beamtime shift.
    dispose driedBelt
}

// ============================================================
// BB16: finalCleanup (terminal)
// Dispose the residue QC signal. Experiment ends.
// Belt is ready for next experimental shift.
// ============================================================

dispose residueSignal

// [terminal -- no further instructions; exit node for CFG]

module dropletDepositionDetection
module nimsImagingDetection

manifest CelE_CBM3a_Enzyme
manifest G4_Substrate_Probe
manifest PhosphateBuffer_pH6
manifest AcetateBuffer_pH5
manifest HFE7500_Surfactant
manifest DextromethorphanStandard
manifest UniversalMALDI_Matrix

// ============================================================
// On-chip Integration of Droplet Microfluidics and
// Nanostructure-Initiator Mass Spectrometry for Enzyme
// Screening. Heinemann et al., Lab on a Chip, 2016.
// DOI: 10.1039/c6lc01182a
//
// Platform: uNIMS -- integrates a digital microfluidics (DMF)
// chip (electrowetting-on-dielectric, EWOD) with a patterned
// NIMS array (640 pads, 5x5 cm silicon wafer) for time-resolved
// enzyme kinetics via mass spectrometry imaging.
//
// PROTOCOL OVERVIEW:
//   PART 1: Dextromethorphan (DXM) standard deposition to
//           validate microfluidic droplet actuation onto NIMS
//           pads. 150 nL droplets actuated over NIMS pads;
//           MS imaging confirms analyte sorption at m/z 272.
//
//   PART 2A: CelE kinetics at pH 6 (phosphate buffer, 50 mM).
//            G4 substrate-probe reacted with CelE-CBM3a.
//            Droplets incubated at 10, 20, 30, 40, 50 min
//            (parallel loading, 6 pads per time point).
//            Degradation products G3, G2, G1 monitored by
//            MS imaging. Fractional conversion readout.
//
//   PART 2B: CelE kinetics at pH 5 (acetate buffer, 100 mM).
//            Same enzyme/substrate; continuous series loading.
//            Time points: 10, 20, 40 min.
//            Result: similar product distribution to pH 6;
//            CelE is robust across both pH conditions.
//
// DEVICE DETAILS:
//   - Microfluidics chip: glass substrate, 128 chrome electrodes
//     (5 cm L x 500 um W x 375 um H), 5 um SU-8-5 dielectric,
//     PDMS fluidics channel (500 um W x 225 um H), 31 digital
//     arrayers aligned to NIMS pads.
//   - T-junction for droplet generation: pressure-driven flow,
//     ~150 nL droplets in HFE-7500 immiscible oil phase.
//   - Dropbot control: 20 V hold, 90 V / 10 kHz fast actuation
//     (250 ms bursts) for droplet movement in/out of pockets.
//   - NIMS array: ICP-RIE etched silicon nanostructures
//     (DRIE, SF6/O2 30/20 ratio, -80 C, 6 mTorr), patterned
//     with photopatternable PDMS (3% benzophenone, 10:1 ratio).
//   - Reversible PDMS seal between DMF chip and NIMS array
//     allows removal for MS imaging on ABSciex 5800 MALDI-TOF
//     (positive mode, laser intensity 4150, focus m/z 1200,
//     50 um laser step, universal MALDI matrix 20 mg/mL MeOH).
//   - Analysis: OpenMSI spot set analysis.
//
// DROPLET VOLUMES:
//   All droplets ~150 nL (unit). 6 uL plugs broken into
//   droplets at t-junction (0.05 uL/s reaction cocktail,
//   0.2 uL/s HFE-7500 oil phase). BioScript `dispense 1 units`
//   abstracts the 150 nL droplet throughout.
//
// TEMPERATURE: All reactions at room temperature (25 C).
//   `heat` statements model incubation timing on NIMS pads.
//
// FRACTIONAL CONVERSION QUANTIFICATION:
//   Signal normalised as [G1]/([G4]+[G3]+[G2]+[G1]) etc.
//   This internal normalisation eliminates sensitivity to
//   droplet volume variation (device maintains +/-10% SD in
//   droplet size; turbulent mixing at t-junction causes
//   initial larger droplets).
//
// NOTE ON SURFACTANT INTERFERENCE:
//   HFE-7500 + surfactant stabilises droplets but suppresses
//   NIMS ionisation; MS imaging (not spot analysis) was used
//   to detect all degradation products. NIMS surface acts as
//   capture substrate; probe (fluorous-tagged) and products
//   remain adsorbed after droplet removal. Surfactant
//   adherence to NIMS surface negatively impacts sensitivity.
//   Future directions: NIMS-compatible surfactants.
//
// CFG STRUCTURE:
//   BB1  main              -- DXM validation + pH6 kinetics +
//                             pH5 kinetics (all dispense/mix/heat)
//   BB2  validationPass    -- depositionSignal > 0: DXM confirmed
//                             on NIMS pads; dispose and continue
//   BB3  validationFail    -- depositionSignal <= 0: no analyte
//                             sorption; drain DXM droplets
//   BB4  validationJoin    -- join: pH6 kinetics branch begins
//   BB5  pH6Pass           -- pH6Signal > 0: valid kinetics
//                             detected; dispose all pH6 droplets
//   BB6  pH6Fail           -- pH6Signal <= 0: no product signal;
//                             drain all pH6 droplets
//   BB7  pH6Join           -- join: pH5 kinetics branch begins
//   BB8  pH5Pass           -- pH5Signal > 0: valid kinetics;
//                             dispose all pH5 droplets
//   BB9  pH5Fail           -- pH5Signal <= 0: no product signal;
//                             drain all pH5 droplets
//   BB10 finalCleanup      -- terminal: dispose all QC signals;
//                             NIMS array removed for MS imaging
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// PART 1 - STEP 1: Prepare HFE-7500 oil phase.
//   Novec HFE-7500 (3M, US) with 100 uL Picoglide surfactant
//   pumped through channel for 30 min to coat PDMS surface.
//   Oil phase separates aqueous droplets at t-junction and
//   maintains droplet integrity during EWOD actuation.
// ------------------------------------------------------------

oilPhase = dispense 1 units of HFE7500_Surfactant

// ------------------------------------------------------------
// PART 1 - STEP 2: Dispense dextromethorphan standard.
//   1 mg/mL DXM in H2O. Used for rudimentary testing of
//   microfluidic functions and NIMS array evaluation.
//   150 nL droplet dispensed from syringe (prefilled 5 uL plug).
//   DXM detects at m/z 272 (H+) -- matrix-free ionisation
//   confirmed; no ionisation on surrounding structures.
// ------------------------------------------------------------

dxmDroplet = dispense 1 units of DextromethorphanStandard

// ------------------------------------------------------------
// PART 1 - STEP 3: Generate DXM droplets at t-junction.
//   Aqueous DXM plug broken into ~150 nL droplets by
//   immiscible HFE-7500 oil phase at t-junction.
//   Droplet synchronisation matches droplet formation with
//   electrode actuation for uniform spacing.
//   `mix` abstracts the t-junction droplet generation event.
// ------------------------------------------------------------

dxmDropletInOil = mix dxmDroplet with oilPhase for 5s

// ------------------------------------------------------------
// PART 1 - STEP 4: Load DXM droplets onto NIMS pads.
//   Flow stopped; 20 V hold on electrodes. Droplets actuated
//   onto uNIMS pads (90 V, 10 kHz, 250 ms bursts) and
//   incubated to allow DXM to sorb onto NIMS surface.
//   `heat` at 25 C models room-temperature sorption contact.
//   After sorption, droplets ejected from pocket.
// ------------------------------------------------------------

heat dxmDropletInOil at 25c for 10m

// ------------------------------------------------------------
// PART 1 - STEP 5: Coat NIMS array with universal MALDI matrix.
//   20 mg/mL MeOH universal MALDI matrix applied to NIMS
//   array after removal from uNIMS system. Required for
//   ABSciex 5800 MALDI-TOF MS imaging.
//   `mix` abstracts matrix co-crystallisation step.
// ------------------------------------------------------------

maldiMatrix = dispense 1 units of UniversalMALDI_Matrix
dxmNimsArray = mix dxmDropletInOil with maldiMatrix for 1m

// ------------------------------------------------------------
// PART 1 - STEP 6: MS imaging QC -- DXM deposition detection.
//   nimsImagingDetection module abstracts ABSciex 5800
//   MALDI-TOF MS imaging (50 um laser step, m/z 272 ion map).
//   OpenMSI spot set analysis confirms DXM deposition pattern.
//   QC gate: signal > 0 confirms successful analyte sorption
//   onto uNIMS pads (not surrounding structures).
// ------------------------------------------------------------

depositionSignal = detect nimsImagingDetection on dxmNimsArray for 30s

// ============================================================
// BB2 / BB3: DXM validation QC gate
// Pass (BB2): depositionSignal > 0 -> DXM detected on NIMS
//             pads; dispose and proceed to kinetics branch.
// Fail (BB3): depositionSignal <= 0 -> no sorption (surfactant
//             suppression or actuation failure); drain.
// Both branches converge at BB4 (validationJoin).
// ============================================================

if (depositionSignal > 0) {
    dispose dxmNimsArray
} else {
    drain dxmNimsArray
}

// ============================================================
// BB4: validationJoin
// Dispose DXM deposition QC signal. Control falls into
// pH 6 kinetics branch (BB5/BB6).
// ============================================================

dispose depositionSignal

// ============================================================
// PART 2A: CelE Kinetics at pH 6 (phosphate buffer, 50 mM)
// ============================================================

// ------------------------------------------------------------
// PART 2A - STEP 1: Prepare enzyme/substrate reaction mix.
//   Reaction premixed off-chip in 0.5 mL eppendorf tube:
//     4 uL phosphate buffer (50 mM, pH 6) +
//     1 uL G4 substrate-probe (1,4-beta-D-cellotetraose-probe,
//       MW 1515.48, formula C55H78F17N5O24, detected at m/z
//       1516.43 H+) +
//     1 uL CelE-CBM3a (240 ug/mL endoglucanase, GH5 domain
//       from C. thermocellum Cthe_0797 fused to CBM3a).
//   Final volume: 6 uL plug drawn into syringe tubing.
//   BioScript: each component dispensed as 1 unit; merged to
//   form reaction cocktail. Buffer is the major volume component.
// ------------------------------------------------------------

// Three buffer units to approximate 4:1:1 volume ratio
// (4 uL buffer : 1 uL substrate : 1 uL enzyme).
// Compiler requires explicit sequential merging of multi-unit
// buffer volumes; chained mix accumulates 3+1=4 buffer units.

ph6_buf1 = dispense 1 units of PhosphateBuffer_pH6
ph6_buf2 = dispense 1 units of PhosphateBuffer_pH6
ph6_buf3 = dispense 1 units of PhosphateBuffer_pH6
ph6_buf4 = dispense 1 units of PhosphateBuffer_pH6

ph6_buf_12   = mix ph6_buf1 with ph6_buf2 for 5s
ph6_buf_34   = mix ph6_buf3 with ph6_buf4 for 5s
ph6_bufBulk  = mix ph6_buf_12 with ph6_buf_34 for 5s

ph6_substrate = dispense 1 units of G4_Substrate_Probe
ph6_enzyme    = dispense 1 units of CelE_CBM3a_Enzyme

ph6_subBuf   = mix ph6_substrate with ph6_bufBulk for 10s
ph6_reactionCocktail = mix ph6_subBuf with ph6_enzyme for 10s

// ------------------------------------------------------------
// PART 2A - STEP 2: Generate reaction droplets at t-junction.
//   6 uL plug injected at 0.05 uL/s reaction cocktail,
//   0.2 uL/s HFE-7500 oil to generate ~150 nL droplets.
//   Central fluidics chamber filled with droplet train.
//   Flow stopped (syringe pump halted); 20 V electrode hold.
// ------------------------------------------------------------

oilPhase_pH6 = dispense 1 units of HFE7500_Surfactant
ph6_dropletsInOil = mix ph6_reactionCocktail with oilPhase_pH6 for 5s

// ------------------------------------------------------------
// PART 2A - STEP 3: Parallel loading onto uNIMS pads.
//   All 31 arrayer electrodes actuated simultaneously.
//   Droplets loaded in parallel onto NIMS pads (Fig. 4A).
//   Incubation times: 10, 20, 30, 40, 50 min over six
//   successive pad positions (6 pads per time point).
//   At each interval, 6 droplets synchronously ejected from
//   pocket into central chamber and evacuated.
//   G4 substrate (m/z 1516) degraded to:
//     G3 cellotriose-probe   (m/z 1354, C49H68F17N5O19)
//     G2 cellobiose-probe    (m/z 1192, C43H58F17N5O14)
//     G1 glucose-probe       (m/z 1030, C37H48F17N5O9)
//   `heat` blocks model the sequential incubation time points.
//   Room temperature (25 C) throughout.
// ------------------------------------------------------------

// Time point 1: 10 min incubation
heat ph6_dropletsInOil at 25c for 10m

// Time point 2: 20 min incubation (cumulative)
heat ph6_dropletsInOil at 25c for 10m

// Time point 3: 30 min incubation (cumulative)
heat ph6_dropletsInOil at 25c for 10m

// Time point 4: 40 min incubation (cumulative)
heat ph6_dropletsInOil at 25c for 10m

// Time point 5: 50 min incubation (cumulative; final time point)
heat ph6_dropletsInOil at 25c for 10m

// ------------------------------------------------------------
// PART 2A - STEP 4: Coat NIMS array with MALDI matrix.
//   After all time points completed, uNIMS chip removed from
//   system. NIMS array coated with universal MALDI matrix
//   (20 mg/mL MeOH). Mounted in ABSciex 5800 MALDI-TOF.
// ------------------------------------------------------------

maldiMatrix_pH6  = dispense 1 units of UniversalMALDI_Matrix
ph6_nimsArray    = mix ph6_dropletsInOil with maldiMatrix_pH6 for 1m

// ------------------------------------------------------------
// PART 2A - STEP 5: MS imaging and kinetics detection.
//   ABSciex 5800 MALDI-TOF; positive ionisation; 50 um step.
//   OpenMSI spot set analysis; fractional conversion:
//   [G1]/([G4]+[G3]+[G2]+[G1]) for each time point pad.
//   nimsImagingDetection abstracts the full MS imaging scan
//   and OpenMSI analysis of G4, G3, G2, G1 product map.
// ------------------------------------------------------------

ph6Signal = detect nimsImagingDetection on ph6_nimsArray for 30s

// ============================================================
// BB5 / BB6: pH 6 kinetics QC gate
// Pass (BB5): ph6Signal > 0 -> G3/G2/G1 hydrolysis products
//             detected by MS imaging; dispose all pH6 droplets.
// Fail (BB6): ph6Signal <= 0 -> no product signal (surfactant
//             suppression or enzyme inactivity); drain.
// Both branches converge at BB7 (pH6Join).
// ============================================================

if (ph6Signal > 0) {
    dispose ph6_nimsArray
} else {
    drain ph6_nimsArray
}

// ============================================================
// BB7: pH6Join
// Dispose pH 6 kinetics QC signal. Control falls into
// pH 5 kinetics branch (BB8/BB9).
// ============================================================

dispose ph6Signal

// ============================================================
// PART 2B: CelE Kinetics at pH 5 (acetate buffer, 100 mM)
// ============================================================

// ------------------------------------------------------------
// PART 2B - STEP 1: Prepare enzyme/substrate reaction mix.
//   Same as PART 2A but with 100 mM acetate buffer (pH 5).
//   Reaction premixed off-chip: 4 uL acetate buffer +
//   1 uL G4 substrate-probe + 1 uL CelE-CBM3a (240 ug/mL).
//   Result: CelE produces similar product distributions at
//   pH 5 and pH 6, demonstrating robustness to process
//   conditions (reaction profile consistent with Deng, 2015).
//   pH 5 run loaded continuously in series (Fig. 4B).
// ------------------------------------------------------------

ph5_buf1 = dispense 1 units of AcetateBuffer_pH5
ph5_buf2 = dispense 1 units of AcetateBuffer_pH5
ph5_buf3 = dispense 1 units of AcetateBuffer_pH5
ph5_buf4 = dispense 1 units of AcetateBuffer_pH5

ph5_buf_12  = mix ph5_buf1 with ph5_buf2 for 5s
ph5_buf_34  = mix ph5_buf3 with ph5_buf4 for 5s
ph5_bufBulk = mix ph5_buf_12 with ph5_buf_34 for 5s

ph5_substrate = dispense 1 units of G4_Substrate_Probe
ph5_enzyme    = dispense 1 units of CelE_CBM3a_Enzyme

ph5_subBuf          = mix ph5_substrate with ph5_bufBulk for 10s
ph5_reactionCocktail = mix ph5_subBuf with ph5_enzyme for 10s

// ------------------------------------------------------------
// PART 2B - STEP 2: Generate reaction droplets at t-junction.
//   Continuous series loading used for pH 5 run (Fig. 4B).
//   6 uL plug injected; droplets removed from pad directly
//   from flow (Supplementary Video). HFE-7500 oil phase
//   separates droplets during continuous series actuation.
// ------------------------------------------------------------

oilPhase_pH5      = dispense 1 units of HFE7500_Surfactant
ph5_dropletsInOil = mix ph5_reactionCocktail with oilPhase_pH5 for 5s

// ------------------------------------------------------------
// PART 2B - STEP 3: Series loading; incubation time points.
//   Droplets loaded continuously in series onto NIMS pads.
//   Time points: 10, 20, 40 min (three time points for pH 5).
//   At each time point, droplets ejected and fresh droplets
//   actuated into pocket for next incubation interval.
//   G4 degradation to G3, G2, G1 monitored as for pH 6.
// ------------------------------------------------------------

// Time point 1: 10 min incubation
heat ph5_dropletsInOil at 25c for 10m

// Time point 2: 20 min incubation (cumulative)
heat ph5_dropletsInOil at 25c for 10m

// Time point 3: 40 min incubation (cumulative)
heat ph5_dropletsInOil at 25c for 20m

// ------------------------------------------------------------
// PART 2B - STEP 4: Coat NIMS array with MALDI matrix.
//   uNIMS chip removed; NIMS array coated with universal
//   MALDI matrix. Re-mounted in ABSciex 5800 MALDI-TOF.
// ------------------------------------------------------------

maldiMatrix_pH5 = dispense 1 units of UniversalMALDI_Matrix
ph5_nimsArray   = mix ph5_dropletsInOil with maldiMatrix_pH5 for 1m

// ------------------------------------------------------------
// PART 2B - STEP 5: MS imaging and kinetics detection.
//   Same MS imaging and OpenMSI analysis as PART 2A.
//   Fractional conversion at each time point compared to pH 6.
//   nimsImagingDetection abstracts full MALDI-TOF scan.
// ------------------------------------------------------------

ph5Signal = detect nimsImagingDetection on ph5_nimsArray for 30s

// ============================================================
// BB8 / BB9: pH 5 kinetics QC gate
// Pass (BB8): ph5Signal > 0 -> G3/G2/G1 hydrolysis products
//             detected by MS imaging; dispose all pH5 droplets.
// Fail (BB9): ph5Signal <= 0 -> no product signal; drain.
// Both branches converge at BB10 (finalCleanup).
// ============================================================

if (ph5Signal > 0) {
    dispose ph5_nimsArray
} else {
    drain ph5_nimsArray
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose pH 5 kinetics QC signal. Experiment complete.
// NIMS array removed from uNIMS system and placed in
// ABSciex 5800 MALDI-TOF for final MS imaging.
// Each NIMS array supports up to 20 enzyme/condition assays
// (31 pads per run; 640 pads total; scalable to 620 assays
// at 1 pad/enzyme with modified protocol).
// ============================================================

dispose ph5Signal

// [terminal -- no further instructions; exit node for CFG]

module bacterialRecoveryQC
module rRNASpeciesDetection
module mRNASusceptibilityDetection

manifest WholeBlood
manifest PBS_BSA_Buffer
manifest SheathFluid
manifest EcoliClinicalIsolate
manifest EcoliClinicalIsolate_Susceptible
manifest EcoliClinicalIsolate_Resistant
manifest RLT_Lysis_Buffer
manifest Ciprofloxacin_Stock

// ============================================================
// Direct Detection and Drug-Resistance Profiling of
// Bacteremias Using Inertial Microfluidics
// Hou, Bhattacharyya, Hung, Han - Lab Chip 2015, 15, 2297
// DOI: 10.1039/c5lc00311c
//
// PROTOCOL OVERVIEW:
//   Two sequential diagnostic workflows are encoded:
//
//   WORKFLOW 1 (Species Identification via rRNA):
//     Bacteria (~100 cfu/mL) are isolated from 3x-diluted
//     whole blood using a PDMS spiral microchannel device
//     (500 um x 80 um, ~10 cm length) operating on Dean
//     Flow Fractionation (DFF). Blood is pumped at 1700 uL/min
//     via syringe pump; sheath fluid (PBS+BSA) at ~10x ratio
//     pins sample at the outer wall. Larger blood cells
//     (RBCs ~6-8 um; leukocytes ~7-12 um) focus inertially
//     at the inner wall and exit the waste outlet. Bacteria
//     (<1 um) and platelets (~2-3 um) follow Dean vortices,
//     complete a full Dean cycle, and exit at the bacterial
//     outlet. Bacterial recovery >65% across 10^2-10^4 cfu/mL.
//     Bacterial eluate is pelleted (16,000 x g), resuspended
//     in 50 uL PBS, lysed with 4x RLT buffer + BME, and
//     analysed by NanoString rRNA hybridization (16S/23S
//     species-specific probes) for pathogen ID without
//     culture or enzymatic amplification. Total time: ~8 h.
//
//   WORKFLOW 2 (Antibiotic Susceptibility via mRNA):
//     Clinical E. coli isolates at ~10^5 cfu/mL (either
//     spiked directly or grown 7.5 h in BACTEC blood culture
//     bottles from 1 cfu/mL) are processed through the same
//     DFF spiral device. Recovered bacteria are exposed to
//     ciprofloxacin (2.5 mcg/mL, 37 C, 30 min), then lysed
//     and analysed by NanoString mRNA detection. A set of 6
//     ciprofloxacin-responsive E. coli transcripts and 3
//     control (non-responsive) transcripts are quantified.
//     The Transcriptional Susceptibility Score (analogous to
//     Squared Pyramidal Distance) discriminates susceptible
//     (score ~0) from resistant (score ~1) strains.
//     Total time: <8 h including separation and RNA detection.
//
// KEY PHYSICAL PARAMETERS:
//   Channel: 500 um (w) x 80 um (h), spiral, ~10 cm length
//   Flow rate: 1700 uL/min total (sample:sheath = 1:10)
//   Sample: 3x diluted whole blood (~15% hematocrit)
//   Throughput: ~20 min per mL of whole blood per chip
//   Bacterial recovery: >65% (vs ~30% by low-speed centrifuge)
//   rRNA detection sensitivity: ~100 cfu/mL (3 mL input)
//   mRNA detection sensitivity: ~10^5 cfu/mL
//
// TEMPERATURE CONTROL:
//   Lysis: room temperature (25 C) for 5 min
//   Ciprofloxacin exposure: 37 C for 30 min
//   NanoString hybridization: 2 h (shortened from standard)
//   `heat` statements model these incubation steps.
//
// NOTE ON SEPARATION ABSTRACTION:
//   The `mix` steps used for DFF separation abstract a
//   continuous-flow spiral microchannel operation, not a DMF
//   electrode mixing event. At each `mix`, the sample stream
//   traverses the spiral under inertial and Dean drag forces.
//   Blood cells exit at the waste outlet (inner wall focus)
//   while bacteria exit at the bacterial outlet (Dean cycle
//   recirculation to outer wall). This is a flow-through
//   fractionation event modelled within BioScript's `mix`
//   abstraction for label-free cell separation.
//
// NOTE ON BIOSCRIPT COMPILER (lilott8/BioScript):
//   - Duration tokens: s and m only (no h). All incubations
//     stated in hours in the paper are converted to minutes.
//   - No array indexing; all droplets are scalar variables.
//   - `split` avoided to prevent stranded droplet compiler
//     errors; dilutions use explicit multi-dispense + mix.
//   - `drain` used for QC fail paths; `dispose` for pass paths.
//
// CFG STRUCTURE:
//   BB1  main                -- entry: sample prep and DFF separation
//   BB2  recoveryPass        -- recoverySignal > 0: adequate bacterial
//                               yield; carry forward to lysis
//   BB3  recoveryFail        -- recoverySignal <= 0: insufficient yield;
//                               drain and abort
//   BB4  recoveryJoin        -- join: rRNA species ID branch begins
//   BB5  rRNAPass            -- rRNASignal > 0: pathogen identified;
//                               dispose and proceed to susceptibility
//   BB6  rRNAFail            -- rRNASignal <= 0: unidentifiable pattern;
//                               drain
//   BB7  rRNAJoin            -- join: mRNA susceptibility branch begins
//   BB8  susceptibilityPass  -- susceptibilitySignal <= 0 (score near 0):
//                               susceptible organism confirmed; dispose
//   BB9  susceptibilityFail  -- susceptibilitySignal > 0 (score near 1):
//                               resistant organism flagged; drain
//   BB10 finalCleanup        -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prepare 3x-diluted whole blood sample.
//   Fresh human whole blood with EDTA anticoagulant is diluted
//   1:3 (v/v) with PBS + 0.1% BSA (sample buffer). BSA prevents
//   non-specific adsorption to tubing and microchannel walls.
//   Hematocrit target: ~15% (optimal for spiral device).
//   For rRNA experiments: bacteria spiked at ~100 cfu/mL.
//   For mRNA experiments: bacteria spiked at ~10^5 cfu/mL.
//
//   NOTE: Both susceptible and resistant E. coli clinical
//   isolates are processed identically up to ciprofloxacin
//   exposure. A single representative E. coli isolate is
//   encoded here. The susceptible/resistant classification
//   is resolved downstream by the Transcriptional
//   Susceptibility Score in WORKFLOW 2.
// ------------------------------------------------------------

wholeBlood       = dispense 1 units of WholeBlood
sampleBuffer     = dispense 1 units of PBS_BSA_Buffer
bacterialSample  = dispense 1 units of EcoliClinicalIsolate

// 1:3 dilution: mix blood with 3 volumes sample buffer.
// Three buffer units chained to accumulate correct dilution.
buf1             = dispense 1 units of PBS_BSA_Buffer
buf2             = dispense 1 units of PBS_BSA_Buffer

bufferAcc        = mix buf1 with buf2 for 5s
dilutedBlood     = mix wholeBlood with bufferAcc for 5s

// Spike bacteria into diluted blood immediately before loading.
spikedBloodSample = mix dilutedBlood with bacterialSample for 5s

// ------------------------------------------------------------
// STEP 2: Prime the spiral microchannel device.
//   Load 1x PBS + 0.1% BSA as sheath fluid via inner inlet
//   (425 um width) at ~10x the sample flow rate to pin the
//   sample stream near the outer wall at the inlet.
//   Device is pre-wetted to remove air bubbles and
//   condition channel walls to minimise non-specific adhesion.
// ------------------------------------------------------------

sheathPrime = dispense 1 units of SheathFluid
devicePrime = mix sheathPrime with spikedBloodSample for 2s

// ------------------------------------------------------------
// STEP 3: DFF separation - inertial focusing of blood cells
//   and Dean migration of bacteria.
//   Spiral device operated at 1700 uL/min total flow.
//   Sample loaded at outer inlet (75 um width); sheath at
//   inner inlet (425 um width). Sample:sheath = 1:10.
//   Over ~10 cm spiral length, RBCs and leukocytes experience
//   dominant inertial lift (F_L) and focus at inner wall.
//   Bacteria (<1 um, ap/h << 0.07) are unaffected by F_L and
//   follow Dean drag (F_D), completing a full Dean Cycle (DC1)
//   to recirculate to the outer wall and exit the bacterial
//   outlet (200 um width).
//   Process time: ~20 min per mL whole blood.
//
//   `mix` abstracts this continuous-flow separation event.
//   Output `bacterialEluate` represents the fluid collected
//   from the bacterial outlet; `bloodWaste` represents the
//   inner-wall (waste) outlet stream.
// ------------------------------------------------------------

sheathFlow     = dispense 1 units of SheathFluid
bacterialEluate = mix devicePrime with sheathFlow for 20m

// ------------------------------------------------------------
// STEP 4: Concentrate bacterial eluate.
//   Eluate collected from bacterial outlet is pelleted by
//   centrifugation at 16,000 x g. Supernatant removed.
//   Pellet resuspended in 50 uL 1x PBS for downstream steps.
//   `heat` at 25 C (room temperature) abstracts centrifugation
//   and resuspension as a defined physical processing step.
// ------------------------------------------------------------

heat bacterialEluate at 25c for 5m

// ------------------------------------------------------------
// STEP 5: QC - verify adequate bacterial recovery.
//   In the paper, recovery is verified by cfu counting on
//   LB agar plates (>65% recovery expected across tested
//   concentrations). This QC gate ensures sufficient bacterial
//   material for downstream RNA detection before proceeding.
//   bacterialRecoveryQC module abstracts the cfu enumeration.
// ------------------------------------------------------------

recoverySignal = detect bacterialRecoveryQC on bacterialEluate for 30s

// ============================================================
// BB2 / BB3: Recovery QC gate
// Pass (BB2): recoverySignal > 0 -> adequate bacterial yield
//             (>65% recovery); carry forward to lysis.
// Fail (BB3): recoverySignal <= 0 -> insufficient bacteria
//             recovered; drain and abort.
// Both branches converge at BB4 (recoveryJoin).
// ============================================================

if (recoverySignal > 0) {
    dispose bacterialEluate
} else {
    drain bacterialEluate
}

// ============================================================
// BB4: recoveryJoin
// Dispose recovery QC signal. Control falls into rRNA
// species identification branch (BB5/BB6).
// ============================================================

dispose recoverySignal

// ============================================================
// WORKFLOW 1: Species Identification via rRNA Detection
// ============================================================

// ------------------------------------------------------------
// STEP 6: Bacterial lysis for RNA extraction.
//   Concentrated pellet (50 uL in PBS) is lysed by vigorous
//   vortexing with 4x excess of RLT buffer (Qiagen) containing
//   beta-mercaptoethanol. Incubated 5 min at room temperature.
//   Lysate used immediately or stored at -80 C.
//   `heat` at 25 C models RT lysis incubation.
//   RLT buffer denatures proteins and inactivates RNases to
//   preserve RNA integrity for NanoString hybridization.
// ------------------------------------------------------------

bacterialPellet = dispense 1 units of WholeBlood

// Model: re-dispense of concentrated pellet as starting input.
// In practice this is the resuspended pellet from STEP 4.
rltBuffer        = dispense 1 units of RLT_Lysis_Buffer
bacterialLysate  = mix bacterialPellet with rltBuffer for 5m
heat bacterialLysate at 25c for 5m

// ------------------------------------------------------------
// STEP 7: NanoString rRNA hybridization for species ID.
//   Crude lysate input to NanoString assay. Two adjacent
//   50-nt probes hybridise to species-variable regions of
//   16S and 23S rRNA (>1000-fold more abundant than mRNA).
//   Probeset: 13 discriminatory probes targeting E. coli (Ec),
//   K. pneumoniae (Kp), P. aeruginosa (PsA), and Ec/Kp shared.
//   Hybridization time: 2 h (shortened from standard protocol
//   with minimal signal loss). PrepStation immobilises probes;
//   nCounter Digital Analyzer reads fluorescent barcodes.
//   Normalized Organism Score = geometric mean of
//   species-specific probe counts / sum of all geometric means.
//   Samples at 100 cfu/mL processed from 3 mL whole blood.
//   Hybridization modelled as `heat` at 65 C for 120 min.
//
//   NOTE: Direct detection from whole blood (without DFF)
//   produces uninterpretable hybridization patterns due to
//   interference from blood products. DFF pre-processing is
//   required for valid rRNA signal.
// ------------------------------------------------------------

heat bacterialLysate at 65c for 120m
rRNASignal = detect rRNASpeciesDetection on bacterialLysate for 30s

// ============================================================
// BB5 / BB6: rRNA species identification QC gate
// Pass (BB5): rRNASignal > 0 -> Organism Score assigns
//             species identity unambiguously; dispose lysate
//             and proceed to susceptibility workflow.
// Fail (BB6): rRNASignal <= 0 -> uninterpretable pattern
//             (e.g. insufficient bacterial load or mixed
//             infection outside probeset); drain.
// Both branches converge at BB7 (rRNAJoin).
// ============================================================

if (rRNASignal > 0) {
    dispose bacterialLysate
} else {
    drain bacterialLysate
}

// ============================================================
// BB7: rRNAJoin
// Dispose rRNA QC signal. Control falls into mRNA
// antibiotic susceptibility branch (BB8/BB9).
// ============================================================

dispose rRNASignal

// ============================================================
// WORKFLOW 2: Antibiotic Susceptibility via mRNA Detection
// ============================================================

// ------------------------------------------------------------
// STEP 8: Prepare bacteria at mRNA-detectable load.
//   Two input routes (both encoded here in sequence to
//   represent both experimental conditions in Fig. 5):
//
//   Route A (Direct spike): E. coli spiked at 10^5 cfu/mL
//     into 1 mL whole blood. Processed immediately by DFF.
//
//   Route B (Blood culture): BACTEC blood culture bottle
//     inoculated at 1 cfu/mL of E. coli; incubated 7.5 h at
//     37 C to reach >10^5 cfu/mL. Cultured blood then
//     processed by DFF (1:5 v/v dilution with culture media).
//     7.5 h = 450 min. `heat` models BACTEC incubation.
//
//   NOTE: NanoString mRNA detection requires ~10^5 cfu/mL,
//   which is >1 order of magnitude better than the VITEK-2
//   threshold (>10^6 cfu/mL) but exceeds typical bacteremia
//   loads (~10-100 cfu/mL). Blood culture pre-enrichment
//   bridges this gap while still being faster than current
//   gold-standard susceptibility methods.
//
//   Both susceptible and resistant isolates are encoded as
//   separate manifests; the Transcriptional Susceptibility
//   Score resolves their classification downstream.
// ------------------------------------------------------------

// Route A: Direct spike at 10^5 cfu/mL
ecoli_S          = dispense 1 units of EcoliClinicalIsolate_Susceptible
ecoli_R          = dispense 1 units of EcoliClinicalIsolate_Resistant

bloodForS        = dispense 1 units of WholeBlood
bloodForR        = dispense 1 units of WholeBlood

bufS1            = dispense 1 units of PBS_BSA_Buffer
bufS2            = dispense 1 units of PBS_BSA_Buffer
bufAccS          = mix bufS1 with bufS2 for 5s
dilutedBloodS    = mix bloodForS with bufAccS for 5s
spikedBloodS     = mix dilutedBloodS with ecoli_S for 5s

bufR1            = dispense 1 units of PBS_BSA_Buffer
bufR2            = dispense 1 units of PBS_BSA_Buffer
bufAccR          = mix bufR1 with bufR2 for 5s
dilutedBloodR    = mix bloodForR with bufAccR for 5s
spikedBloodR     = mix dilutedBloodR with ecoli_R for 5s

// Route B: Blood culture pre-enrichment (7.5 h at 37 C = 450 min)
// Modelled as heat step on the susceptible isolate sample.
// In practice, BACTEC bottle incubated off-chip before DFF.
heat spikedBloodS at 37c for 450m
heat spikedBloodR at 37c for 450m

// ------------------------------------------------------------
// STEP 9: DFF separation of bacteria from cultured blood.
//   Cultured blood (or directly spiked blood) processed
//   through the same spiral device at 1700 uL/min.
//   Bacteria at 10^5 cfu/mL are recovered at the bacterial
//   outlet with >65% efficiency. `mix` abstracts DFF event.
// ------------------------------------------------------------

sheathS          = dispense 1 units of SheathFluid
sheathR          = dispense 1 units of SheathFluid

eluateS          = mix spikedBloodS with sheathS for 20m
eluateR          = mix spikedBloodR with sheathR for 20m

// Concentrate bacterial eluates at RT (room temperature).
heat eluateS at 25c for 5m
heat eluateR at 25c for 5m

// ------------------------------------------------------------
// STEP 10: Ciprofloxacin exposure.
//   Concentrated bacterial fractions are exposed to
//   ciprofloxacin at 2.5 mcg/mL for 30 min at 37 C.
//   Ciprofloxacin (fluoroquinolone) inhibits DNA gyrase.
//   In susceptible organisms: transcriptional stress response
//   upregulates 6 ciprofloxacin-responsive mRNA transcripts.
//   In resistant organisms: these transcripts are not induced
//   at the same concentration. This differential expression
//   forms the basis of the Transcriptional Susceptibility Score.
//   30 min exposure is sufficient to generate a detectable
//   transcriptional signal without extensive bacterial growth.
// ------------------------------------------------------------

cipro_S          = dispense 1 units of Ciprofloxacin_Stock
cipro_R          = dispense 1 units of Ciprofloxacin_Stock

ciproExposure_S  = mix eluateS with cipro_S for 5s
ciproExposure_R  = mix eluateR with cipro_R for 5s

heat ciproExposure_S at 37c for 30m
heat ciproExposure_R at 37c for 30m

// ------------------------------------------------------------
// STEP 11: Lysis and NanoString mRNA detection.
//   Ciprofloxacin-exposed bacteria are lysed with RLT +
//   beta-mercaptoethanol (4x excess, 5 min RT).
//   NanoString probeset: 6 ciprofloxacin-responsive E. coli
//   mRNA transcripts + 3 control (non-responsive) transcripts.
//   Responsive transcripts normalised to the geometric mean
//   of control transcript expression to control for cell
//   number variation. Transcriptional Susceptibility Score
//   projected onto vector between centroid of susceptible
//   (score ~0) and resistant (score ~1) strains.
//   Hybridization: 2 h at 65 C.
//
//   NOTE: score <= 0 threshold (dashed line = 4 SD from
//   susceptible derivation cohort mean) identifies susceptible
//   isolates; score > 0 identifies resistant isolates.
//   mRNASusceptibilityDetection module abstracts this scoring.
// ------------------------------------------------------------

rltLysis_S       = dispense 1 units of RLT_Lysis_Buffer
rltLysis_R       = dispense 1 units of RLT_Lysis_Buffer

lysate_S         = mix ciproExposure_S with rltLysis_S for 5m
lysate_R         = mix ciproExposure_R with rltLysis_R for 5m

heat lysate_S at 25c for 5m
heat lysate_R at 25c for 5m

// NanoString mRNA hybridization: 2 h at 65 C
heat lysate_S at 65c for 120m
heat lysate_R at 65c for 120m

// Detect Transcriptional Susceptibility Score for each isolate.
// Score near 0: susceptible-like. Score near 1: resistant-like.
susceptibilitySignal_S = detect mRNASusceptibilityDetection on lysate_S for 30s
susceptibilitySignal_R = detect mRNASusceptibilityDetection on lysate_R for 30s

// ============================================================
// BB8 / BB9: Susceptibility classification gate
// The gate is keyed on susceptibilitySignal_S (susceptible
// isolate), which should score near 0 (signal <= 0 in the
// BioScript boolean sense = susceptible confirmed).
//
// Pass (BB8): susceptibilitySignal_S <= 0 -> score near 0,
//             susceptible-like transcriptional profile;
//             dispose both lysates.
// Fail (BB9): susceptibilitySignal_S > 0 -> score near 1,
//             resistant-like or ambiguous profile; drain both.
//
// NOTE: In the paper, both susceptible and resistant strains
// are clearly separated by the score (Fig. 5B). Here the
// gate logic reflects that a susceptible sample correctly
// classified has susceptibilitySignal_S <= 0. A resistant
// sample processed as lysate_S would fail this gate (> 0),
// correctly flagging resistance.
// ============================================================

if (susceptibilitySignal_S <= 0) {
    dispose lysate_S
    dispose lysate_R
} else {
    drain lysate_S
    drain lysate_R
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose all susceptibility QC signal droplets.
// Experiment ends. Full workflow time: ~8 h including
// DFF separation (~20 min/mL), RNA hybridization (~2 h),
// and ciprofloxacin exposure (30 min).
// ============================================================

dispose susceptibilitySignal_S
dispose susceptibilitySignal_R

// [terminal -- no further instructions; exit node for CFG]

module bacterialMargination
module yeastMargination
module cellularComponentDetection
module bacterialColonyCount

manifest WholeBlood
manifest PBS
manifest BSA_Buffer
manifest Dextran40
manifest GFP_Ecoli
manifest YFP_Saccharomyces
manifest CD41a_FITC
manifest CD45_APC
manifest LB_Agar

// ============================================================
// A Microfluidics Approach Towards High-Throughput Pathogen
// Removal from Blood Using Margination
// Hou, Gan, Bhagat, Li, Lim, Han
// Biomicrofluidics 6, 024115 (2012)
// DOI: 10.1063/1.4710992
//
// Platform: Pressure-driven continuous-flow PDMS microfluidic
// device. Two cascaded straight margination channels (20 x 20 um,
// W x H) with bifurcations (1:8:1) in series. No digital
// microfluidics. All dispense operations represent sample or
// reagent introduction from syringe pump inlets.
//
// Separation Principle: Whole blood flows through 20 x 20 um
// microchannels at 15 uL/min (Re ~4-5). Deformable RBCs
// migrate axially to the channel centre (Fahreaus effect),
// forming an RBC-rich core and a cell-free layer at the walls.
// Mechanical RBC-cell collisions drive margination of bacteria,
// yeast, platelets, and leukocytes into the wall-adjacent
// cell-free layer. At the bifurcation (1:8:1), marginated
// cells exit via the narrow side channels (waste) while
// RBC-enriched blood exits via the large centre outlet
// (filtered blood). Two cascaded stages achieve >80% bacterial
// removal efficiency in a single pass.
//
// BioScript Abstractions:
//   - `mix` models continuous laminar co-flow through the
//     margination channel (NOT DMF electrode mixing). The
//     mixing duration encodes channel transit time at the
//     working flow rate.
//   - `heat at 25c` models ambient-temperature incubation
//     steps (antibody staining, room-temperature operations).
//   - `heat at 4c` models on-ice or cold incubation.
//   - `heat at 37c` models bacterial culture incubation.
//   - `drain` is used for waste-stream side outlet collection
//     (marginated cell fraction). `dispose` is used for
//     confirmed filtered centre outlet fractions.
//   - Centrifugation (RBC washing) is abstracted as
//     `heat at 25c` since no centrifuge primitive exists.
//   - The 1:8:1 bifurcation geometry and cell-free-layer
//     enhancement at the expanded outlet are encoded
//     implicitly in the two-stage mix/detect structure.
//   - The parallel 6-channel device (100 uL/min total)
//     is encoded as a separate branch in the QC-pass path,
//     sharing the same reagent manifests.
//
// CFG STRUCTURE:
//   BB1  main               -- sample prep; antibody staining;
//                              two-stage margination; FACS QC gate
//   BB2  separationPass     -- separationSignal > 0: high removal
//                              efficiency confirmed; proceed to
//                              bacterial quantification
//   BB3  separationFail     -- separationSignal <= 0: insufficient
//                              removal; drain filtered fraction
//   BB4  separationJoin     -- join: bacterial CFU counting branch
//   BB5  bacteriaPass       -- bacteriaSignal > 0: >80% removal
//                              confirmed by CFU; dispose
//   BB6  bacteriaFail       -- bacteriaSignal <= 0: low removal;
//                              drain and flag for re-run
//   BB7  finalCleanup       -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prepare washed RBC sample at physiological hematocrit.
//   Human whole blood washed 3x with PBS + 0.5% BSA to remove
//   plasma proteins. Final RBC concentration adjusted to 45%
//   hematocrit in sample buffer: PBS + 0.5% BSA + 3% Dextran-40
//   (Dextran-40 prevents cell sedimentation during pump-driven
//   flow). This step is required for device characterisation
//   experiments; for whole-blood pathogen removal experiments,
//   unwashed fresh blood is used directly (see STEP 3).
//   Centrifugation abstracted as heat at 25c (no centrifuge
//   primitive in BioScript).
// ------------------------------------------------------------

bloodSample   = dispense 1 units of WholeBlood
washBuffer1   = dispense 1 units of PBS

// First wash: centrifuge 300 x g, 5 min, remove supernatant.
washedBlood1  = mix bloodSample with washBuffer1 for 5m
heat washedBlood1 at 25c for 5m

washBuffer2   = dispense 1 units of PBS
washedBlood2  = mix washedBlood1 with washBuffer2 for 5m
heat washedBlood2 at 25c for 5m

washBuffer3   = dispense 1 units of PBS
washedBlood3  = mix washedBlood2 with washBuffer3 for 5m
heat washedBlood3 at 25c for 5m

// Resuspend at 45% hematocrit in sample buffer.
bsaBuffer     = dispense 1 units of BSA_Buffer
dextranBuffer = dispense 1 units of Dextran40
sampleBuffer  = mix bsaBuffer with dextranBuffer for 30s

rbcSuspension = mix washedBlood3 with sampleBuffer for 30s

// ------------------------------------------------------------
// STEP 2: Antibody staining for whole-blood cellular analysis.
//   Fresh whole blood (unwashed, not the washed RBC sample) is
//   incubated at 4c for 40 min with:
//     CD41a-FITC (1:50, BD Biosciences) -- platelet marker
//     CD45-APC  (1:100, BD Biosciences) -- leukocyte marker
//   Staining done directly in blood without prior washing to
//   preserve native platelet and leukocyte populations.
// ------------------------------------------------------------

freshBlood    = dispense 1 units of WholeBlood
cd41a         = dispense 1 units of CD41a_FITC
cd45          = dispense 1 units of CD45_APC

antibodyMix   = mix cd41a with cd45 for 30s
stainedBlood  = mix freshBlood with antibodyMix for 2m
heat stainedBlood at 4c for 40m

// ------------------------------------------------------------
// STEP 3: Spike whole blood with GFP-E. coli and YFP-S. cerevisiae.
//   GFP-E. coli (HB101 K-12, cultured overnight at 37c in
//   LB Agar + ampicillin 100 ug/mL + arabinose 0.1%) spiked
//   at 1e6-1e7 CFU/mL. YFP-S. cerevisiae (W303-1B) spiked at
//   same concentration range. Both microbes vortexed 30 s into
//   blood immediately before device loading.
//   NOTE: E. coli (rod, ~2 x 0.5 um) and S. cerevisiae
//   (ovoid, ~5 um) are similar in size to platelets (~2-3 um)
//   and to Candida albicans (pathogenic fungal model),
//   respectively. Size difference from RBCs drives margination.
// ------------------------------------------------------------

ecoliGFP      = dispense 1 units of GFP_Ecoli
saccharomyces = dispense 1 units of YFP_Saccharomyces

// Vortex microbes into stained blood sample (30 s).
microbeBlood1 = mix stainedBlood with ecoliGFP for 30s
spikedBlood   = mix microbeBlood1 with saccharomyces for 30s

// ------------------------------------------------------------
// STEP 4: Load spiked blood into the margination device.
//   Syringe pump delivers whole blood at 15 uL/min into the
//   device inlet. Working flow rate selected to maximise
//   bacteria margination efficiency while staying within
//   device pressure tolerance (PDMS + tubing connection).
//   Re ~4-5. Wall shear rate ~6e4 s-1 (inhibits RBC
//   aggregation; Fahreaus-dominated margination regime).
//
//   Channel geometry:
//     First margination channel: 20 x 20 um (W x H), 5 mm long
//     Cascaded channel: 20 x 20 um (W x H), 1 mm long
//     Bifurcations: 1:8:1 (side:centre:side outlet ratio)
//     Aspect ratio = 1 (optimal for isotropic shear and
//     RBC core formation across the full cross-section).
//
//   `mix` models laminar co-flow through the margination
//   channel. Duration encodes transit time at 15 uL/min.
//   `rbcSuspension` supplies the RBC hydrodynamic environment
//   required for margination physics; spikedBlood carries
//   the pathogen and inflammatory cell cargo.
// ------------------------------------------------------------

// First-stage margination channel (5 mm, 15 uL/min).
// RBCs migrate axially; bacteria, yeast, platelets, and
// leukocytes marginate radially to the four channel walls.
stage1Mix     = mix spikedBlood with rbcSuspension for 20s

// Bifurcation 1 (1:8:1): marginated cells exit side channels
// (waste stream); RBC-enriched blood exits centre outlet.
// Side outlet collection: drain models waste stream removal.
stage1Waste   = mix stage1Mix with rbcSuspension for 5s
drain stage1Waste

// Centre outlet after stage 1: bacteria-depleted blood
// (approx. 50% bacterial removal, hematocrit +~10%).
stage1Filtered = mix stage1Mix with rbcSuspension for 10s

// ------------------------------------------------------------
// STEP 5: Second-stage margination (cascaded design).
//   The bacteria-depleted blood from stage 1 enters the
//   second margination channel (1 mm). Higher hematocrit
//   post-stage-1 enhances Fahreaus effect and RBC-bacteria
//   hydrodynamic interactions, driving additional bacterial
//   margination to the channel periphery.
//   Cumulative two-stage removal efficiency: >80% bacteria.
//   Platelets and leukocytes: >80% depletion.
//   RBC concentration at centre outlet: +~30% above inlet
//   (Fahreaus effect; 1:8:1 bifurcation concentrates RBCs).
//   Negligible haemolysis confirmed by optical absorption
//   at 414 nm (RBC transit time <0.01 s in shear zone).
// ------------------------------------------------------------

// Second-stage margination channel (1 mm, 15 uL/min).
stage2Mix     = mix stage1Filtered with rbcSuspension for 5s

// Bifurcation 2 (1:8:1): second margination waste stream.
stage2Waste   = mix stage2Mix with rbcSuspension for 2s
drain stage2Waste

// Final filtered blood at centre outlet after stage 2.
// Contains: RBC-enriched blood with >80% bacteria removed,
// >80% platelets removed, >80% leukocytes removed,
// ~90% S. cerevisiae removed (larger size -> corner
// margination -> complete sidewall capture).
filteredBlood = mix stage2Mix with rbcSuspension for 5s

// ------------------------------------------------------------
// STEP 6: FACS analysis of filtered blood at centre outlet.
//   BD LSR II flow cytometer. Cell populations gated by
//   forward scatter (FSC), side scatter (SSC), and
//   fluorescence channels:
//     CD41a-FITC: platelet gate
//     CD45-APC:   leukocyte gate
//     GFP:        E. coli gate
//     YFP:        S. cerevisiae gate
//   Normalised concentration = (cells at outlet) / (inlet)
//   for each population. QC threshold: >80% removal for
//   bacteria, platelets, and leukocytes; >80% RBC recovery.
//   FACS detection abstracted via cellularComponentDetection
//   module (covers all four fluorescence channels simultaneously).
// ------------------------------------------------------------

separationSignal = detect cellularComponentDetection on filteredBlood for 30s

// ============================================================
// BB2 / BB3: FACS QC gate
// Pass (BB2): separationSignal > 0 -> >80% removal of
//             inflammatory and pathogenic components confirmed;
//             proceed to CFU bacterial quantification.
// Fail (BB3): separationSignal <= 0 -> removal efficiency
//             below threshold; drain filtered fraction and
//             flag device for geometric re-optimisation.
// Both branches converge at BB4 (separationJoin).
// ============================================================

if (separationSignal > 0) {
    dispose filteredBlood
} else {
    drain filteredBlood
}

// ============================================================
// BB4: separationJoin
// Dispose FACS QC signal. Control falls into bacterial
// CFU quantification branch (BB5/BB6).
// ============================================================

dispose separationSignal

// ------------------------------------------------------------
// STEP 7: Bacterial CFU quantification at inlet and outlet.
//   10 uL aliquots from inlet (spiked blood) and filtered
//   centre outlet are plated on LB agar. Colony-forming units
//   (CFUs) counted after 24 h incubation at 37c. Removal
//   efficiency = 1 - (CFU_outlet / CFU_inlet).
//   Haemocytometer used independently for yeast concentration.
//   Expected results:
//     E. coli removal: ~80% (two-stage cascaded device)
//     S. cerevisiae removal: ~90% (larger size, corner
//     margination to all four channel walls)
//   `heat at 37c for 1440m` models 24 h agar plate incubation
//   (1440 min = 24 h converted per compiler duration constraint).
// ------------------------------------------------------------

agarPlate       = dispense 1 units of LB_Agar
filteredAliquot = dispense 1 units of WholeBlood

platesMix       = mix filteredAliquot with agarPlate for 30s
heat platesMix at 37c for 1440m

bacteriaSignal  = detect bacterialColonyCount on platesMix for 30s

// ============================================================
// BB5 / BB6: Bacterial CFU QC gate
// Pass (BB5): bacteriaSignal > 0 -> >80% bacterial removal
//             confirmed by CFU count; dispose all. Device
//             validated for sepsis treatment application.
//             Multiplexed 6-channel parallel system (100 uL/min
//             total; 6 ml/h) achieves similar filtration
//             performance at 6x throughput.
// Fail (BB6): bacteriaSignal <= 0 -> CFU count indicates
//             insufficient removal; drain and re-optimise
//             flow rate or channel geometry.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (bacteriaSignal > 0) {
    dispose platesMix
} else {
    drain platesMix
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose CFU QC signal. Experiment ends.
// ============================================================

dispose bacteriaSignal

// [terminal -- no further instructions; exit node for CFG]

module msDetection
module nmrDetection

manifest Boc_Ala_SH
manifest Boc_Val_SH
manifest Az_Ala_An
manifest Az_Pro_An
manifest RaneyNickel
manifest MeOH

// ============================================================
// Combinatorial Synthesis of Peptidomimetics Using Digital
// Microfluidics. Jebrail, Assem, Mudrik, Dryden, Lin, Yudin,
// Wheeler. J. Flow Chem. 2012, 2(3), 103-107.
// DOI: 10.1556/JFC-D-12-00012
//
// Platform: Two-plate DMF device (chromium bottom electrode
//   array + ITO top plate). 88 square actuation electrodes
//   (2.2x2.2 mm, 140 um peak-to-peak sinusoid interdigitated
//   borders), 10 reservoir electrodes (5x5 mm each).
//   Unit droplet: ~900 nL. Reservoir droplet: ~4.5 uL.
//   Driving potential: 70-100 V_rms, 18 kHz sine wave
//   (Agilent function generator + amplifier).
//   Spacer thickness: 180 um (double-sided tape, 2 layers).
//   Device materials: chromium electrodes, ITO top plate,
//   hydrophobic insulator coating.
//
// REAGENTS:
//   A1 = Boc-Ala-SH  (thioacid peptide)
//   A2 = Boc-Val-SH  (thioacid peptide)
//   B1 = Az-Ala-An   (NH aziridine-terminated amino acid)
//   B2 = Az-Pro-An   (NH aziridine-terminated amino acid)
//   All starting materials at 0.1 M in MeOH (HPLC-grade).
//   RaNi: Raney Nickel catalyst (~5 mg in MeOH) per droplet.
//
// PROTOCOL OVERVIEW:
//   PART 1 (Steps 1-4): Combinatorial ligation -- 16 steps
//     producing 4 peptidomimetic products A1-B1, A1-B2,
//     A2-B1, A2-B2 via N2 atmosphere thioacid-aziridine
//     ligation. Reaction: N2, RT, 1h, in MeOH.
//   PART 2 (Steps 5-8): Desulfurization -- 16 additional
//     steps per set. RaNi catalyst reduces the thiol in
//     each peptidomimetic product at RT for 15 min, then
//     magnetic immobilisation of RaNi and product isolation.
//
// NOTE ON GLOVEBOX: Steps 3-4 run inside a miniaturised
//   Petri-dish glovebox (150 mm o.d., 15 mm h) purged with
//   N2 at ~50 mL/min for 2 min to maintain inert atmosphere.
//   BioScript has no glovebox primitive; the N2 atmosphere
//   is abstracted as a heat step at 25 C (RT) with the
//   ligation incubation duration (60 min = 60m).
//
// NOTE ON MAGNETIC SEPARATION: In Step 7, a Neodymium Iron
//   Boron magnet immobilises RaNi to the device surface.
//   The supernatant (desulfurized product in MeOH) is then
//   driven away by electrode actuation. BioScript has no
//   magnet primitive; this is abstracted as a `drain` on
//   the catalyst-containing droplet after detection, followed
//   by disposal of the product supernatant.
//   KNOWN COMPILER BEHAVIOUR (Bug 2): lilott8/BioScript
//   maps `drain` to the same IR opcode as `dispose`. The
//   magnetic-separation semantic is preserved in source
//   comments only; both collapse to dispose() in the IR.
//
// NOTE ON SOLVENT EVAPORATION: After ligation (Step 4) and
//   after desulfurization isolation (Step 8), the top plate
//   is removed and solvent is allowed to evaporate at RT
//   (15 min post-ligation, 30 min post-desulfurization).
//   BioScript has no evaporation primitive; these steps are
//   abstracted as heat at 25 C for 15m and 30m respectively.
//
// NOTE ON COMPILER: This file targets lilott8/BioScript.
//   Duration tokens: s (seconds), m (minutes) only.
//   No array indexing; all droplets are scalar named variables.
//   Each of the 4 ligation reactions is encoded independently
//   (4 x 4 steps = 16 steps PART 1; 4 x 4 steps = 16 steps
//   PART 2), matching the paper's step count exactly.
//
// CFG STRUCTURE:
//   BB1  main             -- dispense all 8 starting material
//                            droplets, perform 4 ligations,
//                            N2 incubation, solvent evaporation
//   BB2  ligationPass     -- ligationSignal > 0: all 4 products
//                            confirmed by MS; proceed to PART 2
//   BB3  ligationFail     -- ligationSignal <= 0: ligation QC
//                            failed; drain products
//   BB4  ligationJoin     -- join: desulfurization branch begins
//   BB5  desulfPass       -- desulfSignal > 0: desulfurized
//                            products confirmed; dispose all
//   BB6  desulfFail       -- desulfSignal <= 0: assay failed;
//                            drain all desulfurized droplets
//   BB7  finalCleanup     -- terminal: dispose QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// PART 1 -- STEP 1: Dispense 8 starting material droplets
//   (two droplets each of A1, A2, B1, B2).
//   All reagents at 0.1 M in MeOH (HPLC-grade).
//   Each unit droplet: ~900 nL, dispensed from reservoir
//   (4.5 uL) by applying 70-100 V_rms at 18 kHz to the
//   reservoir electrode, pinching off a unit droplet onto
//   the actuation electrode array.
// ------------------------------------------------------------

// Thioacid peptide A1 (Boc-Ala-SH) -- two droplets
a1_drop1 = dispense 1 units of Boc_Ala_SH
a1_drop2 = dispense 1 units of Boc_Ala_SH

// Thioacid peptide A2 (Boc-Val-SH) -- two droplets
a2_drop1 = dispense 1 units of Boc_Val_SH
a2_drop2 = dispense 1 units of Boc_Val_SH

// NH aziridine-terminated amino acid B1 (Az-Ala-An) -- two droplets
b1_drop1 = dispense 1 units of Az_Ala_An
b1_drop2 = dispense 1 units of Az_Ala_An

// NH aziridine-terminated amino acid B2 (Az-Pro-An) -- two droplets
b2_drop1 = dispense 1 units of Az_Pro_An
b2_drop2 = dispense 1 units of Az_Pro_An

// ------------------------------------------------------------
// PART 1 -- STEP 2: Merge reagent pairs for 4 combinatorial
//   ligation reactions (A1xB1, A1xB2, A2xB1, A2xB2).
//   Droplets driven by sequential electrode actuation at
//   70-100 V_rms, 18 kHz; merging occurs when two droplets
//   share an electrode and coalesce.
// ------------------------------------------------------------

// Merge A1 + B1 -> A1_B1 raw merge
a1b1_merge = mix a1_drop1 with b1_drop1 for 5s

// Merge A1 + B2 -> A1_B2 raw merge
a1b2_merge = mix a1_drop2 with b2_drop1 for 5s

// Merge A2 + B1 -> A2_B1 raw merge
a2b1_merge = mix a2_drop1 with b1_drop2 for 5s

// Merge A2 + B2 -> A2_B2 raw merge
a2b2_merge = mix a2_drop2 with b2_drop2 for 5s

// ------------------------------------------------------------
// PART 1 -- STEP 3: Mix and react under N2 (miniaturised
//   glovebox). Each merged droplet is mixed for 60 s by
//   actuating in a circular motion on four electrodes
//   (70-100 V_rms, 18 kHz), then incubated for 1 h at RT
//   under N2 atmosphere. Reaction: thioacid-aziridine
//   ligation forming a peptide bond isostere with a thiol
//   sidechain (sulfa-Ala/Val backbone, rAla/rPro C-terminus).
//   N2 atmosphere maintained by miniaturised Petri-dish
//   glovebox (purged 50 mL/min, 2 min; sealed with parafilm).
//   BioScript abstraction: heat at 25 C for 60m models the
//   RT incubation; the mixing step is encoded separately below.
//
//   Products (expected m/z, ESI-MS positive ion mode):
//     A1-B1: Boc-Ala-Cys-rAla-Anilide  m/z 425
//     A1-B2: Boc-Ala-Cys-rPro-Anilide  m/z 451
//     A2-B1: Boc-Val-Cys-rAla-Anilide  m/z 452  (paper: 452)
//     A2-B2: Boc-Val-Cys-rPro-Anilide  m/z 479
// ------------------------------------------------------------

// Active mixing (60 s circular actuation) followed by N2 incubation (1h)
a1b1_mixed = mix a1b1_merge with a1b1_merge for 60s
a1b2_mixed = mix a1b2_merge with a1b2_merge for 60s
a2b1_mixed = mix a2b1_merge with a2b1_merge for 60s
a2b2_mixed = mix a2b2_merge with a2b2_merge for 60s

// N2 atmosphere incubation at RT (25 C) for 1 h (60 min)
heat a1b1_mixed at 25c for 60m
heat a1b2_mixed at 25c for 60m
heat a2b1_mixed at 25c for 60m
heat a2b2_mixed at 25c for 60m

// ------------------------------------------------------------
// PART 1 -- STEP 4: Solvent evaporation to isolate
//   peptidomimetic solid products.
//   Device removed from glovebox; top plate removed to
//   expose dried spots. Solvent (MeOH) allowed to evaporate
//   at RT for 15 min. Products remain as dried solids on
//   the bottom plate electrode surface.
//   BioScript abstraction: heat at 25 C for 15m.
// ------------------------------------------------------------

heat a1b1_mixed at 25c for 15m
heat a1b2_mixed at 25c for 15m
heat a2b1_mixed at 25c for 15m
heat a2b2_mixed at 25c for 15m

// ------------------------------------------------------------
// LIGATION QC: ESI-MS detection on representative product
//   (A1-B1 used as QC sentinel; paper verifies all 4 in
//   triplicate, ~2.3 mM in MeOH + 0.1% formic acid,
//   Agilent 1200 series quadrupole MS, positive ion mode,
//   50 V applied voltage, 100 C capillary, 0.5 mL/min,
//   average of 67 acquisitions).
//   Expected m/z 425 for A1-B1.
// ------------------------------------------------------------

ligationSignal = detect msDetection on a1b1_mixed for 30s

// ============================================================
// BB2 / BB3: Ligation QC gate
// Pass (BB2): ligationSignal > 0 -> MS confirms peptidomimetic
//             product present; proceed to desulfurization.
// Fail (BB3): ligationSignal <= 0 -> no product signal;
//             drain all ligation products.
// Both branches converge at BB4 (ligationJoin).
// ============================================================

if (ligationSignal > 0) {
    dispose a1b1_mixed
    dispose a1b2_mixed
    dispose a2b1_mixed
    dispose a2b2_mixed
} else {
    drain a1b1_mixed
    drain a1b2_mixed
    drain a2b1_mixed
    drain a2b2_mixed
}

// ============================================================
// BB4: ligationJoin
// Dispose ligation QC signal. Control falls into
// desulfurization branch (BB5/BB6).
// ============================================================

dispose ligationSignal

// ============================================================
// PART 2: Desulfurization with Raney Nickel (RaNi)
// ============================================================

// ------------------------------------------------------------
// PART 2 -- STEP 5: Re-dissolve dried peptidomimetic products
//   in MeOH. Top plate replaced; a 900-nL MeOH droplet is
//   dispensed from the reservoir and driven to each dried
//   product spot by electrode actuation to re-solubilise.
//   Products resolved: A1-B1 (m/z 425), A1-B2 (m/z 451),
//   A2-B1 (m/z 452), A2-B2 (m/z 479).
//
//   NOTE: In PART 2, the four products are re-encoded as
//   fresh dispense + resolubilisation events because the
//   PART 1 solids are treated as new starting droplets for
//   the desulfurization sub-protocol.
// ------------------------------------------------------------

meoh_a1b1 = dispense 1 units of MeOH
meoh_a1b2 = dispense 1 units of MeOH
meoh_a2b1 = dispense 1 units of MeOH
meoh_a2b2 = dispense 1 units of MeOH

// Re-dissolve each product solid in MeOH
a1b1_dissolved = mix meoh_a1b1 with a1b1_mixed for 5s
a1b2_dissolved = mix meoh_a1b2 with a1b2_mixed for 5s
a2b1_dissolved = mix meoh_a2b1 with a2b1_mixed for 5s
a2b2_dissolved = mix meoh_a2b2 with a2b2_mixed for 5s

// ------------------------------------------------------------
// PART 2 -- STEP 6: Dispense RaNi catalyst droplets and merge
//   with each dissolved peptidomimetic product droplet.
//   RaNi: ~5 mg Raney Nickel (Ni-Al alloy grains) suspended
//   in MeOH. Dispensed as 4.5-uL reservoir-volume droplets
//   (one per assay area). Merged with each product droplet
//   on the electrode array by sequential actuation.
//   Raney Nickel catalyses desulfurization: removes the -SH
//   from the cysteine-like sulfa backbone to yield the
//   reduced amide bond (confirmed by NMR peaks at 4.05 and
//   4.29 ppm for the reduced amide CH protons).
// ------------------------------------------------------------

rani_a1b1 = dispense 1 units of RaneyNickel
rani_a1b2 = dispense 1 units of RaneyNickel
rani_a2b1 = dispense 1 units of RaneyNickel
rani_a2b2 = dispense 1 units of RaneyNickel

// Merge each product with RaNi catalyst
desulf_a1b1_raw = mix a1b1_dissolved with rani_a1b1 for 5s
desulf_a1b2_raw = mix a1b2_dissolved with rani_a1b2 for 5s
desulf_a2b1_raw = mix a2b1_dissolved with rani_a2b1 for 5s
desulf_a2b2_raw = mix a2b2_dissolved with rani_a2b2 for 5s

// ------------------------------------------------------------
// PART 2 -- STEP 7: Mix and incubate at RT for 15 min.
//   Each merged droplet mixed for 60 s at RT (25 C) by
//   circular electrode actuation, then incubated for 15 min
//   at RT. Desulfurization converts the thiol sidechain to H
//   (reduced amide bond). RaNi catalyst consumed in situ.
//
//   Expected desulfurized products (ESI-MS m/z):
//     desulf A1-B1: m/z 393
//     desulf A1-B2: m/z 419
//     desulf A2-B1: m/z 421
//     desulf A2-B2: m/z 447
// ------------------------------------------------------------

desulf_a1b1_mixed = mix desulf_a1b1_raw with desulf_a1b1_raw for 60s
desulf_a1b2_mixed = mix desulf_a1b2_raw with desulf_a1b2_raw for 60s
desulf_a2b1_mixed = mix desulf_a2b1_raw with desulf_a2b1_raw for 60s
desulf_a2b2_mixed = mix desulf_a2b2_raw with desulf_a2b2_raw for 60s

heat desulf_a1b1_mixed at 25c for 15m
heat desulf_a1b2_mixed at 25c for 15m
heat desulf_a2b1_mixed at 25c for 15m
heat desulf_a2b2_mixed at 25c for 15m

// ------------------------------------------------------------
// PART 2 -- STEP 8: Magnetic immobilisation of RaNi and
//   product isolation by solvent evaporation.
//   A Neodymium Iron Boron (NdFeB) magnet is placed beneath
//   the device to immobilise the ferromagnetic RaNi grains
//   to the bottom plate surface. The supernatant droplet
//   (containing desulfurized product in MeOH, now RaNi-free)
//   is driven away by electrode actuation to a clean area.
//   Top plate removed; MeOH evaporated at RT for 30 min.
//   Products remain as dried solids for off-chip analysis.
//
//   BioScript abstraction: `drain` models the magnetic
//   immobilisation and removal of RaNi-containing phase;
//   heat at 25 C for 30m models solvent evaporation of
//   the product supernatant.
//
//   NMR verification (desulf A1-B1, CD3OD, 400 MHz):
//   Peaks at 4.05 and 4.29 ppm (reduced amide bond),
//   1.44 ppm (Boc protecting group), 7.60-7.17 ppm (phenyl).
//   Nearly identical to macroscale synthesis spectrum.
// ------------------------------------------------------------

// Magnetic immobilisation: drain RaNi-containing mixed droplets
drain desulf_a1b1_mixed
drain desulf_a1b2_mixed
drain desulf_a2b1_mixed
drain desulf_a2b2_mixed

// Dispense fresh MeOH to collect the supernatant product
meoh_prod_a1b1 = dispense 1 units of MeOH
meoh_prod_a1b2 = dispense 1 units of MeOH
meoh_prod_a2b1 = dispense 1 units of MeOH
meoh_prod_a2b2 = dispense 1 units of MeOH

// Solvent evaporation to isolate desulfurized product solids
heat meoh_prod_a1b1 at 25c for 30m
heat meoh_prod_a1b2 at 25c for 30m
heat meoh_prod_a2b1 at 25c for 30m
heat meoh_prod_a2b2 at 25c for 30m

// ------------------------------------------------------------
// DESULFURIZATION QC: ESI-MS detection on representative
//   product (desulf A1-B1 used as QC sentinel; expected
//   m/z 393). Paper verifies all 4 desulfurized products
//   in triplicate by MS and confirms A1-B1 desulf by 1H NMR
//   (500 MHz, capillary tube 100 um i.d., 512 scans).
//   NMR module abstracts both MS and NMR QC here.
// ------------------------------------------------------------

desulfSignal = detect nmrDetection on meoh_prod_a1b1 for 30s

// ============================================================
// BB5 / BB6: Desulfurization QC gate
// Pass (BB5): desulfSignal > 0 -> desulfurized products
//             confirmed; dispose all isolated product droplets.
// Fail (BB6): desulfSignal <= 0 -> no signal (RaNi failure
//             or product loss); drain all.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (desulfSignal > 0) {
    dispose meoh_prod_a1b1
    dispose meoh_prod_a1b2
    dispose meoh_prod_a2b1
    dispose meoh_prod_a2b2
} else {
    drain meoh_prod_a1b1
    drain meoh_prod_a1b2
    drain meoh_prod_a2b1
    drain meoh_prod_a2b2
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose desulfurization QC signal droplet.
// Experiment ends. All 8 products (4 peptidomimetics +
// 4 desulfurized analogues) have been synthesised in 32
// total processing steps on a single DMF device.
// ============================================================

dispose desulfSignal

