instructions:

// ============================================================
// FD-seq: Droplet-based single-cell RNA sequencing of
// paraformaldehyde-fixed cells.
// Phan et al., Research Square preprint, Oct 2021.
// DOI: 10.21203/rs.3.pex-1604/v1
//
// Platform: Drop-seq microfluidic chip (Macosko 2015).
// Key innovation: PFA-fixed, stained, sorted cells are
// compatible with droplet-based scRNA-seq via a cross-link
// reversal step (56 C, 60 min) performed inside intact
// droplets before breaking.
//
// COMPILER CONSTRAINTS (lilott8/BioScript):
//   - Duration tokens: `s` and `m` only (no `h`).
//     All hours converted: 60 min = 60m, 90 min = 90m.
//   - `heat` is void and in-place; no assignment.
//   - `detect` result assigned once; never reassigned.
//   - No loop constructs; all washes unrolled explicitly.
//   - `drain` used for failed QC paths.
//   - `dispose` used for waste from passing QC paths.
//
// CFG STRUCTURE:
//   BB1  main              -- entry: fixation, permeabilization,
//                             droplet generation, cross-link
//                             reversal, droplet breaking, RT,
//                             Exo I digestion, WTA PCR
//   BB2  barcodePass       -- barcodeSignal > 0: bead-cell
//                             pairing valid; proceed to
//                             tagmentation
//   BB3  barcodeFail       -- barcodeSignal <= 0: failed
//                             encapsulation QC; drain
//   BB4  barcodeJoin       -- join: tagmentation branch begins
//   BB5  libraryPass       -- librarySignal > 0: valid WTA
//                             library; dispose all
//   BB6  libraryFail       -- librarySignal <= 0: WTA failure;
//                             drain
//   BB7  finalCleanup      -- terminal: dispose QC signals
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// PHASE 1: Cell fixation
//   Wash cells once with 1% BSA in PBS (400g, 5 min).
//   Fix with 4% PFA in PBS at RT for 15 min.
//   Wash once with wash buffer (400g, 5 min).
//
//   NOTE: wash steps modelled as timed mix ops at 25 C
//   (BioScript has no centrifuge primitive; wash incubation
//   time is the relevant biological constraint).
// ------------------------------------------------------------

cellSample      = dispense 1 units of PBS
bsaWash1        = dispense 1 units of BSA_Wash_Buffer
washedCells1    = mix cellSample with bsaWash1 for 5m

pfa             = dispense 1 units of PFA_4pct
fixedCells      = mix washedCells1 with pfa for 15m

bsaWash2        = dispense 1 units of BSA_Wash_Buffer
washedFixed     = mix fixedCells with bsaWash2 for 5m

// ------------------------------------------------------------
// PHASE 2: Permeabilization
//   Permeabilize with 0.1% Triton X-100 in wash buffer
//   at RT for 15 min.
//   Wash twice with wash buffer (400g, 5 min each).
//   (Optional intracellular staining follows permeabilization;
//   abstracted here as the pre-droplet-generation state.)
// ------------------------------------------------------------

triton          = dispense 1 units of TritonX100_01pct
permeabilized   = mix washedFixed with triton for 15m

bsaWash3        = dispense 1 units of BSA_Wash_Buffer
washed3         = mix permeabilized with bsaWash3 for 5m

bsaWash4        = dispense 1 units of BSA_Wash_Buffer
washed4         = mix washed3 with bsaWash4 for 5m

// ------------------------------------------------------------
// PHASE 3: Pre-droplet preparation
//   Wash PFA-fixed cells 3x with 0.01% BSA (2 ml each).
//   Resuspend at 100,000 cells/ml in 0.01% BSA.
//   Drop-seq beads resuspended in lysis buffer + DTT +
//   Proteinase K at 120,000 beads/ml (kept on ice).
//
//   NOTE: Three 0.01% BSA washes unrolled explicitly
//   (compiler has no loop construct).
// ------------------------------------------------------------

bsa001_w1       = dispense 1 units of BSA_001pct
prefixed_w1     = mix washed4 with bsa001_w1 for 2m

bsa001_w2       = dispense 1 units of BSA_001pct
prefixed_w2     = mix prefixed_w1 with bsa001_w2 for 2m

bsa001_w3       = dispense 1 units of BSA_001pct
cellsReady      = mix prefixed_w2 with bsa001_w3 for 2m

lysisBeads      = dispense 1 units of LysisBuffer_DTT_ProtK
dropseqBeads    = dispense 1 units of DropSeq_Beads
beadsReady      = mix lysisBeads with dropseqBeads for 2m

// ------------------------------------------------------------
// PHASE 4: Droplet generation
//   Cell syringe: 3 ml/h. Bead syringe: 3 ml/h.
//   Oil syringe (Bio-Rad): 12 ml/h.
//   Co-encapsulation of single cell + single bead in
//   nanoliter droplet. Collection ~20 min.
//   Modelled as mix of cells + beads (co-encapsulation
//   abstraction) then merge with oil (emulsification).
//
//   NOTE: syringe pump flow and microfluidic chip geometry
//   are not primitives in BioScript. The merge sequence
//   (cells -> beads -> oil) captures the reagent assembly
//   order. Timing (20m) models collection duration.
// ------------------------------------------------------------

cellBeadMix     = mix cellsReady with beadsReady for 20m

oil             = dispense 1 units of Oil_BioRad
emulsion        = mix cellBeadMix with oil for 20m

// ------------------------------------------------------------
// PHASE 5: Cross-link reversal (in-droplet)
//   Incubate emulsion at 56 C for 60 min.
//   PFA cross-links reversed inside intact droplets by
//   proteinase K + heat. This is the key FD-seq step
//   enabling scRNA-seq of fixed cells.
//   Cool at RT for 10 min, then on ice for 5 min.
//   (RT and ice steps modelled as heat at 25 C and 4 C.)
// ------------------------------------------------------------

heat emulsion at 56c for 60m
heat emulsion at 25c for 10m
heat emulsion at 4c for 5m

// ------------------------------------------------------------
// PHASE 6: Droplet breaking
//   Remove excess oil from 50 ml tube.
//   Add 30 ml 6X SSC + 1 ml Perfluorooctan-1-ol.
//   Shake, spin (1000g, 1 min) -> break emulsion.
//   Transfer supernatant twice (30 ml each) to recover beads.
//   Spin (1000g, 3 min); pool beads into 1.5 ml LoBind tube.
//   Wash 2x with 6X SSC, then 1x with 5X Maxima RT buffer.
//
//   Modelled as sequential mix ops representing the
//   chemical breaking and wash cascade.
// ------------------------------------------------------------

ssc1            = dispense 1 units of SSC_6X
pfol            = dispense 1 units of Perfluorooctan1ol
brokenEmulsion  = mix emulsion with ssc1 for 1m
brokenEmulsion2 = mix brokenEmulsion with pfol for 1m

ssc2            = dispense 1 units of SSC_6X
beadFraction1   = mix brokenEmulsion2 with ssc2 for 3m

ssc3            = dispense 1 units of SSC_6X
beadWash1       = mix beadFraction1 with ssc3 for 1m

ssc4            = dispense 1 units of SSC_6X
beadWash2       = mix beadWash1 with ssc4 for 1m

dispose brokenEmulsion

// ------------------------------------------------------------
// PHASE 7: Reverse transcription
//   RT mix (200 ul): nuclease-free water, 5X Maxima H- RT
//   buffer, 20% Ficoll, 10 mM dNTPs, RNase inhibitor,
//   100 uM TSO_RNAhybrid, Maxima H- reverse transcriptase.
//   Incubate: 25 C for 30 min (primer annealing / RT init),
//   then 42 C for 90 min (cDNA synthesis).
//   Wash: 1x TE-SDS, 2x TE-TW, 1x 10 mM Tris pH 8.0.
//
//   All wash steps unrolled explicitly.
//   Duration constraint: 90 min = 90m.
// ------------------------------------------------------------

rtMix           = dispense 1 units of RT_Mix
beadsInRT       = mix beadWash2 with rtMix for 30m

heat beadsInRT at 25c for 30m
heat beadsInRT at 42c for 90m

// Wash post-RT (unrolled; TE-SDS and TE-TW not listed as
// separate manifests -- modelled via BSA_Wash_Buffer
// as generic aqueous wash proxy; biological identity
// annotated in comments).
//   Wash 1: TE-SDS
rtWash1         = dispense 1 units of BSA_Wash_Buffer
rtWashed1       = mix beadsInRT with rtWash1 for 1m
//   Wash 2: TE-TW
rtWash2         = dispense 1 units of BSA_Wash_Buffer
rtWashed2       = mix rtWashed1 with rtWash2 for 1m
//   Wash 3: TE-TW
rtWash3         = dispense 1 units of BSA_Wash_Buffer
rtWashed3       = mix rtWashed2 with rtWash3 for 1m
//   Wash 4: 10 mM Tris pH 8.0
rtWash4         = dispense 1 units of BSA_Wash_Buffer
rtWashed4       = mix rtWashed3 with rtWash4 for 1m

// ------------------------------------------------------------
// PHASE 8: Exonuclease I digestion
//   Exo I mix (200 ul): nuclease-free water, 10X Exo I buffer,
//   Exo I (NEB M0293S).
//   Incubate at 37 C for 45 min with rotation.
//   Removes residual unextended primers from bead surface.
//   Wash: 1x TE-SDS, 2x TE-TW.
// ------------------------------------------------------------

exoMix          = dispense 1 units of ExoI_Mix
beadsInExo      = mix rtWashed4 with exoMix for 5m

heat beadsInExo at 37c for 45m

//   Wash 1: TE-SDS
exoWash1        = dispense 1 units of BSA_Wash_Buffer
exoWashed1      = mix beadsInExo with exoWash1 for 1m
//   Wash 2: TE-TW
exoWash2        = dispense 1 units of BSA_Wash_Buffer
exoWashed2      = mix exoWashed1 with exoWash2 for 1m
//   Wash 3: TE-TW
exoWash3        = dispense 1 units of BSA_Wash_Buffer
exoWashed3      = mix exoWashed2 with exoWash3 for 1m

// Resuspend beads in nuclease-free water for WTA.
wta_water       = dispense 1 units of PBS
beadsForWTA     = mix exoWashed3 with wta_water for 2m

// ------------------------------------------------------------
// PHASE 9: Whole transcriptome amplification (WTA)
//   5,000 beads per 24.6 ul reaction in 96-well plate.
//   PCR mix: Kapa HiFi Readymix + TSO_PCR primer.
//   Program: 95 C 3 min; 4 cycles (98/65/72); 10 cycles
//   (98/67/72); 72 C 5 min.
//   Modelled as sequential heat steps representing the
//   thermocycler program phases:
//     Denaturation init: 95 C, 3 min
//     Cycle set 1 annealing phase (4x): 65 C, 4x3 = 12m
//     Cycle set 2 annealing phase (10x): 67 C, 10x1 = 10m
//     Final extension: 72 C, 5 min
//
//   NOTE: BioScript has no PCR primitive or loop. Each
//   thermocycler phase is encoded as a heat step. The four
//   `heat` calls represent: initial denaturation, low-cycle
//   annealing phase (aggregate), high-cycle annealing phase
//   (aggregate), and final extension.
// ------------------------------------------------------------

wtaMix          = dispense 1 units of WTA_PCR_Mix
wtaReaction     = mix beadsForWTA with wtaMix for 2m

heat wtaReaction at 95c for 3m
heat wtaReaction at 65c for 12m
heat wtaReaction at 67c for 10m
heat wtaReaction at 72c for 5m

// ------------------------------------------------------------
// Barcode / bead QC detection (proxy for Ampure XP
// purification and Qubit quantification step).
//   barcodeIntegrityDetection module abstracts:
//   - AMpure XP 0.6X cleanup of WTA products
//   - Qubit quantification (expected peak 600-700 bp
//     by TapeStation, Figure 1 in paper)
//   Signal > 0: valid WTA library with correct size profile.
//   Signal <= 0: amplification failure or bead quality issue.
// ------------------------------------------------------------

barcodeSignal   = detect barcodeIntegrityDetection on wtaReaction for 10m

// ============================================================
// BB2 / BB3: Barcode / WTA QC gate
// Pass (BB2): barcodeSignal > 0 -> valid WTA product;
//             proceed to tagmentation.
// Fail (BB3): barcodeSignal <= 0 -> WTA failure; drain.
// Both branches converge at BB4 (barcodeJoin).
// ============================================================

if (barcodeSignal > 0) {
    dispose wtaReaction
} else {
    drain wtaReaction
}

// ============================================================
// BB4: barcodeJoin
// Dispose barcode QC signal. Control falls into tagmentation
// (BB5/BB6).
// ============================================================

dispose barcodeSignal

// ------------------------------------------------------------
// PHASE 10: Tagmentation (Nextera XT)
//   Input: 450 pg WTA product per reaction (2 reactions).
//   Step 1: Tagment DNA mix (10 ul) + WTA product (5 ul)
//           + Amplicon Tagment mix (5 ul) -> 55 C, 5 min.
//   Step 2: Neutralise with NT buffer (5 ul), RT 5 min.
//   Step 3: PCR with P5-TSO + Nextera_N7XX primers,
//           Nextera PCR master mix.
//           95 C 30s; 12 cycles (95/55/72); 72 C 5 min.
//   Ampure XP 0.6X cleanup -> store at -20 C.
//   Library peak ~400 bp (Fragment Analyzer, Figure 2).
//
//   NOTE: Two tagmentation reactions run in parallel on
//   the same WTA pool; encoded as two independent reaction
//   arms (tagReaction1, tagReaction2).
// ------------------------------------------------------------

wtaForTag1      = dispense 1 units of WTA_PCR_Mix
wtaForTag2      = dispense 1 units of WTA_PCR_Mix

tdm1            = dispense 1 units of TagmentDNAMix
tdm2            = dispense 1 units of TagmentDNAMix

atm1            = dispense 1 units of AmpliconTagmentMix
atm2            = dispense 1 units of AmpliconTagmentMix

tagStep1a       = mix wtaForTag1 with tdm1 for 1m
tagStep1b       = mix wtaForTag2 with tdm2 for 1m

tagWithATM1     = mix tagStep1a with atm1 for 1m
tagWithATM2     = mix tagStep1b with atm2 for 1m

heat tagWithATM1 at 55c for 5m
heat tagWithATM2 at 55c for 5m

nt1             = dispense 1 units of NTBuffer
nt2             = dispense 1 units of NTBuffer

neutralised1    = mix tagWithATM1 with nt1 for 5m
neutralised2    = mix tagWithATM2 with nt2 for 5m

p5tso1          = dispense 1 units of P5TSO_Primer
p5tso2          = dispense 1 units of P5TSO_Primer
n7xx1           = dispense 1 units of NexteraN7XX_Primer
n7xx2           = dispense 1 units of NexteraN7XX_Primer
npm1            = dispense 1 units of NexteraPCRMasterMix
npm2            = dispense 1 units of NexteraPCRMasterMix

tagPCRmix1      = mix neutralised1 with p5tso1 for 30s
tagPCRmix1b     = mix tagPCRmix1 with n7xx1 for 30s
tagReaction1    = mix tagPCRmix1b with npm1 for 30s

tagPCRmix2      = mix neutralised2 with p5tso2 for 30s
tagPCRmix2b     = mix tagPCRmix2 with n7xx2 for 30s
tagReaction2    = mix tagPCRmix2b with npm2 for 30s

// Tagmentation PCR thermocycler:
//   95 C 30s (denaturation init)
//   12 cycles (95/55/72) -> annealing phase: 12 x 30s = 6m
//   72 C 5 min (final extension)
heat tagReaction1 at 95c for 30s
heat tagReaction1 at 55c for 6m
heat tagReaction1 at 72c for 5m

heat tagReaction2 at 95c for 30s
heat tagReaction2 at 55c for 6m
heat tagReaction2 at 72c for 5m

// ------------------------------------------------------------
// Library QC detection (proxy for Ampure XP 0.6X cleanup +
// BioAnalyzer quantification).
//   wqaQCDetection module abstracts:
//   - Ampure XP cleanup of tagmented library
//   - BioAnalyzer quantification (expected peak ~400 bp,
//     Figure 2 in paper)
//   - NextSeq library loading at appropriate molarity
//   Signal > 0: library passes size + concentration QC.
//   Signal <= 0: tagmentation failure; drain.
// ------------------------------------------------------------

librarySignal   = detect wqaQCDetection on tagReaction1 for 10m

// ============================================================
// BB5 / BB6: Library QC gate
// Pass (BB5): librarySignal > 0 -> valid tagmented library
//             (~400 bp peak); dispose all.
// Fail (BB6): librarySignal <= 0 -> tagmentation failure;
//             drain all.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (librarySignal > 0) {
    dispose tagReaction1
    dispose tagReaction2
} else {
    drain tagReaction1
    drain tagReaction2
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose library QC signal. Experiment ends.
// Sequencing: NextSeq, >=75 cycles, paired-end,
//   read1 = 20bp (cell barcode + UMI), read2 = 60bp (cDNA),
//   index1 = 8bp (N7XX sample index).
// ============================================================

dispose librarySignal

// [terminal -- no further instructions; exit node for CFG]

module iemSensorDetection
module sawLysingDetection
module miR21FreefloatingDetection
module miR21TotalDetection

manifest Plasma_Sample
manifest PBS_1x
manifest PBS_4x
manifest PBS_01x
manifest TAE_Buffer_10x
manifest miR21_OligoProbe
manifest SAW_Actuator
manifest IEM_AEM_Sensor
manifest IEM_CEM_Concentrator

instructions:

// ============================================================
// Extracellular Vesicle microRNA Quantification from Plasma
// Using an Integrated Microfluidic Device
// Ramshani et al., Communications Biology (2019) 2:189
// DOI: 10.1038/s42003-019-0435-1
//
// Protocol: PCR-free absolute quantification of free-floating
// and EV-contained miR-21 from untreated human plasma using
// (1) a surface acoustic wave (SAW) lysing chip that
//     mechanically lyses EVs under continuous flow, and
// (2) a concentration/sensing chip with ion-exchange
//     membranes (IEMs) that concentrate and detect
//     target miRNA via current-voltage curve (CVC) shift.
//
// Biomarker: miRNA hsa-mir-21-5p (miR-21)
//   Sequence: TAGCTTATCAGACTGATGTTGA
//   Correlation: pancreatic cancer, lung cancer,
//                colorectal cancer, hepatocellular carcinoma.
//
// Key specs:
//   Sample volume   : ~20 uL per measurement (40 uL total)
//   Assay time      : ~30 min per measurement (~60 min total)
//   Detection limit : 1 pM
//   Quantification  : <10% uncertainty (absolute, PCR-free)
//   SAW frequency   : 28 MHz, 1 W
//   SAW flow rate   : 250 uL/h
//   EV lysis time   : ~1 min in SAW channel
//   Concentration V : 200 V DC for 20 min
//   Hybridisation   : 20 min (concurrent with concentration)
//   Wash buffer     : 4x PBS (post-hybridisation)
//   CVC buffer      : 0.1x PBS (measurement)
//
// NOTE ON IEM SENSOR ABSTRACTION:
//   The AEM sensor is functionalized with a complementary
//   ssDNA oligoprobe (TCAACATCAGTCTGATAAGCTA) to miR-21.
//   Target hybridisation shifts the over-limiting region of
//   the CVC by Delta-V (V), which is log-linearly correlated
//   to miR-21 concentration:
//     C (nM) = exp((Delta-V - 0.76145) / 0.06614)
//   `detect iemSensorDetection` abstracts the CVC sweep
//   (Gamry 500 potentiostat, Ag-AgCl reference electrodes).
//   `detect sawLysingDetection` abstracts SAW actuation
//   and confirms lysis before downstream sensing.
//   `detect miR21FreefloatingDetection` abstracts CVC shift
//   measurement for the unlysed (free-floating) plasma run.
//   `detect miR21TotalDetection` abstracts CVC shift
//   measurement for the SAW-lysed (total miRNA) plasma run.
//
// NOTE ON CONCENTRATION STEP ABSTRACTION:
//   Application of 200 V DC across the CEM reservoir for
//   20 min creates an ion-depletion zone upstream of the
//   AEM sensor, concentrating negatively charged miRNA
//   by up to three orders of magnitude directly beneath
//   the sensor where hybridisation occurs. This is modelled
//   as a `heat` step at 25c (room temperature) for 20 min
//   (= 1200 s), reflecting the ambient temperature of the
//   concentration/sensing chip during IEM operation.
//
// CFG STRUCTURE:
//   BB1  main                  -- device setup, IEM baseline CVC,
//                                  free-floating miR-21 measurement
//   BB2  freefloatingPass      -- freefloatSignal > 0: valid
//                                  free-floating miR-21 detected;
//                                  proceed to SAW-lysed total run
//   BB3  freefloatingFail      -- freefloatSignal <= 0: no signal
//                                  (below sensor limit); drain
//   BB4  freefloatingJoin      -- join: total miRNA measurement begins
//   BB5  totalPass             -- totalSignal > 0: valid total miR-21
//                                  (free-floating + EV-miRNA) detected;
//                                  dispose and compute EV fraction
//   BB6  totalFail             -- totalSignal <= 0: no total signal;
//                                  drain
//   BB7  finalCleanup          -- terminal: dispose QC signals,
//                                  experiment ends
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Prepare 1x PBS running buffer and establish
//         baseline CVC on the IEM sensor (oligoprobe only,
//         no sample). The sensor is functionalized prior to
//         use with miR-21 complementary ssDNA oligoprobe
//         (TCAACATCAGTCTGATAAGCTA) via standard amine-
//         coupling on the AEM surface.
//         This baseline CVC (miR-21 probe in 1x PBS only)
//         is used as the reference for all Delta-V measurements.
//         Buffer volume: 60 uL (used as driver fluid after
//         sample injection throughout the protocol).
// ------------------------------------------------------------

runningBuffer   = dispense 1 units of PBS_1x
probeBaseline   = dispense 1 units of IEM_AEM_Sensor

baselineMix     = mix runningBuffer with probeBaseline for 5s
baselineSignal  = detect iemSensorDetection on baselineMix for 30s

// ------------------------------------------------------------
// STEP 2: MEASUREMENT 1 - Free-floating miR-21 quantification.
//         ~20 uL of untreated human plasma is injected into
//         the integrated platform with the SAW device OFF
//         (no EV lysis). The sample passes through the lysing
//         chip channel and flows directly into the
//         concentration/sensing chip.
//         Flow rate: 250 uL/h (sample + 60 uL PBS driver).
//         The SAW chip channel is bypassed acoustically
//         (IDT powered off) -- EVs remain intact.
//         Only free-floating miR-21 present in plasma reaches
//         the IEM sensor.
//         NOTE: `mix` here abstracts continuous flow injection
//         through the microfluidic channel; no DMF-style
//         droplet merging occurs. Plasma is used as-is with
//         no sample preparation.
// ------------------------------------------------------------

plasmaRun1      = dispense 1 units of Plasma_Sample
driverBuffer1   = dispense 1 units of PBS_1x

// Continuous-flow channel injection (SAW OFF - no lysis).
// Flow carries 20 uL plasma + 60 uL PBS driver at 250 uL/h.
channelFlow1    = mix plasmaRun1 with driverBuffer1 for 2s

// ------------------------------------------------------------
// STEP 3: IEM concentration - apply 200 V DC across CEM
//         reservoir for 20 min. The resulting depletion zone
//         concentrates negatively charged free-floating
//         miR-21 upstream of the AEM sensor surface.
//         Hybridisation with the oligoprobe occurs
//         concurrently during this 20-min window.
//         Modelled as room-temperature incubation (25 C,
//         20 min = 1200 s) to represent non-thermal IEM
//         electrokinetic concentration at ambient conditions.
// ------------------------------------------------------------

cemConcentrator1 = dispense 1 units of IEM_CEM_Concentrator
concentrating1   = mix channelFlow1 with cemConcentrator1 for 1200s

// IEM electrokinetic concentration at ambient temperature.
heat concentrating1 at 25c for 1200s

// ------------------------------------------------------------
// STEP 4: Post-hybridisation wash with 4x PBS to remove
//         non-hybridised species from the AEM sensor surface.
//         Then pump 0.1x PBS into the channel prior to the
//         CVC measurement sweep.
// ------------------------------------------------------------

washBuffer1     = dispense 1 units of PBS_4x
washed1         = mix concentrating1 with washBuffer1 for 2s

cvcBuffer1      = dispense 1 units of PBS_01x
readyForCVC1    = mix washed1 with cvcBuffer1 for 2s

// ------------------------------------------------------------
// STEP 5: CVC sweep - measure Delta-V for free-floating
//         miR-21. Concentration voltage is terminated;
//         Gamry 500 potentiostat applies current-voltage
//         sweep (0 to 2.5 V) between the AEM sensor reservoir
//         and upstream reservoir via platinum electrodes.
//         Voltage drop measured by Ag-AgCl reference electrodes
//         across the sensor. Delta-V in the over-limiting
//         current region is recorded.
//         miR21FreefloatingDetection abstracts this CVC sweep
//         and returns a positive signal if Delta-V > sensor
//         noise floor (> ~0.1 V for free-floating miR-21
//         in healthy human plasma as per paper Fig. 3).
// ------------------------------------------------------------

freefloatSignal = detect miR21FreefloatingDetection on readyForCVC1 for 30s

// ============================================================
// BB2 / BB3: Free-floating miR-21 QC gate
// Pass (BB2): freefloatSignal > 0 -> measureable Delta-V
//             detected for free-floating miR-21; dispose
//             and proceed to SAW-lysed total measurement.
// Fail (BB3): freefloatSignal <= 0 -> signal below sensor
//             noise floor (< 1 pM); drain and abort.
// Both branches converge at BB4 (freefloatingJoin).
// ============================================================

if (freefloatSignal > 0) {
    dispose readyForCVC1
} else {
    drain readyForCVC1
}

// ============================================================
// BB4: freefloatingJoin
// Dispose free-floating QC signal. Control falls into
// total miRNA measurement branch (BB5/BB6).
// ============================================================

dispose freefloatSignal
dispose baselineSignal

// ------------------------------------------------------------
// STEP 6: MEASUREMENT 2 - Total miR-21 quantification
//         (free-floating + EV-contained miR-21).
//         A fresh 20 uL aliquot of the same plasma sample is
//         injected with the SAW device ACTIVE (28 MHz, 1 W).
//         SAWs refract into the polycarbonate microchannel
//         perpendicular to the IDT array, generating acoustic
//         pressure that mechanically shears EVs open.
//         Residence time: ~1 min in the SAW channel at
//         250 uL/h flow rate -- sufficient for ~100% EV lysis.
//         Released EV-miRNA and free-floating miRNA both
//         flow into the concentration/sensing chip.
//         NOTE: `mix` abstracts SAW channel flow-through.
//         sawLysingDetection confirms acoustic lysis before
//         the lysate enters the IEM chip.
// ------------------------------------------------------------

sawActuator     = dispense 1 units of SAW_Actuator
plasmaRun2      = dispense 1 units of Plasma_Sample
driverBuffer2   = dispense 1 units of PBS_1x

// SAW lysis: 28 MHz, 1 W, ~1 min exposure at 250 uL/h.
// NOTE: `mix` abstracts the channel-flow EV lysis event.
// No DMF electrode mixing occurs; this models acoustic
// pressure shearing of EV membranes under continuous flow.
sawLysate       = mix plasmaRun2 with sawActuator for 60s

// Detect lysis completion (confirms EVs are mechanically
// disrupted before lysate enters concentration/sensing chip).
lysisSignal     = detect sawLysingDetection on sawLysate for 10s

// Flow lysate into concentration/sensing chip under PBS driver.
channelFlow2    = mix sawLysate with driverBuffer2 for 2s

// ------------------------------------------------------------
// STEP 7: IEM concentration - second run.
//         200 V DC applied for 20 min across CEM reservoir.
//         Both free-floating miR-21 and EV-released miR-21
//         (total pool) concentrate upstream of the AEM sensor
//         and hybridise with the miR-21 oligoprobe.
//         IEM sensor is replaced (disposable) between runs
//         to maintain optimised repeatability.
// ------------------------------------------------------------

cemConcentrator2 = dispense 1 units of IEM_CEM_Concentrator
concentrating2   = mix channelFlow2 with cemConcentrator2 for 1200s

// IEM electrokinetic concentration at ambient temperature.
heat concentrating2 at 25c for 1200s

// ------------------------------------------------------------
// STEP 8: Post-hybridisation wash and buffer exchange
//         for the total miRNA CVC measurement.
//         4x PBS wash removes non-hybridised species.
//         0.1x PBS is pumped in before the CVC sweep.
// ------------------------------------------------------------

washBuffer2     = dispense 1 units of PBS_4x
washed2         = mix concentrating2 with washBuffer2 for 2s

cvcBuffer2      = dispense 1 units of PBS_01x
readyForCVC2    = mix washed2 with cvcBuffer2 for 2s

// ------------------------------------------------------------
// STEP 9: CVC sweep - measure Delta-V for total miR-21
//          (free-floating + EV-miRNA).
//          Same potentiostat procedure as STEP 6.
//          Expected Delta-V for total miR-21 in healthy human
//          plasma: ~0.65-0.7 V (vs ~0.1 V for free-floating
//          only) as per paper Fig. 3.
//          The difference in voltage shift between Measurement
//          1 (free-floating) and Measurement 2 (total)
//          directly quantifies the EV-miR-21 fraction.
//          EV-miR-21 concentration is calculated from the
//          calibration curve: C = exp((Delta-V - 0.76145) / 0.06614)
//          miR21TotalDetection abstracts this CVC sweep and
//          returns positive signal if Delta-V significantly
//          exceeds the free-floating baseline (> ~0.2 V shift
//          from free-floating run expected for EV contribution).
// ------------------------------------------------------------

totalSignal     = detect miR21TotalDetection on readyForCVC2 for 30s

// ============================================================
// BB5 / BB6: Total miR-21 QC gate
// Pass (BB5): totalSignal > 0 -> measurable Delta-V for
//             total miR-21 detected; Delta-V > free-floating
//             signal confirming EV-miRNA released by SAW.
//             Dispose all droplets and proceed to cleanup.
// Fail (BB6): totalSignal <= 0 -> no total signal (SAW lysis
//             failure or IEM sensor issue); drain all.
// Both branches converge at BB7 (finalCleanup).
// ============================================================

if (totalSignal > 0) {
    dispose readyForCVC2
    dispose lysisSignal
} else {
    drain readyForCVC2
    drain lysisSignal
}

// ============================================================
// BB7: finalCleanup (terminal)
// Dispose all remaining QC signal droplets.
// The EV-miR-21 expression level is computed off-chip by
// comparing the two voltage shifts using:
//   ExpressionLevel = exp((Delta-V_total - Delta-V_freefloat) / b)
// where b = 0.06614 is the log-linear calibration fitting
// parameter from the IEM sensor calibration curve (Fig. 2b).
// Experiment ends.
// ============================================================

dispose totalSignal
dispose baselineMix

// [terminal -- no further instructions; exit node for CFG]

module lysisDetection
module aktKinaseDetection
module gapdhActivityDetection

manifest HepG2_Cells
manifest EaglesMEM_10FBS_PenStrep
manifest SerumFreeMedium
manifest Insulin
manifest CellTrackerOrange
manifest PBS
manifest LysisBuffer
manifest BSA_PBS
manifest AktAssayBuffer
manifest GapdhAssayBuffer
manifest DeionizedWater

instructions:

// ============================================================
// Microfluidic Probe for Single-Cell Analysis in Adherent
// Tissue Culture
// Sarkar, Kolitz, Lauffenburger, Han --
// Nature Communications 5:3421, 2014.
// DOI: 10.1038/ncomms4421
//
// Protocol: Selective hydrodynamic confinement-based lysis
// of single adherent HepG2 cells from standard tissue
// culture, followed by lysate capture, mixing with assay
// buffers, pneumatic valve-based chamber trapping, and
// multiplexed fluorescence activity measurement of kinase
// Akt (Sox peptide sensor) and housekeeping enzyme GAPDH
// (NADH formation) simultaneously from the same cell.
//
// Device: Three-layer PDMS microfluidic probe.
//   Layer 1 (base): bare glass slide (except at tip)
//   Layer 2 (membrane): ~30 um thin PDMS; forms deformable
//     tip base; contains pneumatic valve lines (V1-V4)
//   Layer 3 (flow): ~5 mm thick PDMS; contains channels,
//     reaction chambers (AB1-AB4), and flow/control ports.
//   Tip channels: 5 um tall (lysis + assay buffer mixing)
//   Reaction chambers: 30 um tall (maximise fluorescence)
//   Assay volume per chamber: ~20 nL
//
// LYSIS ZONE PRINCIPLE: Simultaneous Qout (central channel,
//   lysis buffer outflow, 5 nL/min) and Qin (outer channels,
//   inflow, 50 nL/min total; 25 nL/min per outer channel)
//   create a hydrodynamically confined lysis zone of radius
//   R tunable by Qin/Qout ratio. Zone set slightly smaller
//   than cell diameter (~15 um) to lyse only target cell.
//   Lysis buffer detergent (1% Triton X-100) confined to zone;
//   neighbouring cells remain unaffected even at ~80%
//   confluency. Lysate captured within ~20 s after lysis.
//
// MIXING RATIO: Lysate:assay buffer = 1:4 (set by flow
//   resistance ratio of lysate and assay buffer channels).
//   Repeatability of mixing ratio within 10% CV.
//   Travel time from tip to reaction chamber: 90 s.
//
// MULTIPLEXED ARM (this .bs file): Lysate from a single
//   HepG2 cell subdivided into two chambers -- AB1 (Akt
//   Sox sensor assay) and AB2 (GAPDH NADH assay) -- via
//   pneumatic valve routing. Primary result: Fig. 5 (n=12).
//   Single-activity arms (Akt only: Fig. 4a; GAPDH only:
//   Fig. 4b) are not separately encoded here; they differ
//   only in lysate routing (one chamber instead of two).
//
// NOTE ON `mix` ABSTRACTION:
//   (a) Device priming / BSA coating: `mix` abstracts
//       syringe-pump-driven flow through device channels.
//   (b) Cell labelling and stimulation: `mix` abstracts
//       incubation of cells with dye or insulin in medium.
//   (c) Lysis zone formation: `mix` abstracts simultaneous
//       Qout/Qin flow at probe tip creating lysis zone.
//   (d) Lysate + assay buffer mixing: `mix` abstracts
//       passive resistance-ratio mixing in flow channels
//       before entering reaction chambers.
//   None of these are DMF electrode mixing steps.
//
// NOTE ON TEMPERATURE:
//   Cell culture, labelling, and recovery: 37 C / 5% CO2.
//   Assay chamber monitoring: 30 C (heating chamber,
//     Tokai Hit; lower than 37 C to reduce photobleaching).
//   BioScript `heat` models both incubator and heating stage.
//
// NOTE ON DURATION TOKENS:
//   BioScript supports s and m only; h not supported.
//   Serum starvation 12-24 h -> 720m (minimum, 12 h)
//   Cell attachment 4-16 h -> 240m (minimum, 4 h)
//   BSA coating: 60m (1 h at 50 nL/min)
//   UV bleach: 30m
//   Cell Tracker labelling: 15m-45m -> 15m (minimum)
//   Cell recovery post-labelling: 20m-45m -> 20m (minimum)
//   Stimulation (insulin for Akt): 10m-16.5m -> 10m
//   Lysis + capture: ~20 s -> 20s
//   Valve travel time: 90 s
//   Assay imaging: 20m minimum
//   Clonal expansion: not in this protocol
//
// CFG STRUCTURE:
//   BB1  main              -- entry: device priming, BSA
//                            coating, UV bleach, cell
//                            culture, serum starvation,
//                            cell labelling, insulin
//                            stimulation, lysis zone,
//                            lysate capture
//   BB2  lysisPass         -- lysisSignal > 0: lysis
//                            confirmed (Cell Tracker Orange
//                            fluorescence drop in target
//                            cell); proceed to assay
//   BB3  lysisFail         -- lysisSignal <= 0: lysis
//                            failed (no fluorescence drop
//                            or neighbouring cell affected);
//                            drain lysis zone and retry
//   BB4  lysisJoin         -- join: Akt assay branch begins
//   BB5  aktPass           -- aktSignal > 0: Akt activity
//                            detected above lysis buffer
//                            control baseline; dispose
//   BB6  aktFail           -- aktSignal <= 0: no Akt signal
//                            (possible 'low Akt' phenotype
//                            or cell non-responsive to
//                            insulin); drain Akt chamber
//   BB7  aktJoin           -- join: GAPDH assay branch begins
//   BB8  gapdhPass         -- gapdhSignal > 0: GAPDH
//                            activity detected (housekeeping
//                            loading control confirmed);
//                            dispose assay mixture
//   BB9  gapdhFail         -- gapdhSignal <= 0: GAPDH
//                            not detected; drain chamber
//   BB10 finalCleanup      -- terminal: dispose GAPDH
//                            signal; NOP
// ============================================================

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// STEP 1: Device preparation -- DI water priming.
//         Prime channels with de-ionised water using gas-tight
//         glass syringes (50 uL) connected to lysis buffer
//         and inflow source ports via fused silica tubing
//         (OD 360 um, ID 100 um). Controlled by syringe pumps
//         (Harvard Apparatus PHD 2000).
//         NOTE: `mix` abstracts syringe-pump flow through
//         device channels at low flow rate.
// ------------------------------------------------------------

diWater       = dispense 1 units of DeionizedWater
primedDevice  = mix diWater with diWater for 5m

// ------------------------------------------------------------
// STEP 2: Device preparation -- BSA coating.
//         Coat device channels with 1% BSA in 0.5x PBS to
//         prevent non-specific protein binding to PDMS surfaces.
//         Drawn in at 50 nL/min for at least 1 h (60 min),
//         then washed with de-ionised water.
//         BSA coating is critical to preserve enzyme activity
//         from the picomolar single-cell lysate.
// ------------------------------------------------------------

bsaPbs        = dispense 1 units of BSA_PBS
diWash        = dispense 1 units of DeionizedWater
bsaCoated     = mix primedDevice with bsaPbs for 60m

heat bsaCoated at 25c for 60m

bsaWashed     = mix bsaCoated with diWash for 5m

// ------------------------------------------------------------
// STEP 3: Device preparation -- UV photobleaching.
//         Bleach the area of device observed during assay for
//         at least 30 min using UV light (ex 377 nm) to reduce
//         background fluorescence in reaction chambers.
//         Done immediately before loading assay buffers and
//         before placing the plate on the microscope stage.
// ------------------------------------------------------------

heat bsaWashed at 25c for 30m

// ------------------------------------------------------------
// STEP 4: Load assay buffers into reservoirs.
//         Immediately before use, lysis buffer loaded into
//         syringe at lysis buffer port.
//         Akt assay buffer (50 mM Tris-HCl pH 7.3, 10 mM
//         MgCl2, 1 mM EGTA, 2 mM DTT, 4 mM PKC inhibitor
//         peptide, 10 mM Sox substrate peptide, 1 mM ATP,
//         0.4 mM PKItide, 5 uM GF109203X) loaded into AB1.
//         GAPDH assay buffer (90 mM sodium pyrophosphate pH
//         7.1, 20 mM NaH2PO4, 3 mM DTT, 4 mM NAD+, 10 mM
//         glyceraldehyde 3-phosphate) loaded into AB2.
//         Each reservoir: 20 uL.
//         Lysis buffer: 50 mM beta-glycerophosphate, 10 mM
//         sodium pyrophosphate, 30 mM NaF, 50 mM Tris pH 7.4,
//         1% Triton X-100, 15 mM NaCl, 2 mM EGTA, 100 uM
//         sodium orthovanadate, 1 mM DTT, 1X protease and
//         phosphatase inhibitor cocktails, 20 ug/mL Alexa 488-
//         labelled BSA (for lysis zone visualisation).
//         NOTE: `mix` abstracts passive buffer loading into
//         reservoirs; no active mixing occurs at this step.
// ------------------------------------------------------------

lysisBuffer   = dispense 1 units of LysisBuffer
aktBuffer     = dispense 1 units of AktAssayBuffer
gapdhBuffer   = dispense 1 units of GapdhAssayBuffer
loadedDevice  = mix bsaWashed with lysisBuffer for 2m

// ------------------------------------------------------------
// STEP 5: Cell culture -- HepG2 plating and attachment.
//         HepG2 cells (ATCC HB-8065) plated at 5,000-20,000
//         cells/cm2 on standard tissue culture polystyrene.
//         Medium: Eagle's MEM + 10% FBS + 1% pen/strep
//         (Invitrogen). Culture at 37 C, 5% CO2.
//         Allow to attach for 4-16 h (minimum: 4 h = 240m).
//         NOTE: `mix` abstracts cell seeding and medium
//         addition to tissue culture plate. `heat` models
//         37 C CO2 incubator dwell for attachment.
// ------------------------------------------------------------

hepg2Cells    = dispense 1 units of HepG2_Cells
cultureMedium = dispense 1 units of EaglesMEM_10FBS_PenStrep
platedCells   = mix hepg2Cells with cultureMedium for 2m

heat platedCells at 37c for 240m

// ------------------------------------------------------------
// STEP 6: Serum starvation (12-24 h minimum; 720m).
//         Replace complete medium with serum-free Eagle's MEM
//         to synchronise signalling state before stimulation.
//         Serum starvation sensitises Akt pathway to insulin.
//         Duration: 720m (minimum; 12 h).
//         NOTE: `mix` abstracts medium exchange on plate.
// ------------------------------------------------------------

serumFree     = dispense 1 units of SerumFreeMedium
starvedCells  = mix platedCells with serumFree for 2m

heat starvedCells at 37c for 720m

// ------------------------------------------------------------
// STEP 7: Cell labelling with Cell Tracker Orange dye.
//         Incubate serum-starved cells with 2.5 uM Cell
//         Tracker Orange in serum-free medium for 15-45 min
//         at 37 C (minimum: 15m). Dye labels cytosol;
//         fluorescence drop in target cell confirms lysis.
//         Wash with PBS, then recover in serum-free medium
//         at 37 C for 20-45 min (minimum: 20m) before
//         stimulation. Imaging: rhodamine filter
//         (ex 540 nm, em 570 nm, Semrock).
// ------------------------------------------------------------

cellTracker   = dispense 1 units of CellTrackerOrange
labelledCells = mix starvedCells with cellTracker for 15m

heat labelledCells at 37c for 15m

pbsWash       = dispense 1 units of PBS
washedCells   = mix labelledCells with pbsWash for 2m

recoveryMedium  = dispense 1 units of SerumFreeMedium
recoveredCells  = mix washedCells with recoveryMedium for 2m

heat recoveredCells at 37c for 20m

// ------------------------------------------------------------
// STEP 8: Insulin stimulation to activate Akt.
//         Spike insulin to final concentration 500 ng/mL in
//         serum-free medium (for Akt time-course: cells lysed
//         one by one under continuous stimulation conditions;
//         medium NOT removed; cells lysed directly off plate).
//         Stimulation duration: 10-16.5 min tested;
//         here 10m (minimum tested; Fig. 4a/c/5a).
//         For serum-starved control: medium not replaced;
//         no insulin added.
//         NOTE: `mix` abstracts insulin addition to plate
//         medium. `heat` models 37 C incubator dwell.
// ------------------------------------------------------------

insulinStock    = dispense 1 units of Insulin
stimulatedCells = mix recoveredCells with insulinStock for 2m

heat stimulatedCells at 37c for 10m

// ------------------------------------------------------------
// STEP 9: Single-cell lysis by hydrodynamic confinement.
//         Plate transferred to microscope (Olympus IX71).
//         Microfluidic probe positioned near target HepG2 cell
//         using micromanipulator.
//         Lysis zone created by:
//           Qout (central channel): 5 nL/min lysis buffer
//           Qin (outer channels):   50 nL/min total inflow
//                                   (25 nL/min per channel)
//         Zone radius R set slightly smaller than cell (~15 um)
//         by Qin/Qout = 10 ratio (Fig. 2b of paper).
//         Target cell lysed immediately on exposure; cytosolic
//         Cell Tracker Orange fluorescence drops within ~20 s.
//         Neighbouring cell fluorescence unaffected.
//         Lysate captured by Qin inflow along outer channels.
//         Lysis confirmed by Cell Tracker Orange fluorescence
//         drop monitored on rhodamine filter (ex 540, em 570).
//         `lysisDetection` module abstracts this fluorescence
//         drop QC check on target vs. neighbouring cells.
//         NOTE: `mix` abstracts the simultaneous Qout/Qin
//         flow at tip creating and maintaining the lysis zone.
// ------------------------------------------------------------

lysisZone     = mix loadedDevice with stimulatedCells for 20s
lysisSignal   = detect lysisDetection on lysisZone for 20s

// ============================================================
// BB2 / BB3: Lysis QC gate
// Pass (BB2): lysisSignal > 0 -> Cell Tracker Orange
//             fluorescence drop confirmed in target cell,
//             neighbouring cells unaffected; proceed to
//             assay branches.
// Fail (BB3): lysisSignal <= 0 -> lysis failed (no drop,
//             or neighbouring cell affected); drain lysis
//             zone and retry on next target cell.
// Both branches converge at BB4 (lysisJoin).
// ============================================================

if (lysisSignal > 0) {
    dispose lysisZone
} else {
    drain lysisZone
}

// ============================================================
// BB4: lysisJoin
// Dispose lysis QC signal. Lysate flows through device and
// is subdivided by pneumatic valve routing into AB1 (Akt)
// and AB2 (GAPDH) chambers. Lysate mixed with assay buffer
// at 1:4 ratio by passive resistance-ratio mixing in 5 um
// channels. Valves (V1-V4) actuated with compressed air
// (30 psi) via solenoid valve manifold at 90 s after lysis
// (measured travel time from tip to reaction chambers) to
// trap assay mixture in chambers.
// Assay chambers monitored at 30 C on automated motorised
// stage (Prior Scientific H110) in heating chamber (Tokai
// Hit) placed on Olympus IX71 microscope.
// ============================================================

dispose lysisSignal

// ------------------------------------------------------------
// STEP 10: Akt kinase activity assay (chamber AB1).
//          Sox peptide sensor (10 uM substrate peptide) in
//          Akt assay buffer mixed 1:4 with lysate from AB1.
//          Assay mixture trapped in AB1 reaction chamber by
//          valve actuation (V1/V2 closed) at 90 s after lysis.
//          Fluorescence monitored every 30 s for >= 20 min
//          at 30 C using DAPI filter (ex 377 nm, em 447 nm,
//          Semrock), shutter (Uniblitz, 200 ms exposure).
//          Sox sensor phosphorylation by Akt generates
//          chelation-enhanced fluorescence (CSox fluorophore).
//          Activity = initial slope of fluorescence vs time.
//          LOD: 0.32 pg recombinant active Akt (vs 0.51 ng
//          on plate reader). ~1 ng total protein equivalent
//          per single HepG2 cell lysate.
//          Control: lysis buffer (no lysate) run in parallel.
//          aktKinaseDetection module abstracts the Sox sensor
//          fluorescence slope fitting (initial linear region).
//          NOTE: `mix` abstracts passive resistance-ratio
//          mixing of lysate with Akt assay buffer in 5 um
//          channels before valve closure traps mixture.
// ------------------------------------------------------------

aktAssayMix = mix lysisBuffer with aktBuffer for 90s

heat aktAssayMix at 30c for 20m

aktSignal   = detect aktKinaseDetection on aktAssayMix for 20m

// ============================================================
// BB5 / BB6: Akt activity QC gate
// Pass (BB5): aktSignal > 0 -> Akt activity detected above
//             lysis buffer baseline; 'high Akt' phenotype
//             (insulin-responsive); dispose Akt assay mixture.
// Fail (BB6): aktSignal <= 0 -> Akt activity at or below
//             baseline; 'low Akt' phenotype (non-responsive
//             to insulin; p-value 0.35, consistent with
//             senescent morphology subgroup in Fig. 5a);
//             drain Akt assay mixture.
// Both branches converge at BB7 (aktJoin).
// ============================================================

if (aktSignal > 0) {
    dispose aktAssayMix
} else {
    drain aktAssayMix
}

// ============================================================
// BB7: aktJoin
// Dispose Akt QC signal. GAPDH assay branch begins.
// GAPDH serves as housekeeping loading control to normalise
// Akt activity per cell (Supplementary Fig. 9). GAPDH
// activity unaffected by insulin stimulation (p=0.98 for
// 'high Akt' cells; Fig. 5a dark red markers).
// ============================================================

dispose aktSignal

// ------------------------------------------------------------
// STEP 11: GAPDH activity assay (chamber AB2).
//          GAPDH assay buffer (4 mM NAD+, 10 mM
//          glyceraldehyde 3-phosphate in 90 mM sodium
//          pyrophosphate pH 7.1 + 20 mM NaH2PO4 + 3 mM DTT)
//          mixed 1:4 with lysate from AB2 subdivision.
//          Assay mixture trapped in AB2 reaction chamber by
//          valve actuation (V3/V4 closed) at 90 s after lysis.
//          GAPDH converts NAD+ to NADH (fluorescent);
//          monitored on DAPI filter (ex 377 nm, em 447 nm)
//          every 30 s for >= 20 min at 30 C.
//          LOD lower than Akt (Fig. 4f) due to higher GAPDH
//          expression levels relative to Akt.
//          gapdhActivityDetection module abstracts NADH
//          fluorescence slope fitting (initial linear region).
//          NOTE: Simultaneously acquired with Akt assay (AB1
//          and AB2 chambers imaged on automated stage). Here
//          encoded sequentially for BioScript compatibility
//          (no concurrent parallel detect statements).
// ------------------------------------------------------------

gapdhAssayMix = mix lysisBuffer with gapdhBuffer for 90s

heat gapdhAssayMix at 30c for 20m

gapdhSignal   = detect gapdhActivityDetection on gapdhAssayMix for 20m

// ============================================================
// BB8 / BB9: GAPDH activity QC gate
// Pass (BB8): gapdhSignal > 0 -> GAPDH activity detected;
//             loading control confirmed; dispose GAPDH
//             assay mixture.
// Fail (BB9): gapdhSignal <= 0 -> GAPDH not detected
//             (possible lysate loss or chamber failure);
//             drain GAPDH assay mixture.
// Both branches converge at BB10 (finalCleanup).
// ============================================================

if (gapdhSignal > 0) {
    dispose gapdhAssayMix
} else {
    drain gapdhAssayMix
}

// ============================================================
// BB10: finalCleanup (terminal)
// Dispose GAPDH QC signal. Single-cell multiplexed assay
// cycle complete. Probe repositioned to next target cell
// for subsequent measurement (up to 4 cells in parallel
// using 4 chambers AB1-AB4; lysis is sequential per cell).
// ============================================================

dispose gapdhSignal

// [terminal -- no further instructions; exit node for CFG]

module apoptosisDetection
module cellDeathDetection

manifest PDAC_P1_Cells
manifest PDAC_P2_Cells
manifest PDAC_P3_Cells
manifest GFR_Matrigel
manifest CompleteOrganoidMedia
manifest Gemcitabine_100nM
manifest Paclitaxel_10nM
manifest FluorouracilLow_100nM
manifest FluorouracilHigh_1uM
manifest Docetaxel_10nM
manifest CPT11_100nM
manifest Oxaliplatin_100nM
manifest Cisplatin_100nM
manifest Caspase37_Reagent
manifest PropidiumIodide

// ============================================================
// Automated Microfluidic Platform for Dynamic and
// Combinatorial Drug Screening of Tumor Organoids
// Schuster et al., Nature Communications (2020) 11:5271
// DOI: 10.1038/s41467-020-19058-4
//
// Platform: Two-part PDMS device -- 200-well 3D culture
// chamber array (610 um deep, 20 independent channels) +
// solenoid-valve multiplexer control device (up to 30
// chemical inputs, automated via MATLAB GUI).
//
// Biological scope: Patient-derived PDAC organoids from
// 3 patients grown in GFR Matrigel (14+ days) then subject to:
//   (A) Single-agent screens: 7 chemotherapies, 72-h arm
//   (B) 5 temporal/sequential combination regimens (Patient 1)
//   (C) Multi-patient parallel Gem+5FU temporal (P1/P2/P3)
//
// ABSTRACTION NOTES:
//   - Each `mix` encodes one directed fluid event (multiplexer
//     valve actuation delivering one drug slug to one channel
//     subset). A single source droplet is consumed per mix.
//   - cultureP1/P2/P3 are re-dispensed fresh for each
//     independent treatment arm (separate wells on device).
//   - `heat` is void/in-place; no assignment.
//   - Duration tokens: s and m only.
//       2 h   = 120m   |  30 min = 30m
//       4 h   = 240m   |  48 h  = 2880m
//       72 h  = 4320m  |  7 d   = 10080m
//       14 d  = 20160m |  24 h  = 1440m
//   - No loops: all multi-cycle regimens unrolled.
//   - Each detect result assigned once; disposed after gate.
//   - drain used on failed QC paths.
//
// CFG STRUCTURE:
//   BB1  main              -- culture, growth, all drug arms
//   BB2  apoptosisPass     -- apoptosisQC > 0: dispose all P1
//   BB3  apoptosisFail     -- apoptosisQC <= 0: drain all P1
//   BB4  assayJoin         -- dispose QC signal; multi-pt arm
//   BB5  multiPatPass      -- multiPatQC > 0: dispose P2/P3
//   BB6  multiPatFail      -- multiPatQC <= 0: drain P2/P3
//   BB7  finalCleanup      -- terminal: dispose all QC signals
// ============================================================

instructions:

// ============================================================
// BB1: main
// ============================================================

// ------------------------------------------------------------
// SECTION 1: Organoid culture establishment
//
// Each treatment arm gets its own fresh culture (independent
// wells on the 200-well array). `mix` abstracts manual
// pipetting of dissociated single cells in 70% GFR Matrigel /
// 30% complete media into 610-um wells, followed by Matrigel
// gelation at 37 C and clamping of channel layer.
// ------------------------------------------------------------

// --- Patient 1: Single-agent gemcitabine arm (72-h) ---
sa_mat_gem  = dispense 1 units of GFR_Matrigel
sa_med_gem  = dispense 1 units of CompleteOrganoidMedia
sa_cel_gem  = dispense 1 units of PDAC_P1_Cells
sa_gel_gem  = mix sa_mat_gem with sa_med_gem for 5s
sa_cult_gem = mix sa_cel_gem with sa_gel_gem for 10s

// --- Patient 1: Single-agent paclitaxel arm (72-h) ---
sa_mat_pac  = dispense 1 units of GFR_Matrigel
sa_med_pac  = dispense 1 units of CompleteOrganoidMedia
sa_cel_pac  = dispense 1 units of PDAC_P1_Cells
sa_gel_pac  = mix sa_mat_pac with sa_med_pac for 5s
sa_cult_pac = mix sa_cel_pac with sa_gel_pac for 10s

// --- Patient 1: Single-agent 5-FU arm (72-h) ---
sa_mat_fu   = dispense 1 units of GFR_Matrigel
sa_med_fu   = dispense 1 units of CompleteOrganoidMedia
sa_cel_fu   = dispense 1 units of PDAC_P1_Cells
sa_gel_fu   = mix sa_mat_fu with sa_med_fu for 5s
sa_cult_fu  = mix sa_cel_fu with sa_gel_fu for 10s

// --- Patient 1: Single-agent docetaxel arm (72-h) ---
sa_mat_doc  = dispense 1 units of GFR_Matrigel
sa_med_doc  = dispense 1 units of CompleteOrganoidMedia
sa_cel_doc  = dispense 1 units of PDAC_P1_Cells
sa_gel_doc  = mix sa_mat_doc with sa_med_doc for 5s
sa_cult_doc = mix sa_cel_doc with sa_gel_doc for 10s

// --- Patient 1: Single-agent CPT-11 arm (72-h) ---
sa_mat_cpt  = dispense 1 units of GFR_Matrigel
sa_med_cpt  = dispense 1 units of CompleteOrganoidMedia
sa_cel_cpt  = dispense 1 units of PDAC_P1_Cells
sa_gel_cpt  = mix sa_mat_cpt with sa_med_cpt for 5s
sa_cult_cpt = mix sa_cel_cpt with sa_gel_cpt for 10s

// --- Patient 1: Single-agent oxaliplatin arm (72-h) ---
sa_mat_oxa  = dispense 1 units of GFR_Matrigel
sa_med_oxa  = dispense 1 units of CompleteOrganoidMedia
sa_cel_oxa  = dispense 1 units of PDAC_P1_Cells
sa_gel_oxa  = mix sa_mat_oxa with sa_med_oxa for 5s
sa_cult_oxa = mix sa_cel_oxa with sa_gel_oxa for 10s

// --- Patient 1: Single-agent cisplatin arm (72-h) ---
sa_mat_cis  = dispense 1 units of GFR_Matrigel
sa_med_cis  = dispense 1 units of CompleteOrganoidMedia
sa_cel_cis  = dispense 1 units of PDAC_P1_Cells
sa_gel_cis  = mix sa_mat_cis with sa_med_cis for 5s
sa_cult_cis = mix sa_cel_cis with sa_gel_cis for 10s

// --- Patient 1: Temporal FOLFIRINOX arm ---
fol_mat     = dispense 1 units of GFR_Matrigel
fol_med     = dispense 1 units of CompleteOrganoidMedia
fol_cel     = dispense 1 units of PDAC_P1_Cells
fol_gel     = mix fol_mat with fol_med for 5s
fol_cult    = mix fol_cel with fol_gel for 10s

// --- Patient 1: Temporal FOLFIRI arm ---
firi_mat    = dispense 1 units of GFR_Matrigel
firi_med    = dispense 1 units of CompleteOrganoidMedia
firi_cel    = dispense 1 units of PDAC_P1_Cells
firi_gel    = mix firi_mat with firi_med for 5s
firi_cult   = mix firi_cel with firi_gel for 10s

// --- Patient 1: Temporal FOLFOX arm ---
fox_mat     = dispense 1 units of GFR_Matrigel
fox_med     = dispense 1 units of CompleteOrganoidMedia
fox_cel     = dispense 1 units of PDAC_P1_Cells
fox_gel     = mix fox_mat with fox_med for 5s
fox_cult    = mix fox_cel with fox_gel for 10s

// --- Patient 1: Temporal Gemcitabine + 5-FU arm ---
gf_mat      = dispense 1 units of GFR_Matrigel
gf_med      = dispense 1 units of CompleteOrganoidMedia
gf_cel      = dispense 1 units of PDAC_P1_Cells
gf_gel      = mix gf_mat with gf_med for 5s
gf_cult     = mix gf_cel with gf_gel for 10s

// --- Patient 1: Temporal Gemcitabine + Paclitaxel arm ---
gp_mat      = dispense 1 units of GFR_Matrigel
gp_med      = dispense 1 units of CompleteOrganoidMedia
gp_cel      = dispense 1 units of PDAC_P1_Cells
gp_gel      = mix gp_mat with gp_med for 5s
gp_cult     = mix gp_cel with gp_gel for 10s

// --- Patient 2: Gem+5FU temporal (multi-patient arm) ---
p2_mat      = dispense 1 units of GFR_Matrigel
p2_med      = dispense 1 units of CompleteOrganoidMedia
