// ============================================================
// BB2 / BB3: Primary QC gate (P1 gemcitabine apoptosis signal)
//
// Pass (BB2): apoptosisQC > 0 -> valid caspase 3/7 readout;
//             dispose all P1 single-agent and temporal droplets.
// Fail (BB3): apoptosisQC <= 0 -> detection failure; drain all.
// Both converge at BB4 (assayJoin).
// ============================================================

if (apoptosisQC > 0) {
    dispose gemFinished
    dispose pacFinished
    dispose fuFinished
    dispose docFinished
    dispose cptFinished
    dispose oxaFinished
    dispose cisFinished
    dispose folFinished
    dispose firiFinished
    dispose foxFinished
    dispose gfFinished
    dispose gpFinished
} else {
    drain gemFinished
    drain pacFinished
    drain fuFinished
    drain docFinished
    drain cptFinished
    drain oxaFinished
    drain cisFinished
    drain folFinished
    drain firiFinished
    drain foxFinished
    drain gfFinished
    drain gpFinished
}

// ============================================================
// BB4: assayJoin
// Dispose P1 apoptosis QC signal. Control falls into
// multi-patient parallel QC gate (BB5/BB6).
// ============================================================

dispose apoptosisQC

// ============================================================
// BB5 / BB6: Multi-patient QC gate (P2 apoptosis signal)
//
// Pass (BB5): multiPatQC > 0 -> valid P2 caspase 3/7 signal;
